var PATH_BOOK_POL = {"subject": "思想政治", "book": "必修1《中国特色社会主义》", "version": "统编版", "chapters": [{"no": "第一课", "title": "社会主义从空想到科学、从理论到实践的发展", "units": ["u_pol_1"]}, {"no": "第二课", "title": "只有社会主义才能救中国", "units": ["u_pol_2"]}, {"no": "第三课", "title": "只有中国特色社会主义才能发展中国", "units": ["u_pol_3"]}, {"no": "第四课", "title": "只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴", "units": ["u_pol_4"]}, {"no": "综合探究", "title": "回看走过的路，比较别人的路，远眺前行的路；方向决定道路，道路决定命运", "units": ["u_pol_5"]}], "order": ["u_pol_1", "u_pol_2", "u_pol_3", "u_pol_4", "u_pol_5"], "nodes": {"pol_p001": {"name": "原始社会的解体和阶级社会的演进", "sec": 1, "secTitle": "第一课 社会主义从空想到科学、从理论到实践的发展", "page": 1, "desc": "两对基本矛盾推动社会形态依次更替：原始社会→奴隶社会→封建社会→资本主义社会→共产主义社会。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": [], "next": ["pol_p002"], "content": {"intro": "人类社会不是一成不变的，它由低级向高级不断发展。推动社会前进的是两对基本矛盾：**生产力与生产关系**的矛盾、**经济基础与上层建筑**的矛盾，其中**生产力**是社会发展的最终决定力量。==社会形态依次更替是历史发展的总趋势，但每个国家走过的具体道路又各不相同。==", "learn": [{"h": "原始社会为什么会解体", "p": "原始社会末期，**生产力**发展到出现**剩余产品**，于是**私有制**产生，一部分人占有生产资料和劳动产品，**阶级**分化出现，**国家**随之产生，原始社会走向解体。答题时把链条写全：生产力发展→剩余产品→私有制→阶级→国家，每一环都是一个得分点。"}, {"h": "两对基本矛盾怎么推动社会", "p": "**生产关系一定要适合生产力状况**是人类社会发展的基本规律之一：生产力决定生产关系，生产关系反作用于生产力，适合时促进、不适合时阻碍。**上层建筑一定要适合经济基础状况**是另一条基本规律：经济基础决定上层建筑，上层建筑反作用于经济基础。\\n\\n==两对矛盾贯穿人类社会始终，它们的矛盾运动推动社会形态依次更替。=="}, {"h": "五种社会形态的更替", "p": "社会形态依次是：**原始社会→奴隶社会→封建社会→资本主义社会→共产主义社会**。奴隶社会代替原始社会、封建社会代替奴隶社会、资本主义社会代替封建社会，都是历史的进步。共产主义社会是人类最美好的社会，**社会主义社会是共产主义的初级阶段**。更替呈现**统一性**（依次更替是总趋势）与**多样性**（不同国家可以跨越某些阶段、走不同道路）的统一。"}, {"h": "资本主义为什么必然被代替", "p": "资本主义社会的基本矛盾是**生产社会化与生产资料资本主义私人占有之间的矛盾**，它决定了资本主义必然被社会主义代替。这一矛盾在阶级关系上表现为无产阶级和资产阶级的矛盾，在经济运行中表现为周期性**经济危机**。经济危机的实质是生产相对过剩，根源是资本主义基本矛盾。"}], "pitfalls": ["把阶级斗争或上层建筑说成社会发展的最终决定力量——最终决定力量只能是生产力。", "认为每个国家都必须完整经历五种社会形态——更替是统一性与多样性的统一，中国就跨越了资本主义独立发展阶段。", "把经济危机的原因说成生产绝对过剩——实质是生产相对过剩（相对于劳动人民有支付能力的需求）。"], "basics": [{"q": "社会发展的最终决定力量是（ ）", "opts": ["阶级斗争", "生产力", "上层建筑", "科学技术"], "ans": 1, "why": "生产力是最革命的因素，是社会发展的最终决定力量；科学技术是先进生产力的集中体现和主要标志，但不能等同于生产力本身。"}, {"q": "下列关于经济基础与上层建筑关系的说法，正确的是（ ）", "opts": ["上层建筑决定经济基础", "经济基础决定上层建筑，上层建筑反作用于经济基础", "两者互不影响", "上层建筑的变化与经济基础无关"], "ans": 1, "why": "经济基础决定上层建筑，上层建筑对经济基础具有反作用，这是教材规范表述，不能颠倒。"}, {"q": "人类社会形态更替的正确顺序是（ ）", "opts": ["原始社会→封建社会→奴隶社会→资本主义社会→共产主义社会", "奴隶社会→原始社会→封建社会→资本主义社会→共产主义社会", "原始社会→奴隶社会→封建社会→资本主义社会→共产主义社会", "原始社会→奴隶社会→资本主义社会→封建社会→共产主义社会"], "ans": 2, "why": "按教材：原始社会、奴隶社会、封建社会、资本主义社会、共产主义社会依次更替。"}], "apply": [{"q": "材料：某地出土的一处新石器时代晚期遗址中，既有公共墓葬区的平整墓穴，也有随葬大量玉器、陶器的「大墓」，居住区房屋面积差异明显。考古学家据此推断该社会正处于瓦解之中。这一推断的依据是，当时（ ）", "opts": ["生产力发展，出现了剩余产品和私有制萌芽", "国家机器已经相当完备", "文字已经成熟并广泛使用", "社会分工完全消失"], "ans": 0, "why": "随葬品和房屋的悬殊差异说明私有财产和贫富分化出现；其根源是生产力发展产生剩余产品，私有制随之萌芽，原始社会由此解体。"}, {"q": "材料：进入近代以后，中国没有经历独立发展的资本主义社会，而是经过新民主主义革命直接走上社会主义道路。有人据此说「中国违背了社会历史发展规律」。这种说法错在（ ）", "opts": ["否认了生产力是社会发展的最终决定力量", "没有看到社会形态更替是统一性与多样性的统一", "夸大了上层建筑的反作用", "否认了阶级斗争的推动作用"], "ans": 1, "why": "依次更替是历史发展总趋势（统一性），但具体国家可以跨越某些阶段、走不同道路（多样性）。只讲总趋势、不讲具体道路，恰恰是片面理解规律。"}], "case": {"q": "材料：16—19 世纪，机器大工业使社会生产规模空前扩大，产品跨越国界在世界市场流通；与此同时，生产资料却集中在少数资本家手中，周期性经济危机反复爆发，工人大量失业而仓库里货物堆积。运用本框知识，分析资本主义经济危机爆发的根源，并指出它说明了什么道理。", "a": "根源：资本主义社会的基本矛盾——生产社会化（生产高度社会化、世界市场联系）与生产资料资本主义私人占有之间的矛盾。危机中产品「过剩」不是超过实际需要，而是超过劳动人民有支付能力的需求，是相对过剩。这说明资本主义生产关系已经成为生产力发展的桎梏，资本主义必然被社会主义代替，是不以人的意志为转移的历史趋势。"}, "advance": {"q": "辨析：社会形态的更替完全是由人们的主观选择决定的，想走什么路就能走什么路。", "a": "错误。社会发展有其客观规律：生产力与生产关系、经济基础与上层建筑的矛盾运动决定社会形态的更替，这一过程不以人的意志为转移。但是，人们可以在遵循规律的前提下发挥历史主动性，在多种具体道路中作出选择——更替的统一性与多样性相统一。把选择绝对化，否认规律的客观性，是历史唯心主义。", "kind": "self"}}, "video": {"bvid": "BV15M4m127aY", "p": 1, "t": "社会主义从空想到科学、从理论到实践的发展", "dur": "91:24", "from": "政治老师爱政治", "vtop": ["生产关系是否适应生产力的发展，是判断一种社会形态取代另一种社会形态是进步还是倒退的主要标志——奴隶社会取代原始社会就是历史的进步。", "资本主义社会的基本矛盾是生产社会化与生产资料资本主义私人占有之间的矛盾，它是经济危机爆发的根本原因，也是资本主义一切矛盾与冲突的总根源。", "科学社会主义诞生的标志是《共产党宣言》的发表；实现社会主义由空想到科学的伟大飞跃的，是唯物史观和剩余价值学说这两大理论基石。"], "vsum": "本课是必修一第一课，讲社会主义从空想到科学、从理论到实践的发展，分两框：第一框讲原始社会到奴隶社会、封建社会到资本主义社会，第二框讲科学社会主义的理论与实践。开场先点全书主题：这本书围绕**社会主义的发展**展开，共四课，第一课从整个人类社会发展历史的角度讲社会主义的由来，后面三课讲我们国家的社会主义。第一框第一幕从原始社会到奴隶社会，先讲原始社会。原始社会是人类社会的**最初阶段、最低阶段**，可以比喻为人类的**童年时期**，但这个童年十分漫长：**旧石器时代**是200到300万年至1万年前，人们靠采集天然食物为生，用打制石器；**新石器时代**是1万年前，出现了原始的畜牧业和农业，人们从食物的采集者变成了生产者，用磨制石器。原始社会也因此被称为石器时代。它的生产力状况是**十分低下**：劳动者劳动技能低下、劳动工具简陋、劳动对象范围有限。生产力决定生产关系，原始社会的生产关系可以概括为**“两共两平”**：**共同劳动、共同占有生产资料**，在生产中形成**平等互助**的关系，**平均分配**劳动产品。社会制度是**氏族制度**：按血缘关系结成的氏族是原始人共同生活的基本单位，氏族议事会由氏族全体成年人行使平等表决权，氏族长和军事首领由议事会选举产生，都没有任何特权，尧舜就是原始社会非常贤能的部落联盟首领。原始社会的解体过程是：生产工具改进推动生产力发展，几个人就能获取足够的食物，不用再依赖整个氏族，于是以氏族为单位的共同劳动被以家庭为单位的**个体劳动**取代，生产资料由氏族公有转变为家庭私有，土地变成私有财产就标志着**私有制确立**，贫富分化加剧，氏族成员地位越来越不平等，原始社会逐渐解体。关于私有制有三个观点要辨析：观点一“私有制的产生是社会生产力发展的结果，是不可避免的”是正确的，因为私有制属于生产关系，生产力决定生产关系；观点二“私有观念是人所固有的，所以私有制天然合理而且会永远存在”是错的，私有制不是天然就存在的，也不会永远存在；观点三“私有观念的存在是私有制产生的根本原因”也是错的，私有观念属于上层建筑，是私有制带来的结果而不是原因，准确的关系是生产力发展产生私有制，私有制下才逐渐产生私有观念。再讲奴隶社会。原始社会解体后出现了**奴隶主阶级和奴隶阶级**两大地位不同的集团，阶级就是在一定生产关系中处于不同地位的集团，奴隶社会的产生可以概括为生产力发展、私有制确立、再产生阶级。奴隶的来源有两个：一是部落征战中战争的俘虏沦为奴隶，二是无力偿还债务、债务人全家沦为奴隶。奴隶制生产关系的特点有三点：从所有制看，**奴隶主占有生产资料并完全占有奴隶**，古罗马把奴隶当作“会说话的工具”，可以随意转让、出售、赠送甚至杀害；从分配方式看，奴隶劳动的全部产品都归奴隶主占有和支配，奴隶主只给奴隶最低限度的生活资料；从人与人之间的关系看，奴隶毫无人生自由，是在奴隶主的强制下从事劳动。奴隶社会的主要矛盾就是**奴隶阶级和奴隶主阶级之间的矛盾**。奴隶主的残酷压迫必然引起奴隶反抗，奴隶主为维护本阶级利益建立了军队、监狱、法庭等暴力机关，于是国家就产生了，**国家是阶级矛盾不可调和的产物，是阶级统治的工具**，国家并不是从来就有的，我国历史上的第一个奴隶制国家是**夏**。对奴隶社会的评价要明确是**历史的进步**：奴隶社会取代原始社会后，金属工具广泛应用，奴隶社会也被称为**青铜时代**，三星堆遗址出土的青铜大立人、青铜太阳轮就反映出当时青铜器制作技艺的高超水平；城市开始出现，雅典、斯巴达都是奴隶社会繁荣城市的代表；出现了文字，殷墟的甲骨文证明当时已经有了文字记载，文字的出现就是人类进入文明时代的标志；还出现了脑力劳动和体力劳动的分工，有利于思想艺术的繁荣。所以奴隶制生产关系在当时还是促进了生产力的发展，使人类摆脱蒙昧野蛮的状态，迈入文明时代的门口。判断一种社会形态代替另一种社会形态究竟是历史的进步还是倒退，主要标志是看**生产关系是否适应生产力的发展**。当然也要一分为二地看：奴隶社会后期，奴隶和奴隶主的矛盾加剧，奴隶的反抗和逃亡使奴隶制严重阻碍了生产力的发展，所以它才会被封建社会取代。第一框第二幕从封建社会到资本主义社会，先讲封建社会的产生。奴隶社会后期出现了铁犁、牛耕等先进的生产工具，推动了生产力的发展，但奴隶制的生产关系下奴隶逃亡反抗越来越多，田地荒芜、城市萧条，阻碍了生产力发展，一些开明的奴隶主改变剥削方式，释放奴隶并把土地分成小块分给奴隶耕种、要求他们缴纳地租、承担劳役，公田变为私田，奴隶变成农民、奴隶主变成地主，产生了新的封建制生产关系，它能够适应并推动生产力的发展，所以封建社会的产生仍然是生产力发展的结果。封建制生产关系的特点有三点：地主占有绝大部分土地，农民有自己的劳动工具甚至少量土地；地主通过收取地租等方式占有农民大部分的劳动成果，农民的劳动成果除了缴纳地租还能留下一部分归自己支配；农民有了一定的人身自由。和奴隶相比，农民有了生产资料和一定的人身自由，能够自主劳动、具备生产积极性，进而促进社会生产的发展，所以封建制生产关系和奴隶制生产关系相比是一种进步。封建社会生产力的发展状况是：铁制农具被广泛使用和推广，封建社会也被称为**铁器时代**；耕作技术明显进步，如休耕轮作；水利事业有较大发展，如修建于四川的**都江堰**、秦朝修建的**灵渠**、陕西的**郑国渠**；手工业进一步发展，包括纺织业、陶瓷业、冶铸业；商业和城市逐渐发展起来，唐朝的长安城是当时世界上最大最繁华的国际大都市，长安的东市和西市商业贸易非常发达，我们今天口中的“买东西”就是由唐朝的东西两市得来的。但农民的处境仍然十分悲惨，唐诗“四海无闲田，农夫犹饿死”和杜甫的“朱门酒肉臭，路有冻死骨”都反映了这一点。农民这么惨，根本原因在于封建农业社会最重要的生产资料土地归地主所有，农民不得不依附于地主，所以**封建土地所有制是地主剥削农民的基础**，地主剥削农民的主要方式是**收取地租**，地租的形式包括劳役地租、实物地租和货币地租，此外还有高利贷、苛捐杂税和各种徭役。经济基础决定上层建筑，封建社会的上层建筑分两方面：政治上实行**君主专制、等级森严**，皇帝之下公侯伯子男从高到低排下来，这是封建社会的显著特征；思想上地主阶级鼓吹**君权神授**，把皇帝称为天子、认为是天命所归，提出三纲五常、“君教臣死，臣不得不死”等封建宗法思想和道德，传播封建迷信、钳制人民的思想。所以地主阶级的统治在经济上是剥削、在政治上是压迫、在思想上是钳制，农民面对这三重压迫，实行小规模的抗租抗税和大规模的农民起义或农民战争来反抗，秦朝的**陈胜吴广起义**、汉末的**黄巾起义**就是代表，封建社会的主要矛盾就是**农民阶级和地主阶级的矛盾**。再讲资本主义社会。封建社会后期，随着社会生产力和商品经济的发展，城市手工业者之间的竞争加剧，条件好的作坊主、商人和高利贷者成为早期的资本家，条件差的小生产者和作坊沦为雇佣工人，出现了资本家与工人之间的雇佣关系，典型表现有14世纪的佛罗伦萨手工工场、我国明朝时期苏州杭州的丝织业、四川的井盐业、江西景德镇的制瓷业，这都是资本主义生产关系萌芽的具体表现。封建社会以自然经济为基础，自给自足、男耕女织，不利于商品经济和生产力的发展，所以会被新的资本主义生产关系取代，资本主义的产生就是社会生产力和商品经济发展的结果。资本主义生产关系的特点也有三点：资本家占有一切生产资料；失去生产资料的劳动者不得不出卖自己的劳动力，受雇于资本家成为雇佣工人；资本家在生产过程中占有工人所创造的**剩余价值**。剩余价值是指由工人创造、但被资本家无偿占有的那一部分价值，课上的例子是：资本家给工人的日工资是100元，要求工人工作10个小时，但工人只用6小时就能够创造出100元的价值，剩下4小时创造出来的、被资本家无偿占有的部分就叫做剩余价值。不同于奴隶制和封建制赤裸裸的剥削，资本主义剥削的秘密是资本家购买工人的劳动力，而劳动力创造的价值远远超过资本家给付工人的工资，超过的部分就是剩余价值，这种占有是隐藏在生产过程当中的，是隐蔽的。资本主义生产关系的建立必须具备两个基本条件：一是有大批失去生产资料、有人身自由、能自由出卖劳动力的人，二是有开办资本主义企业所需要的大量货币当作资本，简单说就是要有人、有钱。这两个条件在历史上是西方资产阶级依靠暴力、通过掠夺形成的：英国爆发了被马克思称为“羊吃人”的**圈地运动**，资产阶级新贵族用篱笆、栅栏、壕沟把强占的农民土地圈起来变为私有的大型牧场，大量农民丧失土地和家园；新航路开辟后，西方资产阶级开始暴力掠夺、殖民扩张，把大量非洲黑人运到美洲贩卖，从中获取暴利。所以资本主义社会的形成过程中充满了侵略、征服、掠夺、残杀和奴役，马克思曾说“资本来到世间，从头到脚，每个毛孔都滴着血和肮脏的东西”。资产阶级革命是资本主义制度确立的开始标志。爆发的原因是资本主义生产的发展使新兴资产阶级在经济上有很大的优势，但封建制度的存在使这种优势难以发挥，只有推翻封建政权才能为发展资本主义扫清障碍，这里能明显看出经济基础决定上层建筑。革命的途径是新兴资产阶级和他们的思想家提出**自由、平等、博爱**的口号——这一思想是在欧洲的启蒙运动中提出来的，是资产阶级反封建的思想武器——利用劳动人民的力量，联合封建统治者的敌人、也就是大批农民和劳动人民，发动向封建地主阶级夺取政权的革命。最具代表性的是1644年的**英国资产阶级革命**和1789年的**法国大革命**，资产阶级革命的胜利标志着人类开始进入资本主义社会并确立资本主义制度。资本主义制度确立的意义是：为工业革命的发生提供了政治前提，推动了工业革命的发生和完成，第一次工业革命将人类带入**蒸汽时代**，第二次工业革命将人类带入**电气时代**，生产工具的革命性进步带来了资本主义社会生产力的巨大飞跃，也促进了人类思想的解放，使科学、教育、文化的发展达到了前所未有的高度。马克思在《共产党宣言》中说，资产阶级在它不到一百年的阶级统治中所创造的生产力，比过去一切世代所创造出来的生产力还要多、还要大。原因可以从两个阶级看：资本家为更大限度地追求利润、占有工人的剩余价值，起初采用延长工作时长等粗暴方式，引起工人反抗后就转变成更聪明也更隐性的做法，通过更新技术设备来提高生产率；工人方面，表面上看只要肯付出更多劳动、提高劳动技术水平和熟练程度，就可以拿到更多工资，所以也表现出了比较强烈的积极性。但资本主义发展到一定阶段就不可避免地爆发**经济危机**。经济危机带有明显的周期性，基本上每隔十年左右爆发一次，其中1929到1933年的经济危机最为严重。经济危机的基本特征是**生产相对过剩**，不是与劳动人民的实际需求相比的绝对过剩，而是相对于劳动人民有支付能力的需求来说社会生产的商品显得过剩：社会明明堆积了大量商品卖不出去，贫穷的劳动人民却又无力购买。课上讲了一个经典对话：被解雇的煤矿工人家庭，孩子问爸爸为什么家里这么冷，爸爸说因为家里没有煤了；为什么没有煤，因为我失业了、买不起煤了；为什么失业，因为煤太多了、卖不出去、工厂倒闭了。经济危机的表现是：大量商品卖不出去，生产资料被闲置，大批企业破产，大批工人失业，企业破产和工人失业又导致银行破产，信用关系被破坏，整个社会生活陷入混乱；一方面资本家把卖不出去的商品销毁，比如把牛奶倒进大海、把奶牛杀掉，另一方面失业的普通工人却不得不排队领取社会救助。经济危机爆发的原因分两层：直接原因是**生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小之间的矛盾**，是个别企业内部生产的有组织性与整个社会生产无政府状态之间的矛盾；根本原因在于**生产社会化与生产资料资本主义私人占有之间的矛盾**，这就是资本主义社会的**基本矛盾**。基本矛盾要这样理解：生产社会化也叫社会化大生产，是指由许多人共同使用生产资料、许多工序相互衔接、许多企业相互配合才能进行的生产，它要求生产资料由劳动者共同所有、生产过程按社会需要统一管理调节和控制、社会化产品由劳动者共同占有，但现实却是生产资料被资本家私人占有、生产过程由个别资本家受利益驱使来管理、产品被资本家以剩余价值的形式占有。生产社会化是生产力方面的表现，生产资料私人占有是生产关系上的表现，所以这一基本矛盾从实质上看仍然是**生产力与生产关系之间的矛盾**在资本主义社会中的体现。这一矛盾在经济上的表现就是无产阶级与资产阶级的对立，这也叫做资本主义社会的**主要矛盾**。基本矛盾是资本主义社会一切矛盾与冲突的总根源，贯穿于资本主义社会发展的始终，决定着资本主义的命运。资产阶级采取各种缓和阶级矛盾的措施，比如改善社会福利，但这些措施没有也不可能从根本上改变资本主义的私有制以及它的剥削关系，所以资本主义越发展，科学技术和社会生产力越进步，生产社会化的程度越高，生产资料和劳动产品就越是集中在极少数的资本家手里，基本矛盾的尖锐化就越来越不可避免，这也决定了**资本主义终将被社会主义取代**，虽然这是一个漫长的过程，但这是历史发展的必然趋势。第二框讲科学社会主义的理论与实践，先讲理论部分。科学社会主义产生的思想来源是**空想社会主义**，研究它有助于理清科学社会主义的来龙去脉。空想社会主义产生的背景是：资本主义社会发展中暴露出矛盾，资本家与工人斗争、资本家唯利是图、工人生活越发贫苦，一些先进分子认识到资本主义社会不是人类的理想社会，于是抨击资本主义、提出未来理想社会的构想。康帕内拉的《太阳城》描述了一个理想社会：每个人每天都要劳动，除了基本劳动之外都在做有趣又愉悦身心的体育活动，那里没有私有制，财产都是公有的，也没有贫富差别。空想社会主义的发展经历了三个阶段：第一阶段是16到17世纪末，代表人物有莫尔的《乌托邦》、闵采尔、康帕内拉的《太阳城》，主要思想是用文学的语言批判资本主义的灾难和罪恶，描述一个没有压迫、人人平等的理想社会，这些描述都十分感性；第二阶段是18世纪，代表人物和著作有摩莱里的《自然法典》、马布利的《论法制或法律的原则》，他们摆脱了早期纯粹虚构的幻想，从法律的角度批判资本主义的私有制，以法律条文的形式提出了人人平等、生产资料公有制等未来社会的基本原则，相比第一阶段有了明显进步；第三阶段是19世纪初，也是空想社会主义的最高阶段，代表人物有**圣西门、傅立叶、欧文**，他们在批判资本主义制度的同时对未来社会提出了很多积极的设想，并且已经开始了初步的制度创设和实践。空想社会主义的发展与资本主义社会的产生和发展息息相关：第一阶段资本主义生产处于简单协作阶段，第二阶段出现了工厂手工业，第三阶段已经开始了机器化大生产，资本主义越发展，资产阶级和工人阶级之间的矛盾越激化，空想社会主义的理论也就越来越进步、越来越接近科学的边缘。但即使到了最高阶段，他们的设想还是失败了：圣西门希望建立一种由实业家和学者领导的社会制度、即**实业制度**，采用说服的方法去实现，最终钱财都化光、理想也没有实现；傅立叶倡导建立**和谐制度**，在这一制度下人人劳动、男女平等，把目标实现寄希望于富翁出资，结果没有任何一个富翁肯支持他；欧文自己出资在美国买下一块地进行**新和谐公社**的共产主义新村实验，已经开始着手实践了，但在当时的社会背景下也没办法持续维持下去。他们失败的原因在于：他们对无产阶级只是表示同情，看不到无产阶级自身是埋葬资本主义并实现社会主义的强大力量，把目标的达成寄希望于个别的资本家和富人，试图通过宣传、呼吁、感化、示范等方式实现未来的社会理想，要让资本家出钱去消灭资本主义社会显然行不通。空想社会主义的局限性有两点：第一，它仅仅从**理性、正义等原则**出发、也就是从道德的角度去揭露资本主义的弊端、设计未来社会的美好蓝图，并没有触及到资本主义社会的本质问题；第二，他们主张**阶级调和、反对阶级斗争**，看不到广大人民群众、特别是无产阶级的力量，没有找到消灭资本主义社会、建立新社会的强大力量，没有找到进行社会变革的正确途径，这些想法都过于天真和幼稚，因为无产阶级如果不进行阶级斗争，就绝不可能自然而然地进入未来的社会主义理想社会。但也不能站在今天的角度片面评价当时的思想，因为在当时工业革命尚未完成，资本主义的发展还不够充分，资本主义社会的矛盾并没有充分暴露出来，无产阶级也还没有形成一支独立的力量，所以那些空想社会主义者看不到他们的力量也是情有可原的。科学社会主义产生的历史前提是资本主义的发展和工人运动的兴起。法国里昂工人的第一次起义目的是提高工价、获取经济上的利益，这就是**经济斗争**；第二次起义除了经济上的要求之外还带有更鲜明的政治性质，提出了废除君主制、建立共和政体的口号，这属于**政治斗争**。无产阶级反对资产阶级的阶级斗争有三种基本形式：第一是经济斗争，目的是获得更高的工资、更好的待遇，但单纯的经济斗争不能够消灭资本主义制度，也不能从根本上改变无产阶级受剥削、被压迫的地位，即使胜利了最多也只是减弱了一些剥削；第二种是政治斗争，目的是推翻资产阶级反动统治、建立和巩固无产阶级政权，政治斗争才是最重要的、最具有决定性作用的斗争形式，因为无产阶级只有取得政权才能够获得经济上的解放，而夺取政权的武装斗争是政治斗争的最高方式；第三种是思想理论斗争，主要任务是向无产阶级和广大人民群众宣传革命思想。法国里昂工人能够通过起义与资本家斗争，说明当时的无产阶级队伍逐渐壮大，已经成为一种不可忽视的力量，同时期还发生了英国宪章运动和德国西里西亚纺织工人起义，他们合称为**欧洲三大工人运动**，这三大工人运动的发生标志着工人阶级开始作为独立的政治力量登上了历史舞台，开始联合起来反抗资产阶级的统治，并且将斗争的矛头指向了整个资产阶级和资本主义制度。但这三大工人运动都不约而同地失败了，原因是没有一个强而有力的政党去领导工人运动，最重要的是缺乏先进的、科学的理论来进行指导，在这种形势下科学社会主义思想也就应运而生了。科学社会主义的创立者是**马克思和恩格斯**，二人在早年就树立了为人类解放事业而奋斗的远大理想，积极参加工人运动，注重理论和实践相结合，不断探索资本主义的本质和规律。习近平在纪念马克思诞辰200周年大会上的重要讲话中高度肯定了马克思的贡献，称马克思是全世界无产阶级和劳动人民的革命导师，是马克思主义的主要创始人，至今仍然被公认为“千年第一思想家”。科学社会主义的创立离不开马克思一生中最重要的两大发现：**唯物史观和剩余价值学说**，这为科学社会主义的创立奠定了理论基石。先看唯物史观，它是科学社会主义的**哲学基础**。它是马克思和恩格斯通过研究社会历史、批判地吸收德国古典哲学中的合理成分、彻底摆脱唯心主义思想的束缚而创立的。德国古典哲学中，黑格尔的哲学思想简单概括为**唯心辩证法**，费尔巴哈的思想则是**形而上学唯物主义**，两个人的思想中都各有其合理性、又有其局限性，马克思批判地吸收了二者的合理成分，吸收了黑格尔的辩证法和费尔巴哈的唯物主义思想，站在了巨人的肩膀上，创立了辩证唯物主义和历史唯物主义，历史唯物主义就叫做唯物史观。在唯物史观之前是唯心史观，它从神的意志去解释历史，比如女娲补天、上帝造人，后来思想有了一定程度的进步，认为是某一个卓越的人物、英雄人物创造了历史、推动了历史向前发展，也叫做**英雄史观**，认为英雄造时势。而马克思的唯物史观透过表面现象看到，**物质资料的生产方式才是人类社会存在和发展的基础**，物质资料的生产方式其实就包括生产力和生产关系，所以人类社会的历史其实就是在生产力和生产关系的矛盾运动中不断前进的。在内容上，唯物史观揭示了人类社会发展的一般规律，也就是**生产关系必须要适应生产力发展状况的规律**，同时也认为并不是个别的英雄和领袖创造了历史，而是**人民群众**这一历史主体推动和创造了历史，在阶级社会中，整个社会的被压迫阶级只有通过阶级斗争的方式才能够推翻旧政权、建立新政权，所以也揭示了阶级斗争的巨大作用。再看剩余价值学说，它是科学社会主义的**经济学基础**。它是马克思通过剖析资本主义社会、批判继承英国古典政治经济学的思想成果而创立的，英国古典政治经济学的思想成果可以简单概括为**劳动决定价值**，马克思在这一基础上提出了劳动价值论，进而发现了在资本主义社会中工人劳动创造的价值远远高于资本家给付的工资，提出了剩余价值学说。在资本主义社会中，资产阶级凭借自己对生产资料的占有去无偿地获取工人的剩余价值，工人为了维持基本的生存不得不受雇于资本家、被资本家剥削，要改变这种状况，只有推翻资本主义的生产资料私有制以及维护这种生产关系的整个资产阶级政权。剩余价值学说从经济学的角度揭示了剩余价值的来源，揭示了资本家剥削工人、占有工人劳动的秘密，这种剥削是隐藏在生产过程中的；它也揭示了无产阶级与资产阶级在利益上的根本对立，找到了变革资本主义社会的坚定力量，这一力量指的就是**无产阶级**，为无产阶级的斗争指明了方向，也就是无产阶级必须要通过阶级斗争的方式去推翻资产阶级政权、建立无产阶级政权。唯物史观和剩余价值学说对于科学社会主义的诞生有重要意义：二者为科学社会主义的创立奠定了理论基石，使社会主义实现了**由空想到科学的伟大飞跃**。相比之前的空想社会主义者指望靠资本家大发善心、靠说服、搞共产主义实验等方式去实现理想社会，现在已经触及到了资本主义的本质问题，并且看到了无产阶级的强大力量，也找到了无产阶级要用革命斗争去实现社会发展的根本途径，所以说它克服了空想社会主义者的局限。在科学社会主义的形成中，除了以上两个重大发现之外，还有一个十分重要的事件，就是《共产党宣言》的发表，它标志着**科学社会主义的诞生**。《共产党宣言》的主要内容共三个部分：第一个部分揭示了一个规律，《共产党宣言》分析了资本主义生产方式的内在矛盾与人类社会的发展规律，科学论证了**资本主义必然灭亡、社会主义必然胜利**的历史必然性；第二个部分是对一个政党、也就是无产阶级政党做出了阐述，《共产党宣言》总结了工人运动的经验教训，第一次系统论述了无产阶级政党的性质、特点、任务、策略，阐明了建立无产阶级政党的必要性，其中性质是共产党是代表无产阶级的政党，是无产阶级中最有觉悟、最有战斗力的先进部队，是**无产阶级的先锋队**，特点是共产党除了代表整个无产阶级的根本利益之外没有自己的特殊利益，策略和任务是无产阶级只有在共产党的领导下才能有组织地进行斗争、团结绝大多数人，推翻资产阶级统治、建立无产阶级政权、继续发展社会生产力、使全体社会成员都能够实现全面发展、从而为建立共产主义新社会创造必要的条件；第三个部分阐述了一个目标，也就是未来共产主义社会的理想目标，《共产党宣言》指出，代替那存在着阶级和阶级对立的资产阶级旧社会的，将是这样一个联合体，在那里，**每个人的自由发展是一切人的自由发展的条件**。根据马克思的描述，未来的共产主义理想社会将是一个生产力高度发达、物质财富极大丰富、没有私有制、没有私有观念、一切劳动产品按需分配、全体社会成员具有超高的道德品质和觉悟的社会，到那个时候劳动已经不再是一种谋生手段，而已经上升为了**生活的第一需要**，人们可以实现自由而全面的发展。《共产党宣言》发表的意义是：它标志着科学社会主义的诞生；它的问世是人类思想史上的一个伟大事件，也是第一次全面系统阐述科学社会主义原理的伟大著作；它是一部科学洞见人类社会发展规律的经典著作，是一部充满斗争精神、批判精神、革命精神的经典著作，是一部秉持人民立场、为人民大众谋利益、为全人类谋解放的经典著作；在后面的历史发展中可以更好地指导工人运动，工人阶级从此就拥有了强大的思想武器。教材还讲了马克思主义的基本特征：第一，它是**科学的理论**，因为它正确地揭示了人类社会的发展规律；第二，它是**人民的理论**，第一次创立了人民实现自身解放的思想体系；第三，它是**实践的理论**，它指引着人民改造世界的行动；第四，它也是**不断发展着的、开放的理论**，始终站在时代的前沿。要注意区分：实现社会主义由空想到科学的伟大飞跃的是唯物史观和剩余价值学说，而《共产党宣言》提供的是根本指导、不是具体指导。第二框的实践部分讲社会主义从一国到多国的实践。首先是1871年，**巴黎公社**宣告成立，它是无产阶级夺取政权的第一次尝试，但仅仅存在了70天就被镇压而失败了。真正在实践上取得成功、建立社会主义政权的是1917年的**俄国十月革命**，在以列宁为代表的俄国布尔什维克党的领导下，俄国无产阶级通过革命斗争推翻了资产阶级统治、建立了无产阶级政权。十月革命有着非常重大的历史意义：它建立了**世界上第一个社会主义国家**，将马克思主义关于无产阶级革命的理论变成了现实，实现了社会主义**从理论到制度的伟大跨越**，开启了人类历史的新纪元，从此世界范围内开始有了全新的社会主义国家的存在。受到十月革命的影响，李大钊在一篇文章中写道：“试看将来的环球，必是赤旗的世界”，反映出当时的人们受到了极大的鼓舞和振奋。通过十月革命，俄国确立了社会主义的生产关系，具体内容是：从生产资料所有制上看，是**劳动者共同占有生产资料**；从人与人之间的关系上看，消灭了人剥削人的制度，人们在生产过程中建立起了互助合作的关系；从产品的分配方式上看，个人消费品实行的是**按劳分配**。然后社会主义出现了星星之火可以燎原的势头，在第二次世界大战之后，社会主义在世界范围内获得了巨大的发展，实现了从一国到多国的发展和跨越，并在全球范围内形成了与资本主义阵营相抗衡、相对峙的社会主义阵营，取得了历史性的飞跃。但是社会主义作为一个新事物，它的发展并不是一帆风顺的，二十世纪八十年代末九十年代初，随着**东欧巨变、苏联解体**，世界社会主义运动的发展出现了严重的曲折，社会主义在当时备受质疑。但是要清楚，这并不是马克思主义和科学社会主义的理论出现了错误，而是这些国家的现实做法背离了科学社会主义和马克思主义所导致的结果，这也并不意味着社会主义从此湮灭。把眼光聚焦于21世纪的中国，中国特色社会主义正是科学社会主义在中国的实践与发展，我们的社会主义道路使中国用短短70年的时间就走过了西方发达国家几百年的工业化和现代化历程，创立了**中国式现代化**道路，使我们国家迎来了从站起来、富起来再到强起来的伟大飞跃，在全球范围内也充分展示了社会主义制度的优越性，所以说科学社会主义在今天仍然焕发着强大的生命力，社会主义未来可期。", "vtech": [["国家产生别说反了", "看到国家起源题 → 记住链条：生产力发展→私有制出现→阶级产生→阶级矛盾不可调和时才出现国家；国家是阶级矛盾不可调和的产物、阶级统治的工具，不是从来就有的；我国第一个奴隶制国家是夏。"], ["剩余价值的数会算", "看到剩余价值题 → 记住算法：工人劳动创造的价值减去资本家给付的工资，超过的部分就是被无偿占有的剩余价值；课上例子：日工资100元、工作10小时，6小时就创造出100元，剩下4小时创造的就是剩余价值；剥削的秘密是隐藏在生产过程中的。"], ["经济危机的三层原因别混", "看到经济危机题 → 分三层：基本特征是生产相对过剩（相对于劳动人民有支付能力的需求而言，不是绝对过剩）；直接原因是生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小之间的矛盾；根本原因是资本主义社会的基本矛盾。"], ["空想与科学的分界线", "看到空想社会主义题 → 记住局限有两条：只从理性、正义等道德原则出发，没触及资本主义本质；主张阶级调和、反对阶级斗争，看不到无产阶级的力量；实现由空想到科学飞跃的是唯物史观和剩余价值学说，诞生标志是《共产党宣言》的发表——两者别张冠李戴。"]], "vgaokao": []}}, "pol_p002": {"name": "科学社会主义的理论与实践", "sec": 2, "secTitle": "第一课 社会主义从空想到科学、从理论到实践的发展", "page": 11, "desc": "空想社会主义的局限；《共产党宣言》与两大发现使社会主义由空想变科学；十月革命使科学理论变现实。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p001"], "next": ["pol_p003"], "content": {"intro": "社会主义先有「想」，后有「科学」。圣西门、傅立叶、欧文等**空想社会主义**者描绘了美好社会却找不到实现的路；马克思、恩格斯创立**唯物史观**和**剩余价值学说**，使社会主义从空想变为科学。==1848 年《共产党宣言》发表，标志着科学社会主义的诞生；1917 年十月革命则使科学理论第一次变成了现实。==", "learn": [{"h": "空想社会主义：贡献与局限", "p": "19 世纪初，**圣西门、傅立叶、欧文**揭露和批判资本主义的弊端，对未来社会作出了天才的设想，是科学社会主义的**思想来源**。但他们不懂得社会发展的客观规律，没有揭示资本主义必然灭亡的**经济根源**，没有找到实现理想的**阶级力量**（无产阶级）和正确途径，所以只能是空想。"}, {"h": "两大发现：从空想到科学", "p": "**唯物史观**揭示了人类社会发展的一般规律，揭示了人民群众是历史的创造者；**剩余价值学说**揭示了资本家剥削工人的秘密，揭示了无产阶级和资产阶级对立的经济根源。\\n\\n==两大发现使社会主义建立在科学基础之上，社会主义由此从空想变为科学。==1848 年 2 月《共产党宣言》发表，成为世界上第一个无产阶级政党的党纲，标志着科学社会主义的诞生。"}, {"h": "十月革命：从理论到现实", "p": "1917 年，在列宁领导下，俄国取得了**十月社会主义革命**的胜利，建立了世界上**第一个社会主义国家**，实现了社会主义从理想到现实、从理论到实践的伟大飞跃，开辟了人类历史新纪元。它沉重打击了帝国主义的统治，鼓舞了国际无产阶级革命运动和殖民地半殖民地的民族解放运动。"}, {"h": "科学社会主义在实践中发展", "p": "社会主义由一国到多国、由理想到现实，经历了波澜壮阔又曲折的历程。中国共产党把科学社会主义基本原则同本国具体实际、历史文化传统、时代要求紧密结合，不断推进马克思主义中国化时代化，创立了**中国特色社会主义**——这是科学社会主义在 21 世纪中国的生动实践。苏联解体、东欧剧变是社会主义发展进程中的曲折，但不改变历史前进的总趋势。"}], "pitfalls": ["把空想社会主义说成科学社会主义的理论基石——理论基石（理论基础）是唯物史观和剩余价值学说，空想社会主义只是思想来源。", "记错标志性事件：科学社会主义诞生的标志是《共产党宣言》发表（1848 年），不是巴黎公社，也不是十月革命。", "把十月革命的意义说成「建立了共产主义社会」——它建立的是社会主义国家，社会主义是共产主义的初级阶段。"], "basics": [{"q": "科学社会主义诞生的标志是（ ）", "opts": ["《资本论》出版", "《共产党宣言》发表", "巴黎公社成立", "十月革命胜利"], "ans": 1, "why": "1848 年《共产党宣言》发表，标志着科学社会主义的诞生，也是世界上第一个无产阶级政党党纲的问世。"}, {"q": "使社会主义从空想变为科学的两大理论基石是（ ）", "opts": ["辩证法和剩余价值学说", "唯物史观和剩余价值学说", "空想社会主义和唯物史观", "劳动价值论和唯物史观"], "ans": 1, "why": "唯物史观与剩余价值学说是科学社会主义的理论基石（教材原文亦称「两大发现」）。"}, {"q": "世界上第一个社会主义国家诞生于（ ）", "opts": ["1848 年法国二月革命", "1871 年巴黎公社", "1917 年俄国十月革命", "1949 年中华人民共和国成立"], "ans": 2, "why": "1917 年十月革命建立了世界上第一个社会主义国家，实现了社会主义从理论到现实的飞跃。"}], "apply": [{"q": "材料：傅立叶为自己的理想社会「法朗吉」苦苦等待赞助人十多年，每天中午准时回家等候，从未等到。欧文则倾尽家产在美国购买土地进行「新和谐」公社实验，几年后即告失败。两位空想社会主义者的失败共同说明，他们（ ）", "opts": ["对资本主义的批判不够尖锐", "没有找到实现社会主义的正确途径和依靠力量", "设计的社会制度不够美好", "缺乏个人奋斗精神"], "ans": 1, "why": "空想社会主义者的根本局限在于不懂得社会发展规律，没有找到变革社会的依靠力量（无产阶级）和正确途径，只能寄希望于个别人的善心与实验。"}, {"q": "材料：马克思在研究工厂制度时发现，工人一个工作日创造的价值中，有一部分被资本家无偿占有，这部分价值是理解资本主义剥削的关键。这一发现属于（ ）", "opts": ["唯物史观", "剩余价值学说", "空想社会主义", "历史唯物主义的阶级观点"], "ans": 1, "why": "剩余价值学说揭示了资本家剥削工人的秘密和无产阶级、资产阶级对立的经济根源；唯物史观揭示的是社会发展的一般规律。"}], "case": {"q": "材料：从圣西门的「实业制度」到傅立叶的「法朗吉」，再到欧文的「新和谐」公社，空想社会主义者提出了许多超越时代的社会构想，但无一实现；而马克思主义诞生后不到 70 年，社会主义就先后在多个国家成为现实。运用本框知识说明：为什么说科学社会主义实现了社会主义从空想到科学的飞跃？", "a": "空想社会主义只停留在对资本主义的伦理批判和对未来社会的描绘上，没有揭示资本主义必然灭亡的经济根源，没有找到建立新社会的依靠力量和正确途径。马克思、恩格斯站在无产阶级立场上创立了唯物史观和剩余价值学说，揭示了人类社会发展的一般规律和资本主义剥削的秘密，使社会主义建立在对客观规律认识的基础上，并指明无产阶级是埋葬资本主义、建设新社会的力量——社会主义由此从空想变为科学。"}, "advance": {"q": "有人说：「东欧剧变、苏联解体证明科学社会主义已经失败，历史终结于资本主义。」结合本课知识谈谈你的看法。", "a": "这一说法是错误的。第一，苏联解体、东欧剧变是社会主义在特定国家的挫折，有其复杂原因，但它改变不了资本主义必然被社会主义代替的历史总趋势。第二，社会主义在实践中发展本身就不是一帆风顺的，曲折与前进相伴是历史发展的常态。第三，中国特色社会主义的成功开创了科学社会主义的新境界，用事实证明了科学社会主义的强大生命力。判断一种学说是否「失败」，要看它揭示的规律是否客观、看它在实践中是否继续发展，而不是看一时的成败。", "kind": "self"}}, "video": {"bvid": "BV15M4m127aY", "p": 1, "t": "社会主义从空想到科学、从理论到实践的发展", "dur": "91:24", "from": "政治老师爱政治", "vtop": ["生产关系是否适应生产力的发展，是判断一种社会形态取代另一种社会形态是进步还是倒退的主要标志——奴隶社会取代原始社会就是历史的进步。", "资本主义社会的基本矛盾是生产社会化与生产资料资本主义私人占有之间的矛盾，它是经济危机爆发的根本原因，也是资本主义一切矛盾与冲突的总根源。", "科学社会主义诞生的标志是《共产党宣言》的发表；实现社会主义由空想到科学的伟大飞跃的，是唯物史观和剩余价值学说这两大理论基石。"], "vsum": "本课是必修一第一课，讲社会主义从空想到科学、从理论到实践的发展，分两框：第一框讲原始社会到奴隶社会、封建社会到资本主义社会，第二框讲科学社会主义的理论与实践。开场先点全书主题：这本书围绕**社会主义的发展**展开，共四课，第一课从整个人类社会发展历史的角度讲社会主义的由来，后面三课讲我们国家的社会主义。第一框第一幕从原始社会到奴隶社会，先讲原始社会。原始社会是人类社会的**最初阶段、最低阶段**，可以比喻为人类的**童年时期**，但这个童年十分漫长：**旧石器时代**是200到300万年至1万年前，人们靠采集天然食物为生，用打制石器；**新石器时代**是1万年前，出现了原始的畜牧业和农业，人们从食物的采集者变成了生产者，用磨制石器。原始社会也因此被称为石器时代。它的生产力状况是**十分低下**：劳动者劳动技能低下、劳动工具简陋、劳动对象范围有限。生产力决定生产关系，原始社会的生产关系可以概括为**“两共两平”**：**共同劳动、共同占有生产资料**，在生产中形成**平等互助**的关系，**平均分配**劳动产品。社会制度是**氏族制度**：按血缘关系结成的氏族是原始人共同生活的基本单位，氏族议事会由氏族全体成年人行使平等表决权，氏族长和军事首领由议事会选举产生，都没有任何特权，尧舜就是原始社会非常贤能的部落联盟首领。原始社会的解体过程是：生产工具改进推动生产力发展，几个人就能获取足够的食物，不用再依赖整个氏族，于是以氏族为单位的共同劳动被以家庭为单位的**个体劳动**取代，生产资料由氏族公有转变为家庭私有，土地变成私有财产就标志着**私有制确立**，贫富分化加剧，氏族成员地位越来越不平等，原始社会逐渐解体。关于私有制有三个观点要辨析：观点一“私有制的产生是社会生产力发展的结果，是不可避免的”是正确的，因为私有制属于生产关系，生产力决定生产关系；观点二“私有观念是人所固有的，所以私有制天然合理而且会永远存在”是错的，私有制不是天然就存在的，也不会永远存在；观点三“私有观念的存在是私有制产生的根本原因”也是错的，私有观念属于上层建筑，是私有制带来的结果而不是原因，准确的关系是生产力发展产生私有制，私有制下才逐渐产生私有观念。再讲奴隶社会。原始社会解体后出现了**奴隶主阶级和奴隶阶级**两大地位不同的集团，阶级就是在一定生产关系中处于不同地位的集团，奴隶社会的产生可以概括为生产力发展、私有制确立、再产生阶级。奴隶的来源有两个：一是部落征战中战争的俘虏沦为奴隶，二是无力偿还债务、债务人全家沦为奴隶。奴隶制生产关系的特点有三点：从所有制看，**奴隶主占有生产资料并完全占有奴隶**，古罗马把奴隶当作“会说话的工具”，可以随意转让、出售、赠送甚至杀害；从分配方式看，奴隶劳动的全部产品都归奴隶主占有和支配，奴隶主只给奴隶最低限度的生活资料；从人与人之间的关系看，奴隶毫无人生自由，是在奴隶主的强制下从事劳动。奴隶社会的主要矛盾就是**奴隶阶级和奴隶主阶级之间的矛盾**。奴隶主的残酷压迫必然引起奴隶反抗，奴隶主为维护本阶级利益建立了军队、监狱、法庭等暴力机关，于是国家就产生了，**国家是阶级矛盾不可调和的产物，是阶级统治的工具**，国家并不是从来就有的，我国历史上的第一个奴隶制国家是**夏**。对奴隶社会的评价要明确是**历史的进步**：奴隶社会取代原始社会后，金属工具广泛应用，奴隶社会也被称为**青铜时代**，三星堆遗址出土的青铜大立人、青铜太阳轮就反映出当时青铜器制作技艺的高超水平；城市开始出现，雅典、斯巴达都是奴隶社会繁荣城市的代表；出现了文字，殷墟的甲骨文证明当时已经有了文字记载，文字的出现就是人类进入文明时代的标志；还出现了脑力劳动和体力劳动的分工，有利于思想艺术的繁荣。所以奴隶制生产关系在当时还是促进了生产力的发展，使人类摆脱蒙昧野蛮的状态，迈入文明时代的门口。判断一种社会形态代替另一种社会形态究竟是历史的进步还是倒退，主要标志是看**生产关系是否适应生产力的发展**。当然也要一分为二地看：奴隶社会后期，奴隶和奴隶主的矛盾加剧，奴隶的反抗和逃亡使奴隶制严重阻碍了生产力的发展，所以它才会被封建社会取代。第一框第二幕从封建社会到资本主义社会，先讲封建社会的产生。奴隶社会后期出现了铁犁、牛耕等先进的生产工具，推动了生产力的发展，但奴隶制的生产关系下奴隶逃亡反抗越来越多，田地荒芜、城市萧条，阻碍了生产力发展，一些开明的奴隶主改变剥削方式，释放奴隶并把土地分成小块分给奴隶耕种、要求他们缴纳地租、承担劳役，公田变为私田，奴隶变成农民、奴隶主变成地主，产生了新的封建制生产关系，它能够适应并推动生产力的发展，所以封建社会的产生仍然是生产力发展的结果。封建制生产关系的特点有三点：地主占有绝大部分土地，农民有自己的劳动工具甚至少量土地；地主通过收取地租等方式占有农民大部分的劳动成果，农民的劳动成果除了缴纳地租还能留下一部分归自己支配；农民有了一定的人身自由。和奴隶相比，农民有了生产资料和一定的人身自由，能够自主劳动、具备生产积极性，进而促进社会生产的发展，所以封建制生产关系和奴隶制生产关系相比是一种进步。封建社会生产力的发展状况是：铁制农具被广泛使用和推广，封建社会也被称为**铁器时代**；耕作技术明显进步，如休耕轮作；水利事业有较大发展，如修建于四川的**都江堰**、秦朝修建的**灵渠**、陕西的**郑国渠**；手工业进一步发展，包括纺织业、陶瓷业、冶铸业；商业和城市逐渐发展起来，唐朝的长安城是当时世界上最大最繁华的国际大都市，长安的东市和西市商业贸易非常发达，我们今天口中的“买东西”就是由唐朝的东西两市得来的。但农民的处境仍然十分悲惨，唐诗“四海无闲田，农夫犹饿死”和杜甫的“朱门酒肉臭，路有冻死骨”都反映了这一点。农民这么惨，根本原因在于封建农业社会最重要的生产资料土地归地主所有，农民不得不依附于地主，所以**封建土地所有制是地主剥削农民的基础**，地主剥削农民的主要方式是**收取地租**，地租的形式包括劳役地租、实物地租和货币地租，此外还有高利贷、苛捐杂税和各种徭役。经济基础决定上层建筑，封建社会的上层建筑分两方面：政治上实行**君主专制、等级森严**，皇帝之下公侯伯子男从高到低排下来，这是封建社会的显著特征；思想上地主阶级鼓吹**君权神授**，把皇帝称为天子、认为是天命所归，提出三纲五常、“君教臣死，臣不得不死”等封建宗法思想和道德，传播封建迷信、钳制人民的思想。所以地主阶级的统治在经济上是剥削、在政治上是压迫、在思想上是钳制，农民面对这三重压迫，实行小规模的抗租抗税和大规模的农民起义或农民战争来反抗，秦朝的**陈胜吴广起义**、汉末的**黄巾起义**就是代表，封建社会的主要矛盾就是**农民阶级和地主阶级的矛盾**。再讲资本主义社会。封建社会后期，随着社会生产力和商品经济的发展，城市手工业者之间的竞争加剧，条件好的作坊主、商人和高利贷者成为早期的资本家，条件差的小生产者和作坊沦为雇佣工人，出现了资本家与工人之间的雇佣关系，典型表现有14世纪的佛罗伦萨手工工场、我国明朝时期苏州杭州的丝织业、四川的井盐业、江西景德镇的制瓷业，这都是资本主义生产关系萌芽的具体表现。封建社会以自然经济为基础，自给自足、男耕女织，不利于商品经济和生产力的发展，所以会被新的资本主义生产关系取代，资本主义的产生就是社会生产力和商品经济发展的结果。资本主义生产关系的特点也有三点：资本家占有一切生产资料；失去生产资料的劳动者不得不出卖自己的劳动力，受雇于资本家成为雇佣工人；资本家在生产过程中占有工人所创造的**剩余价值**。剩余价值是指由工人创造、但被资本家无偿占有的那一部分价值，课上的例子是：资本家给工人的日工资是100元，要求工人工作10个小时，但工人只用6小时就能够创造出100元的价值，剩下4小时创造出来的、被资本家无偿占有的部分就叫做剩余价值。不同于奴隶制和封建制赤裸裸的剥削，资本主义剥削的秘密是资本家购买工人的劳动力，而劳动力创造的价值远远超过资本家给付工人的工资，超过的部分就是剩余价值，这种占有是隐藏在生产过程当中的，是隐蔽的。资本主义生产关系的建立必须具备两个基本条件：一是有大批失去生产资料、有人身自由、能自由出卖劳动力的人，二是有开办资本主义企业所需要的大量货币当作资本，简单说就是要有人、有钱。这两个条件在历史上是西方资产阶级依靠暴力、通过掠夺形成的：英国爆发了被马克思称为“羊吃人”的**圈地运动**，资产阶级新贵族用篱笆、栅栏、壕沟把强占的农民土地圈起来变为私有的大型牧场，大量农民丧失土地和家园；新航路开辟后，西方资产阶级开始暴力掠夺、殖民扩张，把大量非洲黑人运到美洲贩卖，从中获取暴利。所以资本主义社会的形成过程中充满了侵略、征服、掠夺、残杀和奴役，马克思曾说“资本来到世间，从头到脚，每个毛孔都滴着血和肮脏的东西”。资产阶级革命是资本主义制度确立的开始标志。爆发的原因是资本主义生产的发展使新兴资产阶级在经济上有很大的优势，但封建制度的存在使这种优势难以发挥，只有推翻封建政权才能为发展资本主义扫清障碍，这里能明显看出经济基础决定上层建筑。革命的途径是新兴资产阶级和他们的思想家提出**自由、平等、博爱**的口号——这一思想是在欧洲的启蒙运动中提出来的，是资产阶级反封建的思想武器——利用劳动人民的力量，联合封建统治者的敌人、也就是大批农民和劳动人民，发动向封建地主阶级夺取政权的革命。最具代表性的是1644年的**英国资产阶级革命**和1789年的**法国大革命**，资产阶级革命的胜利标志着人类开始进入资本主义社会并确立资本主义制度。资本主义制度确立的意义是：为工业革命的发生提供了政治前提，推动了工业革命的发生和完成，第一次工业革命将人类带入**蒸汽时代**，第二次工业革命将人类带入**电气时代**，生产工具的革命性进步带来了资本主义社会生产力的巨大飞跃，也促进了人类思想的解放，使科学、教育、文化的发展达到了前所未有的高度。马克思在《共产党宣言》中说，资产阶级在它不到一百年的阶级统治中所创造的生产力，比过去一切世代所创造出来的生产力还要多、还要大。原因可以从两个阶级看：资本家为更大限度地追求利润、占有工人的剩余价值，起初采用延长工作时长等粗暴方式，引起工人反抗后就转变成更聪明也更隐性的做法，通过更新技术设备来提高生产率；工人方面，表面上看只要肯付出更多劳动、提高劳动技术水平和熟练程度，就可以拿到更多工资，所以也表现出了比较强烈的积极性。但资本主义发展到一定阶段就不可避免地爆发**经济危机**。经济危机带有明显的周期性，基本上每隔十年左右爆发一次，其中1929到1933年的经济危机最为严重。经济危机的基本特征是**生产相对过剩**，不是与劳动人民的实际需求相比的绝对过剩，而是相对于劳动人民有支付能力的需求来说社会生产的商品显得过剩：社会明明堆积了大量商品卖不出去，贫穷的劳动人民却又无力购买。课上讲了一个经典对话：被解雇的煤矿工人家庭，孩子问爸爸为什么家里这么冷，爸爸说因为家里没有煤了；为什么没有煤，因为我失业了、买不起煤了；为什么失业，因为煤太多了、卖不出去、工厂倒闭了。经济危机的表现是：大量商品卖不出去，生产资料被闲置，大批企业破产，大批工人失业，企业破产和工人失业又导致银行破产，信用关系被破坏，整个社会生活陷入混乱；一方面资本家把卖不出去的商品销毁，比如把牛奶倒进大海、把奶牛杀掉，另一方面失业的普通工人却不得不排队领取社会救助。经济危机爆发的原因分两层：直接原因是**生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小之间的矛盾**，是个别企业内部生产的有组织性与整个社会生产无政府状态之间的矛盾；根本原因在于**生产社会化与生产资料资本主义私人占有之间的矛盾**，这就是资本主义社会的**基本矛盾**。基本矛盾要这样理解：生产社会化也叫社会化大生产，是指由许多人共同使用生产资料、许多工序相互衔接、许多企业相互配合才能进行的生产，它要求生产资料由劳动者共同所有、生产过程按社会需要统一管理调节和控制、社会化产品由劳动者共同占有，但现实却是生产资料被资本家私人占有、生产过程由个别资本家受利益驱使来管理、产品被资本家以剩余价值的形式占有。生产社会化是生产力方面的表现，生产资料私人占有是生产关系上的表现，所以这一基本矛盾从实质上看仍然是**生产力与生产关系之间的矛盾**在资本主义社会中的体现。这一矛盾在经济上的表现就是无产阶级与资产阶级的对立，这也叫做资本主义社会的**主要矛盾**。基本矛盾是资本主义社会一切矛盾与冲突的总根源，贯穿于资本主义社会发展的始终，决定着资本主义的命运。资产阶级采取各种缓和阶级矛盾的措施，比如改善社会福利，但这些措施没有也不可能从根本上改变资本主义的私有制以及它的剥削关系，所以资本主义越发展，科学技术和社会生产力越进步，生产社会化的程度越高，生产资料和劳动产品就越是集中在极少数的资本家手里，基本矛盾的尖锐化就越来越不可避免，这也决定了**资本主义终将被社会主义取代**，虽然这是一个漫长的过程，但这是历史发展的必然趋势。第二框讲科学社会主义的理论与实践，先讲理论部分。科学社会主义产生的思想来源是**空想社会主义**，研究它有助于理清科学社会主义的来龙去脉。空想社会主义产生的背景是：资本主义社会发展中暴露出矛盾，资本家与工人斗争、资本家唯利是图、工人生活越发贫苦，一些先进分子认识到资本主义社会不是人类的理想社会，于是抨击资本主义、提出未来理想社会的构想。康帕内拉的《太阳城》描述了一个理想社会：每个人每天都要劳动，除了基本劳动之外都在做有趣又愉悦身心的体育活动，那里没有私有制，财产都是公有的，也没有贫富差别。空想社会主义的发展经历了三个阶段：第一阶段是16到17世纪末，代表人物有莫尔的《乌托邦》、闵采尔、康帕内拉的《太阳城》，主要思想是用文学的语言批判资本主义的灾难和罪恶，描述一个没有压迫、人人平等的理想社会，这些描述都十分感性；第二阶段是18世纪，代表人物和著作有摩莱里的《自然法典》、马布利的《论法制或法律的原则》，他们摆脱了早期纯粹虚构的幻想，从法律的角度批判资本主义的私有制，以法律条文的形式提出了人人平等、生产资料公有制等未来社会的基本原则，相比第一阶段有了明显进步；第三阶段是19世纪初，也是空想社会主义的最高阶段，代表人物有**圣西门、傅立叶、欧文**，他们在批判资本主义制度的同时对未来社会提出了很多积极的设想，并且已经开始了初步的制度创设和实践。空想社会主义的发展与资本主义社会的产生和发展息息相关：第一阶段资本主义生产处于简单协作阶段，第二阶段出现了工厂手工业，第三阶段已经开始了机器化大生产，资本主义越发展，资产阶级和工人阶级之间的矛盾越激化，空想社会主义的理论也就越来越进步、越来越接近科学的边缘。但即使到了最高阶段，他们的设想还是失败了：圣西门希望建立一种由实业家和学者领导的社会制度、即**实业制度**，采用说服的方法去实现，最终钱财都化光、理想也没有实现；傅立叶倡导建立**和谐制度**，在这一制度下人人劳动、男女平等，把目标实现寄希望于富翁出资，结果没有任何一个富翁肯支持他；欧文自己出资在美国买下一块地进行**新和谐公社**的共产主义新村实验，已经开始着手实践了，但在当时的社会背景下也没办法持续维持下去。他们失败的原因在于：他们对无产阶级只是表示同情，看不到无产阶级自身是埋葬资本主义并实现社会主义的强大力量，把目标的达成寄希望于个别的资本家和富人，试图通过宣传、呼吁、感化、示范等方式实现未来的社会理想，要让资本家出钱去消灭资本主义社会显然行不通。空想社会主义的局限性有两点：第一，它仅仅从**理性、正义等原则**出发、也就是从道德的角度去揭露资本主义的弊端、设计未来社会的美好蓝图，并没有触及到资本主义社会的本质问题；第二，他们主张**阶级调和、反对阶级斗争**，看不到广大人民群众、特别是无产阶级的力量，没有找到消灭资本主义社会、建立新社会的强大力量，没有找到进行社会变革的正确途径，这些想法都过于天真和幼稚，因为无产阶级如果不进行阶级斗争，就绝不可能自然而然地进入未来的社会主义理想社会。但也不能站在今天的角度片面评价当时的思想，因为在当时工业革命尚未完成，资本主义的发展还不够充分，资本主义社会的矛盾并没有充分暴露出来，无产阶级也还没有形成一支独立的力量，所以那些空想社会主义者看不到他们的力量也是情有可原的。科学社会主义产生的历史前提是资本主义的发展和工人运动的兴起。法国里昂工人的第一次起义目的是提高工价、获取经济上的利益，这就是**经济斗争**；第二次起义除了经济上的要求之外还带有更鲜明的政治性质，提出了废除君主制、建立共和政体的口号，这属于**政治斗争**。无产阶级反对资产阶级的阶级斗争有三种基本形式：第一是经济斗争，目的是获得更高的工资、更好的待遇，但单纯的经济斗争不能够消灭资本主义制度，也不能从根本上改变无产阶级受剥削、被压迫的地位，即使胜利了最多也只是减弱了一些剥削；第二种是政治斗争，目的是推翻资产阶级反动统治、建立和巩固无产阶级政权，政治斗争才是最重要的、最具有决定性作用的斗争形式，因为无产阶级只有取得政权才能够获得经济上的解放，而夺取政权的武装斗争是政治斗争的最高方式；第三种是思想理论斗争，主要任务是向无产阶级和广大人民群众宣传革命思想。法国里昂工人能够通过起义与资本家斗争，说明当时的无产阶级队伍逐渐壮大，已经成为一种不可忽视的力量，同时期还发生了英国宪章运动和德国西里西亚纺织工人起义，他们合称为**欧洲三大工人运动**，这三大工人运动的发生标志着工人阶级开始作为独立的政治力量登上了历史舞台，开始联合起来反抗资产阶级的统治，并且将斗争的矛头指向了整个资产阶级和资本主义制度。但这三大工人运动都不约而同地失败了，原因是没有一个强而有力的政党去领导工人运动，最重要的是缺乏先进的、科学的理论来进行指导，在这种形势下科学社会主义思想也就应运而生了。科学社会主义的创立者是**马克思和恩格斯**，二人在早年就树立了为人类解放事业而奋斗的远大理想，积极参加工人运动，注重理论和实践相结合，不断探索资本主义的本质和规律。习近平在纪念马克思诞辰200周年大会上的重要讲话中高度肯定了马克思的贡献，称马克思是全世界无产阶级和劳动人民的革命导师，是马克思主义的主要创始人，至今仍然被公认为“千年第一思想家”。科学社会主义的创立离不开马克思一生中最重要的两大发现：**唯物史观和剩余价值学说**，这为科学社会主义的创立奠定了理论基石。先看唯物史观，它是科学社会主义的**哲学基础**。它是马克思和恩格斯通过研究社会历史、批判地吸收德国古典哲学中的合理成分、彻底摆脱唯心主义思想的束缚而创立的。德国古典哲学中，黑格尔的哲学思想简单概括为**唯心辩证法**，费尔巴哈的思想则是**形而上学唯物主义**，两个人的思想中都各有其合理性、又有其局限性，马克思批判地吸收了二者的合理成分，吸收了黑格尔的辩证法和费尔巴哈的唯物主义思想，站在了巨人的肩膀上，创立了辩证唯物主义和历史唯物主义，历史唯物主义就叫做唯物史观。在唯物史观之前是唯心史观，它从神的意志去解释历史，比如女娲补天、上帝造人，后来思想有了一定程度的进步，认为是某一个卓越的人物、英雄人物创造了历史、推动了历史向前发展，也叫做**英雄史观**，认为英雄造时势。而马克思的唯物史观透过表面现象看到，**物质资料的生产方式才是人类社会存在和发展的基础**，物质资料的生产方式其实就包括生产力和生产关系，所以人类社会的历史其实就是在生产力和生产关系的矛盾运动中不断前进的。在内容上，唯物史观揭示了人类社会发展的一般规律，也就是**生产关系必须要适应生产力发展状况的规律**，同时也认为并不是个别的英雄和领袖创造了历史，而是**人民群众**这一历史主体推动和创造了历史，在阶级社会中，整个社会的被压迫阶级只有通过阶级斗争的方式才能够推翻旧政权、建立新政权，所以也揭示了阶级斗争的巨大作用。再看剩余价值学说，它是科学社会主义的**经济学基础**。它是马克思通过剖析资本主义社会、批判继承英国古典政治经济学的思想成果而创立的，英国古典政治经济学的思想成果可以简单概括为**劳动决定价值**，马克思在这一基础上提出了劳动价值论，进而发现了在资本主义社会中工人劳动创造的价值远远高于资本家给付的工资，提出了剩余价值学说。在资本主义社会中，资产阶级凭借自己对生产资料的占有去无偿地获取工人的剩余价值，工人为了维持基本的生存不得不受雇于资本家、被资本家剥削，要改变这种状况，只有推翻资本主义的生产资料私有制以及维护这种生产关系的整个资产阶级政权。剩余价值学说从经济学的角度揭示了剩余价值的来源，揭示了资本家剥削工人、占有工人劳动的秘密，这种剥削是隐藏在生产过程中的；它也揭示了无产阶级与资产阶级在利益上的根本对立，找到了变革资本主义社会的坚定力量，这一力量指的就是**无产阶级**，为无产阶级的斗争指明了方向，也就是无产阶级必须要通过阶级斗争的方式去推翻资产阶级政权、建立无产阶级政权。唯物史观和剩余价值学说对于科学社会主义的诞生有重要意义：二者为科学社会主义的创立奠定了理论基石，使社会主义实现了**由空想到科学的伟大飞跃**。相比之前的空想社会主义者指望靠资本家大发善心、靠说服、搞共产主义实验等方式去实现理想社会，现在已经触及到了资本主义的本质问题，并且看到了无产阶级的强大力量，也找到了无产阶级要用革命斗争去实现社会发展的根本途径，所以说它克服了空想社会主义者的局限。在科学社会主义的形成中，除了以上两个重大发现之外，还有一个十分重要的事件，就是《共产党宣言》的发表，它标志着**科学社会主义的诞生**。《共产党宣言》的主要内容共三个部分：第一个部分揭示了一个规律，《共产党宣言》分析了资本主义生产方式的内在矛盾与人类社会的发展规律，科学论证了**资本主义必然灭亡、社会主义必然胜利**的历史必然性；第二个部分是对一个政党、也就是无产阶级政党做出了阐述，《共产党宣言》总结了工人运动的经验教训，第一次系统论述了无产阶级政党的性质、特点、任务、策略，阐明了建立无产阶级政党的必要性，其中性质是共产党是代表无产阶级的政党，是无产阶级中最有觉悟、最有战斗力的先进部队，是**无产阶级的先锋队**，特点是共产党除了代表整个无产阶级的根本利益之外没有自己的特殊利益，策略和任务是无产阶级只有在共产党的领导下才能有组织地进行斗争、团结绝大多数人，推翻资产阶级统治、建立无产阶级政权、继续发展社会生产力、使全体社会成员都能够实现全面发展、从而为建立共产主义新社会创造必要的条件；第三个部分阐述了一个目标，也就是未来共产主义社会的理想目标，《共产党宣言》指出，代替那存在着阶级和阶级对立的资产阶级旧社会的，将是这样一个联合体，在那里，**每个人的自由发展是一切人的自由发展的条件**。根据马克思的描述，未来的共产主义理想社会将是一个生产力高度发达、物质财富极大丰富、没有私有制、没有私有观念、一切劳动产品按需分配、全体社会成员具有超高的道德品质和觉悟的社会，到那个时候劳动已经不再是一种谋生手段，而已经上升为了**生活的第一需要**，人们可以实现自由而全面的发展。《共产党宣言》发表的意义是：它标志着科学社会主义的诞生；它的问世是人类思想史上的一个伟大事件，也是第一次全面系统阐述科学社会主义原理的伟大著作；它是一部科学洞见人类社会发展规律的经典著作，是一部充满斗争精神、批判精神、革命精神的经典著作，是一部秉持人民立场、为人民大众谋利益、为全人类谋解放的经典著作；在后面的历史发展中可以更好地指导工人运动，工人阶级从此就拥有了强大的思想武器。教材还讲了马克思主义的基本特征：第一，它是**科学的理论**，因为它正确地揭示了人类社会的发展规律；第二，它是**人民的理论**，第一次创立了人民实现自身解放的思想体系；第三，它是**实践的理论**，它指引着人民改造世界的行动；第四，它也是**不断发展着的、开放的理论**，始终站在时代的前沿。要注意区分：实现社会主义由空想到科学的伟大飞跃的是唯物史观和剩余价值学说，而《共产党宣言》提供的是根本指导、不是具体指导。第二框的实践部分讲社会主义从一国到多国的实践。首先是1871年，**巴黎公社**宣告成立，它是无产阶级夺取政权的第一次尝试，但仅仅存在了70天就被镇压而失败了。真正在实践上取得成功、建立社会主义政权的是1917年的**俄国十月革命**，在以列宁为代表的俄国布尔什维克党的领导下，俄国无产阶级通过革命斗争推翻了资产阶级统治、建立了无产阶级政权。十月革命有着非常重大的历史意义：它建立了**世界上第一个社会主义国家**，将马克思主义关于无产阶级革命的理论变成了现实，实现了社会主义**从理论到制度的伟大跨越**，开启了人类历史的新纪元，从此世界范围内开始有了全新的社会主义国家的存在。受到十月革命的影响，李大钊在一篇文章中写道：“试看将来的环球，必是赤旗的世界”，反映出当时的人们受到了极大的鼓舞和振奋。通过十月革命，俄国确立了社会主义的生产关系，具体内容是：从生产资料所有制上看，是**劳动者共同占有生产资料**；从人与人之间的关系上看，消灭了人剥削人的制度，人们在生产过程中建立起了互助合作的关系；从产品的分配方式上看，个人消费品实行的是**按劳分配**。然后社会主义出现了星星之火可以燎原的势头，在第二次世界大战之后，社会主义在世界范围内获得了巨大的发展，实现了从一国到多国的发展和跨越，并在全球范围内形成了与资本主义阵营相抗衡、相对峙的社会主义阵营，取得了历史性的飞跃。但是社会主义作为一个新事物，它的发展并不是一帆风顺的，二十世纪八十年代末九十年代初，随着**东欧巨变、苏联解体**，世界社会主义运动的发展出现了严重的曲折，社会主义在当时备受质疑。但是要清楚，这并不是马克思主义和科学社会主义的理论出现了错误，而是这些国家的现实做法背离了科学社会主义和马克思主义所导致的结果，这也并不意味着社会主义从此湮灭。把眼光聚焦于21世纪的中国，中国特色社会主义正是科学社会主义在中国的实践与发展，我们的社会主义道路使中国用短短70年的时间就走过了西方发达国家几百年的工业化和现代化历程，创立了**中国式现代化**道路，使我们国家迎来了从站起来、富起来再到强起来的伟大飞跃，在全球范围内也充分展示了社会主义制度的优越性，所以说科学社会主义在今天仍然焕发着强大的生命力，社会主义未来可期。", "vtech": [["国家产生别说反了", "看到国家起源题 → 记住链条：生产力发展→私有制出现→阶级产生→阶级矛盾不可调和时才出现国家；国家是阶级矛盾不可调和的产物、阶级统治的工具，不是从来就有的；我国第一个奴隶制国家是夏。"], ["剩余价值的数会算", "看到剩余价值题 → 记住算法：工人劳动创造的价值减去资本家给付的工资，超过的部分就是被无偿占有的剩余价值；课上例子：日工资100元、工作10小时，6小时就创造出100元，剩下4小时创造的就是剩余价值；剥削的秘密是隐藏在生产过程中的。"], ["经济危机的三层原因别混", "看到经济危机题 → 分三层：基本特征是生产相对过剩（相对于劳动人民有支付能力的需求而言，不是绝对过剩）；直接原因是生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小之间的矛盾；根本原因是资本主义社会的基本矛盾。"], ["空想与科学的分界线", "看到空想社会主义题 → 记住局限有两条：只从理性、正义等道德原则出发，没触及资本主义本质；主张阶级调和、反对阶级斗争，看不到无产阶级的力量；实现由空想到科学飞跃的是唯物史观和剩余价值学说，诞生标志是《共产党宣言》的发表——两者别张冠李戴。"]], "vgaokao": []}}, "pol_p003": {"name": "新民主主义革命的胜利", "sec": 3, "secTitle": "第二课 只有社会主义才能救中国", "page": 20, "desc": "旧路走不通→中国共产党诞生→农村包围城市道路→新中国成立及其伟大意义。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p002"], "next": ["pol_p004"], "content": {"intro": "近代中国的大门被列强轰开后，各阶级、各阶层轮番寻找出路，却都失败了。直到**中国共产党**诞生，中国革命的面貌才焕然一新。==1949 年新中国成立，结束了半殖民地半封建社会的历史，中国人民从此站立起来了。==", "learn": [{"h": "探索为什么接连失败", "p": "近代中国沦为**半殖民地半封建社会**，民族独立、人民解放成为两大历史任务。农民阶级（太平天国、义和团）、地主阶级洋务派、资产阶级维新派和革命派先后探索，但都没有改变中国半殖民地半封建社会的性质和人民的悲惨命运。原因在于：没有先进理论指导、没有找到依靠力量、没有触及或无力触及社会根本问题。"}, {"h": "中国共产党的诞生", "p": "五四运动促进了马克思主义在中国的传播，促进了它与中国工人运动的结合。1921 年，**中国共产党**成立——这是中国历史上**开天辟地的大事变**。自从有了中国共产党，中国革命就有了坚强的领导核心，中国人民就有了可以信赖的组织者和领导者，中国革命的面貌就焕然一新。"}, {"h": "走对路：农村包围城市", "p": "**新民主主义革命**是无产阶级领导的、人民大众的、反对帝国主义、封建主义和官僚资本主义的革命。中国半殖民地半封建的社会性质决定了革命不能照抄俄国「中心城市暴动」的道路，党把马克思主义基本原理同中国革命具体实际相结合，开辟了**农村包围城市、武装夺取政权**的正确道路，经过长期浴血奋战，取得新民主主义革命的胜利。"}, {"h": "新中国成立的伟大意义", "p": "1949 年中华人民共和国成立：结束了帝国主义、封建主义和官僚资本主义在中国的统治，结束了中国一百多年被侵略被奴役的屈辱历史和战乱频仍、四分五裂的局面；新中国的成立，**壮大了世界和平、民主和社会主义的力量**。占人类总数四分之一的中国人民从此站立起来了，中国历史进入新纪元。"}], "pitfalls": ["把辛亥革命的评价说反：它结束了封建帝制、传播了民主共和观念，但没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的任务。", "把新民主主义革命的对象漏掉官僚资本主义——对象是帝国主义、封建主义和官僚资本主义三座大山。", "把「站起来」归到社会主义改造——站起来对应 1949 年新中国成立。"], "basics": [{"q": "中国共产党的诞生被称作「开天辟地的大事变」，是因为自从有了中国共产党（ ）", "opts": ["中国立即进入了社会主义社会", "中国革命有了坚强的领导核心，中国革命面貌焕然一新", "封建帝制被彻底推翻", "帝国主义退出了中国"], "ans": 1, "why": "党的诞生使中国革命有了坚强的领导核心和科学的指导思想，中国革命的面貌从此焕然一新；当时中国并未进入社会主义社会。"}, {"q": "新民主主义革命的领导阶级是（ ）", "opts": ["资产阶级", "农民阶级", "无产阶级", "民族资产阶级"], "ans": 2, "why": "新民主主义革命是无产阶级领导的、人民大众的、反对帝国主义、封建主义和官僚资本主义的革命——领导阶级是判断「新」旧民主主义革命的关键。"}, {"q": "中国革命走农村包围城市、武装夺取政权道路的依据是（ ）", "opts": ["照搬俄国十月革命的经验", "中国半殖民地半封建的社会性质和革命形势", "农村自然条件优越", "国际共产主义运动的统一部署"], "ans": 1, "why": "敌强我弱、城市统治力量强大而农村统治薄弱的社会性质与形势，决定了这条道路；它是中国共产党把基本原理同具体实际相结合的创造。"}], "apply": [{"q": "材料：从洋务运动的「自强求富」，到戊戌变法的改良图强，再到辛亥革命推翻帝制，近代中国的探索一轮接一轮，却始终没有实现民族独立和人民解放。这段历史说明（ ）", "opts": ["中国人民缺乏斗争精神", "没有先进政党和科学理论的领导，探索难以成功", "民族独立只能依靠外国援助", "改良道路比革命道路更适合中国"], "ans": 1, "why": "各阶级、各阶层的探索都因阶级的局限性而失败；中国革命的成功，必须有无产阶级政党的领导和科学理论的指导，这是历史得出的结论。"}, {"q": "材料：1949 年 10 月 1 日，毛泽东在天安门城楼上向全世界庄严宣告中华人民共和国中央人民政府成立。消息传到海外，不少华侨说：「腰杆终于挺直了。」中国人民的这种感受，源于新中国的成立（ ）", "opts": ["实现了社会主义现代化", "确立了社会主义基本制度", "结束了被侵略被奴役的屈辱历史，中国人民从此站立起来了", "完成了社会主义改造"], "ans": 2, "why": "新中国成立结束了一百多年被侵略被奴役的屈辱历史；社会主义基本制度的确立是 1956 年的事，不要张冠李戴。"}], "case": {"q": "材料：1927 年大革命失败后，党内有人主张照搬俄国经验、组织城市武装暴动，结果接连受挫；毛泽东则带领部队走向井冈山，在农村建立革命根据地，逐步形成「星星之火，可以燎原」的局面。运用本框知识，谈谈中国共产党开辟农村包围城市道路给我们的启示。", "a": "第一，教条主义行不通：别国经验只能借鉴，不能照抄，中国革命必须从中国的具体国情出发。第二，马克思主义基本原理必须同中国具体实际相结合，这是党取得胜利的根本经验。第三，道路的选择要由社会性质和力量对比决定：敌人统治力量集中于城市、农村相对薄弱，决定了先农村后城市的战略。启示落到今天，就是坚持实事求是，一切从实际出发。"}, "advance": {"q": "辨析：新民主主义革命胜利靠的是运气，没有必然性。", "a": "错误。新民主主义革命的胜利有其深刻的必然性：半殖民地半封建社会的主要矛盾决定了反帝反封建的历史任务；中国共产党的诞生使革命有了坚强的领导核心和科学理论指导；党开辟了符合中国国情的正确道路，并最广泛地动员和组织了人民群众。历史条件与主观努力相结合，胜利是各种因素共同作用的必然结果，绝非偶然。", "kind": "self"}}, "video": {"bvid": "BV1Cr421T75t", "p": 1, "t": "只有社会主义才能救中国", "dur": "47:16", "from": "政治老师爱政治", "vtop": ["资本主义道路在中国行不通：帝国主义不允许、封建势力不愿意、民族资产阶级没能力——三句话记牢行不通的原因。", "新民主主义革命的“新”在三处：无产阶级领导、前途是建立无产阶级领导下的各革命阶级联合专政并过渡到社会主义、属于世界无产阶级革命的一部分。", "过渡时期总路线是“一化三改”：逐步实现国家社会主义工业化，逐步实现对农业、手工业和资本主义工商业的社会主义改造；1956 年三大改造完成，社会主义制度基本确立。"], "vsum": "本课讲第二课**只有社会主义才能救中国**，分两框：第一框新民主主义革命的胜利，时间段是 **1840 年到 1949 年**；第二框社会主义制度在中国的确立，对应社会主义革命时期，也叫过渡时期，时间段是 **1949 年到 1956 年**，之后 1956 年到 1978 年是社会主义建设的艰辛探索。先看近代中国的社会性质：进入近代以来，西方国家通过资产阶级革命和工业革命进入资本主义社会、生产力大发展并对外殖民扩张，而中国因清王朝长期闭关锁国、政治腐败而贫穷落后，沦为**半殖民地半封建社会**：**1840 年第一次鸦片战争**后中国逐渐开始沦为半殖民地半封建社会，**1856 年第二次鸦片战争**后半殖民地化程度进一步加深，**1894 年中日甲午战争**后大大加深，**1900—1901 年八国联军侵华、签订《辛丑条约》**后中国完全沦为半殖民地半封建社会。**半殖民地**指形式上独立、但政治经济文化各方面都受到外国资本主义控制和压迫、丧失了部分主权，当时中国内部有许多外国租界、被称为“国中之国”，如厦门鼓浪屿英租界、哈尔滨俄租界（1907 年起修建索菲亚大教堂）；**半封建**指原有封建属性遭到破坏、资本主义有了一定发展，但封建剥削制度仍占主导地位。易错提醒：不能简单粗暴地理解为政治上半殖民地、经济上半封建。沦为半殖民地半封建社会的原因分内外两面：外部是西方列强入侵，中国深受**帝国主义、封建主义和官僚资本主义**三重压迫；内部是封建制度落后加上长期闭关锁国，使中国在经济政治文化各方面都落后了。由此得出近代中国人民的两大历史任务：**争取民族独立、人民解放**，**实现国家富强、人民幸福**——其中国家富强、人民幸福是民族独立、人民解放的目的，而民族独立、人民解放又是实现国家富强、人民幸福的前提；当时的主要矛盾是**帝国主义与中华民族、封建主义与人民大众的矛盾**。面对内忧外患，无数仁人志士艰苦探索救亡图存之路：**太平天国运动**是农民阶级发起的反封建反侵略起义，**洋务运动**是地主阶级洋务派发起的封建统治者自救运动，**戊戌变法**是资产阶级性质的改良运动，**义和团运动**是农民阶级提出“扶清灭洋”口号的反帝爱国运动，**清末新政**是以慈禧太后为代表的封建统治阶级为延续统治、巩固皇权而进行的改革运动，**辛亥革命**是资产阶级发起的、为推翻清朝专制、建立共和政体的资产阶级民主革命；辛亥革命后中国还尝试过君主立宪制、帝制复辟、议会制、多党制、总统制等各种形式，结果无一例外全部失败，告诉我们**在半殖民地半封建的近代中国，资本主义道路是走不通的**，必须另辟新路。为什么行不通，由近代中国的基本国情决定，分三点：**帝国主义不允许**——帝国主义入侵中国的目的是把中国变成殖民地或半殖民地、维护在华特权，绝不允许中国走资本主义道路强大起来成为竞争对手；**封建势力不愿意**——中国封建势力同帝国主义相勾结，严重阻碍民族资本主义经济发展；**民族资产阶级没能力**——中国民族资产阶级力量十分弱小，又与封建主义和外国资本主义有着千丝万缕的联系，具有软弱性和妥协性，不能承担领导中国人民完成反帝反封建民主革命的使命和任务。正当寻找救国救民的道路屡遭挫折时，**俄国十月革命一声炮响，给中国送来了马克思列宁主义**，中国先进分子从中看到了解决中国问题的新出路，开始接受并传播马克思列宁主义，进入胜利的征程——新民主主义革命时期。新民主主义革命的指导思想是**马克思列宁主义**；开始的标志是 **1919 年五四运动**：中国作为一战战胜国在巴黎和会上受到帝国主义不公正对待，软弱的北洋政府卖国求荣、要把德国在山东的权力拱手让给日本，1919 年 5 月 4 日北京爆发声势浩大的五四运动，喊出“**外争主权，内除国贼**”、拒绝在巴黎和约上签字、废除二十一条、还我青岛、打倒卖国贼等口号。“外争主权”是反对帝国主义的不公正对待，“内除国贼”是反抗卖国求荣的封建北洋政府，所以五四运动是中国人民彻底反抗帝国主义和封建主义的爱国运动，具有彻底反帝反封建的革命性、追求救国强国真理的进步性，又以青年学生为先锋、各族各界群众积极参与，具有广泛性；每年 5 月 4 日设为**五四青年节**。五四运动为中国共产党的成立做了思想上和干部上的准备：思想上促进了马克思列宁主义在中国的传播，干部上初步掌握马列主义的先进分子到工人群众中做宣传和组织工作，实现先进知识分子与工人运动的结合；五四运动在近代以来中华民族追求民族独立和发展进步的历史进程中具有里程碑意义，是**旧民主主义革命走向新民主主义革命的转折点**。1921 年，在马列主义同中国工人运动相结合的过程中，**中国共产党应运而生**，从此中国人民谋求民族独立、人民解放、实现国家富强、人民幸福的斗争有了主心骨，中国共产党成为新民主主义革命的领导力量。此后中国共产党带领中国各族人民经过 28 年浴血奋战，经历**大革命、土地革命战争、抗日战争、解放战争**四个阶段，终于在 1949 年夺取新民主主义革命的伟大胜利、建立中华人民共和国。革命斗争中总结出战胜敌人的**三大法宝：统一战线、武装斗争、党的建设**——统一战线是因为当时中国革命的敌人太强大，单凭无产阶级一个阶级的力量不够，必须组织革命的统一战线，农民是工人阶级的同盟军，还可以联合城市小资产阶级和民族资产阶级，发动群众、团结一切可以团结的力量；武装斗争即“枪杆子里出政权”，是中国共产党从大革命失败的血的教训中得出的宝贵经验，新民主主义革命的特点就是长期的武装斗争、以武装的革命反对武装的反革命，统一战线和武装斗争是战胜敌人的两个基本武器；党的建设方面，只有把党建设好才能更好地领导中国革命走向胜利，1941 年抗日战争时期开始的**延安整风运动**就是中国共产党历史上第一次大规模的整风运动，目的是进行马克思列宁主义教育、提高全党的马列主义水平、纠正党内的错误思想；三大法宝是毛泽东对中国新民主主义革命经验的基本总结。新民主主义革命的性质是**无产阶级领导的、以工农联盟为基础的、人民大众的、反对帝国主义、封建主义和官僚资本主义的民主革命**，其中领导阶级是无产阶级，阶级基础是工农联盟，主体是人民大众，革命任务是反对帝国主义、封建主义和官僚资本主义这三座大山。新民主主义革命与旧民主主义革命相比，“新”在三处：领导权上，新民主主义革命的领导者是无产阶级，旧民主主义革命的领导者是资产阶级；革命前途上，新民主主义革命要建立**无产阶级领导下的各革命阶级的联合专政**并最终过渡到社会主义社会，旧民主主义革命要建立资产阶级共和国和资本主义制度；革命所属范畴上，新民主主义革命属于世界无产阶级革命的一部分，旧民主主义革命属于世界资产阶级革命的一部分。根据革命前途，中国革命必须分两个步骤：第一步是民主革命，改变半殖民地半封建的社会形态，使中国社会变成一个独立的民主主义的社会；第二步是社会主义革命，建设社会主义社会；**新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主义革命的必然趋势**，只有完成前一个革命才能完成后一个革命，两个革命阶段必须相互衔接。1949 年新中国成立，第一步就此完成，也标志着新民主主义革命的胜利。新中国成立的意义可概括为“辞旧”与“迎新”：“辞旧”是指它彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了极少数剥削者统治广大劳动人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，实现了中国从几千年封建专制政治向人民民主的伟大飞跃；“迎新”是指新中国的成立为实现由新民主主义向社会主义的过渡创造了条件，从根本上改变了中国社会的发展方向，为实现国家富强、民族复兴展示了美好前景和现实道路；对外看，新中国的诞生是 20 世纪的伟大历史事件，它在人口约占世界四分之一、领土面积世界第三的中国建立起人民民主制度并逐步建立起社会主义制度，从而大大加强了世界和平民主和社会主义阵营的力量，改变了二战之后国际冷战格局中的力量对比，冲破了帝国主义的东方战线，极大地改变了世界政治力量对比，鼓舞和推动了世界被压迫民族和被压迫人民争取解放的斗争。在新民主主义革命实践中，中国共产党人把马克思列宁主义基本原理同中国革命具体实际相结合，开辟了**农村包围城市、武装夺取政权的正确革命道路**，创立了**毛泽东思想**，这是新民主主义革命中形成的重大理论成果，为夺取新民主主义革命胜利指明正确方向；毛泽东思想也是**马克思主义中国化的第一次伟大飞跃**。第二框讲社会主义制度在中国的确立。新中国成立后并没有马上进入社会主义社会，还要继续通过 1949 年到 1956 年的社会主义改造，完成中国革命的第二步——社会主义革命、建立社会主义社会；1949 年新中国成立到 1956 年三大改造完成这段时期，就是从新民主主义向社会主义的**过渡时期**。建国之初形势十分严峻：农业工业都非常落后，人口素质比较低，教育水平也很低，环境条件也非常恶劣，而且国民党还留下贫穷落后、千疮百孔的烂摊子，撤退时掠夺大量财富、炸毁桥梁矿井等基础设施。在这样的背景下，中国共产党提出过渡时期的总路线和总任务：**要在一个相当长的时期内，逐步实现国家的社会主义工业化，并逐步实现国家对农业、手工业和资本主义工商业的社会主义改造**，简单概括为“**一化三改**”。其中“一化”是由新中国建立之初国家贫穷、工业基础十分薄弱的现状决定的，当时新中国与西方发达国家差距十分大，毛主席曾说：“我们现在能造什么？我们能造桌子椅子，能造茶碗茶壶，但一辆汽车、一架飞机、一辆坦克、一辆拖拉机都造不出来。”“三改”是对农业、手工业和资本主义工商业进行社会主义改造：改造之前这些都属于生产资料私有制，对农业和手工业实行类似生产合作社的改造方式，使之变成社会主义集体所有制，对资本主义工商业实行公私合营的方式，使之变成社会主义公有制，总之就是把生产资料私有制转变为公有制。“一化”是在解放和发展社会生产力，“三改”是在调整生产关系，目的是使生产资料的社会主义公有制占主体地位、成为国家唯一的经济基础。党在过渡时期的总路线和总任务的提出，是根据马克思列宁主义理论、并依据新中国成立之后政治经济条件的新变化作出的重大决策，符合新中国社会发展的实际和规律，反映了从新民主主义向社会主义过渡的历史必然性，具体有四方面：第一，社会主义国营经济迅速发展，逐步成为社会经济中的主导性因素——1949 到 1952 年，国家剥夺国民党四大家族官僚资本归人民国家所有，并采用多种形式接收英美等国在华企业，加上各种措施恢复国民经济，使公有制经济在国民经济中迅速占据绝对优势，为从新民主主义向社会主义过渡提供了重要物质基础；第二，国家积累了利用、限制和管理私营工商业的经验，不同程度地开始了对他们的初步社会主义改造——国家在合理调整工商业的过程中创造了**加工订货、经销代销、统购包销、公司合营**等一系列从低级到高级的国家资本主义形式，使之逐步接受国家的监督和管理，同时 1952 年开展**五反运动**，即反行贿、反偷税漏税、反盗骗国家财产、反偷工减料、反盗窃国家经济情报，打击当时一些不法资本家的“五毒”行为，对工商业者进行守法经营的教育，推动私营企业建立工人监督制度和实行民主改革；第三，个体农业经济难以适应国家工业化建设的新形势，迫切需要组织起来——分散落后的小农经济很难使用大机器、无力抵御自然灾害、不利于生产力发展，如果不把农民组织起来，不仅不能改善农民生活，也不可能为工业发展提供必要的商品粮食原材料等条件，只有农业集体化、规模化才有可能实现社会主义工业化；工业化初期往往采用用农业支持工业的方针，工业化达到相当程度时工业就要反过来反哺农业；具体操作上当时通过互助组、农业合作社的方式把农民组织起来；第四，国际形势有利于中国加快向社会主义阵营转变——二战之后世界两大阵营对抗，以美国为代表的西方国家在外交、经济、军事等领域对中国严密封锁，只有苏联等社会主义国家支持中国，所以新中国在对外关系上实行向社会主义国家“一边倒”的方针，1950 年签订**《中苏友好互助同盟条约》**，苏联对华提供三亿美元贷款和一批工业援助项目，有利于新政权在国际社会上站稳脚跟。这四个方面决定了从新民主主义向社会主义过渡具有历史必然性。1956 年社会主义改造完成，有十分重大的意义：第一，标志着中国实现了从新民主主义向社会主义的转变，从此进入社会主义社会——这里要明确 1840 年以来中国社会性质的变化：1840 年鸦片战争爆发到 1949 年新中国成立属于半殖民地半封建社会，1949 年到 1956 年三大改造期间属于新民主主义性质的社会，1956 年社会主义改造完成之后才真正进入社会主义社会；第二，中国共产党在一个经济文化落后的东方大国创造性地开辟了一条适合中国特点的社会主义改造道路，顺利实现了对生产资料私有制的社会主义改造——对农业和手工业实行从小到大、从低级到高级的改造方式，对资本主义工商业创造性地实行加工订货、统购包销、经销代销、公司合营等形式，都顺利实现了由生产资料私有制向社会主义公有制的转变；第三，在中国建立起了社会主义制度，完成了**中华民族有史以来最为广泛而深刻的社会变革**；第四，社会主义改造的伟大胜利极大地激发了广大人民群众建设社会主义的积极性，社会生产力有了比较迅速的发展，社会秩序更加稳定，人民民主专政更加巩固，从而为我国全面建设社会主义奠定了坚实基础。社会主义改造完成、确立社会主义基本制度、进入社会主义社会之后，就迎来了新的历史时期——**社会主义建设时期（1956—1978 年）**。如何建设社会主义、如何巩固和发展社会主义，是一个崭新的历史课题，没有现成的答案和经验可以遵循；面对新情况新问题，中国共产党以马克思列宁主义基本原理为指导，以苏联的经验教训为借鉴，结合中国具体实际，开始探索适合中国国情的社会主义建设道路，这就是马克思列宁主义原理同中国具体实际的**第二次结合**（第一次结合是与新民主主义革命时期的具体实际相结合，第二次结合则是与社会主义革命和建设时期的具体实际相结合）。在这样的背景下，**1956 年 9 月中共八大召开**，这是新中国成立以来中国共产党召开的第一次全国代表大会；中共八大最重要的贡献是正确分析了国内形势和国内主要矛盾的变化，明确提出了党和全国人民在新形势下的主要任务，为社会主义事业的发展指明了方向。关于主要矛盾，党的八大指出，社会主义改造完成之后，我国的主要矛盾已经不再是无产阶级同资产阶级之间的阶级矛盾，而是**人民对建立先进的工业国的要求同落后的农业国的现实之间的矛盾**，是**人民对于经济文化迅速发展的需要同当前经济文化不能满足人们需要的状况之间的矛盾**；因此主要任务就是**集中力量发展社会生产力，尽快把我国从落后的农业国变为先进的工业国**。在正确方向指引下，我国在社会主义建设时期取得了巨大成就：工业方面建立起独立的、比较完整的工业体系和国民经济体系，50 年代中央集中力量建设鞍钢，其钢铁产量一度占据全国半壁江山、被誉为钢铁行业的“共和国长子”，1956 年在长春第一汽车制造厂诞生了新中国第一辆解放牌汽车；农业方面，党带领农民克服各种困难，大规模建设农业基础设施，兴修了红旗渠等一大批防洪灌溉工程设施，改善农业生产条件，粮食产量有了较大增长，初步满足了占世界四分之一人口的基本生活需求；基础设施方面，建筑、交通运输等获得较快发展，1957 年被誉为“万里长江第一桥”的**武汉长江大桥**正式通车、“天堑变通途”，它是当时我国自行设计建造的最长的铁路公路两用桥，70 年代中国第一条电气化铁路**宝成铁路**正式通车；科教方面，科技发展取得重大突破，教育医疗事业也得到长足发展，1964 年我国成功爆炸第一颗原子弹、打破超级大国核垄断，教育方面保障人民群众受教育的权利，开展大规模扫盲和工农干部文化补习教育，逐渐形成比较完整的国民教育体系；人们的精神面貌也得到极大改变，广大人民群众意气风发、斗志昂扬，面对巨大困难和压力坚持独立自主、自力更生，团结一致、艰苦奋斗，培育和发扬了“**两弹一星**”精神、**大庆精神**等；对外看，中国成为世界上有重要影响的大国，70 年代外交方面取得很多成就：中日建交、中美建交、中国在联合国的合法席位得以恢复。这些成就雄辩地证明了社会主义道路是正确的、只有社会主义才能救中国。但是由于国际局势复杂多变、国内建设任务艰巨繁重，再加上缺乏领导社会主义建设的现成经验，我们在取得伟大成就的同时也犯了错误、经历了曲折：1958 年的**大跃进运动**在发展生产上急于求成，导致出现浮夸风、“放卫星”的严重错误；大跃进过程中又发生**人民公社化运动**，在生产关系上过度、片面地追求“**一大二公**”，使生产力遭到严重破坏；并且在阶级斗争问题上犯了绝对化、扩大化的错误，导致发生“**文化大革命**”这样的十年内乱；所以社会主义建设的探索过程是成就与曲折并存的。这些探索的意义有四方面：第一，得出一个重要结论——我国社会发生翻天覆地的变化，雄辩地证明了**只有社会主义才能救中国**；第二，一个伟大飞跃——新民主主义革命的胜利、中华人民共和国的诞生、社会主义制度的确立和社会主义建设的全面展开，实现了中华民族从“**东亚病夫**”到**站起来的伟大飞跃**；第三，从毛泽东思想的角度看，把马克思列宁主义基本原理同中国社会主义革命和建设时期的具体实际进行了第二次结合，丰富和发展了毛泽东思想，是**马克思主义中国化时代化的第一次历史性飞跃**；第四，承上启下——党在社会主义革命和建设中取得的独创性理论成果和巨大成就，为新的历史时期、也就是改革开放时期开创中国特色社会主义提供了宝贵经验、理论准备和物质基础。习近平总书记在纪念毛泽东同志诞辰 120 周年座谈会的讲话中指出，在中国这样的社会历史条件下，建设社会主义没有先例，犹如攀登一座人迹罕至的高山，一切攀登者都要披荆斩棘开通道路；事物发展的道路是曲折的、迂回的，但前途是光明的，历史总是在向前发展的；总结和吸取历史教训，目的就是以此为鉴、更好地前进。课中穿插的几道练习题，讲题时都是逐个选项对照着讲、对在哪里、错在哪里，考的也都是上面这些点。", "vtech": [["资本主义道路行不通：三句话对应三方", "看到问为什么行不通 → 先对号：帝国主义不允许（怕中国强大起来成为竞争对手）、封建势力不愿意（勾结帝国主义、阻碍民族资本主义发展）、民族资产阶级没能力（力量弱小、软弱性妥协性）；三方缺一不可，别只答一条。"], ["新民主主义革命的“新”：三处对比", "看到新旧对比题 → 抓三处：领导权（无产阶级 vs 资产阶级）、前途（无产阶级领导下的各革命阶级联合专政并过渡到社会主义 vs 资产阶级共和国和资本主义制度）、范畴（世界无产阶级革命的一部分 vs 世界资产阶级革命的一部分）。"], ["社会性质三段别串：1840–1949、1949–1956、1956 之后", "看到社会性质判断题 → 先定时间：1840 年鸦片战争到 1949 年新中国成立是半殖民地半封建社会；1949–1956 年三大改造期间是新民主主义性质的社会；1956 年社会主义改造完成之后才真正进入社会主义社会。"], ["“一化三改”与中共八大主要矛盾", "看到过渡时期总路线 → 默念“一化三改”：逐步实现国家社会主义工业化，逐步实现对农业、手工业和资本主义工商业的社会主义改造；看到中共八大 → 主要矛盾已变：不再是无产阶级同资产阶级之间的阶级矛盾，而是人民对建立先进工业国的要求同落后的农业国现实之间的矛盾，主要任务是集中力量发展社会生产力。"]], "vgaokao": []}}, "pol_p004": {"name": "社会主义制度在中国的确立", "sec": 4, "secTitle": "第二课 只有社会主义才能救中国", "page": 25, "desc": "过渡时期总路线「一化三改」；1956 年改造基本完成，社会主义基本制度确立。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p003"], "next": ["pol_p005"], "content": {"intro": "新中国成立后，中国还没有建立起社会主义制度，摆在党面前的任务是把新民主主义社会转变为社会主义社会。党提出**过渡时期总路线**，用「**一化三改**」完成了这场深刻变革。==1956 年底，社会主义改造基本完成，社会主义基本制度在我国确立起来。==", "learn": [{"h": "过渡时期总路线：一化三改", "p": "从中华人民共和国成立到社会主义改造基本完成，是一个过渡时期。党在这个过渡时期的总路线和总任务，是要在一个相当长的时期内，逐步实现国家的**社会主义工业化**（「一化」，主体），并逐步实现国家对**农业、手工业和资本主义工商业的社会主义改造**（「三改」，两翼）。一化与三改相互联系、相互促进。"}, {"h": "三改是怎样改的", "p": "对农业、手工业，走**合作化**道路，引导个体农民、个体手工业者走集体化道路；对资本主义工商业，通过**和平赎买**等方式进行社会主义改造，创造了委托加工、经销代销、公私合营等适合中国特点的过渡形式。改造把生产资料私有制变为社会主义公有制，把剥削者改造成自食其力的劳动者。"}, {"h": "1956 年：社会主义制度确立", "p": "到 1956 年底，我国绝大部分地区基本上完成了对生产资料私有制的社会主义改造，**社会主义公有制**已成为我国的经济基础，**社会主义基本制度**确立，我国进入了**社会主义社会**。这是中国历史上**最深刻最伟大的社会变革**，为当代中国一切发展进步奠定了根本政治前提和制度基础。"}, {"h": "探索起步：成就与曲折", "p": "社会主义制度确立后，党开始探索适合中国国情的社会主义建设道路，取得了工业、交通、科技等领域的重大成就，建立起独立的比较完整的工业体系和国民经济体系。探索中也经历了严重曲折，但成就始终是主要的，曲折为后来的开拓提供了宝贵经验和理论准备——评价这一时期要用「两个不能否定」的态度：改革开放前和改革开放后两个历史时期本质上都是党领导人民进行社会主义建设的实践探索，不能相互否定。"}], "pitfalls": ["把「一化三改」的三改说成对农业、工业、商业的改造——三改是农业、手工业、资本主义工商业；工业化是「一化」，不是改造对象。", "认为 1949 年新中国一成立就进入了社会主义社会——1949—1956 年是新民主主义社会向社会主义社会过渡的时期。", "对资本主义工商业改造的方式说成没收——创造性地实行了和平赎买。"], "basics": [{"q": "过渡时期总路线的主体是（ ）", "opts": ["对农业的社会主义改造", "逐步实现国家的社会主义工业化", "土地改革", "恢复国民经济"], "ans": 1, "why": "「一化三改」中，「一化」（社会主义工业化）是主体，「三改」是两翼。"}, {"q": "我国社会主义基本制度确立的标志是（ ）", "opts": ["1949 年新中国成立", "1954 年第一部宪法颁布", "1956 年社会主义改造基本完成", "1978 年十一届三中全会召开"], "ans": 2, "why": "1956 年底三大改造基本完成，社会主义公有制成为经济基础，社会主义基本制度确立，我国进入社会主义社会。"}, {"q": "我国对资本主义工商业进行社会主义改造的独特创造是（ ）", "opts": ["没收官僚资本", "和平赎买", "合作化道路", "没收地主土地"], "ans": 1, "why": "和平赎买是我国社会主义改造的创造性举措，把民族资本家改造成自食其力的劳动者；合作化是农业、手工业改造的道路。"}], "apply": [{"q": "材料：1953—1956 年，上海一些私营工厂先接受国家委托加工、订货，继而实行个别企业的公私合营，最后全行业公私合营；原厂主按股分红、领取定息，并被安排参加企业经营管理或政治学习。这一过程体现了（ ）", "opts": ["国家对资本主义工商业的暴力没收", "我国社会主义改造形式的多样性和创造性", "资本主义经济被完全保留", "私营经济成为国民经济主体"], "ans": 1, "why": "从委托加工到公私合营的渐进形式、赎买政策与团结改造并举，体现了社会主义改造从中国实际出发的创造性；改造完成后公有制成为经济基础。"}, {"q": "材料：1957 年，我国钢产量达到 535 万吨，比 1949 年增长约 33 倍；大庆油田、万吨水压机等重大成果相继出现。这些成就取得的制度前提是（ ）", "opts": ["改革开放政策的全面推行", "社会主义基本制度的确立", "社会主义市场经济体制的建立", "加入世界贸易组织"], "ans": 1, "why": "社会主义基本制度的确立为集中力量办大事、进行大规模社会主义建设奠定了根本政治前提和制度基础；其余选项的时间都晚于这一时期。"}], "case": {"q": "材料：新中国成立之初，我国还是一个落后的农业国，连火柴、铁钉都要靠进口，被称为「洋火」「洋钉」。到 1956 年，工业在工农业总产值中的比重由 1949 年的 30% 上升到 51.7%，第一批国产汽车、飞机相继下线。运用过渡时期总路线的知识，说明我国是怎样在短短几年内实现这种转变的。", "a": "党提出过渡时期总路线，实行「一化三改」：以社会主义工业化为主体，国家有计划地进行经济建设，优先发展重工业，建立国家工业化的初步基础；同时对农业、手工业和资本主义工商业进行社会主义改造，使生产关系适应工业化发展的需要，把半殖民地半封建社会的经济结构转变为社会主义经济结构。工业化与改造相互促进，使我国在较短时间里建立起独立的工业体系的初步基础，社会生产力得到解放和发展。"}, "advance": {"q": "有人认为，既然社会主义改造中也出现过急躁冒进的问题，就说明 1956 年确立社会主义制度是个错误。你如何反驳？", "a": "改造工作中的某些缺点和偏差，不能否定社会主义改造和制度确立的伟大意义。第一，社会主义改造基本完成，使社会主义公有制成为我国的经济基础，社会主义基本制度确立，这是中国历史上最深刻最伟大的社会变革。第二，它极大地提高了工农群众的生产积极性，促进了社会生产力的发展。第三，它为当代中国一切发展进步奠定了根本政治前提和制度基础。评价历史事件要分清主流和支流，不能以偏概全。", "kind": "self"}}, "video": {"bvid": "BV1Cr421T75t", "p": 1, "t": "只有社会主义才能救中国", "dur": "47:16", "from": "政治老师爱政治", "vtop": ["资本主义道路在中国行不通：帝国主义不允许、封建势力不愿意、民族资产阶级没能力——三句话记牢行不通的原因。", "新民主主义革命的“新”在三处：无产阶级领导、前途是建立无产阶级领导下的各革命阶级联合专政并过渡到社会主义、属于世界无产阶级革命的一部分。", "过渡时期总路线是“一化三改”：逐步实现国家社会主义工业化，逐步实现对农业、手工业和资本主义工商业的社会主义改造；1956 年三大改造完成，社会主义制度基本确立。"], "vsum": "本课讲第二课**只有社会主义才能救中国**，分两框：第一框新民主主义革命的胜利，时间段是 **1840 年到 1949 年**；第二框社会主义制度在中国的确立，对应社会主义革命时期，也叫过渡时期，时间段是 **1949 年到 1956 年**，之后 1956 年到 1978 年是社会主义建设的艰辛探索。先看近代中国的社会性质：进入近代以来，西方国家通过资产阶级革命和工业革命进入资本主义社会、生产力大发展并对外殖民扩张，而中国因清王朝长期闭关锁国、政治腐败而贫穷落后，沦为**半殖民地半封建社会**：**1840 年第一次鸦片战争**后中国逐渐开始沦为半殖民地半封建社会，**1856 年第二次鸦片战争**后半殖民地化程度进一步加深，**1894 年中日甲午战争**后大大加深，**1900—1901 年八国联军侵华、签订《辛丑条约》**后中国完全沦为半殖民地半封建社会。**半殖民地**指形式上独立、但政治经济文化各方面都受到外国资本主义控制和压迫、丧失了部分主权，当时中国内部有许多外国租界、被称为“国中之国”，如厦门鼓浪屿英租界、哈尔滨俄租界（1907 年起修建索菲亚大教堂）；**半封建**指原有封建属性遭到破坏、资本主义有了一定发展，但封建剥削制度仍占主导地位。易错提醒：不能简单粗暴地理解为政治上半殖民地、经济上半封建。沦为半殖民地半封建社会的原因分内外两面：外部是西方列强入侵，中国深受**帝国主义、封建主义和官僚资本主义**三重压迫；内部是封建制度落后加上长期闭关锁国，使中国在经济政治文化各方面都落后了。由此得出近代中国人民的两大历史任务：**争取民族独立、人民解放**，**实现国家富强、人民幸福**——其中国家富强、人民幸福是民族独立、人民解放的目的，而民族独立、人民解放又是实现国家富强、人民幸福的前提；当时的主要矛盾是**帝国主义与中华民族、封建主义与人民大众的矛盾**。面对内忧外患，无数仁人志士艰苦探索救亡图存之路：**太平天国运动**是农民阶级发起的反封建反侵略起义，**洋务运动**是地主阶级洋务派发起的封建统治者自救运动，**戊戌变法**是资产阶级性质的改良运动，**义和团运动**是农民阶级提出“扶清灭洋”口号的反帝爱国运动，**清末新政**是以慈禧太后为代表的封建统治阶级为延续统治、巩固皇权而进行的改革运动，**辛亥革命**是资产阶级发起的、为推翻清朝专制、建立共和政体的资产阶级民主革命；辛亥革命后中国还尝试过君主立宪制、帝制复辟、议会制、多党制、总统制等各种形式，结果无一例外全部失败，告诉我们**在半殖民地半封建的近代中国，资本主义道路是走不通的**，必须另辟新路。为什么行不通，由近代中国的基本国情决定，分三点：**帝国主义不允许**——帝国主义入侵中国的目的是把中国变成殖民地或半殖民地、维护在华特权，绝不允许中国走资本主义道路强大起来成为竞争对手；**封建势力不愿意**——中国封建势力同帝国主义相勾结，严重阻碍民族资本主义经济发展；**民族资产阶级没能力**——中国民族资产阶级力量十分弱小，又与封建主义和外国资本主义有着千丝万缕的联系，具有软弱性和妥协性，不能承担领导中国人民完成反帝反封建民主革命的使命和任务。正当寻找救国救民的道路屡遭挫折时，**俄国十月革命一声炮响，给中国送来了马克思列宁主义**，中国先进分子从中看到了解决中国问题的新出路，开始接受并传播马克思列宁主义，进入胜利的征程——新民主主义革命时期。新民主主义革命的指导思想是**马克思列宁主义**；开始的标志是 **1919 年五四运动**：中国作为一战战胜国在巴黎和会上受到帝国主义不公正对待，软弱的北洋政府卖国求荣、要把德国在山东的权力拱手让给日本，1919 年 5 月 4 日北京爆发声势浩大的五四运动，喊出“**外争主权，内除国贼**”、拒绝在巴黎和约上签字、废除二十一条、还我青岛、打倒卖国贼等口号。“外争主权”是反对帝国主义的不公正对待，“内除国贼”是反抗卖国求荣的封建北洋政府，所以五四运动是中国人民彻底反抗帝国主义和封建主义的爱国运动，具有彻底反帝反封建的革命性、追求救国强国真理的进步性，又以青年学生为先锋、各族各界群众积极参与，具有广泛性；每年 5 月 4 日设为**五四青年节**。五四运动为中国共产党的成立做了思想上和干部上的准备：思想上促进了马克思列宁主义在中国的传播，干部上初步掌握马列主义的先进分子到工人群众中做宣传和组织工作，实现先进知识分子与工人运动的结合；五四运动在近代以来中华民族追求民族独立和发展进步的历史进程中具有里程碑意义，是**旧民主主义革命走向新民主主义革命的转折点**。1921 年，在马列主义同中国工人运动相结合的过程中，**中国共产党应运而生**，从此中国人民谋求民族独立、人民解放、实现国家富强、人民幸福的斗争有了主心骨，中国共产党成为新民主主义革命的领导力量。此后中国共产党带领中国各族人民经过 28 年浴血奋战，经历**大革命、土地革命战争、抗日战争、解放战争**四个阶段，终于在 1949 年夺取新民主主义革命的伟大胜利、建立中华人民共和国。革命斗争中总结出战胜敌人的**三大法宝：统一战线、武装斗争、党的建设**——统一战线是因为当时中国革命的敌人太强大，单凭无产阶级一个阶级的力量不够，必须组织革命的统一战线，农民是工人阶级的同盟军，还可以联合城市小资产阶级和民族资产阶级，发动群众、团结一切可以团结的力量；武装斗争即“枪杆子里出政权”，是中国共产党从大革命失败的血的教训中得出的宝贵经验，新民主主义革命的特点就是长期的武装斗争、以武装的革命反对武装的反革命，统一战线和武装斗争是战胜敌人的两个基本武器；党的建设方面，只有把党建设好才能更好地领导中国革命走向胜利，1941 年抗日战争时期开始的**延安整风运动**就是中国共产党历史上第一次大规模的整风运动，目的是进行马克思列宁主义教育、提高全党的马列主义水平、纠正党内的错误思想；三大法宝是毛泽东对中国新民主主义革命经验的基本总结。新民主主义革命的性质是**无产阶级领导的、以工农联盟为基础的、人民大众的、反对帝国主义、封建主义和官僚资本主义的民主革命**，其中领导阶级是无产阶级，阶级基础是工农联盟，主体是人民大众，革命任务是反对帝国主义、封建主义和官僚资本主义这三座大山。新民主主义革命与旧民主主义革命相比，“新”在三处：领导权上，新民主主义革命的领导者是无产阶级，旧民主主义革命的领导者是资产阶级；革命前途上，新民主主义革命要建立**无产阶级领导下的各革命阶级的联合专政**并最终过渡到社会主义社会，旧民主主义革命要建立资产阶级共和国和资本主义制度；革命所属范畴上，新民主主义革命属于世界无产阶级革命的一部分，旧民主主义革命属于世界资产阶级革命的一部分。根据革命前途，中国革命必须分两个步骤：第一步是民主革命，改变半殖民地半封建的社会形态，使中国社会变成一个独立的民主主义的社会；第二步是社会主义革命，建设社会主义社会；**新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主义革命的必然趋势**，只有完成前一个革命才能完成后一个革命，两个革命阶段必须相互衔接。1949 年新中国成立，第一步就此完成，也标志着新民主主义革命的胜利。新中国成立的意义可概括为“辞旧”与“迎新”：“辞旧”是指它彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了极少数剥削者统治广大劳动人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，实现了中国从几千年封建专制政治向人民民主的伟大飞跃；“迎新”是指新中国的成立为实现由新民主主义向社会主义的过渡创造了条件，从根本上改变了中国社会的发展方向，为实现国家富强、民族复兴展示了美好前景和现实道路；对外看，新中国的诞生是 20 世纪的伟大历史事件，它在人口约占世界四分之一、领土面积世界第三的中国建立起人民民主制度并逐步建立起社会主义制度，从而大大加强了世界和平民主和社会主义阵营的力量，改变了二战之后国际冷战格局中的力量对比，冲破了帝国主义的东方战线，极大地改变了世界政治力量对比，鼓舞和推动了世界被压迫民族和被压迫人民争取解放的斗争。在新民主主义革命实践中，中国共产党人把马克思列宁主义基本原理同中国革命具体实际相结合，开辟了**农村包围城市、武装夺取政权的正确革命道路**，创立了**毛泽东思想**，这是新民主主义革命中形成的重大理论成果，为夺取新民主主义革命胜利指明正确方向；毛泽东思想也是**马克思主义中国化的第一次伟大飞跃**。第二框讲社会主义制度在中国的确立。新中国成立后并没有马上进入社会主义社会，还要继续通过 1949 年到 1956 年的社会主义改造，完成中国革命的第二步——社会主义革命、建立社会主义社会；1949 年新中国成立到 1956 年三大改造完成这段时期，就是从新民主主义向社会主义的**过渡时期**。建国之初形势十分严峻：农业工业都非常落后，人口素质比较低，教育水平也很低，环境条件也非常恶劣，而且国民党还留下贫穷落后、千疮百孔的烂摊子，撤退时掠夺大量财富、炸毁桥梁矿井等基础设施。在这样的背景下，中国共产党提出过渡时期的总路线和总任务：**要在一个相当长的时期内，逐步实现国家的社会主义工业化，并逐步实现国家对农业、手工业和资本主义工商业的社会主义改造**，简单概括为“**一化三改**”。其中“一化”是由新中国建立之初国家贫穷、工业基础十分薄弱的现状决定的，当时新中国与西方发达国家差距十分大，毛主席曾说：“我们现在能造什么？我们能造桌子椅子，能造茶碗茶壶，但一辆汽车、一架飞机、一辆坦克、一辆拖拉机都造不出来。”“三改”是对农业、手工业和资本主义工商业进行社会主义改造：改造之前这些都属于生产资料私有制，对农业和手工业实行类似生产合作社的改造方式，使之变成社会主义集体所有制，对资本主义工商业实行公私合营的方式，使之变成社会主义公有制，总之就是把生产资料私有制转变为公有制。“一化”是在解放和发展社会生产力，“三改”是在调整生产关系，目的是使生产资料的社会主义公有制占主体地位、成为国家唯一的经济基础。党在过渡时期的总路线和总任务的提出，是根据马克思列宁主义理论、并依据新中国成立之后政治经济条件的新变化作出的重大决策，符合新中国社会发展的实际和规律，反映了从新民主主义向社会主义过渡的历史必然性，具体有四方面：第一，社会主义国营经济迅速发展，逐步成为社会经济中的主导性因素——1949 到 1952 年，国家剥夺国民党四大家族官僚资本归人民国家所有，并采用多种形式接收英美等国在华企业，加上各种措施恢复国民经济，使公有制经济在国民经济中迅速占据绝对优势，为从新民主主义向社会主义过渡提供了重要物质基础；第二，国家积累了利用、限制和管理私营工商业的经验，不同程度地开始了对他们的初步社会主义改造——国家在合理调整工商业的过程中创造了**加工订货、经销代销、统购包销、公司合营**等一系列从低级到高级的国家资本主义形式，使之逐步接受国家的监督和管理，同时 1952 年开展**五反运动**，即反行贿、反偷税漏税、反盗骗国家财产、反偷工减料、反盗窃国家经济情报，打击当时一些不法资本家的“五毒”行为，对工商业者进行守法经营的教育，推动私营企业建立工人监督制度和实行民主改革；第三，个体农业经济难以适应国家工业化建设的新形势，迫切需要组织起来——分散落后的小农经济很难使用大机器、无力抵御自然灾害、不利于生产力发展，如果不把农民组织起来，不仅不能改善农民生活，也不可能为工业发展提供必要的商品粮食原材料等条件，只有农业集体化、规模化才有可能实现社会主义工业化；工业化初期往往采用用农业支持工业的方针，工业化达到相当程度时工业就要反过来反哺农业；具体操作上当时通过互助组、农业合作社的方式把农民组织起来；第四，国际形势有利于中国加快向社会主义阵营转变——二战之后世界两大阵营对抗，以美国为代表的西方国家在外交、经济、军事等领域对中国严密封锁，只有苏联等社会主义国家支持中国，所以新中国在对外关系上实行向社会主义国家“一边倒”的方针，1950 年签订**《中苏友好互助同盟条约》**，苏联对华提供三亿美元贷款和一批工业援助项目，有利于新政权在国际社会上站稳脚跟。这四个方面决定了从新民主主义向社会主义过渡具有历史必然性。1956 年社会主义改造完成，有十分重大的意义：第一，标志着中国实现了从新民主主义向社会主义的转变，从此进入社会主义社会——这里要明确 1840 年以来中国社会性质的变化：1840 年鸦片战争爆发到 1949 年新中国成立属于半殖民地半封建社会，1949 年到 1956 年三大改造期间属于新民主主义性质的社会，1956 年社会主义改造完成之后才真正进入社会主义社会；第二，中国共产党在一个经济文化落后的东方大国创造性地开辟了一条适合中国特点的社会主义改造道路，顺利实现了对生产资料私有制的社会主义改造——对农业和手工业实行从小到大、从低级到高级的改造方式，对资本主义工商业创造性地实行加工订货、统购包销、经销代销、公司合营等形式，都顺利实现了由生产资料私有制向社会主义公有制的转变；第三，在中国建立起了社会主义制度，完成了**中华民族有史以来最为广泛而深刻的社会变革**；第四，社会主义改造的伟大胜利极大地激发了广大人民群众建设社会主义的积极性，社会生产力有了比较迅速的发展，社会秩序更加稳定，人民民主专政更加巩固，从而为我国全面建设社会主义奠定了坚实基础。社会主义改造完成、确立社会主义基本制度、进入社会主义社会之后，就迎来了新的历史时期——**社会主义建设时期（1956—1978 年）**。如何建设社会主义、如何巩固和发展社会主义，是一个崭新的历史课题，没有现成的答案和经验可以遵循；面对新情况新问题，中国共产党以马克思列宁主义基本原理为指导，以苏联的经验教训为借鉴，结合中国具体实际，开始探索适合中国国情的社会主义建设道路，这就是马克思列宁主义原理同中国具体实际的**第二次结合**（第一次结合是与新民主主义革命时期的具体实际相结合，第二次结合则是与社会主义革命和建设时期的具体实际相结合）。在这样的背景下，**1956 年 9 月中共八大召开**，这是新中国成立以来中国共产党召开的第一次全国代表大会；中共八大最重要的贡献是正确分析了国内形势和国内主要矛盾的变化，明确提出了党和全国人民在新形势下的主要任务，为社会主义事业的发展指明了方向。关于主要矛盾，党的八大指出，社会主义改造完成之后，我国的主要矛盾已经不再是无产阶级同资产阶级之间的阶级矛盾，而是**人民对建立先进的工业国的要求同落后的农业国的现实之间的矛盾**，是**人民对于经济文化迅速发展的需要同当前经济文化不能满足人们需要的状况之间的矛盾**；因此主要任务就是**集中力量发展社会生产力，尽快把我国从落后的农业国变为先进的工业国**。在正确方向指引下，我国在社会主义建设时期取得了巨大成就：工业方面建立起独立的、比较完整的工业体系和国民经济体系，50 年代中央集中力量建设鞍钢，其钢铁产量一度占据全国半壁江山、被誉为钢铁行业的“共和国长子”，1956 年在长春第一汽车制造厂诞生了新中国第一辆解放牌汽车；农业方面，党带领农民克服各种困难，大规模建设农业基础设施，兴修了红旗渠等一大批防洪灌溉工程设施，改善农业生产条件，粮食产量有了较大增长，初步满足了占世界四分之一人口的基本生活需求；基础设施方面，建筑、交通运输等获得较快发展，1957 年被誉为“万里长江第一桥”的**武汉长江大桥**正式通车、“天堑变通途”，它是当时我国自行设计建造的最长的铁路公路两用桥，70 年代中国第一条电气化铁路**宝成铁路**正式通车；科教方面，科技发展取得重大突破，教育医疗事业也得到长足发展，1964 年我国成功爆炸第一颗原子弹、打破超级大国核垄断，教育方面保障人民群众受教育的权利，开展大规模扫盲和工农干部文化补习教育，逐渐形成比较完整的国民教育体系；人们的精神面貌也得到极大改变，广大人民群众意气风发、斗志昂扬，面对巨大困难和压力坚持独立自主、自力更生，团结一致、艰苦奋斗，培育和发扬了“**两弹一星**”精神、**大庆精神**等；对外看，中国成为世界上有重要影响的大国，70 年代外交方面取得很多成就：中日建交、中美建交、中国在联合国的合法席位得以恢复。这些成就雄辩地证明了社会主义道路是正确的、只有社会主义才能救中国。但是由于国际局势复杂多变、国内建设任务艰巨繁重，再加上缺乏领导社会主义建设的现成经验，我们在取得伟大成就的同时也犯了错误、经历了曲折：1958 年的**大跃进运动**在发展生产上急于求成，导致出现浮夸风、“放卫星”的严重错误；大跃进过程中又发生**人民公社化运动**，在生产关系上过度、片面地追求“**一大二公**”，使生产力遭到严重破坏；并且在阶级斗争问题上犯了绝对化、扩大化的错误，导致发生“**文化大革命**”这样的十年内乱；所以社会主义建设的探索过程是成就与曲折并存的。这些探索的意义有四方面：第一，得出一个重要结论——我国社会发生翻天覆地的变化，雄辩地证明了**只有社会主义才能救中国**；第二，一个伟大飞跃——新民主主义革命的胜利、中华人民共和国的诞生、社会主义制度的确立和社会主义建设的全面展开，实现了中华民族从“**东亚病夫**”到**站起来的伟大飞跃**；第三，从毛泽东思想的角度看，把马克思列宁主义基本原理同中国社会主义革命和建设时期的具体实际进行了第二次结合，丰富和发展了毛泽东思想，是**马克思主义中国化时代化的第一次历史性飞跃**；第四，承上启下——党在社会主义革命和建设中取得的独创性理论成果和巨大成就，为新的历史时期、也就是改革开放时期开创中国特色社会主义提供了宝贵经验、理论准备和物质基础。习近平总书记在纪念毛泽东同志诞辰 120 周年座谈会的讲话中指出，在中国这样的社会历史条件下，建设社会主义没有先例，犹如攀登一座人迹罕至的高山，一切攀登者都要披荆斩棘开通道路；事物发展的道路是曲折的、迂回的，但前途是光明的，历史总是在向前发展的；总结和吸取历史教训，目的就是以此为鉴、更好地前进。课中穿插的几道练习题，讲题时都是逐个选项对照着讲、对在哪里、错在哪里，考的也都是上面这些点。", "vtech": [["资本主义道路行不通：三句话对应三方", "看到问为什么行不通 → 先对号：帝国主义不允许（怕中国强大起来成为竞争对手）、封建势力不愿意（勾结帝国主义、阻碍民族资本主义发展）、民族资产阶级没能力（力量弱小、软弱性妥协性）；三方缺一不可，别只答一条。"], ["新民主主义革命的“新”：三处对比", "看到新旧对比题 → 抓三处：领导权（无产阶级 vs 资产阶级）、前途（无产阶级领导下的各革命阶级联合专政并过渡到社会主义 vs 资产阶级共和国和资本主义制度）、范畴（世界无产阶级革命的一部分 vs 世界资产阶级革命的一部分）。"], ["社会性质三段别串：1840–1949、1949–1956、1956 之后", "看到社会性质判断题 → 先定时间：1840 年鸦片战争到 1949 年新中国成立是半殖民地半封建社会；1949–1956 年三大改造期间是新民主主义性质的社会；1956 年社会主义改造完成之后才真正进入社会主义社会。"], ["“一化三改”与中共八大主要矛盾", "看到过渡时期总路线 → 默念“一化三改”：逐步实现国家社会主义工业化，逐步实现对农业、手工业和资本主义工商业的社会主义改造；看到中共八大 → 主要矛盾已变：不再是无产阶级同资产阶级之间的阶级矛盾，而是人民对建立先进工业国的要求同落后的农业国现实之间的矛盾，主要任务是集中力量发展社会生产力。"]], "vgaokao": []}}, "pol_p005": {"name": "伟大的改革开放", "sec": 5, "secTitle": "第三课 只有中国特色社会主义才能发展中国", "page": 31, "desc": "十一届三中全会开启新时期；改革开放是关键一招，中华民族迎来了富起来的伟大飞跃。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p004"], "next": ["pol_p006"], "content": {"intro": "1978 年，**党的十一届三中全会**作出实行改革开放的历史性决策。改革开放是党的一次伟大觉醒，是党和人民大踏步赶上时代的**重要法宝**，是坚持和发展中国特色社会主义的**必由之路**，是决定当代中国命运的**关键一招**。==因改革开放，中华民族迎来了从站起来、富起来到强起来的伟大飞跃。==", "learn": [{"h": "改革开放是怎样开启的", "p": "1978 年党的**十一届三中全会**冲破长期「左」的错误的严重束缚，重新确立解放思想、实事求是的思想路线，作出把党和国家工作中心转移到**经济建设**上来、实行改革开放的历史性决策，开启了改革开放和社会主义现代化建设新时期。真理标准问题大讨论为全会作了思想准备。"}, {"h": "改革开放的进程与成就", "p": "改革从农村起步（家庭联产承包责任制），逐步向城市推进；开放从兴办**经济特区**起步，形成由沿海到沿江沿边、由东部到中西部的对外开放格局。我国实现了从生产力相对落后的状况到经济总量跃居世界第二的历史性突破，实现了人民生活从温饱不足到总体小康、奔向全面小康的历史性跨越，推进了中华民族从站起来、**富起来**到强起来的伟大飞跃。"}, {"h": "怎样评价改革开放", "p": "改革开放是**党的一次伟大觉醒**，孕育了党从理论到实践的伟大创造；是党和人民**大踏步赶上时代的重要法宝**；是坚持和发展中国特色社会主义的**必由之路**；是**决定当代中国命运的关键一招**，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。改革开放极大改变了中国的面貌、中华民族的面貌、中国人民的面貌、中国共产党的面貌。"}, {"h": "改革开放只有进行时没有完成时", "p": "改革开放是当代中国最鲜明的特色。改革开放中的矛盾只能用改革开放的办法来解决：新时代要将改革开放进行到底，不断实现人民对美好生活的向往，在新时代创造中华民族新的更大奇迹。停顿和倒退没有出路，这是改革开放四十多年得出的结论。"}], "pitfalls": ["把改革说成改变社会主义制度——改革是社会主义制度的自我完善和发展，是中国的第二次革命，不是改向。", "用改革开放前或后一个历史时期否定另一个——两个时期本质上都是社会主义建设的实践探索，不能相互否定。", "把十一届三中全会的地位说小了：它是新中国成立以来党的历史上具有深远意义的伟大转折。"], "basics": [{"q": "开启改革开放和社会主义现代化建设新时期的会议是（ ）", "opts": ["党的八大", "党的十一届三中全会", "党的十二大", "党的十四大"], "ans": 1, "why": "1978 年党的十一届三中全会作出实行改革开放的历史性决策，是新中国成立以来党的历史上具有深远意义的伟大转折。"}, {"q": "被教材誉为「决定当代中国命运的关键一招」的是（ ）", "opts": ["社会主义改造", "改革开放", "土地改革", "一五计划"], "ans": 1, "why": "改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"}, {"q": "我国对外开放格局的起步是（ ）", "opts": ["加入世界贸易组织", "兴办经济特区", "设立自由贸易试验区", "提出一带一路倡议"], "ans": 1, "why": "1980 年设立深圳等经济特区，对外开放迈出关键一步；加入世贸是 2001 年，自贸区与一带一路更晚。"}], "apply": [{"q": "材料：1978 年，安徽凤阳小岗村 18 户农民签下契约，分田到户搞包干，当年粮食产量相当于此前五年的总和。这一做法很快得到中央肯定并推向全国。这一历史片段说明（ ）", "opts": ["农民的探索与党的决策相结合，开启了农村改革的序幕", "计划经济体制在当时已经被完全废除", "土地所有制由集体所有变为农民私有", "改革开放首先从城市开始"], "ans": 0, "why": "家庭联产承包责任制坚持土地集体所有、包干到户，源于农民群众的创造并经党尊重和推广，改革由此从农村起步；1978 年时计划经济体制远未废除。"}, {"q": "材料：40 多年间，我国国内生产总值由 3679 亿元增长到超过 120 万亿元，成为世界第二大经济体；居民人均可支配收入实际增长 20 多倍，7.7 亿农村贫困人口摆脱贫困。这些变化最有力地证明（ ）", "opts": ["我国已建成社会主义现代化强国", "改革开放极大解放和发展了社会生产力，中华民族迎来了富起来的伟大飞跃", "我国社会主要矛盾已经消除", "公有制经济已完全取代其他经济成分"], "ans": 1, "why": "数据对应的是生产力跃升与人民生活跨越，即「富起来」阶段的成就；现代化强国、社会主要矛盾问题都不能夸大其词。"}], "case": {"q": "材料：深圳从一个小渔村发展为现代化国际化城市，地区生产总值从 1979 年的 1.96 亿元跃升至 3 万亿元以上，创造了世界工业化、城市化发展史上的奇迹。「深圳奇迹」被视为改革开放成就的一个缩影。运用本框知识，分析深圳奇迹产生的根本原因，并谈谈它给新时代青年的启示。", "a": "根本原因在于实行改革开放：党作出实行改革开放的历史性决策，兴办经济特区，解放思想、实事求是，大胆试、大胆闯，极大地解放和发展了社会生产力，使深圳能够大踏步赶上时代。改革开放是党和人民大踏步赶上时代的重要法宝，是决定当代中国命运的关键一招。启示：青年要珍惜改革开放开创的时代条件，坚持解放思想、实事求是，勇于创新、敢于担当，在新时代将改革开放进行到底。"}, "advance": {"q": "辨析：改革就是要改掉社会主义基本制度中不合时宜的一切，包括公有制主体地位。", "a": "错误。改革是社会主义制度的自我完善和发展，目的是使生产关系适应生产力的发展，而不是改变社会主义制度的根本性质。坚持公有制主体地位、坚持党的领导、坚持中国特色社会主义道路，是改革必须坚持的正确方向。把改革说成改变根本制度，是对改革性质的根本误解，教材的口径是：改革开放只有进行时没有完成时，但方向不能变。", "kind": "self"}}, "video": {"bvid": "BV18T421k7Qr", "p": 1, "t": "只有中国特色社会主义才能发展中国", "dur": "51:24", "from": "政治老师爱政治", "vtop": ["十一届三中全会1978年12月召开，开启改革开放和社会主义现代化建设新时期，是新中国成立以来党的历史上具有深远意义的伟大转折——与社会主义制度确立的“最为广泛而深刻的社会变革”区分开。", "改革开放分三个阶段：起步阶段1978—1992、新阶段1992—2012、全面深化阶段2012年十八大以来；改革是社会主义制度的自我完善和发展，不是根本变革社会主义制度。", "意义记“四个面貌、三个飞跃”：改革开放是党和人民大踏步赶上时代的重要法宝（是“赶上”不是“引领”）、坚持和发展中国特色社会主义的必由之路、决定当代中国命运的关键一招；中华民族迎来从站起来、富起来到强起来的伟大飞跃（是“迎来”不是“实现”）。"], "vsum": "本课讲必修一第三课，分两框：第一框是**伟大的改革开放**，第二框是**中国特色社会主义的创立、发展和完善**。开场先看两组信息：1965年美国的人均GDP是中国的41倍，到1978年变成了76倍，差距还在持续扩大；西德一个露天煤矿年产煤5000万吨只有2000名职工，国内却需要16万名工人；法国一家钢铁厂年产钢350万吨、职工7000人，武汉钢铁公司年产量230万吨却有6.7万人；70年代中美两国农村状况对比也直观显示当时中国人民的生活水平和居住环境严重落后于美国。总之当时经济上濒临崩溃，人民生活温饱尚不能解决，国家已经到了何去何从的重大历史关头。邓小平同志指出，如果现在再不进行改革，我们的现代化事业和社会主义事业都会被葬送。正是在这样的历史关头，我们党在**1978年12月**召开了**十一届三中全会**，开启了改革开放的历程。在十一届三中全会上，首先重新确立了马克思主义的**思想路线、政治路线和组织路线**：思想路线就是否定当时错误的“两个凡是”的观点，重新确立**解放思想、实事求是**；政治路线指的是**以经济建设为中心，实行改革开放**；组织路线指的是在实际上形成了**以邓小平为核心的党中央第二代领导集体**。其次还实现了党和国家工作中心的战略转移，也就是否定了“以阶级斗争为纲”，把党和国家的工作重点转移到**社会主义现代化建设**上来。十一届三中全会开启了改革开放和社会主义现代化建设的新时期，实现了新中国成立以来党的历史上具有**深远意义的伟大转折**。这里要注意区分：之前第二课讲到，社会主义制度的确立是中华民族有史以来最为广泛而深刻的社会变革，而改革开放则是中华人民共和国成立以来党的历史上具有深远意义的伟大转折。十一届三中全会之后，中国正式进入了改革开放时期。那到底什么是改革开放呢？首先**改革**指的是在**坚持社会主义制度的前提下**，调整生产关系同生产力、上层建筑同经济基础之间不相适应的环节，它既包括经济体制的改革，也就是要把当时高度集中的**计划经济体制**改革为**社会主义市场经济体制**，还包括政治方面的改革，包括发展民主、加强法治等。邓小平同志指出，改革是**中国的第二次革命**。改革是社会主义制度的一种**自我完善与发展**，而不是要从根本上变革或者说推翻社会主义制度。下面是**开放**，开放指的是**对外开放**，它是加快我国现代化建设的必然选择，也是必须长期坚持的一项**基本国策**。所以改革开放可以简单概括为**对内改革与对外开放**，无论从时间还是内容上，改革与开放都不是完全孤立的，它们之间是相辅相成、密不可分的。改革开放的进程可以分为**三个阶段**。第一个阶段称为**起步阶段**，指的是**1978年到1992年**。在对内改革方面，十一届三中全会之后，农村改革率先取得突破，**家庭联产承包责任制**推行，乡镇企业迅速发展。1978年冬，安徽凤阳县小岗村18户村民在一份分田到户的秘密契约上按下鲜红的手印，实行农业“大包干”，18枚红手印把农村原有的生产合作社变更为家庭联产承包责任制，最终上升为我国农村的**基本经营制度**。家庭联产承包责任制是在**土地公有制**的基础上，将土地长期承包给农民各家各户来使用，由集体经营变为分户自主经营、自负盈亏，当时流行一个顺口溜叫“交够国家的、留足集体的，剩下的全是自己的”。小岗村搞了大包干，第二年粮食产量增加了**四倍**，农民收入增加了**16倍**，村民人均收入从上年的22元跃升到了350元，小岗村一年就越过了温饱线。到1984年，**十二届三中全会**召开，标志着中国改革的重点**从农村转向了城市**，企业改革迈出重要步伐，尤其是国企改革，提出了**政企分开、自负盈亏**，降低国企对国家的依赖。90年代一大批效率低下、管理落后的国企被淘汰、关闭，还引发了一波下岗潮，放在当时是社会的阵痛，但从长远看有利于促进国企效率的提高和国家经济的腾飞。在对外开放方面，**1980年**设立了**深圳、珠海、汕头、厦门四个经济特区**，**1984年**开放了大连、青岛等**14个沿海港口城市**，**1988年**设立海南省、建立海南经济特区，**1990年**开放了上海浦东，1992年开放了沿长江五个城市、17个内陆省会城市，还有东北、西北、西南等一系列沿边城市，至此我国**全方位、多层次、宽领域**的对外开放格局基本形成：全方位指的是对世界所有国家开放；多层次指的是由点到线到面，先开放几个经济特区，此后又开放一批沿海港口城市，沿东南海岸线形成一条线，接着持续开放珠三角、闽南三角、长三角几大区域；宽领域不仅仅是在经济上打开国门，更是涵盖了经济、政治、科技、教育、文化、体育、卫生等众多领域。第二个阶段是**1992年到2012年**，也称为改革开放的**新阶段**，以**1992年邓小平南方谈话**和**党的十四大明确建立社会主义市场经济体制目标**为标志。南方谈话指的是邓小平在1992年年初视察武昌、深圳、珠海、上海等地的谈话，邓小平发表了“**计划经济不等于社会主义，资本主义也有计划；市场经济不等于资本主义，社会主义也有市场，计划与市场都是经济手段**”的重要论述。所以在这一阶段，对内改革完全是围绕着社会主义市场经济这一条主线展开的：在计划经济时代，粮票、布票、电视机票、自行车票都是产物，生产什么、生产多少、卖到哪里都是国家说了算，束缚了企业的手脚。1992年十四大提出建立社会主义市场经济体制的目标之后，1993年党的**十四届三中全会**就建立社会主义市场经济体制进行了部署，到了2003年党的**十六届三中全会**就围绕完善社会主义市场经济体制进行了部署。在对外开放方面，**2001年**中国成功地**加入了世界贸易组织**，标志着我国对外开放进入了一个新的阶段，中国的对外开放由**政策性开放向制度性开放**转变，入世之后中国积极兑现承诺，大幅度降低关税，积极参与国际经济合作和国际分工，加速与国际市场接轨，对外贸易得到了快速发展。**2012年党的十八大**提出了**全面建成小康社会和全面深化改革开放**的目标，于是进入改革开放的第三个阶段，叫做**全面深化阶段**。在对内改革方面，十八大以来党以巨大的政治勇气全面深化改革，打响改革攻坚战，加强改革顶层设计，坚决破除各方面的体制机制弊端，各领域基础性制度框架基本建立，许多领域实现了历史性变革、系统性重塑、整体性重构，新一轮党和国家机构改革全面完成，**中国特色社会主义制度更加成熟更加定型**，国家治理体系和治理能力现代化水平明显提高，比如十八大以来国家在反腐败领域坚持刀刃向内、重拳出击、保持高压态势。在对外开放方面，实行更加积极主动的开放战略，构建面向全球的高标准自由贸易区网络，加快推进自由贸易试验区、海南自由贸易港建设，共建“**一带一路**”成为深受欢迎的国际公共产品和国际合作平台，形成更大范围、更宽领域、更深层次对外开放格局。所以在全面深化阶段，对内持续深化改革，对外继续扩大开放，改革开放不断向纵深推进。其实在刚才每个阶段提到的代表性事件和重要会议中，经常出现**三中全会**：党的全国代表大会**每五年举行一次**，选举产生中央委员会，该届中央委员会召开的第三次全体会议就是三中全会。三中全会多出重大决策，尤其是经济改革的决策居多；改革开放以来党的历届三中全会都讨论深化改革问题，释放的重要信号就是我们党坚定不移高举改革开放伟大旗帜，坚定不移坚持党的十一届三中全会以来的理论、路线、方针和政策。课上两道练习题：第一题，关于中国故事的内容对应正确的是B选项——五四运动产生了马克思主义中国化的首个理论成果是错误的，首个理论成果指的是**毛泽东思想**；“半条被子”承载中国共产党的初心使命、执政为民，前半句正确但后半句错误，半条被子说的是革命过程中红军把自己的一条被子分给了人民群众半条，当时共产党还没有实现执政；“大包干”开启了波澜壮阔的改革开放是正确的，大包干说的是1978年的农村改革，开始实行家庭联产承包责任制；“一带一路”体现中国特色社会主义道路新发展新实践也是正确的。第二题，某校搜集的资料是1978年党召开十一届三中全会作出改革开放的决策，2013年党召开十八届三中全会系统设计全面推进改革，到2018年党召开十九届三中全会部署推进党和国家机构改革，符合这次研究性学习主题的是A选项——从1978年到2018年，关于改革这一主题一直没有停止、一直在深化，所以“实践永无止境，改革开放也永无止境”正确，改革就是对社会主义制度的自我完善与发展也正确；“从根本上改变了中国社会的发展方向”这是新中国成立的意义，新中国成立是在1949年，不符合主题；“中华民族有史以来最为广泛而深刻的社会变革”指的是三大改造确立社会主义制度，发生在1956年，也不符合主题。现在来总结改革开放的**意义**。首先通过40多年的改革开放，极大地改变了**四个面貌**：第一改变了**中国的面貌**，铸就了中国特色社会主义的生机与活力；第二改变了**中华民族的面貌**，提升了中华民族在国际上的地位和影响；第三改变了**中国人民的面貌**，满足了中国人民追求美好生活的愿望和期待；第四改变了**中国共产党的面貌**，中国共产党在今天已经成为了党员人数超过**九千万**的世界最大的执政党，还锻造了中国共产党驾驭市场经济的能力和本领。此外，自1978年实行改革开放之后，我国的经济实力在世界的排名不断前进，我国已经一跃成为**世界第二大经济体**，并且也是**制造业第一大国**。改革开放之后，全国居民人均可支配收入由**171元**增加到了**2.6万元**，贫困人口累计减少**7.4亿人**，建成了世界最大的社保体系，成为了世界上最有安全感的国家之一。所以说改革开放迎来了**三个飞跃**：中华民族迎来了**从站起来、富起来到强起来**的伟大飞跃，注意这里是**迎来**了而不是实现了；改革开放之后，中国共产党围绕中国特色社会主义这一主题，在实践中不断探索，取得了邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想等一系列重大理论创新成果，中国特色社会主义迎来了**从创立、发展到完善**的伟大飞跃；中国人民迎来了**从温饱不足到小康富裕**的伟大飞跃。今天的中华民族正以崭新的姿态屹立于世界的东方。所以我们说改革开放是党和人民**大踏步赶上时代的重要法宝**，注意是赶上时代而不是引领时代；还是**坚持和发展中国特色社会主义的必由之路**；是**决定当代中国命运的关键一招**，是决定实现**两个一百年**奋斗目标、实现中华民族伟大复兴的关键一招。2018年是改革开放40周年，党中央在北京人民大会堂隆重举行了庆祝改革开放四十周年大会，表彰一批为改革开放作出杰出贡献的个人，授予**改革先锋**称号，代表人物有国防科技事业改革发展的重要推动者**于敏**、公共卫生事件应急体系建设的重要推动者**钟南山**、杂交水稻研究的开创者**袁隆平**等，他们无不拥护中国共产党的领导和我们的社会主义制度，拥护改革开放，敢于冲破思想观念的束缚，敢于啃硬骨头、敢于涉险滩，爱岗敬业、无私奉献、作风优良。所以说改革开放的成功还得益于中国共产党的坚强领导和人民群众的开拓进取：**中国共产党是改革开放的领导核心**，而**人民是改革开放伟大奇迹的创造者**，是推动改革开放的力量源泉。那么时至今日，我国的改革开放就此完成了吗？当然没有，因为**实践发展永无止境，解放思想永无止境，改革开放也永无止境**，停顿和倒退没有出路；对外开放是中国的基本国策，当今世界是开放的世界，开放带来进步，封闭必然落后，**改革开放只有进行时，没有完成时**，改革开放一直在路上。第一框小结：共学习了两个问题，分别是改革开放的进程和意义；进程上先了解开端十一届三中全会，再分起步阶段、新阶段、全面深化阶段三个阶段及每个阶段的代表性事件；意义上学习了四个方面，概括为四个面貌、三个飞跃、重要法宝必由之路关键一招，以及改革开放永无止境。第二框是**中国特色社会主义的创立、发展和完善**，要学习四个问题：第一，改革开放以来党的全部理论和实践的**主题**是什么、如何理解；第二，中国共产党在实践探索中取得了哪些**重大理论创新成果**，从时间节点、主题、主要内容和历史贡献方面加以把握；第三，改革开放以来我国取得一切成绩和进步的**根本原因**；第四，中国特色社会主义**道路、理论、制度、文化**的重要性以及相互关系。1982年，中国共产党**第十二次全国代表大会**在北京召开，邓小平主持大会开幕式并致开幕词，在开幕词中他指出，我们的现代化建设必须要从中国的实际出发，应该学习和借鉴外国经验，但是绝不能照抄照搬，要把马克思主义的普遍真理同我国的具体实际结合起来，**走自己的路，建设有中国特色的社会主义**，这是我们总结长期历史经验得出的基本结论。所以说，以1982年党的十二大开幕式上邓小平第一次明确提出“走自己的路，建设有中国特色的社会主义”为标志，从此以后党的全部理论创新和实践创新，都是紧紧围绕着这一主题展开的，这一主题也可以简化为**中国特色社会主义**。这一主题的提出促使中国共产党坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，不断推进理论、实践、制度创新，成功开创、坚持和发展了中国特色社会主义。中国特色社会主义在发展过程中取得了**四大理论创新成果**：**邓小平理论**、“**三个代表”重要思想**、**科学发展观**和**习近平新时代中国特色社会主义思想**，这些合起来也被称为**中国特色社会主义理论体系**。这四大理论成果从四个方面回答了时代之问。问题一，我们要走什么样的道路？邓小平理论给出了答案，我们要走的是**中国特色社会主义道路**。这一理论是在十一届三中全会以后逐步形成的，围绕**什么是社会主义以及怎样建设社会主义**的主题，作出了第一次比较系统的回答。在邓小平理论出现之前，当时对社会主义的认识是不全面的：当时认为社会主义就是无产阶级专政、就是公有制，甚至把一些买卖自家鸡蛋的行为都定性为走资本主义道路、定性为挖社会主义的墙角；但按照马克思主义的理论，社会主义应该是人类的理想社会，理想社会最起码物质生活条件应该是富足的，而当时人民生活甚至连温饱都无法解决。所以邓小平对什么是社会主义、怎样建设社会主义的问题作出了回应，比如我们耳熟能详的那句话“**贫穷不是社会主义**”就是邓小平理论所提出的。在主要内容上，作出了把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策，**深刻揭示了社会主义本质**，确立社会主义初级阶段的基本路线，明确提出走自己的路、建设中国特色社会主义，科学回答了建设中国特色社会主义的一系列基本问题，制定了**三步走**战略。这里出现了三个名词，分别是社会主义本质、社会主义初级阶段基本路线以及三步走战略。第一个，**社会主义本质**是**解放生产力、发展生产力，消灭剥削、消除两极分化，最终达到共同富裕**。第二，党在**社会主义初级阶段的基本路线**是领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生、艰苦创业，为把我国建设成为**富强民主文明和谐美丽的社会主义现代化强国**而奋斗，也可以简称为**一个中心、两个基本点**。**三步走战略**是指：第一步在1981年到1990年实现国民生产总值比1980年翻一番，解决人民的温饱问题，这在20世纪80年代末就已经基本实现；第二步是1991年到20世纪末，国民生产总值再增长一倍，人民生活达到小康水平，这一目标也已经实现，在2000年我们就达到了**总体小康**；第三步目标到21世纪中叶基本实现现代化，人均国民生产总值达到中等发达国家水平，人民过上比较富裕的生活，这也是我们现在继续为之奋斗的目标。在历史贡献上，邓小平理论成功地**开创了中国特色社会主义**。问题二，建设什么样的党？“三个代表”重要思想给出了答案。它是在**1989年十三届四中全会以后**确立的，因为“三个代表”的内容提到，中国共产党要始终代表**中国先进生产力的发展要求**，始终代表**中国先进文化的前进方向**，始终代表**中国最广大人民的根本利益**。所以说它加深了对什么是社会主义、怎样建设社会主义和建设什么样的党、怎样建设党的认识。在主要内容上，确立了社会主义市场经济体制的改革目标和基本框架，确立了社会主义初级阶段**公有制为主体、多种所有制经济共同发展的基本经济制度**和**按劳分配为主体、多种分配方式并存的分配制度**，开创全面改革开放新局面，推进党的建设新的伟大工程。在历史贡献上，当时1989年正是东欧剧变、苏联解体，是世界社会主义出现严重曲折的时候，在国内外形势十分复杂、世界社会主义出现严重曲折的严峻考验面前，**捍卫了中国特色社会主义**，并且成功把中国特色社会主义**推向了21世纪**。问题三，新形势下实现什么样的发展、怎样发展？**科学发展观**给出了答案，它确立于**2002年的党的十六大以后**。科学发展观**第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾**。在主要内容上，强调坚持以人为本、全面协调可持续发展，着力保障和改善民生，促进社会公平正义，推进党的执政能力建设和先进性建设。在历史贡献上，成功在新形势下**坚持和发展了中国特色社会主义**；十六大之后的2002到2012这十年间，我国的国内生产总值有了大幅度的提高，经济总量也从世界第六位上升到世界第二位，国家面貌发生了新的历史性变化。问题四，面对党情、国情、世情的重大变化，处于新时代的我国应该怎么走下去？**习近平新时代中国特色社会主义思想**给出了回答，它是在**2012年党的十八大以来**确立的。当时中国国情的变化最大的状况就是**社会主要矛盾发生了变化**，变成了**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。以习近平同志为主要代表的中国共产党人，坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，坚持毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，深刻总结并充分运用党成立以来的历史经验，从新的实际出发，创立了习近平新时代中国特色社会主义思想。这一思想深刻地回答了**新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义**的重大课题，比如提出了“**五位一体**”总体布局、“**四个全面**”战略布局等一系列新理念新思想新战略。在历史贡献上，这一思想指导并推动党和国家事业取得历史性成就、发生历史性变革，使中国特色社会主义**进入了新时代**。关于这四大理论创新成果，要重点把握它的主题以及历史贡献：邓小平理论开创了中国特色社会主义，“三个代表”重要思想捍卫了中国特色社会主义并成功把它推向了21世纪，科学发展观又在新形势下坚持和发展了中国特色社会主义，习近平新时代中国特色社会主义思想推动中国特色社会主义进入了新时代，其实这一过程也就是中国特色社会主义**从创立到发展再到完善**的过程。课上时代课题排序练习：下列时代课题按照时间先后排列正确的是B选项——“走自己的路，建设有中国特色的社会主义”是邓小平理论在党的十二大上提出的；“建设什么样的党、怎样建设党”是“三个代表”重要思想在1989年之后逐步确立的；“新形势下实现什么样的发展、怎样发展”是科学发展观所回答的时代课题，时间是2002年到2012年；“新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义”是习近平新时代中国特色社会主义思想所回答的时代课题，时间是2012年之后。改革开放以来，我国在方方面面都取得了显著的成绩和进步：经济上我国现在是世界第二大经济体；政治上民主法治不断健全，国家治理体系和治理能力越来越现代化；文化上中国软实力备受全球关注，孔子学院开到了世界各地，越来越多的外国人也开始学习汉语；社会生活上人民从满足物质生活的需要向美好生活的目标迈进；生态文明建设上我们秉持“**绿水青山就是金山银山**”的理念，持续推进美丽中国建设。而以上经济、政治、文化、社会、生态文明五个方面成绩和进步的取得，**根本原因**就在于中国共产党带领中国人民**开辟了中国特色社会主义道路**、形成了**中国特色社会主义理论体系**、确立了**中国特色社会主义制度**、发展了**中国特色社会主义文化**。在这**四个自信**当中，**中国特色社会主义道路是必由之路**，**中国特色社会主义理论体系是行动指南**，**中国特色社会主义制度是中国一切发展进步的根本制度保障**，**中国特色社会主义文化是激励我们不断前进的精神力量**。下面具体研究这四个自信。第一，**中国特色社会主义道路**，它的主要内容是：在中国共产党领导下，立足基本国情，以经济建设为中心，坚持四项基本原则，坚持改革开放，解放和发展社会生产力，建设社会主义市场经济、社会主义民主政治、社会主义先进文化、社会主义和谐社会、社会主义生态文明，这叫做“五位一体”，促进人的全面发展，逐步实现全体人民共同富裕，建设富强民主文明和谐美丽的社会主义现代化强国。因为道路决定命运，中国特色社会主义道路既坚持了科学社会主义的基本原理，还具有鲜明的中国特色，它承载了几代中国共产党人的理想和探索，寄托了无数仁人志士的夙愿和期盼，凝聚了亿万人民的奋斗和牺牲，是党和人民历经千辛万苦、付出极大代价才开辟出来的道路，它也彻底改变了中国人的命运，使中国用70年的时间就走过了西方国家两三百年的工业化现代化道路，使中国一跃成为世界第二大经济体，创造了人类社会发展史上惊天动地的奇迹。所以历史告诉我们，既不要走**封闭僵化的老路**，也不要走**改旗易帜的邪路**，中国特色社会主义道路是实现社会主义现代化、创造人民美好生活的**必由之路**，是一条既适合中国国情、又适合时代发展要求、并且取得巨大成功的唯一正确道路。第二，**中国特色社会主义理论体系**，具体来说包括邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想，这套理论最大的特点是**实践性和创新性**，不是教条式地照搬马克思列宁主义，而是马克思列宁主义的中国化，是我们党从新的实践和时代特征出发，坚持和发展马克思主义，科学回答了建设中国特色社会主义的一系列基本问题，实现了马克思主义中国化时代化新的飞跃。十八大以来，党勇于理论探索和创新，深化对共产党执政规律、社会主义建设规律和人类社会发展规律的认识，取得重大理论创新成果，集中体现为习近平新时代中国特色社会主义思想；习近平新时代中国特色社会主义思想把中国特色社会主义理论体系推到了一个新的高度，牢牢把握了人民群众对美好生活的需要，贯穿了以人民为中心的初心和价值追求，具有跨时代意义和强大的真理力量。第三，**中国特色社会主义制度**，它是党和人民在长期实践探索中形成的科学制度体系，具体来说，它包括**人民代表大会制度**这一根本政治制度和三项基本政治制度，也包括中国特色社会主义法律体系，还包括国有制为主体、多种所有制经济共同发展的基本经济制度，以及建立在上述制度基础上的经济体制、政治体制、文化体制、社会体制等等，所以说是一个庞大的制度体系。我国国家治理一切工作和活动都依照中国特色社会主义制度展开，我国国家治理体系和治理能力就是中国特色社会主义制度及其执行能力的集中体现。而**制度优势是一个国家的最大优势，制度竞争是国家间最根本的竞争**，制度稳则国家稳。中国特色社会主义制度在实现广泛民主的基础上形成了正确的集中，具有**举国体制**优势，能够**集中力量办大事**，所以在脱贫攻坚、在抗击疫情、在发展航天事业的过程中，我们才能形成共同推动中国发展进步的强大力量。所以说中国特色社会主义制度和治理体系，是以马克思主义为指导、植根中国大地、具有深厚中华文化根基、深得人民拥护的制度和治理体系，是具有强大生命力和巨大优越性的制度和治理体系，是能够持续推动国家进步和发展、确保中华民族实现伟大复兴的制度和治理体系，所以我们有足够的理由充满**制度自信**。第四，**中国特色社会主义文化**，从形成来看，源自于中华民族五千多年文明历史所孕育的**中华优秀传统文化**，熔铸于党领导人民在革命、建设、改革中创造的**革命文化和社会主义先进文化**，植根于中国特色社会主义的伟大实践。发展中国特色社会主义文化就是以马克思主义为指导，坚守中华文化立场，立足当代中国现实，结合当今时代特点，发展**面向现代化、面向世界、面向未来的，民族的、科学的、大众的社会主义文化**，推动社会主义精神文明和物质文明协调发展。我们的文化有着丰富的内涵，由中华优秀传统文化、革命文化和社会主义先进文化共同组成。世界四大文明当中，只有中华文明是延续的。传统文化中，**大禹治水、愚公移山、精卫填海、女娲补天、夸父追日**讲的就是一心为公、自强不息。中国共产党人继承了这种精神，在战争年代抛头颅、洒热血，为了民族解放甘愿献出生命；社会主义建设年代，**雷锋、焦裕禄、王进喜、钱学森**怀着满腔热血投入到祖国的建设事业上。这种一心为国家、为民族奋斗的精神，正是中华文化之魂，具有强大的力量。所以说中国特色社会主义文化激荡着中华民族最深沉的精神追求，代表着中华民族独特的精神标识，是激励全党、全国各族人民奋勇前进的强大精神力量。并且，这**四个自信**之间并不是孤立的，他们是相互联系、相互作用，统一于中国特色社会主义伟大实践的。中国共产党从1921年成立至今，已经走过了一百多年的历史，党带领中国人民实现了中国的发展与壮大，让世界看到了可望而不可及的中国风骨、中国力量。所以说当今世界要说哪个政党、哪个国家、哪个民族能够自信的话，那中国共产党、中华人民共和国、中华民族是最有理由自信的。课上两道练习题：第一题，下列选项与四个自信对应正确的是A选项——道路自信“以中国式现代化全面推进中华民族伟大复兴”是正确的；把马克思主义基本原理同中华优秀传统文化相结合应该是理论自信，不是制度自信；坚持和完善“一国两制”、推进祖国统一属于制度自信，不是理论自信；坚持“两个毫不动摇”、构建高水平社会主义市场经济体制，经济制度也属于制度自信，不是文化自信。第二题，2023年12月甘肃发生地震造成重大人员伤亡，地震发生之后，财政部、应急管理部紧急向甘肃、青海预拨中央自然灾害救灾资金2亿元，国家综合性消防救援队伍共出动了一千多名消防救援人员赴灾区救援，国家卫健委紧急调派专家赶赴甘肃，组织临近甘肃的三支国家紧急医学救援队伍赴灾区支援，材料表明了中国特色社会主义制度，答案是B选项——这是在人民遇到巨大灾难的时候，多个不同的行为主体紧急集结、奔赴灾区，所以体现了能够集中人力、物力、财力办大事，也体现了在社会主义国家之下，是把人民的生命财产安全摆在第一位的，具有巨大的优越性。最后课堂小结：关于第三课第二框，中国特色社会主义的创立、发展和完善，我们共学习了两个问题，第一是改革开放以来党的全部理论和实践的主题，第二是中国特色社会主义道路、理论、制度和文化。首先关于党的全部理论和实践的主题，先明确是什么，简单概括就是中国特色社会主义；然后中国特色社会主义在发展的过程中还取得了四个重大的理论创新成果，分别是邓小平理论、“三个代表”重要思想、科学发展观以及习近平新时代中国特色社会主义思想，还要明确各自的时间节点、历史贡献、主要内容等。第二，围绕中国特色社会主义道路、理论、制度和文化，也就是四个自信来学习：首先要知道，这就是改革开放以来我国取得一切成就和进步的根本原因；其次还要分别掌握道路自信、理论自信、制度自信、文化自信以及他们之间的内在联系。", "vtech": [["“伟大转折”与“社会变革”别混", "看到“最”开头的定性句先问对象：十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折；社会主义制度的确立才是中华民族有史以来最为广泛而深刻的社会变革（三大改造，1956年）；“从根本上改变中国社会的发展方向”是新中国成立（1949年）的意义，不是改革开放。"], ["改革三阶段先定年份再想事件", "看到阶段题先定年份：起步阶段1978—1992、新阶段1992—2012、全面深化阶段2012年十八大以来；再把事件按年份落位：1980年四个经济特区、1984年14个沿海港口城市、1992年南方谈话、2001年加入世贸组织，1993年十四届三中全会部署建立市场经济体制、2003年十六届三中全会部署完善。"], ["意义题抓“四个面貌、三个飞跃”", "看到意义题先默写框架：四个面貌是中国、中华民族、中国人民、中国共产党的面貌；三个飞跃是中华民族从站起来、富起来到强起来，中国特色社会主义从创立、发展到完善，中国人民从温饱不足到小康富裕；注意“迎来”不是“实现”，“赶上时代”不是“引领时代”。"], ["四大理论成果按时间排历史贡献", "看到理论成果题先按时间排：邓小平理论开创了中国特色社会主义，“三个代表”重要思想捍卫了它并成功把它推向21世纪，科学发展观在新形势下坚持和发展了它，习近平新时代中国特色社会主义思想推动它进入新时代；时代课题排序也先定时间：十二大（1982年）—1989年后—2002—2012年—2012年十八大后。"]], "vgaokao": []}}, "pol_p006": {"name": "中国特色社会主义的创立、发展和完善", "sec": 6, "secTitle": "第三课 只有中国特色社会主义才能发展中国", "page": 35, "desc": "从邓小平理论到习近平新时代中国特色社会主义思想一脉相承；坚定四个自信。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p005"], "next": ["pol_p007"], "content": {"intro": "改革开放以来，党全部理论和实践的主题，就是坚持和发展**中国特色社会主义**。从邓小平理论到习近平新时代中国特色社会主义思想，理论成果**一脉相承又与时俱进**。==中国特色社会主义是党和人民历经千辛万苦、付出巨大代价取得的根本成就，是历史和人民的选择。==", "learn": [{"h": "中国特色社会主义的创立", "p": "党的**十二大**上，邓小平明确提出「把马克思主义的普遍真理同我国的具体实际结合起来，走自己的道路，建设有中国特色的社会主义」。**邓小平理论**围绕「什么是社会主义、怎样建设社会主义」这个根本问题，第一次比较系统地初步回答了在中国这样经济文化比较落后的国家如何建设社会主义的一系列基本问题，是中国特色社会主义理论体系的开篇之作。"}, {"h": "理论体系的发展与完善", "p": "党的十三届四中全会以后形成的**「三个代表」重要思想**，进一步回答了什么是社会主义、怎样建设社会主义的问题，创造性地回答了建设什么样的党、怎样建设党的问题。党的十六大以来形成的**科学发展观**，回答了实现什么样的发展、怎样发展的重大问题。党的十八大以来，**习近平新时代中国特色社会主义思想**使中国特色社会主义理论体系得到进一步丰富和发展。"}, {"h": "为什么说它是历史和人民的选择", "p": "中国特色社会主义不是从天上掉下来的，是党和人民历经千辛万苦、付出巨大代价取得的**根本成就**。近代以来各种主义、各种道路都在中国试过，只有中国特色社会主义使中国大踏步赶上时代。它植根于中国大地、反映中国人民意愿、适应中国和时代发展进步要求。"}, {"h": "坚定四个自信", "p": "我们要坚定**道路自信、理论自信、制度自信、文化自信**。中国特色社会主义道路是实现社会主义现代化、创造人民美好生活的必由之路；中国特色社会主义理论体系是指导党和人民实现中华民族伟大复兴的正确理论；中国特色社会主义制度是当代中国发展进步的根本制度保障；中国特色社会主义文化是激励全党全国各族人民奋勇前进的强大精神力量。其中，**文化自信是更基础、更广泛、更深厚的自信**。==中国特色社会主义是社会主义，不是别的什么主义，必须始终坚持科学社会主义基本原则。=="}], "pitfalls": ["把邓小平理论的地位说成中国特色社会主义理论体系的全部——它是开篇之作，理论体系还包括其后形成的重要思想。", "四个自信漏项或错位：是道路、理论、制度、文化四个自信，文化自信「更基础、更广泛、更深厚」。", "把中国特色社会主义说成「中国特色的资本主义」——它是社会主义，不是别的什么主义。"], "basics": [{"q": "首次明确提出「建设有中国特色的社会主义」命题的是（ ）", "opts": ["党的十一大", "党的十二大", "党的十三大", "党的十四大"], "ans": 1, "why": "1982 年党的十二大开幕词中，邓小平提出「建设有中国特色的社会主义」，这一命题成为邓小平理论和整个理论体系的主题。"}, {"q": "中国特色社会主义理论体系的开篇之作是（ ）", "opts": ["「三个代表」重要思想", "科学发展观", "邓小平理论", "习近平新时代中国特色社会主义思想"], "ans": 2, "why": "邓小平理论第一次比较系统地初步回答了社会主义建设的一系列基本问题，是中国特色社会主义理论体系的开篇之作。"}, {"q": "四个自信中，被称为「更基础、更广泛、更深厚的自信」的是（ ）", "opts": ["道路自信", "理论自信", "制度自信", "文化自信"], "ans": 3, "why": "教材原文：文化自信，是更基础、更广泛、更深厚的自信，是更基本、更深沉、更持久的力量。"}], "apply": [{"q": "材料：有同学读了近代史后提问：资本主义道路试过，改良道路试过，为什么偏偏中国特色社会主义走通了？最有说服力的回答是（ ）", "opts": ["因为它完全照搬了苏联模式", "因为它是党和人民把科学社会主义基本原则同中国具体实际相结合、历经艰辛探索取得的根本成就", "因为它放弃了马克思主义指导", "因为它只是发展速度更快一点而已"], "ans": 1, "why": "中国特色社会主义的成功，在于既坚持科学社会主义基本原则，又根据中国实际和时代特征赋予其鲜明的中国特色，是历史和人民的选择。"}, {"q": "材料：从「恢复高考」到「千万工程」，从自贸试验区扩容到新质生产力加快发展，几十年来中国的发展步伐从未停歇，但不同时期理论表述在不断更新。这体现了中国特色社会主义理论体系（ ）", "opts": ["前后矛盾、相互否定", "一脉相承又与时俱进", "已经定型、不需要发展", "只包含邓小平理论"], "ans": 1, "why": "从邓小平理论到习近平新时代中国特色社会主义思想，围绕坚持和发展中国特色社会主义这一主题一脉相承，又在实践中不断丰富发展。"}], "case": {"q": "材料：一位外国学者感叹：中国用几十年时间走完了发达国家几百年走过的工业化历程，却避免了殖民掠夺和战争扩张，「中国道路」打破了「现代化只能走西方道路」的神话。运用本框知识，说明为什么必须坚定中国特色社会主义道路自信。", "a": "第一，中国特色社会主义道路是实现社会主义现代化、创造人民美好生活的必由之路，它使中国大踏步赶上时代、迎来从站起来、富起来到强起来的伟大飞跃，已经被实践证明是成功的道路。第二，这条道路是党和人民历经千辛万苦、付出巨大代价取得的根本成就，植根于中国大地、反映中国人民意愿、适应中国和时代发展进步要求，不是照搬任何国家的模式。第三，道路自信不是盲目自大，而是建立在实践成就和规律认识基础上的坚定信念——既不走封闭僵化的老路，也不走改旗易帜的邪路。"}, "advance": {"q": "结合本框内容，谈谈中国特色社会主义理论体系各成果之间的关系。", "a": "第一，主题相同：都围绕坚持和发展中国特色社会主义这一主题，回答时代提出的重大问题，只是侧重点不同——邓小平理论着重回答「什么是社会主义、怎样建设社会主义」，「三个代表」重要思想创造性地回答「建设什么样的党、怎样建设党」，科学发展观着重回答「实现什么样的发展、怎样发展」，习近平新时代中国特色社会主义思想系统回答「新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义」。第二，一脉相承：后者都是对前者的继承和发展，共同构成中国特色社会主义理论体系。第三，与时俱进：每一成果都是党在新的实践基础上推进理论创新的产物。", "kind": "self"}}, "video": {"bvid": "BV18T421k7Qr", "p": 1, "t": "只有中国特色社会主义才能发展中国", "dur": "51:24", "from": "政治老师爱政治", "vtop": ["十一届三中全会1978年12月召开，开启改革开放和社会主义现代化建设新时期，是新中国成立以来党的历史上具有深远意义的伟大转折——与社会主义制度确立的“最为广泛而深刻的社会变革”区分开。", "改革开放分三个阶段：起步阶段1978—1992、新阶段1992—2012、全面深化阶段2012年十八大以来；改革是社会主义制度的自我完善和发展，不是根本变革社会主义制度。", "意义记“四个面貌、三个飞跃”：改革开放是党和人民大踏步赶上时代的重要法宝（是“赶上”不是“引领”）、坚持和发展中国特色社会主义的必由之路、决定当代中国命运的关键一招；中华民族迎来从站起来、富起来到强起来的伟大飞跃（是“迎来”不是“实现”）。"], "vsum": "本课讲必修一第三课，分两框：第一框是**伟大的改革开放**，第二框是**中国特色社会主义的创立、发展和完善**。开场先看两组信息：1965年美国的人均GDP是中国的41倍，到1978年变成了76倍，差距还在持续扩大；西德一个露天煤矿年产煤5000万吨只有2000名职工，国内却需要16万名工人；法国一家钢铁厂年产钢350万吨、职工7000人，武汉钢铁公司年产量230万吨却有6.7万人；70年代中美两国农村状况对比也直观显示当时中国人民的生活水平和居住环境严重落后于美国。总之当时经济上濒临崩溃，人民生活温饱尚不能解决，国家已经到了何去何从的重大历史关头。邓小平同志指出，如果现在再不进行改革，我们的现代化事业和社会主义事业都会被葬送。正是在这样的历史关头，我们党在**1978年12月**召开了**十一届三中全会**，开启了改革开放的历程。在十一届三中全会上，首先重新确立了马克思主义的**思想路线、政治路线和组织路线**：思想路线就是否定当时错误的“两个凡是”的观点，重新确立**解放思想、实事求是**；政治路线指的是**以经济建设为中心，实行改革开放**；组织路线指的是在实际上形成了**以邓小平为核心的党中央第二代领导集体**。其次还实现了党和国家工作中心的战略转移，也就是否定了“以阶级斗争为纲”，把党和国家的工作重点转移到**社会主义现代化建设**上来。十一届三中全会开启了改革开放和社会主义现代化建设的新时期，实现了新中国成立以来党的历史上具有**深远意义的伟大转折**。这里要注意区分：之前第二课讲到，社会主义制度的确立是中华民族有史以来最为广泛而深刻的社会变革，而改革开放则是中华人民共和国成立以来党的历史上具有深远意义的伟大转折。十一届三中全会之后，中国正式进入了改革开放时期。那到底什么是改革开放呢？首先**改革**指的是在**坚持社会主义制度的前提下**，调整生产关系同生产力、上层建筑同经济基础之间不相适应的环节，它既包括经济体制的改革，也就是要把当时高度集中的**计划经济体制**改革为**社会主义市场经济体制**，还包括政治方面的改革，包括发展民主、加强法治等。邓小平同志指出，改革是**中国的第二次革命**。改革是社会主义制度的一种**自我完善与发展**，而不是要从根本上变革或者说推翻社会主义制度。下面是**开放**，开放指的是**对外开放**，它是加快我国现代化建设的必然选择，也是必须长期坚持的一项**基本国策**。所以改革开放可以简单概括为**对内改革与对外开放**，无论从时间还是内容上，改革与开放都不是完全孤立的，它们之间是相辅相成、密不可分的。改革开放的进程可以分为**三个阶段**。第一个阶段称为**起步阶段**，指的是**1978年到1992年**。在对内改革方面，十一届三中全会之后，农村改革率先取得突破，**家庭联产承包责任制**推行，乡镇企业迅速发展。1978年冬，安徽凤阳县小岗村18户村民在一份分田到户的秘密契约上按下鲜红的手印，实行农业“大包干”，18枚红手印把农村原有的生产合作社变更为家庭联产承包责任制，最终上升为我国农村的**基本经营制度**。家庭联产承包责任制是在**土地公有制**的基础上，将土地长期承包给农民各家各户来使用，由集体经营变为分户自主经营、自负盈亏，当时流行一个顺口溜叫“交够国家的、留足集体的，剩下的全是自己的”。小岗村搞了大包干，第二年粮食产量增加了**四倍**，农民收入增加了**16倍**，村民人均收入从上年的22元跃升到了350元，小岗村一年就越过了温饱线。到1984年，**十二届三中全会**召开，标志着中国改革的重点**从农村转向了城市**，企业改革迈出重要步伐，尤其是国企改革，提出了**政企分开、自负盈亏**，降低国企对国家的依赖。90年代一大批效率低下、管理落后的国企被淘汰、关闭，还引发了一波下岗潮，放在当时是社会的阵痛，但从长远看有利于促进国企效率的提高和国家经济的腾飞。在对外开放方面，**1980年**设立了**深圳、珠海、汕头、厦门四个经济特区**，**1984年**开放了大连、青岛等**14个沿海港口城市**，**1988年**设立海南省、建立海南经济特区，**1990年**开放了上海浦东，1992年开放了沿长江五个城市、17个内陆省会城市，还有东北、西北、西南等一系列沿边城市，至此我国**全方位、多层次、宽领域**的对外开放格局基本形成：全方位指的是对世界所有国家开放；多层次指的是由点到线到面，先开放几个经济特区，此后又开放一批沿海港口城市，沿东南海岸线形成一条线，接着持续开放珠三角、闽南三角、长三角几大区域；宽领域不仅仅是在经济上打开国门，更是涵盖了经济、政治、科技、教育、文化、体育、卫生等众多领域。第二个阶段是**1992年到2012年**，也称为改革开放的**新阶段**，以**1992年邓小平南方谈话**和**党的十四大明确建立社会主义市场经济体制目标**为标志。南方谈话指的是邓小平在1992年年初视察武昌、深圳、珠海、上海等地的谈话，邓小平发表了“**计划经济不等于社会主义，资本主义也有计划；市场经济不等于资本主义，社会主义也有市场，计划与市场都是经济手段**”的重要论述。所以在这一阶段，对内改革完全是围绕着社会主义市场经济这一条主线展开的：在计划经济时代，粮票、布票、电视机票、自行车票都是产物，生产什么、生产多少、卖到哪里都是国家说了算，束缚了企业的手脚。1992年十四大提出建立社会主义市场经济体制的目标之后，1993年党的**十四届三中全会**就建立社会主义市场经济体制进行了部署，到了2003年党的**十六届三中全会**就围绕完善社会主义市场经济体制进行了部署。在对外开放方面，**2001年**中国成功地**加入了世界贸易组织**，标志着我国对外开放进入了一个新的阶段，中国的对外开放由**政策性开放向制度性开放**转变，入世之后中国积极兑现承诺，大幅度降低关税，积极参与国际经济合作和国际分工，加速与国际市场接轨，对外贸易得到了快速发展。**2012年党的十八大**提出了**全面建成小康社会和全面深化改革开放**的目标，于是进入改革开放的第三个阶段，叫做**全面深化阶段**。在对内改革方面，十八大以来党以巨大的政治勇气全面深化改革，打响改革攻坚战，加强改革顶层设计，坚决破除各方面的体制机制弊端，各领域基础性制度框架基本建立，许多领域实现了历史性变革、系统性重塑、整体性重构，新一轮党和国家机构改革全面完成，**中国特色社会主义制度更加成熟更加定型**，国家治理体系和治理能力现代化水平明显提高，比如十八大以来国家在反腐败领域坚持刀刃向内、重拳出击、保持高压态势。在对外开放方面，实行更加积极主动的开放战略，构建面向全球的高标准自由贸易区网络，加快推进自由贸易试验区、海南自由贸易港建设，共建“**一带一路**”成为深受欢迎的国际公共产品和国际合作平台，形成更大范围、更宽领域、更深层次对外开放格局。所以在全面深化阶段，对内持续深化改革，对外继续扩大开放，改革开放不断向纵深推进。其实在刚才每个阶段提到的代表性事件和重要会议中，经常出现**三中全会**：党的全国代表大会**每五年举行一次**，选举产生中央委员会，该届中央委员会召开的第三次全体会议就是三中全会。三中全会多出重大决策，尤其是经济改革的决策居多；改革开放以来党的历届三中全会都讨论深化改革问题，释放的重要信号就是我们党坚定不移高举改革开放伟大旗帜，坚定不移坚持党的十一届三中全会以来的理论、路线、方针和政策。课上两道练习题：第一题，关于中国故事的内容对应正确的是B选项——五四运动产生了马克思主义中国化的首个理论成果是错误的，首个理论成果指的是**毛泽东思想**；“半条被子”承载中国共产党的初心使命、执政为民，前半句正确但后半句错误，半条被子说的是革命过程中红军把自己的一条被子分给了人民群众半条，当时共产党还没有实现执政；“大包干”开启了波澜壮阔的改革开放是正确的，大包干说的是1978年的农村改革，开始实行家庭联产承包责任制；“一带一路”体现中国特色社会主义道路新发展新实践也是正确的。第二题，某校搜集的资料是1978年党召开十一届三中全会作出改革开放的决策，2013年党召开十八届三中全会系统设计全面推进改革，到2018年党召开十九届三中全会部署推进党和国家机构改革，符合这次研究性学习主题的是A选项——从1978年到2018年，关于改革这一主题一直没有停止、一直在深化，所以“实践永无止境，改革开放也永无止境”正确，改革就是对社会主义制度的自我完善与发展也正确；“从根本上改变了中国社会的发展方向”这是新中国成立的意义，新中国成立是在1949年，不符合主题；“中华民族有史以来最为广泛而深刻的社会变革”指的是三大改造确立社会主义制度，发生在1956年，也不符合主题。现在来总结改革开放的**意义**。首先通过40多年的改革开放，极大地改变了**四个面貌**：第一改变了**中国的面貌**，铸就了中国特色社会主义的生机与活力；第二改变了**中华民族的面貌**，提升了中华民族在国际上的地位和影响；第三改变了**中国人民的面貌**，满足了中国人民追求美好生活的愿望和期待；第四改变了**中国共产党的面貌**，中国共产党在今天已经成为了党员人数超过**九千万**的世界最大的执政党，还锻造了中国共产党驾驭市场经济的能力和本领。此外，自1978年实行改革开放之后，我国的经济实力在世界的排名不断前进，我国已经一跃成为**世界第二大经济体**，并且也是**制造业第一大国**。改革开放之后，全国居民人均可支配收入由**171元**增加到了**2.6万元**，贫困人口累计减少**7.4亿人**，建成了世界最大的社保体系，成为了世界上最有安全感的国家之一。所以说改革开放迎来了**三个飞跃**：中华民族迎来了**从站起来、富起来到强起来**的伟大飞跃，注意这里是**迎来**了而不是实现了；改革开放之后，中国共产党围绕中国特色社会主义这一主题，在实践中不断探索，取得了邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想等一系列重大理论创新成果，中国特色社会主义迎来了**从创立、发展到完善**的伟大飞跃；中国人民迎来了**从温饱不足到小康富裕**的伟大飞跃。今天的中华民族正以崭新的姿态屹立于世界的东方。所以我们说改革开放是党和人民**大踏步赶上时代的重要法宝**，注意是赶上时代而不是引领时代；还是**坚持和发展中国特色社会主义的必由之路**；是**决定当代中国命运的关键一招**，是决定实现**两个一百年**奋斗目标、实现中华民族伟大复兴的关键一招。2018年是改革开放40周年，党中央在北京人民大会堂隆重举行了庆祝改革开放四十周年大会，表彰一批为改革开放作出杰出贡献的个人，授予**改革先锋**称号，代表人物有国防科技事业改革发展的重要推动者**于敏**、公共卫生事件应急体系建设的重要推动者**钟南山**、杂交水稻研究的开创者**袁隆平**等，他们无不拥护中国共产党的领导和我们的社会主义制度，拥护改革开放，敢于冲破思想观念的束缚，敢于啃硬骨头、敢于涉险滩，爱岗敬业、无私奉献、作风优良。所以说改革开放的成功还得益于中国共产党的坚强领导和人民群众的开拓进取：**中国共产党是改革开放的领导核心**，而**人民是改革开放伟大奇迹的创造者**，是推动改革开放的力量源泉。那么时至今日，我国的改革开放就此完成了吗？当然没有，因为**实践发展永无止境，解放思想永无止境，改革开放也永无止境**，停顿和倒退没有出路；对外开放是中国的基本国策，当今世界是开放的世界，开放带来进步，封闭必然落后，**改革开放只有进行时，没有完成时**，改革开放一直在路上。第一框小结：共学习了两个问题，分别是改革开放的进程和意义；进程上先了解开端十一届三中全会，再分起步阶段、新阶段、全面深化阶段三个阶段及每个阶段的代表性事件；意义上学习了四个方面，概括为四个面貌、三个飞跃、重要法宝必由之路关键一招，以及改革开放永无止境。第二框是**中国特色社会主义的创立、发展和完善**，要学习四个问题：第一，改革开放以来党的全部理论和实践的**主题**是什么、如何理解；第二，中国共产党在实践探索中取得了哪些**重大理论创新成果**，从时间节点、主题、主要内容和历史贡献方面加以把握；第三，改革开放以来我国取得一切成绩和进步的**根本原因**；第四，中国特色社会主义**道路、理论、制度、文化**的重要性以及相互关系。1982年，中国共产党**第十二次全国代表大会**在北京召开，邓小平主持大会开幕式并致开幕词，在开幕词中他指出，我们的现代化建设必须要从中国的实际出发，应该学习和借鉴外国经验，但是绝不能照抄照搬，要把马克思主义的普遍真理同我国的具体实际结合起来，**走自己的路，建设有中国特色的社会主义**，这是我们总结长期历史经验得出的基本结论。所以说，以1982年党的十二大开幕式上邓小平第一次明确提出“走自己的路，建设有中国特色的社会主义”为标志，从此以后党的全部理论创新和实践创新，都是紧紧围绕着这一主题展开的，这一主题也可以简化为**中国特色社会主义**。这一主题的提出促使中国共产党坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，不断推进理论、实践、制度创新，成功开创、坚持和发展了中国特色社会主义。中国特色社会主义在发展过程中取得了**四大理论创新成果**：**邓小平理论**、“**三个代表”重要思想**、**科学发展观**和**习近平新时代中国特色社会主义思想**，这些合起来也被称为**中国特色社会主义理论体系**。这四大理论成果从四个方面回答了时代之问。问题一，我们要走什么样的道路？邓小平理论给出了答案，我们要走的是**中国特色社会主义道路**。这一理论是在十一届三中全会以后逐步形成的，围绕**什么是社会主义以及怎样建设社会主义**的主题，作出了第一次比较系统的回答。在邓小平理论出现之前，当时对社会主义的认识是不全面的：当时认为社会主义就是无产阶级专政、就是公有制，甚至把一些买卖自家鸡蛋的行为都定性为走资本主义道路、定性为挖社会主义的墙角；但按照马克思主义的理论，社会主义应该是人类的理想社会，理想社会最起码物质生活条件应该是富足的，而当时人民生活甚至连温饱都无法解决。所以邓小平对什么是社会主义、怎样建设社会主义的问题作出了回应，比如我们耳熟能详的那句话“**贫穷不是社会主义**”就是邓小平理论所提出的。在主要内容上，作出了把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策，**深刻揭示了社会主义本质**，确立社会主义初级阶段的基本路线，明确提出走自己的路、建设中国特色社会主义，科学回答了建设中国特色社会主义的一系列基本问题，制定了**三步走**战略。这里出现了三个名词，分别是社会主义本质、社会主义初级阶段基本路线以及三步走战略。第一个，**社会主义本质**是**解放生产力、发展生产力，消灭剥削、消除两极分化，最终达到共同富裕**。第二，党在**社会主义初级阶段的基本路线**是领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生、艰苦创业，为把我国建设成为**富强民主文明和谐美丽的社会主义现代化强国**而奋斗，也可以简称为**一个中心、两个基本点**。**三步走战略**是指：第一步在1981年到1990年实现国民生产总值比1980年翻一番，解决人民的温饱问题，这在20世纪80年代末就已经基本实现；第二步是1991年到20世纪末，国民生产总值再增长一倍，人民生活达到小康水平，这一目标也已经实现，在2000年我们就达到了**总体小康**；第三步目标到21世纪中叶基本实现现代化，人均国民生产总值达到中等发达国家水平，人民过上比较富裕的生活，这也是我们现在继续为之奋斗的目标。在历史贡献上，邓小平理论成功地**开创了中国特色社会主义**。问题二，建设什么样的党？“三个代表”重要思想给出了答案。它是在**1989年十三届四中全会以后**确立的，因为“三个代表”的内容提到，中国共产党要始终代表**中国先进生产力的发展要求**，始终代表**中国先进文化的前进方向**，始终代表**中国最广大人民的根本利益**。所以说它加深了对什么是社会主义、怎样建设社会主义和建设什么样的党、怎样建设党的认识。在主要内容上，确立了社会主义市场经济体制的改革目标和基本框架，确立了社会主义初级阶段**公有制为主体、多种所有制经济共同发展的基本经济制度**和**按劳分配为主体、多种分配方式并存的分配制度**，开创全面改革开放新局面，推进党的建设新的伟大工程。在历史贡献上，当时1989年正是东欧剧变、苏联解体，是世界社会主义出现严重曲折的时候，在国内外形势十分复杂、世界社会主义出现严重曲折的严峻考验面前，**捍卫了中国特色社会主义**，并且成功把中国特色社会主义**推向了21世纪**。问题三，新形势下实现什么样的发展、怎样发展？**科学发展观**给出了答案，它确立于**2002年的党的十六大以后**。科学发展观**第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾**。在主要内容上，强调坚持以人为本、全面协调可持续发展，着力保障和改善民生，促进社会公平正义，推进党的执政能力建设和先进性建设。在历史贡献上，成功在新形势下**坚持和发展了中国特色社会主义**；十六大之后的2002到2012这十年间，我国的国内生产总值有了大幅度的提高，经济总量也从世界第六位上升到世界第二位，国家面貌发生了新的历史性变化。问题四，面对党情、国情、世情的重大变化，处于新时代的我国应该怎么走下去？**习近平新时代中国特色社会主义思想**给出了回答，它是在**2012年党的十八大以来**确立的。当时中国国情的变化最大的状况就是**社会主要矛盾发生了变化**，变成了**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。以习近平同志为主要代表的中国共产党人，坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，坚持毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，深刻总结并充分运用党成立以来的历史经验，从新的实际出发，创立了习近平新时代中国特色社会主义思想。这一思想深刻地回答了**新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义**的重大课题，比如提出了“**五位一体**”总体布局、“**四个全面**”战略布局等一系列新理念新思想新战略。在历史贡献上，这一思想指导并推动党和国家事业取得历史性成就、发生历史性变革，使中国特色社会主义**进入了新时代**。关于这四大理论创新成果，要重点把握它的主题以及历史贡献：邓小平理论开创了中国特色社会主义，“三个代表”重要思想捍卫了中国特色社会主义并成功把它推向了21世纪，科学发展观又在新形势下坚持和发展了中国特色社会主义，习近平新时代中国特色社会主义思想推动中国特色社会主义进入了新时代，其实这一过程也就是中国特色社会主义**从创立到发展再到完善**的过程。课上时代课题排序练习：下列时代课题按照时间先后排列正确的是B选项——“走自己的路，建设有中国特色的社会主义”是邓小平理论在党的十二大上提出的；“建设什么样的党、怎样建设党”是“三个代表”重要思想在1989年之后逐步确立的；“新形势下实现什么样的发展、怎样发展”是科学发展观所回答的时代课题，时间是2002年到2012年；“新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义”是习近平新时代中国特色社会主义思想所回答的时代课题，时间是2012年之后。改革开放以来，我国在方方面面都取得了显著的成绩和进步：经济上我国现在是世界第二大经济体；政治上民主法治不断健全，国家治理体系和治理能力越来越现代化；文化上中国软实力备受全球关注，孔子学院开到了世界各地，越来越多的外国人也开始学习汉语；社会生活上人民从满足物质生活的需要向美好生活的目标迈进；生态文明建设上我们秉持“**绿水青山就是金山银山**”的理念，持续推进美丽中国建设。而以上经济、政治、文化、社会、生态文明五个方面成绩和进步的取得，**根本原因**就在于中国共产党带领中国人民**开辟了中国特色社会主义道路**、形成了**中国特色社会主义理论体系**、确立了**中国特色社会主义制度**、发展了**中国特色社会主义文化**。在这**四个自信**当中，**中国特色社会主义道路是必由之路**，**中国特色社会主义理论体系是行动指南**，**中国特色社会主义制度是中国一切发展进步的根本制度保障**，**中国特色社会主义文化是激励我们不断前进的精神力量**。下面具体研究这四个自信。第一，**中国特色社会主义道路**，它的主要内容是：在中国共产党领导下，立足基本国情，以经济建设为中心，坚持四项基本原则，坚持改革开放，解放和发展社会生产力，建设社会主义市场经济、社会主义民主政治、社会主义先进文化、社会主义和谐社会、社会主义生态文明，这叫做“五位一体”，促进人的全面发展，逐步实现全体人民共同富裕，建设富强民主文明和谐美丽的社会主义现代化强国。因为道路决定命运，中国特色社会主义道路既坚持了科学社会主义的基本原理，还具有鲜明的中国特色，它承载了几代中国共产党人的理想和探索，寄托了无数仁人志士的夙愿和期盼，凝聚了亿万人民的奋斗和牺牲，是党和人民历经千辛万苦、付出极大代价才开辟出来的道路，它也彻底改变了中国人的命运，使中国用70年的时间就走过了西方国家两三百年的工业化现代化道路，使中国一跃成为世界第二大经济体，创造了人类社会发展史上惊天动地的奇迹。所以历史告诉我们，既不要走**封闭僵化的老路**，也不要走**改旗易帜的邪路**，中国特色社会主义道路是实现社会主义现代化、创造人民美好生活的**必由之路**，是一条既适合中国国情、又适合时代发展要求、并且取得巨大成功的唯一正确道路。第二，**中国特色社会主义理论体系**，具体来说包括邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想，这套理论最大的特点是**实践性和创新性**，不是教条式地照搬马克思列宁主义，而是马克思列宁主义的中国化，是我们党从新的实践和时代特征出发，坚持和发展马克思主义，科学回答了建设中国特色社会主义的一系列基本问题，实现了马克思主义中国化时代化新的飞跃。十八大以来，党勇于理论探索和创新，深化对共产党执政规律、社会主义建设规律和人类社会发展规律的认识，取得重大理论创新成果，集中体现为习近平新时代中国特色社会主义思想；习近平新时代中国特色社会主义思想把中国特色社会主义理论体系推到了一个新的高度，牢牢把握了人民群众对美好生活的需要，贯穿了以人民为中心的初心和价值追求，具有跨时代意义和强大的真理力量。第三，**中国特色社会主义制度**，它是党和人民在长期实践探索中形成的科学制度体系，具体来说，它包括**人民代表大会制度**这一根本政治制度和三项基本政治制度，也包括中国特色社会主义法律体系，还包括国有制为主体、多种所有制经济共同发展的基本经济制度，以及建立在上述制度基础上的经济体制、政治体制、文化体制、社会体制等等，所以说是一个庞大的制度体系。我国国家治理一切工作和活动都依照中国特色社会主义制度展开，我国国家治理体系和治理能力就是中国特色社会主义制度及其执行能力的集中体现。而**制度优势是一个国家的最大优势，制度竞争是国家间最根本的竞争**，制度稳则国家稳。中国特色社会主义制度在实现广泛民主的基础上形成了正确的集中，具有**举国体制**优势，能够**集中力量办大事**，所以在脱贫攻坚、在抗击疫情、在发展航天事业的过程中，我们才能形成共同推动中国发展进步的强大力量。所以说中国特色社会主义制度和治理体系，是以马克思主义为指导、植根中国大地、具有深厚中华文化根基、深得人民拥护的制度和治理体系，是具有强大生命力和巨大优越性的制度和治理体系，是能够持续推动国家进步和发展、确保中华民族实现伟大复兴的制度和治理体系，所以我们有足够的理由充满**制度自信**。第四，**中国特色社会主义文化**，从形成来看，源自于中华民族五千多年文明历史所孕育的**中华优秀传统文化**，熔铸于党领导人民在革命、建设、改革中创造的**革命文化和社会主义先进文化**，植根于中国特色社会主义的伟大实践。发展中国特色社会主义文化就是以马克思主义为指导，坚守中华文化立场，立足当代中国现实，结合当今时代特点，发展**面向现代化、面向世界、面向未来的，民族的、科学的、大众的社会主义文化**，推动社会主义精神文明和物质文明协调发展。我们的文化有着丰富的内涵，由中华优秀传统文化、革命文化和社会主义先进文化共同组成。世界四大文明当中，只有中华文明是延续的。传统文化中，**大禹治水、愚公移山、精卫填海、女娲补天、夸父追日**讲的就是一心为公、自强不息。中国共产党人继承了这种精神，在战争年代抛头颅、洒热血，为了民族解放甘愿献出生命；社会主义建设年代，**雷锋、焦裕禄、王进喜、钱学森**怀着满腔热血投入到祖国的建设事业上。这种一心为国家、为民族奋斗的精神，正是中华文化之魂，具有强大的力量。所以说中国特色社会主义文化激荡着中华民族最深沉的精神追求，代表着中华民族独特的精神标识，是激励全党、全国各族人民奋勇前进的强大精神力量。并且，这**四个自信**之间并不是孤立的，他们是相互联系、相互作用，统一于中国特色社会主义伟大实践的。中国共产党从1921年成立至今，已经走过了一百多年的历史，党带领中国人民实现了中国的发展与壮大，让世界看到了可望而不可及的中国风骨、中国力量。所以说当今世界要说哪个政党、哪个国家、哪个民族能够自信的话，那中国共产党、中华人民共和国、中华民族是最有理由自信的。课上两道练习题：第一题，下列选项与四个自信对应正确的是A选项——道路自信“以中国式现代化全面推进中华民族伟大复兴”是正确的；把马克思主义基本原理同中华优秀传统文化相结合应该是理论自信，不是制度自信；坚持和完善“一国两制”、推进祖国统一属于制度自信，不是理论自信；坚持“两个毫不动摇”、构建高水平社会主义市场经济体制，经济制度也属于制度自信，不是文化自信。第二题，2023年12月甘肃发生地震造成重大人员伤亡，地震发生之后，财政部、应急管理部紧急向甘肃、青海预拨中央自然灾害救灾资金2亿元，国家综合性消防救援队伍共出动了一千多名消防救援人员赴灾区救援，国家卫健委紧急调派专家赶赴甘肃，组织临近甘肃的三支国家紧急医学救援队伍赴灾区支援，材料表明了中国特色社会主义制度，答案是B选项——这是在人民遇到巨大灾难的时候，多个不同的行为主体紧急集结、奔赴灾区，所以体现了能够集中人力、物力、财力办大事，也体现了在社会主义国家之下，是把人民的生命财产安全摆在第一位的，具有巨大的优越性。最后课堂小结：关于第三课第二框，中国特色社会主义的创立、发展和完善，我们共学习了两个问题，第一是改革开放以来党的全部理论和实践的主题，第二是中国特色社会主义道路、理论、制度和文化。首先关于党的全部理论和实践的主题，先明确是什么，简单概括就是中国特色社会主义；然后中国特色社会主义在发展的过程中还取得了四个重大的理论创新成果，分别是邓小平理论、“三个代表”重要思想、科学发展观以及习近平新时代中国特色社会主义思想，还要明确各自的时间节点、历史贡献、主要内容等。第二，围绕中国特色社会主义道路、理论、制度和文化，也就是四个自信来学习：首先要知道，这就是改革开放以来我国取得一切成就和进步的根本原因；其次还要分别掌握道路自信、理论自信、制度自信、文化自信以及他们之间的内在联系。", "vtech": [["“伟大转折”与“社会变革”别混", "看到“最”开头的定性句先问对象：十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折；社会主义制度的确立才是中华民族有史以来最为广泛而深刻的社会变革（三大改造，1956年）；“从根本上改变中国社会的发展方向”是新中国成立（1949年）的意义，不是改革开放。"], ["改革三阶段先定年份再想事件", "看到阶段题先定年份：起步阶段1978—1992、新阶段1992—2012、全面深化阶段2012年十八大以来；再把事件按年份落位：1980年四个经济特区、1984年14个沿海港口城市、1992年南方谈话、2001年加入世贸组织，1993年十四届三中全会部署建立市场经济体制、2003年十六届三中全会部署完善。"], ["意义题抓“四个面貌、三个飞跃”", "看到意义题先默写框架：四个面貌是中国、中华民族、中国人民、中国共产党的面貌；三个飞跃是中华民族从站起来、富起来到强起来，中国特色社会主义从创立、发展到完善，中国人民从温饱不足到小康富裕；注意“迎来”不是“实现”，“赶上时代”不是“引领时代”。"], ["四大理论成果按时间排历史贡献", "看到理论成果题先按时间排：邓小平理论开创了中国特色社会主义，“三个代表”重要思想捍卫了它并成功把它推向21世纪，科学发展观在新形势下坚持和发展了它，习近平新时代中国特色社会主义思想推动它进入新时代；时代课题排序也先定时间：十二大（1982年）—1989年后—2002—2012年—2012年十八大后。"]], "vgaokao": []}}, "pol_p007": {"name": "中国特色社会主义进入新时代", "sec": 7, "secTitle": "第四课 只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴", "page": 42, "desc": "新时代的历史方位；社会主要矛盾变化了，但基本国情和国际地位「两个没有变」。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p006"], "next": ["pol_p008"], "content": {"intro": "党的十八大以来，中国发展站到新的历史起点上，中国特色社会主义进入**新时代**。新时代最显著的判断是：我国社会主要矛盾已经转化为**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。==矛盾变了，但我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国是世界最大发展中国家的国际地位没有变。==", "learn": [{"h": "新时代意味着什么", "p": "中国特色社会主义进入新时代，意味着近代以来久经磨难的中华民族迎来了从站起来、富起来到**强起来**的伟大飞跃，迎来了实现中华民族伟大复兴的光明前景；意味着科学社会主义在 21 世纪的中国焕发出强大生机活力；意味着中国特色社会主义道路、理论、制度、文化不断发展，拓展了发展中国家走向现代化的途径。新时代是承前启后、继往开来、在新的历史条件下继续夺取中国特色社会主义伟大胜利的时代。"}, {"h": "社会主要矛盾的变化", "p": "党的十九大作出重大政治论断：我国社会主要矛盾已经转化为**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。变化的原因是：我国社会生产力水平总体上显著提高，社会生产能力在很多方面进入世界前列，人民生活水平显著提高，对美好生活的向往更加强烈，需求呈现多样化多层次多方面的特点；同时，发展不平衡不充分的问题更加突出，成为满足人民日益增长的美好生活需要的主要制约因素。"}, {"h": "变与不变要一起讲", "p": "主要矛盾的变化是关系全局的历史性变化，对党和国家工作提出了许多新要求。但是，我国社会主要矛盾的变化**没有改变**我们对我国社会主义所处历史阶段的判断：我国仍处于并将长期处于**社会主义初级阶段**的基本国情没有变，我国是世界最大发展中国家的国际地位没有变——这就是「**两个没有变**」。全党要牢牢把握社会主义初级阶段这个基本国情，牢牢立足社会主义初级阶段这个最大实际。"}, {"h": "新时代的两步走安排", "p": "从党的十九大到二十大，是「两个一百年」奋斗目标的历史交汇期。综合分析国际国内形势和我国发展条件，党把全面建成社会主义现代化强国的进程分两个阶段：从 2020 年到 2035 年，**基本实现社会主义现代化**；从 2035 年到本世纪中叶，把我国建成富强民主文明和谐美丽的**社会主义现代化强国**。"}], "pitfalls": ["因为主要矛盾变化就断言「我国已经不再是社会主义初级阶段」——这是最经典的错误选项。", "把新时代的主要矛盾表述写错：是「美好生活需要」与「不平衡不充分的发展」，不是旧表述的「物质文化需要」与「落后的社会生产」。", "把「强起来」归到改革开放初期——站起来（1949）、富起来（改革开放）、强起来（新时代）各有对应阶段。"], "basics": [{"q": "中国特色社会主义新时代，我国社会主要矛盾是（ ）", "opts": ["人民日益增长的物质文化需要同落后的社会生产之间的矛盾", "人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾", "无产阶级和资产阶级之间的矛盾", "先进的社会制度同落后的生产力之间的矛盾"], "ans": 1, "why": "党的十九大报告的规范表述，注意与改革开放初期表述（选项 A，那是主要矛盾的旧表述）区分。"}, {"q": "我国社会主要矛盾发生变化，但没有变的是（ ）", "opts": ["社会生产力水平", "人民生活水平", "我国仍处于并将长期处于社会主义初级阶段的基本国情", "人民群众的需求结构"], "ans": 2, "why": "「两个没有变」：社会主义初级阶段的基本国情没有变，世界最大发展中国家的国际地位没有变。"}, {"q": "从 2035 年到本世纪中叶，我国的发展目标是（ ）", "opts": ["基本实现社会主义现代化", "建成富强民主文明和谐美丽的社会主义现代化强国", "总体达到小康水平", "解决人民温饱问题"], "ans": 1, "why": "两步走：2035 年基本实现社会主义现代化；本世纪中叶建成社会主义现代化强国。"}], "apply": [{"q": "材料：某同学在作文中写道：「主要矛盾都变了，可见我国已经告别社会主义初级阶段，跨入高级阶段了。」这句话的错误在于（ ）", "opts": ["否认了社会主要矛盾已经发生变化", "把社会主要矛盾的变化等同于社会主义所处历史阶段的变化", "夸大了发展不平衡不充分的问题", "低估了我国社会生产力水平"], "ans": 1, "why": "教材明确指出：社会主要矛盾的变化，没有改变我们对我国社会主义所处历史阶段的判断，基本国情和国际地位「两个没有变」。"}, {"q": "材料：今天，人们对「美好生活」的期待不再只是吃饱穿暖，还有更好的教育、更稳定的工作、更满意的收入、更优美的环境；同时，城乡、区域之间发展差距仍然存在。这段材料集中反映了（ ）", "opts": ["我国社会生产已经绝对过剩", "人民需要升级与发展不平衡不充分成为主要制约因素", "人民的需要无法被满足", "我国已经不存在发展问题"], "ans": 1, "why": "前半句对应「美好生活需要」升级，后半句对应「不平衡不充分的发展」——这正是新时代社会主要矛盾的两个方面。"}], "case": {"q": "材料：党的十九大闭幕后，一家报纸评论说：主要矛盾的转化是「关系全局的历史性变化」；但同时强调，作出这一判断绝不意味着可以脱离社会主义初级阶段这个最大实际去盲目冒进。结合本框知识，谈谈应如何理解主要矛盾转化中的「变」与「不变」。", "a": "「变」：随着社会生产力显著提高和人民需求的升级，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，党和国家的工作重心、发展思路必须随之调整，着力解决发展不平衡不充分的问题。「不变」：主要矛盾的变化没有改变社会主义所处的历史阶段——我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国是世界最大发展中国家的国际地位没有变。坚持「变」与「不变」的统一，才能既积极进取又脚踏实地，不犯超越阶段的错误。"}, "advance": {"q": "进入新时代，为什么仍然必须牢牢坚持以经济建设为中心？", "a": "第一，我国仍处于并将长期处于社会主义初级阶段，发展仍是解决我国一切问题的基础和关键，主要矛盾的解决最终要靠发展。第二，我国是世界最大发展中国家，发展不平衡不充分的问题仍然突出，只有持续解放和发展社会生产力，才能不断满足人民日益增长的美好生活需要。第三，党的基本路线是国家的生命线、人民的幸福线，以经济建设为中心是兴国之要。因此，新时代不是不要发展，而是要实现更高质量、更有效率、更加公平、更可持续、更为安全的发展。", "kind": "self"}}, "video": {"bvid": "BV1YE421A7Qj", "p": 1, "t": "只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴", "dur": "83:10", "from": "政治老师爱政治", "vtop": ["新时代我国社会的主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾——“变”的是主要矛盾，“不变”的是社会主义初级阶段的基本国情和世界上最大的发展中国家的国际地位。", "中国梦的内涵是国家富强、民族振兴、人民幸福：国家富强是基础，民族振兴是核心内容，人民幸福是奋斗目标；中国梦归根到底是人民的梦。", "十个明确讲“是什么”（理论层面），十四个坚持讲“怎么做”（实践层面、基本方略）——两者别搞反；基本方略是十四个坚持，不是十个明确。"], "vsum": "本课讲第四课，只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴，讲的是我们国家 2012 年进入新时代之后的这段历史，分三框。第一框是中国特色社会主义进入新时代。先看什么是新时代：2017 年党的十九大作出判断，经过长期努力，中国特色社会主义进入了新时代，这是我国发展新的历史方位；但进入新时代是从 2012 年党的十八大开始算起的。**新时代的科学内涵**可以从五个方面把握：第一，从伟大事业看，是承前启后、继往开来，在新的历史条件下继续夺取中国特色社会主义伟大胜利的时代；第二，从奋斗目标看，是决胜全面建成小康社会、进而全面建设社会主义现代化强国的时代，其中决胜全面建成小康社会是第一个百年奋斗目标，全面建设社会主义现代化强国是第二个百年奋斗目标；第三，从人民的期待看，是全国各族人民团结奋斗、不断创造美好生活、逐步实现全体人民共同富裕的时代；第四，从历史使命看，是全体中华儿女勠力同心、奋力实现中华民族伟大复兴中国梦的时代；第五，从世界意义看，是我国不断为人类作出更大贡献的时代。中国特色社会主义进入新时代有重大意义：历史意义上，意味着近代以来久经磨难的中华民族迎来了从站起来、富起来到强起来的伟大飞跃，迎来了实现中华民族伟大复兴的光明前景——注意是“迎来了”而不是“实现了”；政治意义上，意味着科学社会主义在 21 世纪的中国焕发出强大生机活力，在世界上高高举起了中国特色社会主义伟大旗帜；世界意义上，中国走出了一条中国式现代化道路，打破了发展中国家对西方国家现代化的路径依赖，为他们树立了榜样、提供了全新选择。第二个问题是新时代我国社会的主要矛盾。党对社会主要矛盾的认识有过三次：1956 年党的八大、1981 年党的十一届六中全会、2017 年党的十九大。新时代我国社会的主要矛盾是**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。转变的原因有两方面：从人民需求看，由原来的物质文化需要发展为美好生活需要，要求更多、更高、更广泛；从社会生产看，社会生产力水平显著提高，社会生产能力在很多方面进入了世界前列，再说“落后的社会生产”已经不合适，不平衡的发展包括东中西区域之间、城乡之间的不平衡，不充分的发展体现在关键核心技术上的短板。如何解决主要矛盾，要把握“变与不变”：变的是主要矛盾的变化，人民日益增长的美好生活需要是合理的、正当的，不能让人民群众降低需求标准，只能从不平衡不充分的发展角度去解决，要在继续推动发展的基础上，着力解决好发展不平衡不充分的问题，大力提升发展的质量和效益；不变的有两个，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国作为世界上最大的发展中国家的国际地位没有变。所以要牢牢把握社会主义初级阶段这个基本国情，牢牢立足这个最大实际，牢牢坚持党的基本路线——以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生、艰苦创业，为把我国建设成为富强民主文明和谐美丽的社会主义现代化强国而奋斗。第三个问题是新时代坚持和发展中国特色社会主义要一以贯之：从历史进程看，中国特色社会主义是在改革开放四十多年的伟大实践中得来的，是在新中国成立七十多年的持续探索中得来的，是党领导人民进行伟大社会革命一百年的实践中得来的，是在近代以来中华民族由衰到盛一百八十多年的历史进程中得来的；中国特色社会主义是实现中华民族伟大复兴的必由之路；每一个人都是新时代的见证者、开创者、建设者，要不忘初心、牢记使命，以永不懈怠的精神状态和一往无前的奋斗姿态，一以贯之坚持和发展中国特色社会主义。第二框是实现中华民族伟大复兴的中国梦。**中国梦**这一概念的提出是在 2012 年 11 月 29 日，习近平总书记来到中国国家博物馆参观“复兴之路”展览并发表重要讲话，其中首次提出实现中华民族伟大复兴就是中华民族近代以来最伟大的梦想。“复兴”就是再一次强大兴盛起来：古代中华民族创造过辉煌灿烂的文明，科学技术曾经长期处于世界前列，有文明于世的四大发明；进入近代以来，由于闭关自守和没落的封建专制制度，以及西方列强的入侵，逐步沦为半殖民地半封建社会，遭受了前所未有的苦难。中国梦的内涵有三层：**国家富强**是中国梦的实现基础，中国梦首先是强国梦；**民族振兴**是中国梦的核心内容；**人民幸福**是中国梦的奋斗目标，国家富强和民族振兴最终的落脚点都是为了人民幸福；三者分别代表国家的追求、民族的向往和人民的期盼，融为一体，体现了中华民族和中国人民的整体利益。如何实现中国梦，从三个角度回答：从中国梦与人民的关系看，中国梦归根到底是人民的梦，人民是中国梦的主体，是中国梦的创造者和享有者，要紧紧依靠人民来实现，不断为人民造福；从中国梦与中华儿女的关系看，中国梦是国家的梦、民族的梦，同时也是每一个中华儿女的梦，国家好、民族好，大家才会好，要把人生理想融入国家和民族的伟大梦想之中，把小我融入大我，敢于有梦、勇于追梦、勤于圆梦；从中国梦与世界梦的关系看，中国梦与世界人民的梦想息息相通，中国一心一意办好自己的事，实现国家发展和稳定，既是对自己负责，也是为世界做贡献，中国维和部队是全球执行维和任务最多的国家。接下来是中国共产党的初心和使命：2017 年 10 月 18 日，习近平同志在党的十九大报告中说，中国共产党人的初心和使命就是**为中国人民谋幸福、为中华民族谋复兴**。为了实现中华民族伟大复兴的伟大梦想，必须进行**伟大斗争**（包括反腐败斗争、意识形态领域的斗争、反分裂斗争、维护国家利益的斗争等）、推进**党的建设新的伟大工程**、推进**中国特色社会主义伟大事业**。**四个伟大**之间紧密联系、相互贯通、相互作用，共同贯穿于新时代中国特色社会主义的发展过程，但各有侧重：伟大梦想是目标，伟大斗争是动力，深入推进党的建设这一新的伟大工程是保证，推进中国特色社会主义事业这一伟大事业是改革开放以来党的全部理论和实践的主题；在四个伟大中起决定性作用的是党的建设新的伟大工程。办好中国的事情关键在党，没有中国共产党的领导，民族复兴必然是空想；要更加自觉地增强**四个自信**——中国特色社会主义道路自信、理论自信、制度自信、文化自信，既不走封闭僵化的老路，也不走改旗易帜的邪路。第三个问题是分两步走建成社会主义现代化强国：1987 年召开的十三大明确提出了三步走战略，前两步已经完成，第三步的目标是到 21 世纪中叶基本实现现代化；而党的十九大明确了新时代中国特色社会主义发展的战略安排，可以简称为两步走：第一个阶段从 2020 年到 2035 年，在全面建成小康社会的基础上，再奋斗 15 年，基本实现社会主义现代化；第二个阶段从 2035 年到本世纪中叶，在基本实现现代化的基础上，再奋斗 15 年，把我国建成富强民主文明和谐美丽的社会主义现代化强国。如何建成，从国家角度要牢牢把握坚持和加强党的全面领导等重大原则，增强忧患意识，坚持底线思维；要抓住大有可为的历史机遇期；从青年角度，青年兴则国家兴，青年强则国家强，广大青年要坚定理想信念、志存高远、脚踏实地，在实现中国梦的生动实践中放飞青春梦想。第三框是习近平新时代中国特色社会主义思想，分上下两集。上集先讲这一思想回答的时代课题：新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义，建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国，建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党。然后讲这一思想产生的背景。国际背景是：世界进入新的动荡变革期，世界经济复苏乏力，逆全球化思潮抬头，单边主义、保护主义明显上升，世界需要中国理念、中国智慧、中国方案；中国发挥着世界和平的建设者、全球发展的贡献者、国际秩序的维护者的重要作用，构建人类命运共同体的理念被写入了联合国大会的相关决议。国内背景包括四个方面：第一，中华民族伟大复兴进入关键时期，社会生产力水平总体上显著提高，比历史上任何时期都更接近、更有能力、更有信心实现中华民族伟大复兴的目标；第二，中国式现代化拓展推进，中国仅用短短七十多年的时间，在发展的很多方面走过了西方发达国家上百年甚至数百年的资本主义现代化发展历程，创造了世所罕见的经济快速发展和社会长期稳定两大奇迹，中国式现代化是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，是人与自然和谐共生的现代化，是走和平发展道路的现代化；第三，科学社会主义的发展，20 世纪 80 年代末 90 年代初东欧剧变、苏联解体，世界社会主义运动的发展出现了严重的曲折，但中国用自己的发展成果证明了“中国崩溃论”的崩溃和“社会主义失败论”的失败；第四，党的自我革命开辟新的境界，正是在党不断实现自我净化、自我完善、自我革新、自我提高，以伟大自我革命引领伟大社会革命的过程中创立并不断丰富发展的。下集讲这一思想的主要内容，包括**十个明确**、**十四个坚持**和十三个方面成就。**十个明确**是这一思想最为核心关键的组成部分，是支撑习近平新时代中国特色社会主义思想的四梁八柱，集中反映着我们党对科学社会主义在当今时代的理论思考和理论贡献。其中第一明确是坚持和发展中国特色社会主义的总任务是实现社会主义现代化和中华民族伟大复兴，在全面建成小康社会的基础上，分两步走在本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国，以中国式现代化推进中华民族的伟大复兴；第八明确是党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，把人民军队建设成为世界一流军队；第九明确是中国特色大国外交要服务民族复兴、促进人类进步，推动建设新型国际关系、推动构建人类命运共同体；第十明确是全面从严治党的战略方针，提出新时代党的建设总要求，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争，以伟大自我革命引领伟大社会革命。**十四个坚持**是坚持和发展中国特色社会主义的基本方略，涵盖坚持党的领导和五位一体总体布局、四个全面战略布局，涵盖国防和军队建设、维护国家安全、对外战略，是实现两个一百年奋斗目标、实现中华民族伟大复兴中国梦的路线图和方法论。要注意区分：十个明确讲的是“是什么”的问题，侧重于理论层面的高度概括；十四个坚持讲的是“怎么做”的问题，侧重于在实践层面如何展开，两者体现了理论与实践的结合、认识论与方法论相统一。十三个方面成就是指 2021 年党的十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》，从 13 个方面分领域总结了新时代党和国家事业取得的历史性成就、发生的历史性变革。最后是这一思想的地位和作用：这一思想实现了马克思主义中国化时代化新的飞跃，是当代中国的马克思主义，是 21 世纪的马克思主义，是中华文化和中国精神的时代精华；它是马克思主义中国化的最新成果——注意是“最新成果”而不是“最终成果”；在当代中国，坚持和发展习近平新时代中国特色社会主义思想，就是真正坚持和发展马克思主义，就是真正坚持和发展科学社会主义。易混易错提醒：中国特色社会主义最本质的特征是党的领导；基本方略是十四个坚持，不是十个明确；要以党的自我革命引领伟大社会革命，顺序不能反；改革开放前三十年是探索、是铺垫，后三十年是继承、是发展，两者不能割裂。", "vtech": [["主要矛盾题先分变与不变", "看到新时代主要矛盾题 → 先分清“变”与“不变”：变的是主要矛盾（人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾）；不变的是社会主义初级阶段的基本国情和世界上最大的发展中国家的国际地位；“进入新时代就不再是社会主义初级阶段”是典型错句。"], ["“迎来了”不是“实现了”", "看到进入新时代的意义题 → 盯住“迎来了实现中华民族伟大复兴的光明前景”：是“迎来了”不是“实现了”；站起来、富起来到强起来的伟大飞跃，强起来是正在进行时，别写成已经完成。"], ["四个伟大各有分工，起决定作用的是伟大工程", "看到四个伟大题 → 先定分工：伟大梦想是目标，伟大斗争是动力，伟大工程是保证，伟大事业是中国特色社会主义事业；四者紧密联系、相互贯通，但起决定性作用的是党的建设新的伟大工程。"], ["自我革命引领社会革命，顺序别反", "看到“以……引领……”题 → 记住正确顺序是以党的伟大自我革命引领伟大社会革命；“以伟大社会革命引领自我革命”是说反了的错句；同样，十个明确是理论层面的“是什么”，十四个坚持才是实践层面的路线图和方法论。"]], "vgaokao": []}}, "pol_p008": {"name": "实现中华民族伟大复兴的中国梦", "sec": 8, "secTitle": "第四课 只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴", "page": 47, "desc": "中国梦的本质是国家富强、民族振兴、人民幸福；归根到底是人民的梦。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p007"], "next": ["pol_p009"], "content": {"intro": "**中国梦**的本质是实现**国家富强、民族振兴、人民幸福**。它把国家的追求、民族的向往、人民的期盼融为一体，是国家的梦、民族的梦，也是每一个中国人的梦。==中国梦归根到底是人民的梦，必须紧紧依靠人民来实现，必须不断为人民造福。==", "learn": [{"h": "中国梦的本质", "p": "实现中华民族伟大复兴，就是中华民族近代以来**最伟大的梦想**。中国梦的本质是**国家富强、民族振兴、人民幸福**：国家富强是物质基础，民族振兴是精神追求，人民幸福是根本归宿。三个词必须连起来答，少一个都不完整。"}, {"h": "中国梦归根到底是人民的梦", "p": "中国梦是国家的、民族的，也是每一个中国人的。生活在我们伟大祖国和伟大时代的中国人民，共同享有人生出彩的机会，共同享有梦想成真的机会。中国梦**归根到底是人民的梦**，必须紧紧依靠人民来实现，必须不断为人民造福。"}, {"h": "怎样实现中国梦", "p": "实现中国梦必须走**中国道路**（中国特色社会主义道路），必须弘扬**中国精神**（以爱国主义为核心的民族精神和以改革创新为核心的时代精神），必须凝聚**中国力量**（中国各族人民大团结的力量）。道路、精神、力量三者缺一不可，是教材的标准搭配。"}, {"h": "新时代青年的使命", "p": "青年兴则国家兴，青年强则国家强。新时代中国青年要热爱祖国、忠于祖国、忠于人民，要立鸿鹄志、做奋斗者要求真学问、练真本领，要知行合一、做实干家。青年要在实现中国梦的生动实践中放飞青春梦想，在为人民利益的不懈奋斗中书写人生华章——新时代是奋斗者的时代，幸福都是奋斗出来的。"}], "pitfalls": ["把中国梦的本质漏写或改词：必须是国家富强、民族振兴、人民幸福，不能把「人民幸福」换成「共同富裕」（那是社会主义本质的要求，场合不同）。", "把中国梦说成只是国家层面的事情——它归根到底是人民的梦，与每个人的梦想相连。", "实现中国梦的三条件张冠李戴：走中国道路、弘扬中国精神、凝聚中国力量。"], "basics": [{"q": "中国梦的本质是实现（ ）", "opts": ["国家富强、民族振兴、人民幸福", "经济繁荣、军事强大、文化输出", "共同富裕、民主法治、公平正义", "民族独立、人民解放、国家统一"], "ans": 0, "why": "教材规范表述：中国梦的本质是实现国家富强、民族振兴、人民幸福。"}, {"q": "下列说法中，对中国梦理解正确的是（ ）", "opts": ["中国梦是国家的梦，与普通人无关", "中国梦归根到底是人民的梦", "中国梦就是每个人的发财梦", "实现中国梦主要靠外国援助"], "ans": 1, "why": "中国梦是国家的、民族的，也是每一个中国人的，归根到底是人民的梦，必须紧紧依靠人民来实现。"}, {"q": "实现中国梦必须走中国道路，这条道路是（ ）", "opts": ["资本主义道路", "封闭僵化的老路", "中国特色社会主义道路", "改旗易帜的邪路"], "ans": 2, "why": "实现中国梦必须走中国道路、弘扬中国精神、凝聚中国力量，中国道路就是中国特色社会主义道路。"}], "apply": [{"q": "材料：「得其大者可以兼其小。」只有把人生理想融入国家和民族的事业中，才能最终成就一番事业。一位航天工程师说，自己最大的梦想就是亲手送中国人登上月球。这段话表明（ ）", "opts": ["个人梦必须取代国家梦", "国家梦的实现排斥个人梦", "个人梦与国家梦、民族梦紧密相连，把个人奋斗融入国家事业才能成就大事", "青年只需关心个人前途"], "ans": 2, "why": "中国梦是国家梦、民族梦与个人梦的统一体；个人只有把理想融入国家和民族的事业中，才能最终成就一番事业。"}, {"q": "材料：从「天眼」探空到「奋斗者」号深潜，从脱贫攻坚驻村第一书记到边境线上的戍边战士，无数普通人在平凡岗位上书写了不平凡的人生。这告诉新时代青年（ ）", "opts": ["只有从事高精尖工作才有价值", "幸福都是奋斗出来的，要在实现中国梦的实践中放飞青春梦想", "个人奋斗与国家发展没有关系", "梦想的实现主要靠机遇"], "ans": 1, "why": "材料呈现的是各行各业普通人以奋斗托举梦想，落点是「幸福都是奋斗出来的」与青年的时代使命。"}], "case": {"q": "材料：某校开展「我的梦·中国梦」主题演讲，有同学提出疑问：「中国梦那么宏大，跟我一个普通高中生有什么关系？我只想考个好大学、找份好工作。」请你运用本框知识回应这位同学。", "a": "第一，中国梦是国家的、民族的，也是每一个中国人的，国家富强、民族振兴最终落脚点是人民幸福，个人前途命运与国家、民族的前途命运紧密相连。第二，国家好、民族好，大家才会好：正是因为国家发展进步，普通人才共同享有人生出彩、梦想成真的机会。第三，中国梦归根到底是人民的梦，必须紧紧依靠人民来实现——考个好大学、学好本领，本身就是在为实现中国梦积蓄力量；把人生理想融入国家和民族的事业中，小梦想才能获得大舞台。所以，中国梦不是与己无关的口号，而是每个青年都参与其中的事业。"}, "advance": {"q": "谈谈你对「中国梦是历史的、现实的，也是未来的；是我们这一代的，更是青年一代的」这句话的理解。", "a": "说它是历史的，因为实现中华民族伟大复兴是近代以来无数仁人志士前赴后继的追求，中国梦凝结着几代中国人的夙愿；说它是现实的，因为经过长期努力，中国特色社会主义进入新时代，我们比历史上任何时期都更接近、更有信心和能力实现这个目标；说它也是未来的，因为全面建成社会主义现代化强国、实现民族复兴仍需接续奋斗。中华民族伟大复兴的中国梦，终将在一代代青年的接力奋斗中变为现实——青年一代有理想、有本领、有担当，国家就有前途，民族就有希望。", "kind": "self"}}, "video": {"bvid": "BV1YE421A7Qj", "p": 1, "t": "只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴", "dur": "83:10", "from": "政治老师爱政治", "vtop": ["新时代我国社会的主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾——“变”的是主要矛盾，“不变”的是社会主义初级阶段的基本国情和世界上最大的发展中国家的国际地位。", "中国梦的内涵是国家富强、民族振兴、人民幸福：国家富强是基础，民族振兴是核心内容，人民幸福是奋斗目标；中国梦归根到底是人民的梦。", "十个明确讲“是什么”（理论层面），十四个坚持讲“怎么做”（实践层面、基本方略）——两者别搞反；基本方略是十四个坚持，不是十个明确。"], "vsum": "本课讲第四课，只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴，讲的是我们国家 2012 年进入新时代之后的这段历史，分三框。第一框是中国特色社会主义进入新时代。先看什么是新时代：2017 年党的十九大作出判断，经过长期努力，中国特色社会主义进入了新时代，这是我国发展新的历史方位；但进入新时代是从 2012 年党的十八大开始算起的。**新时代的科学内涵**可以从五个方面把握：第一，从伟大事业看，是承前启后、继往开来，在新的历史条件下继续夺取中国特色社会主义伟大胜利的时代；第二，从奋斗目标看，是决胜全面建成小康社会、进而全面建设社会主义现代化强国的时代，其中决胜全面建成小康社会是第一个百年奋斗目标，全面建设社会主义现代化强国是第二个百年奋斗目标；第三，从人民的期待看，是全国各族人民团结奋斗、不断创造美好生活、逐步实现全体人民共同富裕的时代；第四，从历史使命看，是全体中华儿女勠力同心、奋力实现中华民族伟大复兴中国梦的时代；第五，从世界意义看，是我国不断为人类作出更大贡献的时代。中国特色社会主义进入新时代有重大意义：历史意义上，意味着近代以来久经磨难的中华民族迎来了从站起来、富起来到强起来的伟大飞跃，迎来了实现中华民族伟大复兴的光明前景——注意是“迎来了”而不是“实现了”；政治意义上，意味着科学社会主义在 21 世纪的中国焕发出强大生机活力，在世界上高高举起了中国特色社会主义伟大旗帜；世界意义上，中国走出了一条中国式现代化道路，打破了发展中国家对西方国家现代化的路径依赖，为他们树立了榜样、提供了全新选择。第二个问题是新时代我国社会的主要矛盾。党对社会主要矛盾的认识有过三次：1956 年党的八大、1981 年党的十一届六中全会、2017 年党的十九大。新时代我国社会的主要矛盾是**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。转变的原因有两方面：从人民需求看，由原来的物质文化需要发展为美好生活需要，要求更多、更高、更广泛；从社会生产看，社会生产力水平显著提高，社会生产能力在很多方面进入了世界前列，再说“落后的社会生产”已经不合适，不平衡的发展包括东中西区域之间、城乡之间的不平衡，不充分的发展体现在关键核心技术上的短板。如何解决主要矛盾，要把握“变与不变”：变的是主要矛盾的变化，人民日益增长的美好生活需要是合理的、正当的，不能让人民群众降低需求标准，只能从不平衡不充分的发展角度去解决，要在继续推动发展的基础上，着力解决好发展不平衡不充分的问题，大力提升发展的质量和效益；不变的有两个，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国作为世界上最大的发展中国家的国际地位没有变。所以要牢牢把握社会主义初级阶段这个基本国情，牢牢立足这个最大实际，牢牢坚持党的基本路线——以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生、艰苦创业，为把我国建设成为富强民主文明和谐美丽的社会主义现代化强国而奋斗。第三个问题是新时代坚持和发展中国特色社会主义要一以贯之：从历史进程看，中国特色社会主义是在改革开放四十多年的伟大实践中得来的，是在新中国成立七十多年的持续探索中得来的，是党领导人民进行伟大社会革命一百年的实践中得来的，是在近代以来中华民族由衰到盛一百八十多年的历史进程中得来的；中国特色社会主义是实现中华民族伟大复兴的必由之路；每一个人都是新时代的见证者、开创者、建设者，要不忘初心、牢记使命，以永不懈怠的精神状态和一往无前的奋斗姿态，一以贯之坚持和发展中国特色社会主义。第二框是实现中华民族伟大复兴的中国梦。**中国梦**这一概念的提出是在 2012 年 11 月 29 日，习近平总书记来到中国国家博物馆参观“复兴之路”展览并发表重要讲话，其中首次提出实现中华民族伟大复兴就是中华民族近代以来最伟大的梦想。“复兴”就是再一次强大兴盛起来：古代中华民族创造过辉煌灿烂的文明，科学技术曾经长期处于世界前列，有文明于世的四大发明；进入近代以来，由于闭关自守和没落的封建专制制度，以及西方列强的入侵，逐步沦为半殖民地半封建社会，遭受了前所未有的苦难。中国梦的内涵有三层：**国家富强**是中国梦的实现基础，中国梦首先是强国梦；**民族振兴**是中国梦的核心内容；**人民幸福**是中国梦的奋斗目标，国家富强和民族振兴最终的落脚点都是为了人民幸福；三者分别代表国家的追求、民族的向往和人民的期盼，融为一体，体现了中华民族和中国人民的整体利益。如何实现中国梦，从三个角度回答：从中国梦与人民的关系看，中国梦归根到底是人民的梦，人民是中国梦的主体，是中国梦的创造者和享有者，要紧紧依靠人民来实现，不断为人民造福；从中国梦与中华儿女的关系看，中国梦是国家的梦、民族的梦，同时也是每一个中华儿女的梦，国家好、民族好，大家才会好，要把人生理想融入国家和民族的伟大梦想之中，把小我融入大我，敢于有梦、勇于追梦、勤于圆梦；从中国梦与世界梦的关系看，中国梦与世界人民的梦想息息相通，中国一心一意办好自己的事，实现国家发展和稳定，既是对自己负责，也是为世界做贡献，中国维和部队是全球执行维和任务最多的国家。接下来是中国共产党的初心和使命：2017 年 10 月 18 日，习近平同志在党的十九大报告中说，中国共产党人的初心和使命就是**为中国人民谋幸福、为中华民族谋复兴**。为了实现中华民族伟大复兴的伟大梦想，必须进行**伟大斗争**（包括反腐败斗争、意识形态领域的斗争、反分裂斗争、维护国家利益的斗争等）、推进**党的建设新的伟大工程**、推进**中国特色社会主义伟大事业**。**四个伟大**之间紧密联系、相互贯通、相互作用，共同贯穿于新时代中国特色社会主义的发展过程，但各有侧重：伟大梦想是目标，伟大斗争是动力，深入推进党的建设这一新的伟大工程是保证，推进中国特色社会主义事业这一伟大事业是改革开放以来党的全部理论和实践的主题；在四个伟大中起决定性作用的是党的建设新的伟大工程。办好中国的事情关键在党，没有中国共产党的领导，民族复兴必然是空想；要更加自觉地增强**四个自信**——中国特色社会主义道路自信、理论自信、制度自信、文化自信，既不走封闭僵化的老路，也不走改旗易帜的邪路。第三个问题是分两步走建成社会主义现代化强国：1987 年召开的十三大明确提出了三步走战略，前两步已经完成，第三步的目标是到 21 世纪中叶基本实现现代化；而党的十九大明确了新时代中国特色社会主义发展的战略安排，可以简称为两步走：第一个阶段从 2020 年到 2035 年，在全面建成小康社会的基础上，再奋斗 15 年，基本实现社会主义现代化；第二个阶段从 2035 年到本世纪中叶，在基本实现现代化的基础上，再奋斗 15 年，把我国建成富强民主文明和谐美丽的社会主义现代化强国。如何建成，从国家角度要牢牢把握坚持和加强党的全面领导等重大原则，增强忧患意识，坚持底线思维；要抓住大有可为的历史机遇期；从青年角度，青年兴则国家兴，青年强则国家强，广大青年要坚定理想信念、志存高远、脚踏实地，在实现中国梦的生动实践中放飞青春梦想。第三框是习近平新时代中国特色社会主义思想，分上下两集。上集先讲这一思想回答的时代课题：新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义，建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国，建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党。然后讲这一思想产生的背景。国际背景是：世界进入新的动荡变革期，世界经济复苏乏力，逆全球化思潮抬头，单边主义、保护主义明显上升，世界需要中国理念、中国智慧、中国方案；中国发挥着世界和平的建设者、全球发展的贡献者、国际秩序的维护者的重要作用，构建人类命运共同体的理念被写入了联合国大会的相关决议。国内背景包括四个方面：第一，中华民族伟大复兴进入关键时期，社会生产力水平总体上显著提高，比历史上任何时期都更接近、更有能力、更有信心实现中华民族伟大复兴的目标；第二，中国式现代化拓展推进，中国仅用短短七十多年的时间，在发展的很多方面走过了西方发达国家上百年甚至数百年的资本主义现代化发展历程，创造了世所罕见的经济快速发展和社会长期稳定两大奇迹，中国式现代化是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，是人与自然和谐共生的现代化，是走和平发展道路的现代化；第三，科学社会主义的发展，20 世纪 80 年代末 90 年代初东欧剧变、苏联解体，世界社会主义运动的发展出现了严重的曲折，但中国用自己的发展成果证明了“中国崩溃论”的崩溃和“社会主义失败论”的失败；第四，党的自我革命开辟新的境界，正是在党不断实现自我净化、自我完善、自我革新、自我提高，以伟大自我革命引领伟大社会革命的过程中创立并不断丰富发展的。下集讲这一思想的主要内容，包括**十个明确**、**十四个坚持**和十三个方面成就。**十个明确**是这一思想最为核心关键的组成部分，是支撑习近平新时代中国特色社会主义思想的四梁八柱，集中反映着我们党对科学社会主义在当今时代的理论思考和理论贡献。其中第一明确是坚持和发展中国特色社会主义的总任务是实现社会主义现代化和中华民族伟大复兴，在全面建成小康社会的基础上，分两步走在本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国，以中国式现代化推进中华民族的伟大复兴；第八明确是党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，把人民军队建设成为世界一流军队；第九明确是中国特色大国外交要服务民族复兴、促进人类进步，推动建设新型国际关系、推动构建人类命运共同体；第十明确是全面从严治党的战略方针，提出新时代党的建设总要求，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争，以伟大自我革命引领伟大社会革命。**十四个坚持**是坚持和发展中国特色社会主义的基本方略，涵盖坚持党的领导和五位一体总体布局、四个全面战略布局，涵盖国防和军队建设、维护国家安全、对外战略，是实现两个一百年奋斗目标、实现中华民族伟大复兴中国梦的路线图和方法论。要注意区分：十个明确讲的是“是什么”的问题，侧重于理论层面的高度概括；十四个坚持讲的是“怎么做”的问题，侧重于在实践层面如何展开，两者体现了理论与实践的结合、认识论与方法论相统一。十三个方面成就是指 2021 年党的十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》，从 13 个方面分领域总结了新时代党和国家事业取得的历史性成就、发生的历史性变革。最后是这一思想的地位和作用：这一思想实现了马克思主义中国化时代化新的飞跃，是当代中国的马克思主义，是 21 世纪的马克思主义，是中华文化和中国精神的时代精华；它是马克思主义中国化的最新成果——注意是“最新成果”而不是“最终成果”；在当代中国，坚持和发展习近平新时代中国特色社会主义思想，就是真正坚持和发展马克思主义，就是真正坚持和发展科学社会主义。易混易错提醒：中国特色社会主义最本质的特征是党的领导；基本方略是十四个坚持，不是十个明确；要以党的自我革命引领伟大社会革命，顺序不能反；改革开放前三十年是探索、是铺垫，后三十年是继承、是发展，两者不能割裂。", "vtech": [["主要矛盾题先分变与不变", "看到新时代主要矛盾题 → 先分清“变”与“不变”：变的是主要矛盾（人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾）；不变的是社会主义初级阶段的基本国情和世界上最大的发展中国家的国际地位；“进入新时代就不再是社会主义初级阶段”是典型错句。"], ["“迎来了”不是“实现了”", "看到进入新时代的意义题 → 盯住“迎来了实现中华民族伟大复兴的光明前景”：是“迎来了”不是“实现了”；站起来、富起来到强起来的伟大飞跃，强起来是正在进行时，别写成已经完成。"], ["四个伟大各有分工，起决定作用的是伟大工程", "看到四个伟大题 → 先定分工：伟大梦想是目标，伟大斗争是动力，伟大工程是保证，伟大事业是中国特色社会主义事业；四者紧密联系、相互贯通，但起决定性作用的是党的建设新的伟大工程。"], ["自我革命引领社会革命，顺序别反", "看到“以……引领……”题 → 记住正确顺序是以党的伟大自我革命引领伟大社会革命；“以伟大社会革命引领自我革命”是说反了的错句；同样，十个明确是理论层面的“是什么”，十四个坚持才是实践层面的路线图和方法论。"]], "vgaokao": []}}, "pol_p009": {"name": "习近平新时代中国特色社会主义思想", "sec": 9, "secTitle": "第四课 只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴", "page": 57, "desc": "长期坚持的指导思想；核心要义是坚持和发展中国特色社会主义；「八个明确」「十四个坚持」。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p008"], "next": ["pol_p010"], "content": {"intro": "**习近平新时代中国特色社会主义思想**是马克思主义中国化最新成果，是党和国家必须**长期坚持的指导思想**。它的核心要义是**坚持和发展中国特色社会主义**，系统回答了新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义这个重大时代课题。==「八个明确」讲清了思想的主要内容，「十四个坚持」构成了新时代的基本方略。==", "learn": [{"h": "地位：长期坚持的指导思想", "p": "党的十九大把习近平新时代中国特色社会主义思想确立为党必须长期坚持的指导思想并写入党章，十三届全国人大一次会议将其载入宪法。它是马克思主义中国化最新成果，是当代中国马克思主义、21 世纪马克思主义，是中国特色社会主义理论体系的重要组成部分，是全党全国人民为实现中华民族伟大复兴而奋斗的行动指南。"}, {"h": "核心要义与重大时代课题", "p": "这一思想的核心要义是**坚持和发展中国特色社会主义**，从理论和实践结合上系统回答了新时代坚持和发展**什么样的**中国特色社会主义、**怎样**坚持和发展中国特色社会主义这个重大时代课题。答题时把课题原句默写出来，得分点就稳了。"}, {"h": "八个明确：主要内容", "p": "**「八个明确」**回答「是什么」：明确坚持和发展中国特色社会主义的总任务是实现社会主义现代化和中华民族伟大复兴；明确新时代我国社会主要矛盾；明确中国特色社会主义事业总体布局是「五位一体」、战略布局是「四个全面」；明确全面深化改革、全面依法治国、强军、党的建设和**中国特色大国外交**等根本方向。其中第一条（总任务）和第二条（主要矛盾）是最常考的两条。"}, {"h": "十四个坚持：基本方略", "p": "**「十四个坚持」**回答「怎么做」：坚持党对一切工作的领导、坚持以人民为中心、坚持全面深化改革、坚持新发展理念、坚持人民当家作主、坚持全面依法治国、坚持社会主义核心价值体系、坚持在发展中保障和改善民生、坚持人与自然和谐共生、坚持总体国家安全观、坚持党对人民军队的绝对领导、坚持「一国两制」和推进祖国统一、坚持推动构建人类命运共同体、坚持全面从严治党。第一条「坚持党对一切工作的领导」是首要一条——党政军民学，东西南北中，党是领导一切的。"}], "pitfalls": ["把「八个明确」和「十四个坚持」混淆：明确讲主要内容（是什么），坚持讲基本方略（怎么做）。", "把这一思想的地位缩小为「某个领域的指导思想」——它是全党全国必须长期坚持的指导思想，已写入党章和宪法。", "说新思想「只是对以往理论的重复」——它是在新的历史条件下对重大时代课题的系统回答，是马克思主义中国化的新飞跃。"], "basics": [{"q": "习近平新时代中国特色社会主义思想的核心要义是（ ）", "opts": ["坚持和发展中国特色社会主义", "实现共产主义", "全面建成小康社会", "坚持改革开放"], "ans": 0, "why": "教材原文：这一思想的核心要义，就是坚持和发展中国特色社会主义。"}, {"q": "「八个明确」与「十四个坚持」的关系是（ ）", "opts": ["前者是基本方略，后者是主要内容", "前者是主要内容，后者是基本方略", "两者内容完全相同", "两者互不相关"], "ans": 1, "why": "「八个明确」是思想的主要内容，回答「是什么」；「十四个坚持」是新时代坚持和发展中国特色社会主义的基本方略，回答「怎么做」。"}, {"q": "把习近平新时代中国特色社会主义思想写入党章的会议是（ ）", "opts": ["党的十七大", "党的十八大", "党的十九大", "党的二十大"], "ans": 2, "why": "党的十九大将这一思想确立为党的指导思想并写入党章；2018 年十三届全国人大一次会议将其载入宪法。"}], "apply": [{"q": "材料：某地推进乡村振兴时，干部们坚持先开村民议事会、再定产业项目，把「群众满不满意」作为检验工作的第一标准。这一做法在基本方略中最直接地体现了（ ）", "opts": ["坚持党对人民军队的绝对领导", "坚持以人民为中心", "坚持总体国家安全观", "坚持「一国两制」和推进祖国统一"], "ans": 1, "why": "把人民立场、群众满意作为出发点和落脚点，正是「坚持以人民为中心」；其余三条与材料情境无关。"}, {"q": "材料：新时代十年，我国建成了世界上规模最大的教育体系、社会保障体系、医疗卫生体系，历史性地解决了绝对贫困问题，生态环境保护发生历史性转折。这些成就取得的根本原因在于（ ）", "opts": ["我国已经没有发展难题", "有习近平新时代中国特色社会主义思想的科学指引和党的坚强领导", "外国资本的大量涌入", "人口红利的持续扩大"], "ans": 1, "why": "新时代伟大成就的根本原因，是党中央的坚强领导和习近平新时代中国特色社会主义思想的科学指引；其余选项或与事实不符，或非根本原因。"}], "case": {"q": "材料：教材指出，习近平新时代中国特色社会主义思想是「当代中国马克思主义、21 世纪马克思主义」。有同学困惑：马克思主义是 19 世纪的学说，为什么说它在 21 世纪的中国有了新发展？运用本框知识谈谈你的理解。", "a": "第一，马克思主义是开放的、发展的理论，总是随着实践的发展而发展；中国共产党坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，不断推进马克思主义中国化时代化。第二，这一思想面对新时代的新课题——坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义，作出了系统回答，形成了「八个明确」「十四个坚持」等原创性成果，实现了马克思主义中国化新的飞跃。第三，实践是检验真理的标准：新时代十年伟大变革的成功，证明了这一思想的科学性和真理性。所以，说它是 21 世纪马克思主义，既是对其理论品格的概括，也是对其指导地位的确认。"}, "advance": {"q": "为什么说习近平新时代中国特色社会主义思想是全党全国人民为实现中华民族伟大复兴而奋斗的行动指南？", "a": "第一，它科学回答了新时代坚持和发展中国特色社会主义的一系列重大问题，为民族复兴提供了方向指引。第二，它明确了总任务是实现社会主义现代化和中华民族伟大复兴，并作出分两步走的战略安排，为民族复兴规划了路线图和时间表。第三，它是被实践证明了的科学理论：新时代十年的伟大变革表明，它是引领党和国家事业不断从胜利走向新的胜利的思想武器。第四，它已经全党确立、载入宪法，成为全党全国各族人民共同的意志和行动遵循。", "kind": "self"}}, "video": {"bvid": "BV1YE421A7Qj", "p": 1, "t": "只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴", "dur": "83:10", "from": "政治老师爱政治", "vtop": ["新时代我国社会的主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾——“变”的是主要矛盾，“不变”的是社会主义初级阶段的基本国情和世界上最大的发展中国家的国际地位。", "中国梦的内涵是国家富强、民族振兴、人民幸福：国家富强是基础，民族振兴是核心内容，人民幸福是奋斗目标；中国梦归根到底是人民的梦。", "十个明确讲“是什么”（理论层面），十四个坚持讲“怎么做”（实践层面、基本方略）——两者别搞反；基本方略是十四个坚持，不是十个明确。"], "vsum": "本课讲第四课，只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴，讲的是我们国家 2012 年进入新时代之后的这段历史，分三框。第一框是中国特色社会主义进入新时代。先看什么是新时代：2017 年党的十九大作出判断，经过长期努力，中国特色社会主义进入了新时代，这是我国发展新的历史方位；但进入新时代是从 2012 年党的十八大开始算起的。**新时代的科学内涵**可以从五个方面把握：第一，从伟大事业看，是承前启后、继往开来，在新的历史条件下继续夺取中国特色社会主义伟大胜利的时代；第二，从奋斗目标看，是决胜全面建成小康社会、进而全面建设社会主义现代化强国的时代，其中决胜全面建成小康社会是第一个百年奋斗目标，全面建设社会主义现代化强国是第二个百年奋斗目标；第三，从人民的期待看，是全国各族人民团结奋斗、不断创造美好生活、逐步实现全体人民共同富裕的时代；第四，从历史使命看，是全体中华儿女勠力同心、奋力实现中华民族伟大复兴中国梦的时代；第五，从世界意义看，是我国不断为人类作出更大贡献的时代。中国特色社会主义进入新时代有重大意义：历史意义上，意味着近代以来久经磨难的中华民族迎来了从站起来、富起来到强起来的伟大飞跃，迎来了实现中华民族伟大复兴的光明前景——注意是“迎来了”而不是“实现了”；政治意义上，意味着科学社会主义在 21 世纪的中国焕发出强大生机活力，在世界上高高举起了中国特色社会主义伟大旗帜；世界意义上，中国走出了一条中国式现代化道路，打破了发展中国家对西方国家现代化的路径依赖，为他们树立了榜样、提供了全新选择。第二个问题是新时代我国社会的主要矛盾。党对社会主要矛盾的认识有过三次：1956 年党的八大、1981 年党的十一届六中全会、2017 年党的十九大。新时代我国社会的主要矛盾是**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。转变的原因有两方面：从人民需求看，由原来的物质文化需要发展为美好生活需要，要求更多、更高、更广泛；从社会生产看，社会生产力水平显著提高，社会生产能力在很多方面进入了世界前列，再说“落后的社会生产”已经不合适，不平衡的发展包括东中西区域之间、城乡之间的不平衡，不充分的发展体现在关键核心技术上的短板。如何解决主要矛盾，要把握“变与不变”：变的是主要矛盾的变化，人民日益增长的美好生活需要是合理的、正当的，不能让人民群众降低需求标准，只能从不平衡不充分的发展角度去解决，要在继续推动发展的基础上，着力解决好发展不平衡不充分的问题，大力提升发展的质量和效益；不变的有两个，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国作为世界上最大的发展中国家的国际地位没有变。所以要牢牢把握社会主义初级阶段这个基本国情，牢牢立足这个最大实际，牢牢坚持党的基本路线——以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生、艰苦创业，为把我国建设成为富强民主文明和谐美丽的社会主义现代化强国而奋斗。第三个问题是新时代坚持和发展中国特色社会主义要一以贯之：从历史进程看，中国特色社会主义是在改革开放四十多年的伟大实践中得来的，是在新中国成立七十多年的持续探索中得来的，是党领导人民进行伟大社会革命一百年的实践中得来的，是在近代以来中华民族由衰到盛一百八十多年的历史进程中得来的；中国特色社会主义是实现中华民族伟大复兴的必由之路；每一个人都是新时代的见证者、开创者、建设者，要不忘初心、牢记使命，以永不懈怠的精神状态和一往无前的奋斗姿态，一以贯之坚持和发展中国特色社会主义。第二框是实现中华民族伟大复兴的中国梦。**中国梦**这一概念的提出是在 2012 年 11 月 29 日，习近平总书记来到中国国家博物馆参观“复兴之路”展览并发表重要讲话，其中首次提出实现中华民族伟大复兴就是中华民族近代以来最伟大的梦想。“复兴”就是再一次强大兴盛起来：古代中华民族创造过辉煌灿烂的文明，科学技术曾经长期处于世界前列，有文明于世的四大发明；进入近代以来，由于闭关自守和没落的封建专制制度，以及西方列强的入侵，逐步沦为半殖民地半封建社会，遭受了前所未有的苦难。中国梦的内涵有三层：**国家富强**是中国梦的实现基础，中国梦首先是强国梦；**民族振兴**是中国梦的核心内容；**人民幸福**是中国梦的奋斗目标，国家富强和民族振兴最终的落脚点都是为了人民幸福；三者分别代表国家的追求、民族的向往和人民的期盼，融为一体，体现了中华民族和中国人民的整体利益。如何实现中国梦，从三个角度回答：从中国梦与人民的关系看，中国梦归根到底是人民的梦，人民是中国梦的主体，是中国梦的创造者和享有者，要紧紧依靠人民来实现，不断为人民造福；从中国梦与中华儿女的关系看，中国梦是国家的梦、民族的梦，同时也是每一个中华儿女的梦，国家好、民族好，大家才会好，要把人生理想融入国家和民族的伟大梦想之中，把小我融入大我，敢于有梦、勇于追梦、勤于圆梦；从中国梦与世界梦的关系看，中国梦与世界人民的梦想息息相通，中国一心一意办好自己的事，实现国家发展和稳定，既是对自己负责，也是为世界做贡献，中国维和部队是全球执行维和任务最多的国家。接下来是中国共产党的初心和使命：2017 年 10 月 18 日，习近平同志在党的十九大报告中说，中国共产党人的初心和使命就是**为中国人民谋幸福、为中华民族谋复兴**。为了实现中华民族伟大复兴的伟大梦想，必须进行**伟大斗争**（包括反腐败斗争、意识形态领域的斗争、反分裂斗争、维护国家利益的斗争等）、推进**党的建设新的伟大工程**、推进**中国特色社会主义伟大事业**。**四个伟大**之间紧密联系、相互贯通、相互作用，共同贯穿于新时代中国特色社会主义的发展过程，但各有侧重：伟大梦想是目标，伟大斗争是动力，深入推进党的建设这一新的伟大工程是保证，推进中国特色社会主义事业这一伟大事业是改革开放以来党的全部理论和实践的主题；在四个伟大中起决定性作用的是党的建设新的伟大工程。办好中国的事情关键在党，没有中国共产党的领导，民族复兴必然是空想；要更加自觉地增强**四个自信**——中国特色社会主义道路自信、理论自信、制度自信、文化自信，既不走封闭僵化的老路，也不走改旗易帜的邪路。第三个问题是分两步走建成社会主义现代化强国：1987 年召开的十三大明确提出了三步走战略，前两步已经完成，第三步的目标是到 21 世纪中叶基本实现现代化；而党的十九大明确了新时代中国特色社会主义发展的战略安排，可以简称为两步走：第一个阶段从 2020 年到 2035 年，在全面建成小康社会的基础上，再奋斗 15 年，基本实现社会主义现代化；第二个阶段从 2035 年到本世纪中叶，在基本实现现代化的基础上，再奋斗 15 年，把我国建成富强民主文明和谐美丽的社会主义现代化强国。如何建成，从国家角度要牢牢把握坚持和加强党的全面领导等重大原则，增强忧患意识，坚持底线思维；要抓住大有可为的历史机遇期；从青年角度，青年兴则国家兴，青年强则国家强，广大青年要坚定理想信念、志存高远、脚踏实地，在实现中国梦的生动实践中放飞青春梦想。第三框是习近平新时代中国特色社会主义思想，分上下两集。上集先讲这一思想回答的时代课题：新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义，建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国，建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党。然后讲这一思想产生的背景。国际背景是：世界进入新的动荡变革期，世界经济复苏乏力，逆全球化思潮抬头，单边主义、保护主义明显上升，世界需要中国理念、中国智慧、中国方案；中国发挥着世界和平的建设者、全球发展的贡献者、国际秩序的维护者的重要作用，构建人类命运共同体的理念被写入了联合国大会的相关决议。国内背景包括四个方面：第一，中华民族伟大复兴进入关键时期，社会生产力水平总体上显著提高，比历史上任何时期都更接近、更有能力、更有信心实现中华民族伟大复兴的目标；第二，中国式现代化拓展推进，中国仅用短短七十多年的时间，在发展的很多方面走过了西方发达国家上百年甚至数百年的资本主义现代化发展历程，创造了世所罕见的经济快速发展和社会长期稳定两大奇迹，中国式现代化是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，是人与自然和谐共生的现代化，是走和平发展道路的现代化；第三，科学社会主义的发展，20 世纪 80 年代末 90 年代初东欧剧变、苏联解体，世界社会主义运动的发展出现了严重的曲折，但中国用自己的发展成果证明了“中国崩溃论”的崩溃和“社会主义失败论”的失败；第四，党的自我革命开辟新的境界，正是在党不断实现自我净化、自我完善、自我革新、自我提高，以伟大自我革命引领伟大社会革命的过程中创立并不断丰富发展的。下集讲这一思想的主要内容，包括**十个明确**、**十四个坚持**和十三个方面成就。**十个明确**是这一思想最为核心关键的组成部分，是支撑习近平新时代中国特色社会主义思想的四梁八柱，集中反映着我们党对科学社会主义在当今时代的理论思考和理论贡献。其中第一明确是坚持和发展中国特色社会主义的总任务是实现社会主义现代化和中华民族伟大复兴，在全面建成小康社会的基础上，分两步走在本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国，以中国式现代化推进中华民族的伟大复兴；第八明确是党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，把人民军队建设成为世界一流军队；第九明确是中国特色大国外交要服务民族复兴、促进人类进步，推动建设新型国际关系、推动构建人类命运共同体；第十明确是全面从严治党的战略方针，提出新时代党的建设总要求，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争，以伟大自我革命引领伟大社会革命。**十四个坚持**是坚持和发展中国特色社会主义的基本方略，涵盖坚持党的领导和五位一体总体布局、四个全面战略布局，涵盖国防和军队建设、维护国家安全、对外战略，是实现两个一百年奋斗目标、实现中华民族伟大复兴中国梦的路线图和方法论。要注意区分：十个明确讲的是“是什么”的问题，侧重于理论层面的高度概括；十四个坚持讲的是“怎么做”的问题，侧重于在实践层面如何展开，两者体现了理论与实践的结合、认识论与方法论相统一。十三个方面成就是指 2021 年党的十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》，从 13 个方面分领域总结了新时代党和国家事业取得的历史性成就、发生的历史性变革。最后是这一思想的地位和作用：这一思想实现了马克思主义中国化时代化新的飞跃，是当代中国的马克思主义，是 21 世纪的马克思主义，是中华文化和中国精神的时代精华；它是马克思主义中国化的最新成果——注意是“最新成果”而不是“最终成果”；在当代中国，坚持和发展习近平新时代中国特色社会主义思想，就是真正坚持和发展马克思主义，就是真正坚持和发展科学社会主义。易混易错提醒：中国特色社会主义最本质的特征是党的领导；基本方略是十四个坚持，不是十个明确；要以党的自我革命引领伟大社会革命，顺序不能反；改革开放前三十年是探索、是铺垫，后三十年是继承、是发展，两者不能割裂。", "vtech": [["主要矛盾题先分变与不变", "看到新时代主要矛盾题 → 先分清“变”与“不变”：变的是主要矛盾（人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾）；不变的是社会主义初级阶段的基本国情和世界上最大的发展中国家的国际地位；“进入新时代就不再是社会主义初级阶段”是典型错句。"], ["“迎来了”不是“实现了”", "看到进入新时代的意义题 → 盯住“迎来了实现中华民族伟大复兴的光明前景”：是“迎来了”不是“实现了”；站起来、富起来到强起来的伟大飞跃，强起来是正在进行时，别写成已经完成。"], ["四个伟大各有分工，起决定作用的是伟大工程", "看到四个伟大题 → 先定分工：伟大梦想是目标，伟大斗争是动力，伟大工程是保证，伟大事业是中国特色社会主义事业；四者紧密联系、相互贯通，但起决定性作用的是党的建设新的伟大工程。"], ["自我革命引领社会革命，顺序别反", "看到“以……引领……”题 → 记住正确顺序是以党的伟大自我革命引领伟大社会革命；“以伟大社会革命引领自我革命”是说反了的错句；同样，十个明确是理论层面的“是什么”，十四个坚持才是实践层面的路线图和方法论。"]], "vgaokao": []}}, "pol_p010": {"name": "综合探究一：回看走过的路，比较别人的路，远眺前行的路", "sec": 10, "secTitle": "综合探究", "page": 66, "desc": "道路问题关乎国家前途命运；中国特色社会主义道路是历史和人民的选择。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p009"], "next": ["pol_p011"], "content": {"intro": "回望百年，三条线索最清楚：走过的路证明**只有中国特色社会主义才能发展中国**；比较别人的路，要懂得**各国发展道路各有特色，不能盲目照搬**；远眺前行的路，我们比历史上任何时期都更接近民族复兴的目标。==道路问题关系党和国家的前途命运，走对路不容易，走错路要付出惨痛代价。==", "learn": [{"h": "回看走过的路", "p": "从新民主主义革命到社会主义革命和建设，再到改革开放和新时代，中国共产党领导人民走出了一条中国特色社会主义道路。这条道路来之不易，是党和人民历经千辛万苦、付出巨大代价取得的**根本成就**，必须倍加珍惜。回头看是为了更清醒地向前走：历史雄辩地证明，没有中国共产党就没有新中国，就没有中国特色社会主义。"}, {"h": "比较别人的路", "p": "世界上没有放之四海而皆准的发展道路，各国的历史传统、文化血脉、基本国情各不相同，发展道路必然各具特色。照搬照抄别国的模式注定行不通：苏联解体的教训之一，就是放弃了社会主义道路。==「鞋子合不合脚，自己穿了才知道」——一个国家的发展道路合不合适，只能由这个国家的人民来判断。=="}, {"h": "远眺前行的路", "p": "站在新时代的起点上，全面建成社会主义现代化强国、实现中华民族伟大复兴的前景无比光明。同时也要清醒：前进道路上仍有风险挑战，必须增强忧患意识、坚持底线思维，发扬斗争精神。新时代青年要坚定不移听党话、跟党走，把个人奋斗汇入民族复兴的洪流。"}], "pitfalls": ["把「别人走过的路」一概否定——我们反对的是照搬模式，不是拒绝借鉴人类文明的有益成果。", "认为道路问题只是领导层的事——道路合不合适，最终由这个国家的人民来判断，人民是历史的创造者。", "把独立自主误解为闭关自守——走自己的路与对外开放、交流互鉴并不矛盾。"], "basics": [{"q": "「鞋子合不合脚，自己穿了才知道。」这句话用于发展道路问题，最准确的理解是（ ）", "opts": ["发展道路不能有任何借鉴", "一个国家的发展道路合不合适，只能由这个国家的人民来判断", "各国道路可以随意互换", "道路问题无关紧要"], "ans": 1, "why": "原话强调的是独立自主地选择道路、由本国人民判断道路的合适与否，而不是拒绝一切借鉴。"}, {"q": "回看走过的路，得出的最根本结论是（ ）", "opts": ["历史发展没有规律可循", "中国特色社会主义道路是党和人民历经千辛万苦取得的根本成就，必须倍加珍惜", "过去的道路已经全部过时", "革命时期经验对今天没有意义"], "ans": 1, "why": "这是综合探究一的核心结论：道路来之不易，要坚持和发展下去。"}], "apply": [{"q": "材料：某国曾宣布要「在一夜之间」全面移植西方制度与经济模式，实行激进的「休克疗法」，结果经济大幅衰退、社会动荡，多年才逐步恢复。这一事例给我们的教训是（ ）", "opts": ["现代化只能靠计划经济实现", "脱离本国国情、照搬他国模式的发展道路注定行不通", "对外开放必然导致经济衰退", "发展道路一经选定便不能调整"], "ans": 1, "why": "道路选择必须从本国国情出发；照搬照抄别国的模式，无论出于何种愿望，都会付出沉重代价。"}, {"q": "材料：面对「中国为什么能」的提问，历史学家指出，中国的成功既不是靠对外军事扩张，也不是靠殖民掠夺，而是靠一代又一代人的顽强拼搏、靠党领导人民开辟的正确道路。这说明（ ）", "opts": ["中国特色社会主义道路符合中国国情、反映人民意愿", "中国道路是西方道路的翻版", "道路问题纯粹取决于外部环境", "拼搏精神可以代替道路选择"], "ans": 0, "why": "落点是道路的正确性：它从中国实际出发、顺应人民愿望，所以能创造发展奇迹。"}], "case": {"q": "材料：班级开展「道路自信」主题研讨，有同学发言说：「发达国家走的道路既然被证明有效，我们照着走就行了，何必自己摸索？」请你运用本探究的知识反驳这一观点。", "a": "第一，道路没有模板：各国的历史传统、文化血脉、基本国情不同，发展道路必然各具特色，不存在放之四海而皆准的一条路。第二，照搬必付代价：历史上照搬别国模式而陷入动荡、衰退的例子并不鲜见，苏联解体的重要教训之一就是放弃了适合自己的社会主义道路。第三，我们的道路已被实践证明：中国特色社会主义道路使中国大踏步赶上时代、迎来伟大飞跃，它植根中国大地、反映人民意愿，是历史和人民的选择。第四，走自己的路不等于拒绝借鉴：人类文明的一切有益成果都可以吸收，但「学步」不能丢了「自我」——鞋子合不合脚，自己穿了才知道。"}, "advance": {"q": "综合运用全册知识，谈谈新时代青年应如何「远眺前行的路」。", "a": "第一，坚定信仰信念信心：坚定对马克思主义的信仰、对中国特色社会主义的信念、对实现中华民族伟大复兴中国梦的信心。第二，认清方位与使命：我国发展进入新时代，青年生逢其时、重任在肩，要立鸿鹄志、做奋斗者。第三，坚持实干路径：把学习的具体目标同民族复兴的宏大目标结合起来，求真学问、练真本领，知行合一、做实干家。第四，保持清醒坚韧：前进道路不会一帆风顺，要增强忧患意识，发扬斗争精神，在接力奋斗中把前行的路走稳走实。", "kind": "self"}}, "video": {"bvid": "BV1gt4y1h7H6", "p": 1, "t": "综合探究", "dur": "38:31", "from": "教政治的月亮姐姐", "vtop": ["生产力决定生产关系、经济基础决定上层建筑；生产关系一定要适应生产力的状况，上层建筑一定要适应经济基础的状况——这是贯穿人类社会始终的基本矛盾。", "五种社会形态依次更替的根本原因是生产力发展；社会发展的总趋势是前进的、上升的，发展的过程是曲折的；在阶级社会里，阶级斗争是推动阶级社会发展的直接动力。", "在中国资本主义道路走不通——封建势力与帝国主义勾结、帝国主义不允许、中国资产阶级不具备条件；中国特色社会主义是科学社会主义理论逻辑和中国社会发展历史逻辑的辩证统一，必须毫不动摇地走下去。"], "vsum": "本课是必修一的综合探究，分两集、两位老师讲。第一集是“教政治的月亮姐姐”讲探究一，第二集换了一位老师“政是奋斗时”讲探究二，两集拼在一起共 38 分 31 秒。开场先说这节课的定位：前面必修一的知识点基本上已经上完了，综合探究是对前面所学内容的补充和回忆，很多老师上课时会直接忽略，但按课标要求是要讲的。总议题是“**回看走过的路，比较别人的路，远眺前行的路**”，这句话出自习近平总书记在哲学社会科学工作座谈会上的讲话：回望是为了更好地出发，比较是为了更加看清楚符合自己的路在哪里，眺望是为了描定好前行的方向。教材 62 页设计了三个探究题目，正好对应议题里的三句话：如何理解人类社会发展的一般进程，对应“回看走过的路”；如何看待世界各地历史发展的不同轨迹，对应“比较别人的路”；如何看待中国特色社会主义的科学真理性及历史必然性，对应“远眺前行的路”。第一个议题先回忆五种社会形态：**原始社会**是人类历史上第一个社会形态，存在了两三百万年，生产力的主要标志是使用石器，实行共同劳动、共同占有生产资料、平均分配；原始社会瓦解后出现**奴隶社会**，奴隶主在经济和上层建筑中居于主导地位；奴隶社会瓦解后是**封建社会**，地主阶级统治其他阶级的根本是封建土地所有制，地主通过掌握土地对农民用地租、放高利贷等手段进行剥削；封建社会之后是**资本主义社会**，资本归个人私有、雇佣劳动为基础，资本家通过雇佣关系赚取利润、占有剩余价值；资本主义社会之后是**社会主义社会**，目前世界上社会主义国家只有五个——中国、越南、朝鲜、老挝和古巴，都是由共产党执政。推动人类社会从低级向高级发展的，是**生产力的发展**。老师用一张表把五种社会形态放在一起对比，对比分三根线：生产力包括劳动者、劳动工具和劳动对象——原始社会劳动者技能水平非常低，到社会主义社会劳动者得到解放；劳动工具从原始社会的石器，到奴隶社会的金属工具、封建社会的铁制工具，再到资本主义社会和社会主义社会的机器；劳动对象从原始社会的自然界，发展到后来的自然界和太空。生产关系包括生产资料归谁所有、人们在生产中的地位和相互关系、产品分配关系——原始社会共同占有生产资料、平等互助、平均分配；奴隶社会是奴隶主占有生产资料并完全占有奴隶；封建社会是地主占有绝大部分土地；资本主义社会是资本家占有一切生产资料；社会主义社会是劳动者共同占有生产资料、平等互助合作、按劳分配。接着讲两组基本概念：**生产力**是人们利用和改造自然的能力，包括劳动者和劳动资料，劳动资料又包括生产工具和劳动对象，其中劳动者在生产中起主导作用，生产工具是生产力发展水平的重要标志。**生产关系**是在生产中形成的人与人之间的关系，包括生产资料所有制关系、人们在生产中的地位和相互关系、产品分配关系，其中**生产资料所有制是生产关系的基础**，决定着生产关系的其他两个方面。**经济基础**是指由社会一定发展阶段的生产力所决定的生产关系的总和；**上层建筑**是指建立在一定经济基础上的社会意识形态以及与之相适应的政治法律制度和设施等的总和，又分为思想上的上层建筑（政治思想、法律、道德、宗教、文学艺术等）和政治上的上层建筑（政治法律制度和设施、军队、警察、法庭、监狱等）。两组概念合起来就是两对关系：**生产力决定生产关系，生产关系反作用于生产力**——有什么样的生产力，就要求有什么样的生产关系与之相适应；生产关系适应生产力发展状况时促进生产力发展，不适应时阻碍甚至破坏生产力的发展。**经济基础决定上层建筑，上层建筑反作用于经济基础**——上层建筑适合经济基础状况时促进经济基础的巩固和完善，不适合时阻碍经济基础的发展和变革；当上层建筑为先进的经济基础服务时促进生产力的发展、推动社会进步，为落后的经济基础服务时束缚生产力的发展。由此得出议题一的结论：贯穿于人类社会始终的基本矛盾，是**生产力和生产关系的矛盾**以及**经济基础和上层建筑的矛盾**；**生产关系一定要适应生产力的状况，上层建筑一定要适应经济基础的状况**；这一规律决定着社会形态的依次更替、推动着人类向前发展。社会发展的总趋势是前进的、上升的，发展的过程是曲折的；在阶级社会里，社会基本矛盾的解决主要是通过阶级斗争实现，**阶级斗争是推动阶级社会发展的直接动力**。第二个议题看世界各国历史发展的不同轨迹，先看英国和美国。**英国的君主立宪制**是在保留君主制的前提下，通过立宪树立人民主权、限制君主权力，实现事实上的共和主义理想但不采用共和政体：议会是国家的最高立法机关、最高国家权力机关，由议会选举产生的政府首脑组织政府，是真正的国家权力中心，君主是象征性的国家元首，职责都是礼仪性的。英国君主立宪制从 1640 年革命开始，到 1689 年确立，形成的原因由英国的特殊国情决定：资产阶级新贵族和君主之间有一种长期的相互利用的关系，这是最主要的原因；英国历史上绝对君主制一直不够强大，议会始终保持着较多的权力；英国民众对君主有着强烈的感情；受启蒙思想的影响。课上还放了一段视频讲**光荣革命**：从 1688 年起，英国正式确立了议会高于王权的政治原则，并在以后的几十年里逐步建立起君主立宪制；英国人赶走詹姆斯二世、建立君主立宪制的革命没有流血，所以被历史学家称为光荣革命，它创造了一种用和平变革的方式实现社会进步的模式。**美国的民主共和制**是总统和议会分别由选举产生、任期限定，内阁由总统组织并对总统负责，总统既是国家元首又是政府首脑，与议会之间有权力制约的关系；美国形成民主共和制也是由它的国情决定的：所处的地理位置形成了人民渴望自由的政治基因，移民的到来形成了不同的州，殖民的历史造就了美国民主自由的思想。同样都是资本主义国家，英国是君主立宪制、美国是民主共和制，根子就在各自不同的国情。再看中国的情况：历史的以及血的代价告诉我们，在中国资本主义道路走不通，原因有三方面：封建势力同帝国主义相勾结，严重阻碍了民族资本主义经济的发展；帝国主义势力不允许中国走资本主义道路，帝国主义入侵中国的目的是要把中国变成他们的殖民地或者半殖民地，绝对不允许中国走资本主义道路变得强大起来、成为自己的竞争对手；中国的资产阶级也不具备建立资本主义制度的条件，靠中国资产阶级的力量，中国最终也不可能成为一个独立的资本主义国家。所以世界各国历史发展道路具有**多样性**，会受地理环境、文化传统和外部影响等因素的影响，各国各地区各民族的发展道路都会有着不同的表现；人类社会发展的一般进程，正是由各国各地区各民族历史的多样性反映出来的。中国要坚定不移地沿着**中国特色社会主义道路**前进，中国特色社会主义是党和人民历经千辛万苦、付出巨大代价取得的根本成就，是实现中华民族伟大复兴的正确道路。第三个议题通过几位历史人物的生平和天津利顺德大饭店的历史，来看中国特色社会主义的科学真理性与历史必然性。1912 年 2 月 12 日，溥仪被迫退位，宣告了统治中国几千年的封建统治结束；以梁启超为代表的资产阶级改良派，没有触动封建统治的根基，没有改变中国半殖民地半封建的社会制度；以孙中山先生为代表的资产阶级革命派，因为软弱性和妥协性，没有发动和依靠民众，也没有改变中国半殖民地半封建的社会制度；以毛泽东同志为代表的中国共产党人，经过浴血奋战成立了新中国，改变了中国的性质和面貌。利顺德饭店的命运跟着中国走：建国初饭店客人减少 40%、处于亏本状态，1952 年利顺德转交人民政府，成为名副其实的国有官办大型企业，一年之后就扭亏为盈；1978 年随着改革开放，利顺德加入改革开放的洪流，2010 年天津利顺德大饭店豪华精选酒店开业。社会主义制度和改革开放不仅让利顺德重新换发了生机，更让新中国换发了生机。回顾三个时间点：新中国成立为实现由新民主主义向社会主义过渡创造了前提条件，从根本上改变了中国社会的发展方向；1956 年生产资料私有制的社会主义改造取得决定性胜利，标志着我国实现了从新民主主义到社会主义的转变；1978 年至今中国进入改革开放的伟大进程。议题三的结论是：**中国特色社会主义是科学社会主义理论逻辑和中国社会发展历史逻辑的辩证统一，是根植于中国大地、反映中国人民意愿、适应中国和时代发展进步要求的科学社会主义**；中国特色社会主义道路是当代中国大踏步赶上时代、引领时代发展的康庄大道，必须毫不动摇地走下去。到这里探究一讲完，第一集的老师还总结说，必修一基本上就是这个样子，下节课开始上必修二经济与社会的内容。第二集换了一位老师“政是奋斗时”，讲综合探究二“**方向决定道路，道路决定命运**”。先讲方向、道路和命运这几个词：方向其实就是旗帜，我们中国高举中国特色社会主义的旗帜，走的是中国特色社会主义的道路；一个党、一个国家朝着什么样的方向发展，选择高举什么样的旗帜、走什么样的道路，就预示着将会有怎样的前途和命运，关系到国家能否实现富强、人民能否过上幸福的生活。我们选择走中国特色社会主义道路，这是实现社会主义现代化的必由之路，是实现国家富强、民族振兴的必由之路，是实现中华民族伟大复兴中国梦的必由之路。这一探究从四个方面分析。第一是聚焦中国成就：孙中山先生在《建国方略》里构想了中国建设的宏伟蓝图，要修建约 16 万公里的铁路、160 万公里公路、开凿并整治全国水道和运河、建设三个世界级大港、发展内河交通和水利、发展电力事业，只有这样才能振兴中华；如今孙中山先生描绘的蓝图早已实现，中国人创造的许多成就原本超出了孙中山先生的设想——中国从站起来、富起来到强起来，我们比历史上任何时期都更接近中华民族伟大复兴的目标，也比历史上任何时期都更有信心、有能力实现这个目标。为什么孙中山的设想在当时没有实现？从根本上说，他代表的是民族资产阶级，中国的资产阶级无法引导中国革命取得胜利，革命如果不能胜利，就没有和平稳定的社会条件；在半殖民地半封建的旧中国，资本主义道路是行不通的；从主观上说，资产阶级自身存在局限性，有软弱性和妥协性。为什么如今可以实现？首先是**党的领导**：党的领导是中国特色社会主义制度的最大优势，也是中国特色社会主义最本质的特征；在党的领导下，我们开辟了中国特色社会主义道路，形成了中国特色社会主义理论体系，确立了中国特色社会主义制度，发展了中国特色社会主义文化。还有全国各族人民的共同奋斗、顽强奋斗。实践证明，把马克思主义基本原理同中国具体实际相结合，坚持和发展中国特色社会主义，是实现中华民族伟大复兴中国梦的必由之路。新中国取得辉煌成就的原因还可以从这些角度想：根本原因就是中国共产党的领导，社会主义制度的优越性、能够集中力量办大事，国家统一、民族团结、新中国的综合国力提升，我们党带领我们走了自己的道路、建设了中国特色社会主义，坚持中国特色社会主义道路、理论、制度、文化，最后离不开人民——人民是改革开放伟大奇迹的创造者，是推动改革开放的力量源泉，还有党的建设。第二是点赞中国道路：回顾科学社会主义的发展历程，唯物史观和剩余价值学说的创立，使科学社会主义从空想到科学；巴黎公社使科学社会主义从理论到实践；俄国十月革命使科学社会主义从一国到多国；但是苏联解体让世界社会主义遭受了严重的挫折；21 世纪，科学社会主义在中国焕发出强大的生机与活力。苏联解体、东欧剧变之后，唱衰中国的舆论在国际上不绝于耳，“中国崩溃论”“历史终结论”等言论从未中断过，中国又是怎样面对这些言论的？批判“历史终结论”可以从三个角度：从社会历史发展的总趋势来看，马克思、恩格斯关于资本主义社会基本矛盾的分析指出，社会主义必然胜利、资本主义必然灭亡，社会发展的道路是曲折的，但社会主义的前途是光明的，所以走中国特色社会主义道路、选择科学社会主义是没有问题的；从实践的角度来说，中国特色社会主义是马克思主义基本原理同中国具体实际相结合的成果，是科学社会主义理论逻辑和中国社会发展历史逻辑的统一，中国特色社会主义的成功证明了科学社会主义具有强大的生机与活力；最后还是要集中力量办好自己的事情，为赢得未来打下更坚实的基础。第二个问题是各国的发展道路应该由各国人民去选择：人类社会发展有统一性和各国道路多样性这两种特点，世界上没有放之四海而皆准的具体发展模式，也没有一成不变的发展道路；如何判断我们这条道路是正确的，人民最有发言权，要看中国特色社会主义这样的道路有没有让我们的人民站起来、富起来、强起来，有没有让人民的生活水平不断提高；所谓“鞋子合不合脚，只有自己知道”，各国的发展道路也是由各国人民去选择的，任何干涉别国发展道路的做法都是错误的，要批判干涉别国发展道路的做法，并且一直坚定不移地走中国特色社会主义的道路，继续使科学社会主义焕发出强大的生机与活力。第三是贡献中国智慧、中国方案：绿水青山就是金山银山的理念、人类命运共同体在国际上达成共识、中国对其他国家的援助，都是中国在为世界贡献中国方案、中国智慧，还有国际减贫、推动全球气候治理、加强政策沟通、构建开放型世界经济，最熟悉的是一带一路，以及中国提倡的人类命运共同体、可持续发展观、全球治理观。中国方案、中国智慧的意义可以从三个角度梳理：从全球治理方面看，中国提出的新兴治理观念，比如构建人类命运共同体、构建新型国际关系，有利于全球治理；从政治文明方面看，中国高举和平发展、合作共赢等价值观念，维护了国际的公平正义；从共同发展的角度看，相互尊重、平等协商的思想开辟了与各国发展交往的新路，为各国共同发展提供了新动力。第四是坚定自信，实现中国梦：为什么要有自信？“四个自信”是实现中国梦、实现“两个一百年”奋斗目标的迫切需要，强调“四个自信”可以回应国外敌对势力对中国道路的质疑和否定；还可以从信心、信念、信仰的重要性来答，失去了自信会怎么样，课本 73 页有相关内容。为什么能有自信？分开讲四个自信各自的好处：理论自信之所以自信，不仅基于自身的科学性、时代性，更基于改革开放以来我国经济发展取得的巨大成就；文化自信更好说，我们是一个拥有 5000 多年文化的历史古国，这样的文化能够生生不息、源远流长，在人类文明的浩瀚星空中，中华文化应该是最值得、最有理由充满自信的；道路自信就是说我们所选择的道路是怎么走过来的——是在改革开放 40 多年的伟大实践中走出来的，是在中华人民共和国成立 70 多年的持续探索中走出来的，是在对近代以来 170 多年中华民族发展历程的深刻总结中走出来的，是在对中华民族 5000 多年悠久文明的传承中走出来的；制度自信在于它具有独特的优势、具有活力和潜力，中国所选择的制度适应我国的国情和发展要求，取得了显著的制度成效，是人民当家作主和中国发展进步的根本制度保障。如何坚定“四个自信”？要内化于心、外化于行，落实到实践上，“四个自信”也要不断创新，持续推进中国特色社会主义道路、制度、理论、文化。最后是实现中国梦：中国梦就是中华民族伟大复兴的中国梦，要全面建成社会主义现代化强国，这是实现“两个一百年”奋斗目标中的第二个百年奋斗目标；要实现中国梦，还离不开青年学生，实现中国梦、实现“两个一百年”奋斗目标都会涉及人民、涉及广大青年学生。课的最后做了一个小结：方向决定道路、道路决定命运，从聚焦中国成就、点赞中国道路、贡献中国智慧、坚定自信这四个方面探讨——为什么中国会取得这样的成就，是因为我们走自己的道路、坚持党的领导、建设中国特色社会主义；为什么中国不会被唱衰，是因为我们建立了社会主义基本经济制度、社会主义民主政治，是因为中国特色社会主义取得了伟大胜利，实践证明了选择科学社会主义、选择走中国特色社会主义道路的正确性；中国也要为世界的发展做出自己的贡献；最后坚定自信，畅想 2035 年建成社会主义现代化国家时那时候的中国是什么样，青年一代又有新的责任和担当。", "vtech": [["生产力与生产关系：谁决定谁、谁反作用于谁", "看到“决定”先想：生产力决定生产关系，经济基础决定上层建筑；看到“反作用”再看适应还是不适应——适应就促进，不适应就阻碍甚至破坏；易错点：生产资料所有制是生产关系的基础，决定着生产关系的其他两个方面，不要把决定关系说反。"], ["五种社会形态对比表：抓三根线", "看到对比题按三根线逐项核对：生产力看劳动者、劳动工具、劳动对象；生产关系看所有制、地位关系、分配；原始社会是共同占有、平均分配，社会主义社会是劳动者共同占有、按劳分配；易错点：目前世界上社会主义国家只有五个——中国、越南、朝鲜、老挝、古巴，都是由共产党执政。"], ["英国君主立宪制 vs 美国民主共和制：政体不同看国情", "英国：君主只是象征性国家元首、职责都是礼仪性的，议会是最高立法机关和最高国家权力机关，政府首脑由议会多数党领袖出任，是真正的国家权力中心，1640 年革命开始、1689 年确立；美国：总统既是国家元首又是政府首脑，与议会相互制约；判断信号：同是资本主义国家、政体不同，根子在各自的特殊国情，不要只记政体名称不记形成原因。"], ["中国道路为什么走得通：三点否定资本主义道路", "看到“中国资本主义道路为什么走不通”先答三点：封建势力同帝国主义相勾结、严重阻碍民族资本主义经济发展；帝国主义不允许中国变强大、成为自己的竞争对手；中国资产阶级自身软弱妥协、不具备建立资本主义制度的条件；正面论证看利顺德饭店：1952 年收归国有、一年扭亏为盈，1978 年改革开放后重焕生机。"]], "vgaokao": []}}, "pol_p011": {"name": "综合探究二：方向决定道路，道路决定命运", "sec": 11, "secTitle": "综合探究", "page": 71, "desc": "资本主义道路在中国走不通；坚持社会主义方向，走自己的路。", "criteria": ["能复述本框核心概念与教材规范表述", "能看懂材料并提取关键信息", "能独立做对基础题", "能独立做对材料型应用题", "能用是什么/为什么/怎么办的角度组织主观题答案"], "diag": null, "pre": ["pol_p010"], "next": [], "content": {"intro": "为什么中国最终选择了社会主义道路？因为**方向决定道路，道路决定命运**。封建主义救不了中国，资本主义道路在中国也走不通。==只有社会主义才能救中国，只有中国特色社会主义才能发展中国——这是历史的结论、人民的选择。==", "learn": [{"h": "资本主义道路为什么走不通", "p": "第一，**帝国主义不允许**：帝国主义列强侵略中国的目的是要把中国变成它们的殖民地、半殖民地，绝不允许中国成为独立富强的资本主义国家。第二，**封建势力不容许**：封建地主阶级和买办大资产阶级勾结内外反动势力，必然阻挠民族资本主义的独立发展。第三，**民族资产阶级自身的软弱性**：它与帝国主义、封建主义存在千丝万缕的联系，缺乏彻底的反帝反封建的勇气和力量。三重原因决定了，资产阶级共和国的方案在中国行不通。"}, {"h": "方向是怎样被找到的", "p": "十月革命一声炮响，给我们送来了马克思列宁主义。在科学理论的指引下，先进的中国人找到了社会主义这个方向。中国共产党把马克思主义基本原理同中国具体实际相结合，先通过新民主主义革命走社会主义的「必经阶段」，再通过社会主义改造确立社会主义基本制度，最终开辟了中国特色社会主义道路。方向对了，路才越走越宽。"}, {"h": "坚持方向，坚定不移走下去", "p": "方向决定前途，道路决定命运。我们要坚定不移走中国特色社会主义道路，既不走封闭僵化的老路，也不走改旗易帜的邪路。苏联解体、东欧剧变的深刻教训说明，一旦放弃社会主义方向，就会付出亡党亡国的惨痛代价。改革开放中要坚持四项基本原则这个立国之本，保证改革沿着正确方向前进。"}], "pitfalls": ["论证资本主义道路走不通时只写一条原因——三条要齐：帝国主义不允许、封建势力阻挠、民族资产阶级软弱性。", "把「方向决定道路」理解为方向可以主观随意选——方向的确立同样要以国情和历史条件为依据。", "把坚持四项基本原则与改革开放对立起来——四项基本原则保证改革开放的正确方向，二者统一于建设中国特色社会主义的实践。"], "basics": [{"q": "近代中国，资产阶级共和国方案行不通的首要外部原因是（ ）", "opts": ["民族资产阶级人数太少", "帝国主义不允许中国成为独立富强的资本主义国家", "农民阶级反对一切变革", "中国文化传统排斥共和"], "ans": 1, "why": "帝国主义侵略中国的目的是变中国为其殖民地、半殖民地，绝不允许中国独立富强，这是资本主义道路走不通的外部根源。"}, {"q": "「方向决定道路，道路决定命运」这一命题的直接结论是（ ）", "opts": ["方向问题无足轻重", "必须坚定不移走中国特色社会主义道路", "可以先随便选条路再说", "别国的方向就是我们的方向"], "ans": 1, "why": "社会主义方向的正确打开方式，就是走中国特色社会主义道路，既不走老路，也不走邪路。"}], "apply": [{"q": "材料：20 世纪，拉丁美洲一些国家长期仿效西方发展模式，经济几度陷入「中等收入陷阱」，社会动荡反复出现；东亚的中国却靠独立自主探索出的道路稳步迈向现代化。对比最能说明（ ）", "opts": ["西方模式适用于所有国家", "发展道路必须与本国的历史文化传统和基本国情相契合", "现代化只能靠封闭实现", "地理位置决定发展成就"], "ans": 1, "why": "两组对比的变量是道路与国情的契合程度：契合则兴，照搬则困。这正是「方向决定道路、道路决定命运」的材料化表达。"}, {"q": "材料：有人在网上留言：「只要能富起来，走哪条路都一样。」从本探究的观点看，这一说法（ ）", "opts": ["完全正确，目标比道路重要", "错误，不同道路通向完全不同的命运，社会主义道路是中国繁荣发展的必由之路", "正确，道路问题早已过时", "错误，但理由是道路根本不存在"], "ans": 1, "why": "道路决定命运：近代中国反复试错证明，只有社会主义道路能引领中国走向繁荣富强；把道路工具化、随意化，是对历史结论的否定。"}], "case": {"q": "材料：从 1840 年到 1949 年，中国人为救亡图存尝试过君主立宪、议会制、多党制、总统制等几乎所有的西方政治制度模式，结果都以失败告终；而选择了社会主义道路之后，中国只用几十年就走完了发达国家几百年的工业化历程。运用「方向决定道路，道路决定命运」的知识，谈谈你对这段历史对比的理解。", "a": "第一，方向决定道路：一个国家实行什么样的主义、走什么样的道路，关键要看这个主义、这条道路能否解决该国面临的历史性课题；西方制度模式与半殖民地半封建的中国国情水土不服，所以注定失败。第二，道路决定命运：社会主义方向指引中国走上了新民主主义革命和中国特色社会主义的道路，国家的命运由此彻底改变——从山河破碎到独立富强，证明了道路选择的决定性意义。第三，结论：坚持和发展中国特色社会主义，是历史的结论、人民的选择，必须坚定方向自信，既不走封闭僵化的老路，也不走改旗易帜的邪路。"}, "advance": {"q": "结合全册内容，谈谈为什么说「办好中国的事情，关键在党」。", "a": "第一，从历史看：中国特色社会主义最本质的特征是中国共产党领导，没有共产党就没有新中国，就没有社会主义制度的确立，就没有改革开放和中国特色社会主义道路的开辟。第二，从理论看：党是最高政治领导力量，坚持党对一切工作的领导是新时代基本方略的第一条。第三，从实践看：新时代伟大变革充分证明，党的领导是党和国家的根本所在、命脉所在，是全国各族人民的利益所系、命运所系。第四，从青年角度看：坚定不移听党话、跟党走，是把个人成长融入国家命运的根本保证。", "kind": "self"}}, "video": {"bvid": "BV1gt4y1h7H6", "p": 1, "t": "综合探究", "dur": "38:31", "from": "教政治的月亮姐姐", "vtop": ["生产力决定生产关系、经济基础决定上层建筑；生产关系一定要适应生产力的状况，上层建筑一定要适应经济基础的状况——这是贯穿人类社会始终的基本矛盾。", "五种社会形态依次更替的根本原因是生产力发展；社会发展的总趋势是前进的、上升的，发展的过程是曲折的；在阶级社会里，阶级斗争是推动阶级社会发展的直接动力。", "在中国资本主义道路走不通——封建势力与帝国主义勾结、帝国主义不允许、中国资产阶级不具备条件；中国特色社会主义是科学社会主义理论逻辑和中国社会发展历史逻辑的辩证统一，必须毫不动摇地走下去。"], "vsum": "本课是必修一的综合探究，分两集、两位老师讲。第一集是“教政治的月亮姐姐”讲探究一，第二集换了一位老师“政是奋斗时”讲探究二，两集拼在一起共 38 分 31 秒。开场先说这节课的定位：前面必修一的知识点基本上已经上完了，综合探究是对前面所学内容的补充和回忆，很多老师上课时会直接忽略，但按课标要求是要讲的。总议题是“**回看走过的路，比较别人的路，远眺前行的路**”，这句话出自习近平总书记在哲学社会科学工作座谈会上的讲话：回望是为了更好地出发，比较是为了更加看清楚符合自己的路在哪里，眺望是为了描定好前行的方向。教材 62 页设计了三个探究题目，正好对应议题里的三句话：如何理解人类社会发展的一般进程，对应“回看走过的路”；如何看待世界各地历史发展的不同轨迹，对应“比较别人的路”；如何看待中国特色社会主义的科学真理性及历史必然性，对应“远眺前行的路”。第一个议题先回忆五种社会形态：**原始社会**是人类历史上第一个社会形态，存在了两三百万年，生产力的主要标志是使用石器，实行共同劳动、共同占有生产资料、平均分配；原始社会瓦解后出现**奴隶社会**，奴隶主在经济和上层建筑中居于主导地位；奴隶社会瓦解后是**封建社会**，地主阶级统治其他阶级的根本是封建土地所有制，地主通过掌握土地对农民用地租、放高利贷等手段进行剥削；封建社会之后是**资本主义社会**，资本归个人私有、雇佣劳动为基础，资本家通过雇佣关系赚取利润、占有剩余价值；资本主义社会之后是**社会主义社会**，目前世界上社会主义国家只有五个——中国、越南、朝鲜、老挝和古巴，都是由共产党执政。推动人类社会从低级向高级发展的，是**生产力的发展**。老师用一张表把五种社会形态放在一起对比，对比分三根线：生产力包括劳动者、劳动工具和劳动对象——原始社会劳动者技能水平非常低，到社会主义社会劳动者得到解放；劳动工具从原始社会的石器，到奴隶社会的金属工具、封建社会的铁制工具，再到资本主义社会和社会主义社会的机器；劳动对象从原始社会的自然界，发展到后来的自然界和太空。生产关系包括生产资料归谁所有、人们在生产中的地位和相互关系、产品分配关系——原始社会共同占有生产资料、平等互助、平均分配；奴隶社会是奴隶主占有生产资料并完全占有奴隶；封建社会是地主占有绝大部分土地；资本主义社会是资本家占有一切生产资料；社会主义社会是劳动者共同占有生产资料、平等互助合作、按劳分配。接着讲两组基本概念：**生产力**是人们利用和改造自然的能力，包括劳动者和劳动资料，劳动资料又包括生产工具和劳动对象，其中劳动者在生产中起主导作用，生产工具是生产力发展水平的重要标志。**生产关系**是在生产中形成的人与人之间的关系，包括生产资料所有制关系、人们在生产中的地位和相互关系、产品分配关系，其中**生产资料所有制是生产关系的基础**，决定着生产关系的其他两个方面。**经济基础**是指由社会一定发展阶段的生产力所决定的生产关系的总和；**上层建筑**是指建立在一定经济基础上的社会意识形态以及与之相适应的政治法律制度和设施等的总和，又分为思想上的上层建筑（政治思想、法律、道德、宗教、文学艺术等）和政治上的上层建筑（政治法律制度和设施、军队、警察、法庭、监狱等）。两组概念合起来就是两对关系：**生产力决定生产关系，生产关系反作用于生产力**——有什么样的生产力，就要求有什么样的生产关系与之相适应；生产关系适应生产力发展状况时促进生产力发展，不适应时阻碍甚至破坏生产力的发展。**经济基础决定上层建筑，上层建筑反作用于经济基础**——上层建筑适合经济基础状况时促进经济基础的巩固和完善，不适合时阻碍经济基础的发展和变革；当上层建筑为先进的经济基础服务时促进生产力的发展、推动社会进步，为落后的经济基础服务时束缚生产力的发展。由此得出议题一的结论：贯穿于人类社会始终的基本矛盾，是**生产力和生产关系的矛盾**以及**经济基础和上层建筑的矛盾**；**生产关系一定要适应生产力的状况，上层建筑一定要适应经济基础的状况**；这一规律决定着社会形态的依次更替、推动着人类向前发展。社会发展的总趋势是前进的、上升的，发展的过程是曲折的；在阶级社会里，社会基本矛盾的解决主要是通过阶级斗争实现，**阶级斗争是推动阶级社会发展的直接动力**。第二个议题看世界各国历史发展的不同轨迹，先看英国和美国。**英国的君主立宪制**是在保留君主制的前提下，通过立宪树立人民主权、限制君主权力，实现事实上的共和主义理想但不采用共和政体：议会是国家的最高立法机关、最高国家权力机关，由议会选举产生的政府首脑组织政府，是真正的国家权力中心，君主是象征性的国家元首，职责都是礼仪性的。英国君主立宪制从 1640 年革命开始，到 1689 年确立，形成的原因由英国的特殊国情决定：资产阶级新贵族和君主之间有一种长期的相互利用的关系，这是最主要的原因；英国历史上绝对君主制一直不够强大，议会始终保持着较多的权力；英国民众对君主有着强烈的感情；受启蒙思想的影响。课上还放了一段视频讲**光荣革命**：从 1688 年起，英国正式确立了议会高于王权的政治原则，并在以后的几十年里逐步建立起君主立宪制；英国人赶走詹姆斯二世、建立君主立宪制的革命没有流血，所以被历史学家称为光荣革命，它创造了一种用和平变革的方式实现社会进步的模式。**美国的民主共和制**是总统和议会分别由选举产生、任期限定，内阁由总统组织并对总统负责，总统既是国家元首又是政府首脑，与议会之间有权力制约的关系；美国形成民主共和制也是由它的国情决定的：所处的地理位置形成了人民渴望自由的政治基因，移民的到来形成了不同的州，殖民的历史造就了美国民主自由的思想。同样都是资本主义国家，英国是君主立宪制、美国是民主共和制，根子就在各自不同的国情。再看中国的情况：历史的以及血的代价告诉我们，在中国资本主义道路走不通，原因有三方面：封建势力同帝国主义相勾结，严重阻碍了民族资本主义经济的发展；帝国主义势力不允许中国走资本主义道路，帝国主义入侵中国的目的是要把中国变成他们的殖民地或者半殖民地，绝对不允许中国走资本主义道路变得强大起来、成为自己的竞争对手；中国的资产阶级也不具备建立资本主义制度的条件，靠中国资产阶级的力量，中国最终也不可能成为一个独立的资本主义国家。所以世界各国历史发展道路具有**多样性**，会受地理环境、文化传统和外部影响等因素的影响，各国各地区各民族的发展道路都会有着不同的表现；人类社会发展的一般进程，正是由各国各地区各民族历史的多样性反映出来的。中国要坚定不移地沿着**中国特色社会主义道路**前进，中国特色社会主义是党和人民历经千辛万苦、付出巨大代价取得的根本成就，是实现中华民族伟大复兴的正确道路。第三个议题通过几位历史人物的生平和天津利顺德大饭店的历史，来看中国特色社会主义的科学真理性与历史必然性。1912 年 2 月 12 日，溥仪被迫退位，宣告了统治中国几千年的封建统治结束；以梁启超为代表的资产阶级改良派，没有触动封建统治的根基，没有改变中国半殖民地半封建的社会制度；以孙中山先生为代表的资产阶级革命派，因为软弱性和妥协性，没有发动和依靠民众，也没有改变中国半殖民地半封建的社会制度；以毛泽东同志为代表的中国共产党人，经过浴血奋战成立了新中国，改变了中国的性质和面貌。利顺德饭店的命运跟着中国走：建国初饭店客人减少 40%、处于亏本状态，1952 年利顺德转交人民政府，成为名副其实的国有官办大型企业，一年之后就扭亏为盈；1978 年随着改革开放，利顺德加入改革开放的洪流，2010 年天津利顺德大饭店豪华精选酒店开业。社会主义制度和改革开放不仅让利顺德重新换发了生机，更让新中国换发了生机。回顾三个时间点：新中国成立为实现由新民主主义向社会主义过渡创造了前提条件，从根本上改变了中国社会的发展方向；1956 年生产资料私有制的社会主义改造取得决定性胜利，标志着我国实现了从新民主主义到社会主义的转变；1978 年至今中国进入改革开放的伟大进程。议题三的结论是：**中国特色社会主义是科学社会主义理论逻辑和中国社会发展历史逻辑的辩证统一，是根植于中国大地、反映中国人民意愿、适应中国和时代发展进步要求的科学社会主义**；中国特色社会主义道路是当代中国大踏步赶上时代、引领时代发展的康庄大道，必须毫不动摇地走下去。到这里探究一讲完，第一集的老师还总结说，必修一基本上就是这个样子，下节课开始上必修二经济与社会的内容。第二集换了一位老师“政是奋斗时”，讲综合探究二“**方向决定道路，道路决定命运**”。先讲方向、道路和命运这几个词：方向其实就是旗帜，我们中国高举中国特色社会主义的旗帜，走的是中国特色社会主义的道路；一个党、一个国家朝着什么样的方向发展，选择高举什么样的旗帜、走什么样的道路，就预示着将会有怎样的前途和命运，关系到国家能否实现富强、人民能否过上幸福的生活。我们选择走中国特色社会主义道路，这是实现社会主义现代化的必由之路，是实现国家富强、民族振兴的必由之路，是实现中华民族伟大复兴中国梦的必由之路。这一探究从四个方面分析。第一是聚焦中国成就：孙中山先生在《建国方略》里构想了中国建设的宏伟蓝图，要修建约 16 万公里的铁路、160 万公里公路、开凿并整治全国水道和运河、建设三个世界级大港、发展内河交通和水利、发展电力事业，只有这样才能振兴中华；如今孙中山先生描绘的蓝图早已实现，中国人创造的许多成就原本超出了孙中山先生的设想——中国从站起来、富起来到强起来，我们比历史上任何时期都更接近中华民族伟大复兴的目标，也比历史上任何时期都更有信心、有能力实现这个目标。为什么孙中山的设想在当时没有实现？从根本上说，他代表的是民族资产阶级，中国的资产阶级无法引导中国革命取得胜利，革命如果不能胜利，就没有和平稳定的社会条件；在半殖民地半封建的旧中国，资本主义道路是行不通的；从主观上说，资产阶级自身存在局限性，有软弱性和妥协性。为什么如今可以实现？首先是**党的领导**：党的领导是中国特色社会主义制度的最大优势，也是中国特色社会主义最本质的特征；在党的领导下，我们开辟了中国特色社会主义道路，形成了中国特色社会主义理论体系，确立了中国特色社会主义制度，发展了中国特色社会主义文化。还有全国各族人民的共同奋斗、顽强奋斗。实践证明，把马克思主义基本原理同中国具体实际相结合，坚持和发展中国特色社会主义，是实现中华民族伟大复兴中国梦的必由之路。新中国取得辉煌成就的原因还可以从这些角度想：根本原因就是中国共产党的领导，社会主义制度的优越性、能够集中力量办大事，国家统一、民族团结、新中国的综合国力提升，我们党带领我们走了自己的道路、建设了中国特色社会主义，坚持中国特色社会主义道路、理论、制度、文化，最后离不开人民——人民是改革开放伟大奇迹的创造者，是推动改革开放的力量源泉，还有党的建设。第二是点赞中国道路：回顾科学社会主义的发展历程，唯物史观和剩余价值学说的创立，使科学社会主义从空想到科学；巴黎公社使科学社会主义从理论到实践；俄国十月革命使科学社会主义从一国到多国；但是苏联解体让世界社会主义遭受了严重的挫折；21 世纪，科学社会主义在中国焕发出强大的生机与活力。苏联解体、东欧剧变之后，唱衰中国的舆论在国际上不绝于耳，“中国崩溃论”“历史终结论”等言论从未中断过，中国又是怎样面对这些言论的？批判“历史终结论”可以从三个角度：从社会历史发展的总趋势来看，马克思、恩格斯关于资本主义社会基本矛盾的分析指出，社会主义必然胜利、资本主义必然灭亡，社会发展的道路是曲折的，但社会主义的前途是光明的，所以走中国特色社会主义道路、选择科学社会主义是没有问题的；从实践的角度来说，中国特色社会主义是马克思主义基本原理同中国具体实际相结合的成果，是科学社会主义理论逻辑和中国社会发展历史逻辑的统一，中国特色社会主义的成功证明了科学社会主义具有强大的生机与活力；最后还是要集中力量办好自己的事情，为赢得未来打下更坚实的基础。第二个问题是各国的发展道路应该由各国人民去选择：人类社会发展有统一性和各国道路多样性这两种特点，世界上没有放之四海而皆准的具体发展模式，也没有一成不变的发展道路；如何判断我们这条道路是正确的，人民最有发言权，要看中国特色社会主义这样的道路有没有让我们的人民站起来、富起来、强起来，有没有让人民的生活水平不断提高；所谓“鞋子合不合脚，只有自己知道”，各国的发展道路也是由各国人民去选择的，任何干涉别国发展道路的做法都是错误的，要批判干涉别国发展道路的做法，并且一直坚定不移地走中国特色社会主义的道路，继续使科学社会主义焕发出强大的生机与活力。第三是贡献中国智慧、中国方案：绿水青山就是金山银山的理念、人类命运共同体在国际上达成共识、中国对其他国家的援助，都是中国在为世界贡献中国方案、中国智慧，还有国际减贫、推动全球气候治理、加强政策沟通、构建开放型世界经济，最熟悉的是一带一路，以及中国提倡的人类命运共同体、可持续发展观、全球治理观。中国方案、中国智慧的意义可以从三个角度梳理：从全球治理方面看，中国提出的新兴治理观念，比如构建人类命运共同体、构建新型国际关系，有利于全球治理；从政治文明方面看，中国高举和平发展、合作共赢等价值观念，维护了国际的公平正义；从共同发展的角度看，相互尊重、平等协商的思想开辟了与各国发展交往的新路，为各国共同发展提供了新动力。第四是坚定自信，实现中国梦：为什么要有自信？“四个自信”是实现中国梦、实现“两个一百年”奋斗目标的迫切需要，强调“四个自信”可以回应国外敌对势力对中国道路的质疑和否定；还可以从信心、信念、信仰的重要性来答，失去了自信会怎么样，课本 73 页有相关内容。为什么能有自信？分开讲四个自信各自的好处：理论自信之所以自信，不仅基于自身的科学性、时代性，更基于改革开放以来我国经济发展取得的巨大成就；文化自信更好说，我们是一个拥有 5000 多年文化的历史古国，这样的文化能够生生不息、源远流长，在人类文明的浩瀚星空中，中华文化应该是最值得、最有理由充满自信的；道路自信就是说我们所选择的道路是怎么走过来的——是在改革开放 40 多年的伟大实践中走出来的，是在中华人民共和国成立 70 多年的持续探索中走出来的，是在对近代以来 170 多年中华民族发展历程的深刻总结中走出来的，是在对中华民族 5000 多年悠久文明的传承中走出来的；制度自信在于它具有独特的优势、具有活力和潜力，中国所选择的制度适应我国的国情和发展要求，取得了显著的制度成效，是人民当家作主和中国发展进步的根本制度保障。如何坚定“四个自信”？要内化于心、外化于行，落实到实践上，“四个自信”也要不断创新，持续推进中国特色社会主义道路、制度、理论、文化。最后是实现中国梦：中国梦就是中华民族伟大复兴的中国梦，要全面建成社会主义现代化强国，这是实现“两个一百年”奋斗目标中的第二个百年奋斗目标；要实现中国梦，还离不开青年学生，实现中国梦、实现“两个一百年”奋斗目标都会涉及人民、涉及广大青年学生。课的最后做了一个小结：方向决定道路、道路决定命运，从聚焦中国成就、点赞中国道路、贡献中国智慧、坚定自信这四个方面探讨——为什么中国会取得这样的成就，是因为我们走自己的道路、坚持党的领导、建设中国特色社会主义；为什么中国不会被唱衰，是因为我们建立了社会主义基本经济制度、社会主义民主政治，是因为中国特色社会主义取得了伟大胜利，实践证明了选择科学社会主义、选择走中国特色社会主义道路的正确性；中国也要为世界的发展做出自己的贡献；最后坚定自信，畅想 2035 年建成社会主义现代化国家时那时候的中国是什么样，青年一代又有新的责任和担当。", "vtech": [["生产力与生产关系：谁决定谁、谁反作用于谁", "看到“决定”先想：生产力决定生产关系，经济基础决定上层建筑；看到“反作用”再看适应还是不适应——适应就促进，不适应就阻碍甚至破坏；易错点：生产资料所有制是生产关系的基础，决定着生产关系的其他两个方面，不要把决定关系说反。"], ["五种社会形态对比表：抓三根线", "看到对比题按三根线逐项核对：生产力看劳动者、劳动工具、劳动对象；生产关系看所有制、地位关系、分配；原始社会是共同占有、平均分配，社会主义社会是劳动者共同占有、按劳分配；易错点：目前世界上社会主义国家只有五个——中国、越南、朝鲜、老挝、古巴，都是由共产党执政。"], ["英国君主立宪制 vs 美国民主共和制：政体不同看国情", "英国：君主只是象征性国家元首、职责都是礼仪性的，议会是最高立法机关和最高国家权力机关，政府首脑由议会多数党领袖出任，是真正的国家权力中心，1640 年革命开始、1689 年确立；美国：总统既是国家元首又是政府首脑，与议会相互制约；判断信号：同是资本主义国家、政体不同，根子在各自的特殊国情，不要只记政体名称不记形成原因。"], ["中国道路为什么走得通：三点否定资本主义道路", "看到“中国资本主义道路为什么走不通”先答三点：封建势力同帝国主义相勾结、严重阻碍民族资本主义经济发展；帝国主义不允许中国变强大、成为自己的竞争对手；中国资产阶级自身软弱妥协、不具备建立资本主义制度的条件；正面论证看利顺德饭店：1952 年收归国有、一年扭亏为盈，1978 年改革开放后重焕生机。"]], "vgaokao": []}}}, "units": {"u_pol_1": {"id": "u_pol_1", "name": "社会主义从空想到科学、从理论到实践的发展", "secs": "第一课", "pageFrom": 1, "pageTo": 19, "members": ["pol_p001", "pol_p002"], "video": {"bvid": "BV15M4m127aY", "p": 1, "t": "社会主义从空想到科学、从理论到实践的发展", "dur": "91:24", "from": "政治老师爱政治", "vtop": ["生产关系是否适应生产力的发展，是判断一种社会形态取代另一种社会形态是进步还是倒退的主要标志——奴隶社会取代原始社会就是历史的进步。", "资本主义社会的基本矛盾是生产社会化与生产资料资本主义私人占有之间的矛盾，它是经济危机爆发的根本原因，也是资本主义一切矛盾与冲突的总根源。", "科学社会主义诞生的标志是《共产党宣言》的发表；实现社会主义由空想到科学的伟大飞跃的，是唯物史观和剩余价值学说这两大理论基石。"], "vsum": "本课是必修一第一课，讲社会主义从空想到科学、从理论到实践的发展，分两框：第一框讲原始社会到奴隶社会、封建社会到资本主义社会，第二框讲科学社会主义的理论与实践。开场先点全书主题：这本书围绕**社会主义的发展**展开，共四课，第一课从整个人类社会发展历史的角度讲社会主义的由来，后面三课讲我们国家的社会主义。第一框第一幕从原始社会到奴隶社会，先讲原始社会。原始社会是人类社会的**最初阶段、最低阶段**，可以比喻为人类的**童年时期**，但这个童年十分漫长：**旧石器时代**是200到300万年至1万年前，人们靠采集天然食物为生，用打制石器；**新石器时代**是1万年前，出现了原始的畜牧业和农业，人们从食物的采集者变成了生产者，用磨制石器。原始社会也因此被称为石器时代。它的生产力状况是**十分低下**：劳动者劳动技能低下、劳动工具简陋、劳动对象范围有限。生产力决定生产关系，原始社会的生产关系可以概括为**“两共两平”**：**共同劳动、共同占有生产资料**，在生产中形成**平等互助**的关系，**平均分配**劳动产品。社会制度是**氏族制度**：按血缘关系结成的氏族是原始人共同生活的基本单位，氏族议事会由氏族全体成年人行使平等表决权，氏族长和军事首领由议事会选举产生，都没有任何特权，尧舜就是原始社会非常贤能的部落联盟首领。原始社会的解体过程是：生产工具改进推动生产力发展，几个人就能获取足够的食物，不用再依赖整个氏族，于是以氏族为单位的共同劳动被以家庭为单位的**个体劳动**取代，生产资料由氏族公有转变为家庭私有，土地变成私有财产就标志着**私有制确立**，贫富分化加剧，氏族成员地位越来越不平等，原始社会逐渐解体。关于私有制有三个观点要辨析：观点一“私有制的产生是社会生产力发展的结果，是不可避免的”是正确的，因为私有制属于生产关系，生产力决定生产关系；观点二“私有观念是人所固有的，所以私有制天然合理而且会永远存在”是错的，私有制不是天然就存在的，也不会永远存在；观点三“私有观念的存在是私有制产生的根本原因”也是错的，私有观念属于上层建筑，是私有制带来的结果而不是原因，准确的关系是生产力发展产生私有制，私有制下才逐渐产生私有观念。再讲奴隶社会。原始社会解体后出现了**奴隶主阶级和奴隶阶级**两大地位不同的集团，阶级就是在一定生产关系中处于不同地位的集团，奴隶社会的产生可以概括为生产力发展、私有制确立、再产生阶级。奴隶的来源有两个：一是部落征战中战争的俘虏沦为奴隶，二是无力偿还债务、债务人全家沦为奴隶。奴隶制生产关系的特点有三点：从所有制看，**奴隶主占有生产资料并完全占有奴隶**，古罗马把奴隶当作“会说话的工具”，可以随意转让、出售、赠送甚至杀害；从分配方式看，奴隶劳动的全部产品都归奴隶主占有和支配，奴隶主只给奴隶最低限度的生活资料；从人与人之间的关系看，奴隶毫无人生自由，是在奴隶主的强制下从事劳动。奴隶社会的主要矛盾就是**奴隶阶级和奴隶主阶级之间的矛盾**。奴隶主的残酷压迫必然引起奴隶反抗，奴隶主为维护本阶级利益建立了军队、监狱、法庭等暴力机关，于是国家就产生了，**国家是阶级矛盾不可调和的产物，是阶级统治的工具**，国家并不是从来就有的，我国历史上的第一个奴隶制国家是**夏**。对奴隶社会的评价要明确是**历史的进步**：奴隶社会取代原始社会后，金属工具广泛应用，奴隶社会也被称为**青铜时代**，三星堆遗址出土的青铜大立人、青铜太阳轮就反映出当时青铜器制作技艺的高超水平；城市开始出现，雅典、斯巴达都是奴隶社会繁荣城市的代表；出现了文字，殷墟的甲骨文证明当时已经有了文字记载，文字的出现就是人类进入文明时代的标志；还出现了脑力劳动和体力劳动的分工，有利于思想艺术的繁荣。所以奴隶制生产关系在当时还是促进了生产力的发展，使人类摆脱蒙昧野蛮的状态，迈入文明时代的门口。判断一种社会形态代替另一种社会形态究竟是历史的进步还是倒退，主要标志是看**生产关系是否适应生产力的发展**。当然也要一分为二地看：奴隶社会后期，奴隶和奴隶主的矛盾加剧，奴隶的反抗和逃亡使奴隶制严重阻碍了生产力的发展，所以它才会被封建社会取代。第一框第二幕从封建社会到资本主义社会，先讲封建社会的产生。奴隶社会后期出现了铁犁、牛耕等先进的生产工具，推动了生产力的发展，但奴隶制的生产关系下奴隶逃亡反抗越来越多，田地荒芜、城市萧条，阻碍了生产力发展，一些开明的奴隶主改变剥削方式，释放奴隶并把土地分成小块分给奴隶耕种、要求他们缴纳地租、承担劳役，公田变为私田，奴隶变成农民、奴隶主变成地主，产生了新的封建制生产关系，它能够适应并推动生产力的发展，所以封建社会的产生仍然是生产力发展的结果。封建制生产关系的特点有三点：地主占有绝大部分土地，农民有自己的劳动工具甚至少量土地；地主通过收取地租等方式占有农民大部分的劳动成果，农民的劳动成果除了缴纳地租还能留下一部分归自己支配；农民有了一定的人身自由。和奴隶相比，农民有了生产资料和一定的人身自由，能够自主劳动、具备生产积极性，进而促进社会生产的发展，所以封建制生产关系和奴隶制生产关系相比是一种进步。封建社会生产力的发展状况是：铁制农具被广泛使用和推广，封建社会也被称为**铁器时代**；耕作技术明显进步，如休耕轮作；水利事业有较大发展，如修建于四川的**都江堰**、秦朝修建的**灵渠**、陕西的**郑国渠**；手工业进一步发展，包括纺织业、陶瓷业、冶铸业；商业和城市逐渐发展起来，唐朝的长安城是当时世界上最大最繁华的国际大都市，长安的东市和西市商业贸易非常发达，我们今天口中的“买东西”就是由唐朝的东西两市得来的。但农民的处境仍然十分悲惨，唐诗“四海无闲田，农夫犹饿死”和杜甫的“朱门酒肉臭，路有冻死骨”都反映了这一点。农民这么惨，根本原因在于封建农业社会最重要的生产资料土地归地主所有，农民不得不依附于地主，所以**封建土地所有制是地主剥削农民的基础**，地主剥削农民的主要方式是**收取地租**，地租的形式包括劳役地租、实物地租和货币地租，此外还有高利贷、苛捐杂税和各种徭役。经济基础决定上层建筑，封建社会的上层建筑分两方面：政治上实行**君主专制、等级森严**，皇帝之下公侯伯子男从高到低排下来，这是封建社会的显著特征；思想上地主阶级鼓吹**君权神授**，把皇帝称为天子、认为是天命所归，提出三纲五常、“君教臣死，臣不得不死”等封建宗法思想和道德，传播封建迷信、钳制人民的思想。所以地主阶级的统治在经济上是剥削、在政治上是压迫、在思想上是钳制，农民面对这三重压迫，实行小规模的抗租抗税和大规模的农民起义或农民战争来反抗，秦朝的**陈胜吴广起义**、汉末的**黄巾起义**就是代表，封建社会的主要矛盾就是**农民阶级和地主阶级的矛盾**。再讲资本主义社会。封建社会后期，随着社会生产力和商品经济的发展，城市手工业者之间的竞争加剧，条件好的作坊主、商人和高利贷者成为早期的资本家，条件差的小生产者和作坊沦为雇佣工人，出现了资本家与工人之间的雇佣关系，典型表现有14世纪的佛罗伦萨手工工场、我国明朝时期苏州杭州的丝织业、四川的井盐业、江西景德镇的制瓷业，这都是资本主义生产关系萌芽的具体表现。封建社会以自然经济为基础，自给自足、男耕女织，不利于商品经济和生产力的发展，所以会被新的资本主义生产关系取代，资本主义的产生就是社会生产力和商品经济发展的结果。资本主义生产关系的特点也有三点：资本家占有一切生产资料；失去生产资料的劳动者不得不出卖自己的劳动力，受雇于资本家成为雇佣工人；资本家在生产过程中占有工人所创造的**剩余价值**。剩余价值是指由工人创造、但被资本家无偿占有的那一部分价值，课上的例子是：资本家给工人的日工资是100元，要求工人工作10个小时，但工人只用6小时就能够创造出100元的价值，剩下4小时创造出来的、被资本家无偿占有的部分就叫做剩余价值。不同于奴隶制和封建制赤裸裸的剥削，资本主义剥削的秘密是资本家购买工人的劳动力，而劳动力创造的价值远远超过资本家给付工人的工资，超过的部分就是剩余价值，这种占有是隐藏在生产过程当中的，是隐蔽的。资本主义生产关系的建立必须具备两个基本条件：一是有大批失去生产资料、有人身自由、能自由出卖劳动力的人，二是有开办资本主义企业所需要的大量货币当作资本，简单说就是要有人、有钱。这两个条件在历史上是西方资产阶级依靠暴力、通过掠夺形成的：英国爆发了被马克思称为“羊吃人”的**圈地运动**，资产阶级新贵族用篱笆、栅栏、壕沟把强占的农民土地圈起来变为私有的大型牧场，大量农民丧失土地和家园；新航路开辟后，西方资产阶级开始暴力掠夺、殖民扩张，把大量非洲黑人运到美洲贩卖，从中获取暴利。所以资本主义社会的形成过程中充满了侵略、征服、掠夺、残杀和奴役，马克思曾说“资本来到世间，从头到脚，每个毛孔都滴着血和肮脏的东西”。资产阶级革命是资本主义制度确立的开始标志。爆发的原因是资本主义生产的发展使新兴资产阶级在经济上有很大的优势，但封建制度的存在使这种优势难以发挥，只有推翻封建政权才能为发展资本主义扫清障碍，这里能明显看出经济基础决定上层建筑。革命的途径是新兴资产阶级和他们的思想家提出**自由、平等、博爱**的口号——这一思想是在欧洲的启蒙运动中提出来的，是资产阶级反封建的思想武器——利用劳动人民的力量，联合封建统治者的敌人、也就是大批农民和劳动人民，发动向封建地主阶级夺取政权的革命。最具代表性的是1644年的**英国资产阶级革命**和1789年的**法国大革命**，资产阶级革命的胜利标志着人类开始进入资本主义社会并确立资本主义制度。资本主义制度确立的意义是：为工业革命的发生提供了政治前提，推动了工业革命的发生和完成，第一次工业革命将人类带入**蒸汽时代**，第二次工业革命将人类带入**电气时代**，生产工具的革命性进步带来了资本主义社会生产力的巨大飞跃，也促进了人类思想的解放，使科学、教育、文化的发展达到了前所未有的高度。马克思在《共产党宣言》中说，资产阶级在它不到一百年的阶级统治中所创造的生产力，比过去一切世代所创造出来的生产力还要多、还要大。原因可以从两个阶级看：资本家为更大限度地追求利润、占有工人的剩余价值，起初采用延长工作时长等粗暴方式，引起工人反抗后就转变成更聪明也更隐性的做法，通过更新技术设备来提高生产率；工人方面，表面上看只要肯付出更多劳动、提高劳动技术水平和熟练程度，就可以拿到更多工资，所以也表现出了比较强烈的积极性。但资本主义发展到一定阶段就不可避免地爆发**经济危机**。经济危机带有明显的周期性，基本上每隔十年左右爆发一次，其中1929到1933年的经济危机最为严重。经济危机的基本特征是**生产相对过剩**，不是与劳动人民的实际需求相比的绝对过剩，而是相对于劳动人民有支付能力的需求来说社会生产的商品显得过剩：社会明明堆积了大量商品卖不出去，贫穷的劳动人民却又无力购买。课上讲了一个经典对话：被解雇的煤矿工人家庭，孩子问爸爸为什么家里这么冷，爸爸说因为家里没有煤了；为什么没有煤，因为我失业了、买不起煤了；为什么失业，因为煤太多了、卖不出去、工厂倒闭了。经济危机的表现是：大量商品卖不出去，生产资料被闲置，大批企业破产，大批工人失业，企业破产和工人失业又导致银行破产，信用关系被破坏，整个社会生活陷入混乱；一方面资本家把卖不出去的商品销毁，比如把牛奶倒进大海、把奶牛杀掉，另一方面失业的普通工人却不得不排队领取社会救助。经济危机爆发的原因分两层：直接原因是**生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小之间的矛盾**，是个别企业内部生产的有组织性与整个社会生产无政府状态之间的矛盾；根本原因在于**生产社会化与生产资料资本主义私人占有之间的矛盾**，这就是资本主义社会的**基本矛盾**。基本矛盾要这样理解：生产社会化也叫社会化大生产，是指由许多人共同使用生产资料、许多工序相互衔接、许多企业相互配合才能进行的生产，它要求生产资料由劳动者共同所有、生产过程按社会需要统一管理调节和控制、社会化产品由劳动者共同占有，但现实却是生产资料被资本家私人占有、生产过程由个别资本家受利益驱使来管理、产品被资本家以剩余价值的形式占有。生产社会化是生产力方面的表现，生产资料私人占有是生产关系上的表现，所以这一基本矛盾从实质上看仍然是**生产力与生产关系之间的矛盾**在资本主义社会中的体现。这一矛盾在经济上的表现就是无产阶级与资产阶级的对立，这也叫做资本主义社会的**主要矛盾**。基本矛盾是资本主义社会一切矛盾与冲突的总根源，贯穿于资本主义社会发展的始终，决定着资本主义的命运。资产阶级采取各种缓和阶级矛盾的措施，比如改善社会福利，但这些措施没有也不可能从根本上改变资本主义的私有制以及它的剥削关系，所以资本主义越发展，科学技术和社会生产力越进步，生产社会化的程度越高，生产资料和劳动产品就越是集中在极少数的资本家手里，基本矛盾的尖锐化就越来越不可避免，这也决定了**资本主义终将被社会主义取代**，虽然这是一个漫长的过程，但这是历史发展的必然趋势。第二框讲科学社会主义的理论与实践，先讲理论部分。科学社会主义产生的思想来源是**空想社会主义**，研究它有助于理清科学社会主义的来龙去脉。空想社会主义产生的背景是：资本主义社会发展中暴露出矛盾，资本家与工人斗争、资本家唯利是图、工人生活越发贫苦，一些先进分子认识到资本主义社会不是人类的理想社会，于是抨击资本主义、提出未来理想社会的构想。康帕内拉的《太阳城》描述了一个理想社会：每个人每天都要劳动，除了基本劳动之外都在做有趣又愉悦身心的体育活动，那里没有私有制，财产都是公有的，也没有贫富差别。空想社会主义的发展经历了三个阶段：第一阶段是16到17世纪末，代表人物有莫尔的《乌托邦》、闵采尔、康帕内拉的《太阳城》，主要思想是用文学的语言批判资本主义的灾难和罪恶，描述一个没有压迫、人人平等的理想社会，这些描述都十分感性；第二阶段是18世纪，代表人物和著作有摩莱里的《自然法典》、马布利的《论法制或法律的原则》，他们摆脱了早期纯粹虚构的幻想，从法律的角度批判资本主义的私有制，以法律条文的形式提出了人人平等、生产资料公有制等未来社会的基本原则，相比第一阶段有了明显进步；第三阶段是19世纪初，也是空想社会主义的最高阶段，代表人物有**圣西门、傅立叶、欧文**，他们在批判资本主义制度的同时对未来社会提出了很多积极的设想，并且已经开始了初步的制度创设和实践。空想社会主义的发展与资本主义社会的产生和发展息息相关：第一阶段资本主义生产处于简单协作阶段，第二阶段出现了工厂手工业，第三阶段已经开始了机器化大生产，资本主义越发展，资产阶级和工人阶级之间的矛盾越激化，空想社会主义的理论也就越来越进步、越来越接近科学的边缘。但即使到了最高阶段，他们的设想还是失败了：圣西门希望建立一种由实业家和学者领导的社会制度、即**实业制度**，采用说服的方法去实现，最终钱财都化光、理想也没有实现；傅立叶倡导建立**和谐制度**，在这一制度下人人劳动、男女平等，把目标实现寄希望于富翁出资，结果没有任何一个富翁肯支持他；欧文自己出资在美国买下一块地进行**新和谐公社**的共产主义新村实验，已经开始着手实践了，但在当时的社会背景下也没办法持续维持下去。他们失败的原因在于：他们对无产阶级只是表示同情，看不到无产阶级自身是埋葬资本主义并实现社会主义的强大力量，把目标的达成寄希望于个别的资本家和富人，试图通过宣传、呼吁、感化、示范等方式实现未来的社会理想，要让资本家出钱去消灭资本主义社会显然行不通。空想社会主义的局限性有两点：第一，它仅仅从**理性、正义等原则**出发、也就是从道德的角度去揭露资本主义的弊端、设计未来社会的美好蓝图，并没有触及到资本主义社会的本质问题；第二，他们主张**阶级调和、反对阶级斗争**，看不到广大人民群众、特别是无产阶级的力量，没有找到消灭资本主义社会、建立新社会的强大力量，没有找到进行社会变革的正确途径，这些想法都过于天真和幼稚，因为无产阶级如果不进行阶级斗争，就绝不可能自然而然地进入未来的社会主义理想社会。但也不能站在今天的角度片面评价当时的思想，因为在当时工业革命尚未完成，资本主义的发展还不够充分，资本主义社会的矛盾并没有充分暴露出来，无产阶级也还没有形成一支独立的力量，所以那些空想社会主义者看不到他们的力量也是情有可原的。科学社会主义产生的历史前提是资本主义的发展和工人运动的兴起。法国里昂工人的第一次起义目的是提高工价、获取经济上的利益，这就是**经济斗争**；第二次起义除了经济上的要求之外还带有更鲜明的政治性质，提出了废除君主制、建立共和政体的口号，这属于**政治斗争**。无产阶级反对资产阶级的阶级斗争有三种基本形式：第一是经济斗争，目的是获得更高的工资、更好的待遇，但单纯的经济斗争不能够消灭资本主义制度，也不能从根本上改变无产阶级受剥削、被压迫的地位，即使胜利了最多也只是减弱了一些剥削；第二种是政治斗争，目的是推翻资产阶级反动统治、建立和巩固无产阶级政权，政治斗争才是最重要的、最具有决定性作用的斗争形式，因为无产阶级只有取得政权才能够获得经济上的解放，而夺取政权的武装斗争是政治斗争的最高方式；第三种是思想理论斗争，主要任务是向无产阶级和广大人民群众宣传革命思想。法国里昂工人能够通过起义与资本家斗争，说明当时的无产阶级队伍逐渐壮大，已经成为一种不可忽视的力量，同时期还发生了英国宪章运动和德国西里西亚纺织工人起义，他们合称为**欧洲三大工人运动**，这三大工人运动的发生标志着工人阶级开始作为独立的政治力量登上了历史舞台，开始联合起来反抗资产阶级的统治，并且将斗争的矛头指向了整个资产阶级和资本主义制度。但这三大工人运动都不约而同地失败了，原因是没有一个强而有力的政党去领导工人运动，最重要的是缺乏先进的、科学的理论来进行指导，在这种形势下科学社会主义思想也就应运而生了。科学社会主义的创立者是**马克思和恩格斯**，二人在早年就树立了为人类解放事业而奋斗的远大理想，积极参加工人运动，注重理论和实践相结合，不断探索资本主义的本质和规律。习近平在纪念马克思诞辰200周年大会上的重要讲话中高度肯定了马克思的贡献，称马克思是全世界无产阶级和劳动人民的革命导师，是马克思主义的主要创始人，至今仍然被公认为“千年第一思想家”。科学社会主义的创立离不开马克思一生中最重要的两大发现：**唯物史观和剩余价值学说**，这为科学社会主义的创立奠定了理论基石。先看唯物史观，它是科学社会主义的**哲学基础**。它是马克思和恩格斯通过研究社会历史、批判地吸收德国古典哲学中的合理成分、彻底摆脱唯心主义思想的束缚而创立的。德国古典哲学中，黑格尔的哲学思想简单概括为**唯心辩证法**，费尔巴哈的思想则是**形而上学唯物主义**，两个人的思想中都各有其合理性、又有其局限性，马克思批判地吸收了二者的合理成分，吸收了黑格尔的辩证法和费尔巴哈的唯物主义思想，站在了巨人的肩膀上，创立了辩证唯物主义和历史唯物主义，历史唯物主义就叫做唯物史观。在唯物史观之前是唯心史观，它从神的意志去解释历史，比如女娲补天、上帝造人，后来思想有了一定程度的进步，认为是某一个卓越的人物、英雄人物创造了历史、推动了历史向前发展，也叫做**英雄史观**，认为英雄造时势。而马克思的唯物史观透过表面现象看到，**物质资料的生产方式才是人类社会存在和发展的基础**，物质资料的生产方式其实就包括生产力和生产关系，所以人类社会的历史其实就是在生产力和生产关系的矛盾运动中不断前进的。在内容上，唯物史观揭示了人类社会发展的一般规律，也就是**生产关系必须要适应生产力发展状况的规律**，同时也认为并不是个别的英雄和领袖创造了历史，而是**人民群众**这一历史主体推动和创造了历史，在阶级社会中，整个社会的被压迫阶级只有通过阶级斗争的方式才能够推翻旧政权、建立新政权，所以也揭示了阶级斗争的巨大作用。再看剩余价值学说，它是科学社会主义的**经济学基础**。它是马克思通过剖析资本主义社会、批判继承英国古典政治经济学的思想成果而创立的，英国古典政治经济学的思想成果可以简单概括为**劳动决定价值**，马克思在这一基础上提出了劳动价值论，进而发现了在资本主义社会中工人劳动创造的价值远远高于资本家给付的工资，提出了剩余价值学说。在资本主义社会中，资产阶级凭借自己对生产资料的占有去无偿地获取工人的剩余价值，工人为了维持基本的生存不得不受雇于资本家、被资本家剥削，要改变这种状况，只有推翻资本主义的生产资料私有制以及维护这种生产关系的整个资产阶级政权。剩余价值学说从经济学的角度揭示了剩余价值的来源，揭示了资本家剥削工人、占有工人劳动的秘密，这种剥削是隐藏在生产过程中的；它也揭示了无产阶级与资产阶级在利益上的根本对立，找到了变革资本主义社会的坚定力量，这一力量指的就是**无产阶级**，为无产阶级的斗争指明了方向，也就是无产阶级必须要通过阶级斗争的方式去推翻资产阶级政权、建立无产阶级政权。唯物史观和剩余价值学说对于科学社会主义的诞生有重要意义：二者为科学社会主义的创立奠定了理论基石，使社会主义实现了**由空想到科学的伟大飞跃**。相比之前的空想社会主义者指望靠资本家大发善心、靠说服、搞共产主义实验等方式去实现理想社会，现在已经触及到了资本主义的本质问题，并且看到了无产阶级的强大力量，也找到了无产阶级要用革命斗争去实现社会发展的根本途径，所以说它克服了空想社会主义者的局限。在科学社会主义的形成中，除了以上两个重大发现之外，还有一个十分重要的事件，就是《共产党宣言》的发表，它标志着**科学社会主义的诞生**。《共产党宣言》的主要内容共三个部分：第一个部分揭示了一个规律，《共产党宣言》分析了资本主义生产方式的内在矛盾与人类社会的发展规律，科学论证了**资本主义必然灭亡、社会主义必然胜利**的历史必然性；第二个部分是对一个政党、也就是无产阶级政党做出了阐述，《共产党宣言》总结了工人运动的经验教训，第一次系统论述了无产阶级政党的性质、特点、任务、策略，阐明了建立无产阶级政党的必要性，其中性质是共产党是代表无产阶级的政党，是无产阶级中最有觉悟、最有战斗力的先进部队，是**无产阶级的先锋队**，特点是共产党除了代表整个无产阶级的根本利益之外没有自己的特殊利益，策略和任务是无产阶级只有在共产党的领导下才能有组织地进行斗争、团结绝大多数人，推翻资产阶级统治、建立无产阶级政权、继续发展社会生产力、使全体社会成员都能够实现全面发展、从而为建立共产主义新社会创造必要的条件；第三个部分阐述了一个目标，也就是未来共产主义社会的理想目标，《共产党宣言》指出，代替那存在着阶级和阶级对立的资产阶级旧社会的，将是这样一个联合体，在那里，**每个人的自由发展是一切人的自由发展的条件**。根据马克思的描述，未来的共产主义理想社会将是一个生产力高度发达、物质财富极大丰富、没有私有制、没有私有观念、一切劳动产品按需分配、全体社会成员具有超高的道德品质和觉悟的社会，到那个时候劳动已经不再是一种谋生手段，而已经上升为了**生活的第一需要**，人们可以实现自由而全面的发展。《共产党宣言》发表的意义是：它标志着科学社会主义的诞生；它的问世是人类思想史上的一个伟大事件，也是第一次全面系统阐述科学社会主义原理的伟大著作；它是一部科学洞见人类社会发展规律的经典著作，是一部充满斗争精神、批判精神、革命精神的经典著作，是一部秉持人民立场、为人民大众谋利益、为全人类谋解放的经典著作；在后面的历史发展中可以更好地指导工人运动，工人阶级从此就拥有了强大的思想武器。教材还讲了马克思主义的基本特征：第一，它是**科学的理论**，因为它正确地揭示了人类社会的发展规律；第二，它是**人民的理论**，第一次创立了人民实现自身解放的思想体系；第三，它是**实践的理论**，它指引着人民改造世界的行动；第四，它也是**不断发展着的、开放的理论**，始终站在时代的前沿。要注意区分：实现社会主义由空想到科学的伟大飞跃的是唯物史观和剩余价值学说，而《共产党宣言》提供的是根本指导、不是具体指导。第二框的实践部分讲社会主义从一国到多国的实践。首先是1871年，**巴黎公社**宣告成立，它是无产阶级夺取政权的第一次尝试，但仅仅存在了70天就被镇压而失败了。真正在实践上取得成功、建立社会主义政权的是1917年的**俄国十月革命**，在以列宁为代表的俄国布尔什维克党的领导下，俄国无产阶级通过革命斗争推翻了资产阶级统治、建立了无产阶级政权。十月革命有着非常重大的历史意义：它建立了**世界上第一个社会主义国家**，将马克思主义关于无产阶级革命的理论变成了现实，实现了社会主义**从理论到制度的伟大跨越**，开启了人类历史的新纪元，从此世界范围内开始有了全新的社会主义国家的存在。受到十月革命的影响，李大钊在一篇文章中写道：“试看将来的环球，必是赤旗的世界”，反映出当时的人们受到了极大的鼓舞和振奋。通过十月革命，俄国确立了社会主义的生产关系，具体内容是：从生产资料所有制上看，是**劳动者共同占有生产资料**；从人与人之间的关系上看，消灭了人剥削人的制度，人们在生产过程中建立起了互助合作的关系；从产品的分配方式上看，个人消费品实行的是**按劳分配**。然后社会主义出现了星星之火可以燎原的势头，在第二次世界大战之后，社会主义在世界范围内获得了巨大的发展，实现了从一国到多国的发展和跨越，并在全球范围内形成了与资本主义阵营相抗衡、相对峙的社会主义阵营，取得了历史性的飞跃。但是社会主义作为一个新事物，它的发展并不是一帆风顺的，二十世纪八十年代末九十年代初，随着**东欧巨变、苏联解体**，世界社会主义运动的发展出现了严重的曲折，社会主义在当时备受质疑。但是要清楚，这并不是马克思主义和科学社会主义的理论出现了错误，而是这些国家的现实做法背离了科学社会主义和马克思主义所导致的结果，这也并不意味着社会主义从此湮灭。把眼光聚焦于21世纪的中国，中国特色社会主义正是科学社会主义在中国的实践与发展，我们的社会主义道路使中国用短短70年的时间就走过了西方发达国家几百年的工业化和现代化历程，创立了**中国式现代化**道路，使我们国家迎来了从站起来、富起来再到强起来的伟大飞跃，在全球范围内也充分展示了社会主义制度的优越性，所以说科学社会主义在今天仍然焕发着强大的生命力，社会主义未来可期。", "vtech": [["国家产生别说反了", "看到国家起源题 → 记住链条：生产力发展→私有制出现→阶级产生→阶级矛盾不可调和时才出现国家；国家是阶级矛盾不可调和的产物、阶级统治的工具，不是从来就有的；我国第一个奴隶制国家是夏。"], ["剩余价值的数会算", "看到剩余价值题 → 记住算法：工人劳动创造的价值减去资本家给付的工资，超过的部分就是被无偿占有的剩余价值；课上例子：日工资100元、工作10小时，6小时就创造出100元，剩下4小时创造的就是剩余价值；剥削的秘密是隐藏在生产过程中的。"], ["经济危机的三层原因别混", "看到经济危机题 → 分三层：基本特征是生产相对过剩（相对于劳动人民有支付能力的需求而言，不是绝对过剩）；直接原因是生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小之间的矛盾；根本原因是资本主义社会的基本矛盾。"], ["空想与科学的分界线", "看到空想社会主义题 → 记住局限有两条：只从理性、正义等道德原则出发，没触及资本主义本质；主张阶级调和、反对阶级斗争，看不到无产阶级的力量；实现由空想到科学飞跃的是唯物史观和剩余价值学说，诞生标志是《共产党宣言》的发表——两者别张冠李戴。"]], "vgaokao": []}}, "u_pol_2": {"id": "u_pol_2", "name": "只有社会主义才能救中国", "secs": "第二课", "pageFrom": 20, "pageTo": 30, "members": ["pol_p003", "pol_p004"], "video": {"bvid": "BV1Cr421T75t", "p": 1, "t": "只有社会主义才能救中国", "dur": "47:16", "from": "政治老师爱政治", "vtop": ["资本主义道路在中国行不通：帝国主义不允许、封建势力不愿意、民族资产阶级没能力——三句话记牢行不通的原因。", "新民主主义革命的“新”在三处：无产阶级领导、前途是建立无产阶级领导下的各革命阶级联合专政并过渡到社会主义、属于世界无产阶级革命的一部分。", "过渡时期总路线是“一化三改”：逐步实现国家社会主义工业化，逐步实现对农业、手工业和资本主义工商业的社会主义改造；1956 年三大改造完成，社会主义制度基本确立。"], "vsum": "本课讲第二课**只有社会主义才能救中国**，分两框：第一框新民主主义革命的胜利，时间段是 **1840 年到 1949 年**；第二框社会主义制度在中国的确立，对应社会主义革命时期，也叫过渡时期，时间段是 **1949 年到 1956 年**，之后 1956 年到 1978 年是社会主义建设的艰辛探索。先看近代中国的社会性质：进入近代以来，西方国家通过资产阶级革命和工业革命进入资本主义社会、生产力大发展并对外殖民扩张，而中国因清王朝长期闭关锁国、政治腐败而贫穷落后，沦为**半殖民地半封建社会**：**1840 年第一次鸦片战争**后中国逐渐开始沦为半殖民地半封建社会，**1856 年第二次鸦片战争**后半殖民地化程度进一步加深，**1894 年中日甲午战争**后大大加深，**1900—1901 年八国联军侵华、签订《辛丑条约》**后中国完全沦为半殖民地半封建社会。**半殖民地**指形式上独立、但政治经济文化各方面都受到外国资本主义控制和压迫、丧失了部分主权，当时中国内部有许多外国租界、被称为“国中之国”，如厦门鼓浪屿英租界、哈尔滨俄租界（1907 年起修建索菲亚大教堂）；**半封建**指原有封建属性遭到破坏、资本主义有了一定发展，但封建剥削制度仍占主导地位。易错提醒：不能简单粗暴地理解为政治上半殖民地、经济上半封建。沦为半殖民地半封建社会的原因分内外两面：外部是西方列强入侵，中国深受**帝国主义、封建主义和官僚资本主义**三重压迫；内部是封建制度落后加上长期闭关锁国，使中国在经济政治文化各方面都落后了。由此得出近代中国人民的两大历史任务：**争取民族独立、人民解放**，**实现国家富强、人民幸福**——其中国家富强、人民幸福是民族独立、人民解放的目的，而民族独立、人民解放又是实现国家富强、人民幸福的前提；当时的主要矛盾是**帝国主义与中华民族、封建主义与人民大众的矛盾**。面对内忧外患，无数仁人志士艰苦探索救亡图存之路：**太平天国运动**是农民阶级发起的反封建反侵略起义，**洋务运动**是地主阶级洋务派发起的封建统治者自救运动，**戊戌变法**是资产阶级性质的改良运动，**义和团运动**是农民阶级提出“扶清灭洋”口号的反帝爱国运动，**清末新政**是以慈禧太后为代表的封建统治阶级为延续统治、巩固皇权而进行的改革运动，**辛亥革命**是资产阶级发起的、为推翻清朝专制、建立共和政体的资产阶级民主革命；辛亥革命后中国还尝试过君主立宪制、帝制复辟、议会制、多党制、总统制等各种形式，结果无一例外全部失败，告诉我们**在半殖民地半封建的近代中国，资本主义道路是走不通的**，必须另辟新路。为什么行不通，由近代中国的基本国情决定，分三点：**帝国主义不允许**——帝国主义入侵中国的目的是把中国变成殖民地或半殖民地、维护在华特权，绝不允许中国走资本主义道路强大起来成为竞争对手；**封建势力不愿意**——中国封建势力同帝国主义相勾结，严重阻碍民族资本主义经济发展；**民族资产阶级没能力**——中国民族资产阶级力量十分弱小，又与封建主义和外国资本主义有着千丝万缕的联系，具有软弱性和妥协性，不能承担领导中国人民完成反帝反封建民主革命的使命和任务。正当寻找救国救民的道路屡遭挫折时，**俄国十月革命一声炮响，给中国送来了马克思列宁主义**，中国先进分子从中看到了解决中国问题的新出路，开始接受并传播马克思列宁主义，进入胜利的征程——新民主主义革命时期。新民主主义革命的指导思想是**马克思列宁主义**；开始的标志是 **1919 年五四运动**：中国作为一战战胜国在巴黎和会上受到帝国主义不公正对待，软弱的北洋政府卖国求荣、要把德国在山东的权力拱手让给日本，1919 年 5 月 4 日北京爆发声势浩大的五四运动，喊出“**外争主权，内除国贼**”、拒绝在巴黎和约上签字、废除二十一条、还我青岛、打倒卖国贼等口号。“外争主权”是反对帝国主义的不公正对待，“内除国贼”是反抗卖国求荣的封建北洋政府，所以五四运动是中国人民彻底反抗帝国主义和封建主义的爱国运动，具有彻底反帝反封建的革命性、追求救国强国真理的进步性，又以青年学生为先锋、各族各界群众积极参与，具有广泛性；每年 5 月 4 日设为**五四青年节**。五四运动为中国共产党的成立做了思想上和干部上的准备：思想上促进了马克思列宁主义在中国的传播，干部上初步掌握马列主义的先进分子到工人群众中做宣传和组织工作，实现先进知识分子与工人运动的结合；五四运动在近代以来中华民族追求民族独立和发展进步的历史进程中具有里程碑意义，是**旧民主主义革命走向新民主主义革命的转折点**。1921 年，在马列主义同中国工人运动相结合的过程中，**中国共产党应运而生**，从此中国人民谋求民族独立、人民解放、实现国家富强、人民幸福的斗争有了主心骨，中国共产党成为新民主主义革命的领导力量。此后中国共产党带领中国各族人民经过 28 年浴血奋战，经历**大革命、土地革命战争、抗日战争、解放战争**四个阶段，终于在 1949 年夺取新民主主义革命的伟大胜利、建立中华人民共和国。革命斗争中总结出战胜敌人的**三大法宝：统一战线、武装斗争、党的建设**——统一战线是因为当时中国革命的敌人太强大，单凭无产阶级一个阶级的力量不够，必须组织革命的统一战线，农民是工人阶级的同盟军，还可以联合城市小资产阶级和民族资产阶级，发动群众、团结一切可以团结的力量；武装斗争即“枪杆子里出政权”，是中国共产党从大革命失败的血的教训中得出的宝贵经验，新民主主义革命的特点就是长期的武装斗争、以武装的革命反对武装的反革命，统一战线和武装斗争是战胜敌人的两个基本武器；党的建设方面，只有把党建设好才能更好地领导中国革命走向胜利，1941 年抗日战争时期开始的**延安整风运动**就是中国共产党历史上第一次大规模的整风运动，目的是进行马克思列宁主义教育、提高全党的马列主义水平、纠正党内的错误思想；三大法宝是毛泽东对中国新民主主义革命经验的基本总结。新民主主义革命的性质是**无产阶级领导的、以工农联盟为基础的、人民大众的、反对帝国主义、封建主义和官僚资本主义的民主革命**，其中领导阶级是无产阶级，阶级基础是工农联盟，主体是人民大众，革命任务是反对帝国主义、封建主义和官僚资本主义这三座大山。新民主主义革命与旧民主主义革命相比，“新”在三处：领导权上，新民主主义革命的领导者是无产阶级，旧民主主义革命的领导者是资产阶级；革命前途上，新民主主义革命要建立**无产阶级领导下的各革命阶级的联合专政**并最终过渡到社会主义社会，旧民主主义革命要建立资产阶级共和国和资本主义制度；革命所属范畴上，新民主主义革命属于世界无产阶级革命的一部分，旧民主主义革命属于世界资产阶级革命的一部分。根据革命前途，中国革命必须分两个步骤：第一步是民主革命，改变半殖民地半封建的社会形态，使中国社会变成一个独立的民主主义的社会；第二步是社会主义革命，建设社会主义社会；**新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主义革命的必然趋势**，只有完成前一个革命才能完成后一个革命，两个革命阶段必须相互衔接。1949 年新中国成立，第一步就此完成，也标志着新民主主义革命的胜利。新中国成立的意义可概括为“辞旧”与“迎新”：“辞旧”是指它彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了极少数剥削者统治广大劳动人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，实现了中国从几千年封建专制政治向人民民主的伟大飞跃；“迎新”是指新中国的成立为实现由新民主主义向社会主义的过渡创造了条件，从根本上改变了中国社会的发展方向，为实现国家富强、民族复兴展示了美好前景和现实道路；对外看，新中国的诞生是 20 世纪的伟大历史事件，它在人口约占世界四分之一、领土面积世界第三的中国建立起人民民主制度并逐步建立起社会主义制度，从而大大加强了世界和平民主和社会主义阵营的力量，改变了二战之后国际冷战格局中的力量对比，冲破了帝国主义的东方战线，极大地改变了世界政治力量对比，鼓舞和推动了世界被压迫民族和被压迫人民争取解放的斗争。在新民主主义革命实践中，中国共产党人把马克思列宁主义基本原理同中国革命具体实际相结合，开辟了**农村包围城市、武装夺取政权的正确革命道路**，创立了**毛泽东思想**，这是新民主主义革命中形成的重大理论成果，为夺取新民主主义革命胜利指明正确方向；毛泽东思想也是**马克思主义中国化的第一次伟大飞跃**。第二框讲社会主义制度在中国的确立。新中国成立后并没有马上进入社会主义社会，还要继续通过 1949 年到 1956 年的社会主义改造，完成中国革命的第二步——社会主义革命、建立社会主义社会；1949 年新中国成立到 1956 年三大改造完成这段时期，就是从新民主主义向社会主义的**过渡时期**。建国之初形势十分严峻：农业工业都非常落后，人口素质比较低，教育水平也很低，环境条件也非常恶劣，而且国民党还留下贫穷落后、千疮百孔的烂摊子，撤退时掠夺大量财富、炸毁桥梁矿井等基础设施。在这样的背景下，中国共产党提出过渡时期的总路线和总任务：**要在一个相当长的时期内，逐步实现国家的社会主义工业化，并逐步实现国家对农业、手工业和资本主义工商业的社会主义改造**，简单概括为“**一化三改**”。其中“一化”是由新中国建立之初国家贫穷、工业基础十分薄弱的现状决定的，当时新中国与西方发达国家差距十分大，毛主席曾说：“我们现在能造什么？我们能造桌子椅子，能造茶碗茶壶，但一辆汽车、一架飞机、一辆坦克、一辆拖拉机都造不出来。”“三改”是对农业、手工业和资本主义工商业进行社会主义改造：改造之前这些都属于生产资料私有制，对农业和手工业实行类似生产合作社的改造方式，使之变成社会主义集体所有制，对资本主义工商业实行公私合营的方式，使之变成社会主义公有制，总之就是把生产资料私有制转变为公有制。“一化”是在解放和发展社会生产力，“三改”是在调整生产关系，目的是使生产资料的社会主义公有制占主体地位、成为国家唯一的经济基础。党在过渡时期的总路线和总任务的提出，是根据马克思列宁主义理论、并依据新中国成立之后政治经济条件的新变化作出的重大决策，符合新中国社会发展的实际和规律，反映了从新民主主义向社会主义过渡的历史必然性，具体有四方面：第一，社会主义国营经济迅速发展，逐步成为社会经济中的主导性因素——1949 到 1952 年，国家剥夺国民党四大家族官僚资本归人民国家所有，并采用多种形式接收英美等国在华企业，加上各种措施恢复国民经济，使公有制经济在国民经济中迅速占据绝对优势，为从新民主主义向社会主义过渡提供了重要物质基础；第二，国家积累了利用、限制和管理私营工商业的经验，不同程度地开始了对他们的初步社会主义改造——国家在合理调整工商业的过程中创造了**加工订货、经销代销、统购包销、公司合营**等一系列从低级到高级的国家资本主义形式，使之逐步接受国家的监督和管理，同时 1952 年开展**五反运动**，即反行贿、反偷税漏税、反盗骗国家财产、反偷工减料、反盗窃国家经济情报，打击当时一些不法资本家的“五毒”行为，对工商业者进行守法经营的教育，推动私营企业建立工人监督制度和实行民主改革；第三，个体农业经济难以适应国家工业化建设的新形势，迫切需要组织起来——分散落后的小农经济很难使用大机器、无力抵御自然灾害、不利于生产力发展，如果不把农民组织起来，不仅不能改善农民生活，也不可能为工业发展提供必要的商品粮食原材料等条件，只有农业集体化、规模化才有可能实现社会主义工业化；工业化初期往往采用用农业支持工业的方针，工业化达到相当程度时工业就要反过来反哺农业；具体操作上当时通过互助组、农业合作社的方式把农民组织起来；第四，国际形势有利于中国加快向社会主义阵营转变——二战之后世界两大阵营对抗，以美国为代表的西方国家在外交、经济、军事等领域对中国严密封锁，只有苏联等社会主义国家支持中国，所以新中国在对外关系上实行向社会主义国家“一边倒”的方针，1950 年签订**《中苏友好互助同盟条约》**，苏联对华提供三亿美元贷款和一批工业援助项目，有利于新政权在国际社会上站稳脚跟。这四个方面决定了从新民主主义向社会主义过渡具有历史必然性。1956 年社会主义改造完成，有十分重大的意义：第一，标志着中国实现了从新民主主义向社会主义的转变，从此进入社会主义社会——这里要明确 1840 年以来中国社会性质的变化：1840 年鸦片战争爆发到 1949 年新中国成立属于半殖民地半封建社会，1949 年到 1956 年三大改造期间属于新民主主义性质的社会，1956 年社会主义改造完成之后才真正进入社会主义社会；第二，中国共产党在一个经济文化落后的东方大国创造性地开辟了一条适合中国特点的社会主义改造道路，顺利实现了对生产资料私有制的社会主义改造——对农业和手工业实行从小到大、从低级到高级的改造方式，对资本主义工商业创造性地实行加工订货、统购包销、经销代销、公司合营等形式，都顺利实现了由生产资料私有制向社会主义公有制的转变；第三，在中国建立起了社会主义制度，完成了**中华民族有史以来最为广泛而深刻的社会变革**；第四，社会主义改造的伟大胜利极大地激发了广大人民群众建设社会主义的积极性，社会生产力有了比较迅速的发展，社会秩序更加稳定，人民民主专政更加巩固，从而为我国全面建设社会主义奠定了坚实基础。社会主义改造完成、确立社会主义基本制度、进入社会主义社会之后，就迎来了新的历史时期——**社会主义建设时期（1956—1978 年）**。如何建设社会主义、如何巩固和发展社会主义，是一个崭新的历史课题，没有现成的答案和经验可以遵循；面对新情况新问题，中国共产党以马克思列宁主义基本原理为指导，以苏联的经验教训为借鉴，结合中国具体实际，开始探索适合中国国情的社会主义建设道路，这就是马克思列宁主义原理同中国具体实际的**第二次结合**（第一次结合是与新民主主义革命时期的具体实际相结合，第二次结合则是与社会主义革命和建设时期的具体实际相结合）。在这样的背景下，**1956 年 9 月中共八大召开**，这是新中国成立以来中国共产党召开的第一次全国代表大会；中共八大最重要的贡献是正确分析了国内形势和国内主要矛盾的变化，明确提出了党和全国人民在新形势下的主要任务，为社会主义事业的发展指明了方向。关于主要矛盾，党的八大指出，社会主义改造完成之后，我国的主要矛盾已经不再是无产阶级同资产阶级之间的阶级矛盾，而是**人民对建立先进的工业国的要求同落后的农业国的现实之间的矛盾**，是**人民对于经济文化迅速发展的需要同当前经济文化不能满足人们需要的状况之间的矛盾**；因此主要任务就是**集中力量发展社会生产力，尽快把我国从落后的农业国变为先进的工业国**。在正确方向指引下，我国在社会主义建设时期取得了巨大成就：工业方面建立起独立的、比较完整的工业体系和国民经济体系，50 年代中央集中力量建设鞍钢，其钢铁产量一度占据全国半壁江山、被誉为钢铁行业的“共和国长子”，1956 年在长春第一汽车制造厂诞生了新中国第一辆解放牌汽车；农业方面，党带领农民克服各种困难，大规模建设农业基础设施，兴修了红旗渠等一大批防洪灌溉工程设施，改善农业生产条件，粮食产量有了较大增长，初步满足了占世界四分之一人口的基本生活需求；基础设施方面，建筑、交通运输等获得较快发展，1957 年被誉为“万里长江第一桥”的**武汉长江大桥**正式通车、“天堑变通途”，它是当时我国自行设计建造的最长的铁路公路两用桥，70 年代中国第一条电气化铁路**宝成铁路**正式通车；科教方面，科技发展取得重大突破，教育医疗事业也得到长足发展，1964 年我国成功爆炸第一颗原子弹、打破超级大国核垄断，教育方面保障人民群众受教育的权利，开展大规模扫盲和工农干部文化补习教育，逐渐形成比较完整的国民教育体系；人们的精神面貌也得到极大改变，广大人民群众意气风发、斗志昂扬，面对巨大困难和压力坚持独立自主、自力更生，团结一致、艰苦奋斗，培育和发扬了“**两弹一星**”精神、**大庆精神**等；对外看，中国成为世界上有重要影响的大国，70 年代外交方面取得很多成就：中日建交、中美建交、中国在联合国的合法席位得以恢复。这些成就雄辩地证明了社会主义道路是正确的、只有社会主义才能救中国。但是由于国际局势复杂多变、国内建设任务艰巨繁重，再加上缺乏领导社会主义建设的现成经验，我们在取得伟大成就的同时也犯了错误、经历了曲折：1958 年的**大跃进运动**在发展生产上急于求成，导致出现浮夸风、“放卫星”的严重错误；大跃进过程中又发生**人民公社化运动**，在生产关系上过度、片面地追求“**一大二公**”，使生产力遭到严重破坏；并且在阶级斗争问题上犯了绝对化、扩大化的错误，导致发生“**文化大革命**”这样的十年内乱；所以社会主义建设的探索过程是成就与曲折并存的。这些探索的意义有四方面：第一，得出一个重要结论——我国社会发生翻天覆地的变化，雄辩地证明了**只有社会主义才能救中国**；第二，一个伟大飞跃——新民主主义革命的胜利、中华人民共和国的诞生、社会主义制度的确立和社会主义建设的全面展开，实现了中华民族从“**东亚病夫**”到**站起来的伟大飞跃**；第三，从毛泽东思想的角度看，把马克思列宁主义基本原理同中国社会主义革命和建设时期的具体实际进行了第二次结合，丰富和发展了毛泽东思想，是**马克思主义中国化时代化的第一次历史性飞跃**；第四，承上启下——党在社会主义革命和建设中取得的独创性理论成果和巨大成就，为新的历史时期、也就是改革开放时期开创中国特色社会主义提供了宝贵经验、理论准备和物质基础。习近平总书记在纪念毛泽东同志诞辰 120 周年座谈会的讲话中指出，在中国这样的社会历史条件下，建设社会主义没有先例，犹如攀登一座人迹罕至的高山，一切攀登者都要披荆斩棘开通道路；事物发展的道路是曲折的、迂回的，但前途是光明的，历史总是在向前发展的；总结和吸取历史教训，目的就是以此为鉴、更好地前进。课中穿插的几道练习题，讲题时都是逐个选项对照着讲、对在哪里、错在哪里，考的也都是上面这些点。", "vtech": [["资本主义道路行不通：三句话对应三方", "看到问为什么行不通 → 先对号：帝国主义不允许（怕中国强大起来成为竞争对手）、封建势力不愿意（勾结帝国主义、阻碍民族资本主义发展）、民族资产阶级没能力（力量弱小、软弱性妥协性）；三方缺一不可，别只答一条。"], ["新民主主义革命的“新”：三处对比", "看到新旧对比题 → 抓三处：领导权（无产阶级 vs 资产阶级）、前途（无产阶级领导下的各革命阶级联合专政并过渡到社会主义 vs 资产阶级共和国和资本主义制度）、范畴（世界无产阶级革命的一部分 vs 世界资产阶级革命的一部分）。"], ["社会性质三段别串：1840–1949、1949–1956、1956 之后", "看到社会性质判断题 → 先定时间：1840 年鸦片战争到 1949 年新中国成立是半殖民地半封建社会；1949–1956 年三大改造期间是新民主主义性质的社会；1956 年社会主义改造完成之后才真正进入社会主义社会。"], ["“一化三改”与中共八大主要矛盾", "看到过渡时期总路线 → 默念“一化三改”：逐步实现国家社会主义工业化，逐步实现对农业、手工业和资本主义工商业的社会主义改造；看到中共八大 → 主要矛盾已变：不再是无产阶级同资产阶级之间的阶级矛盾，而是人民对建立先进工业国的要求同落后的农业国现实之间的矛盾，主要任务是集中力量发展社会生产力。"]], "vgaokao": []}}, "u_pol_3": {"id": "u_pol_3", "name": "只有中国特色社会主义才能发展中国", "secs": "第三课", "pageFrom": 31, "pageTo": 41, "members": ["pol_p005", "pol_p006"], "video": {"bvid": "BV18T421k7Qr", "p": 1, "t": "只有中国特色社会主义才能发展中国", "dur": "51:24", "from": "政治老师爱政治", "vtop": ["十一届三中全会1978年12月召开，开启改革开放和社会主义现代化建设新时期，是新中国成立以来党的历史上具有深远意义的伟大转折——与社会主义制度确立的“最为广泛而深刻的社会变革”区分开。", "改革开放分三个阶段：起步阶段1978—1992、新阶段1992—2012、全面深化阶段2012年十八大以来；改革是社会主义制度的自我完善和发展，不是根本变革社会主义制度。", "意义记“四个面貌、三个飞跃”：改革开放是党和人民大踏步赶上时代的重要法宝（是“赶上”不是“引领”）、坚持和发展中国特色社会主义的必由之路、决定当代中国命运的关键一招；中华民族迎来从站起来、富起来到强起来的伟大飞跃（是“迎来”不是“实现”）。"], "vsum": "本课讲必修一第三课，分两框：第一框是**伟大的改革开放**，第二框是**中国特色社会主义的创立、发展和完善**。开场先看两组信息：1965年美国的人均GDP是中国的41倍，到1978年变成了76倍，差距还在持续扩大；西德一个露天煤矿年产煤5000万吨只有2000名职工，国内却需要16万名工人；法国一家钢铁厂年产钢350万吨、职工7000人，武汉钢铁公司年产量230万吨却有6.7万人；70年代中美两国农村状况对比也直观显示当时中国人民的生活水平和居住环境严重落后于美国。总之当时经济上濒临崩溃，人民生活温饱尚不能解决，国家已经到了何去何从的重大历史关头。邓小平同志指出，如果现在再不进行改革，我们的现代化事业和社会主义事业都会被葬送。正是在这样的历史关头，我们党在**1978年12月**召开了**十一届三中全会**，开启了改革开放的历程。在十一届三中全会上，首先重新确立了马克思主义的**思想路线、政治路线和组织路线**：思想路线就是否定当时错误的“两个凡是”的观点，重新确立**解放思想、实事求是**；政治路线指的是**以经济建设为中心，实行改革开放**；组织路线指的是在实际上形成了**以邓小平为核心的党中央第二代领导集体**。其次还实现了党和国家工作中心的战略转移，也就是否定了“以阶级斗争为纲”，把党和国家的工作重点转移到**社会主义现代化建设**上来。十一届三中全会开启了改革开放和社会主义现代化建设的新时期，实现了新中国成立以来党的历史上具有**深远意义的伟大转折**。这里要注意区分：之前第二课讲到，社会主义制度的确立是中华民族有史以来最为广泛而深刻的社会变革，而改革开放则是中华人民共和国成立以来党的历史上具有深远意义的伟大转折。十一届三中全会之后，中国正式进入了改革开放时期。那到底什么是改革开放呢？首先**改革**指的是在**坚持社会主义制度的前提下**，调整生产关系同生产力、上层建筑同经济基础之间不相适应的环节，它既包括经济体制的改革，也就是要把当时高度集中的**计划经济体制**改革为**社会主义市场经济体制**，还包括政治方面的改革，包括发展民主、加强法治等。邓小平同志指出，改革是**中国的第二次革命**。改革是社会主义制度的一种**自我完善与发展**，而不是要从根本上变革或者说推翻社会主义制度。下面是**开放**，开放指的是**对外开放**，它是加快我国现代化建设的必然选择，也是必须长期坚持的一项**基本国策**。所以改革开放可以简单概括为**对内改革与对外开放**，无论从时间还是内容上，改革与开放都不是完全孤立的，它们之间是相辅相成、密不可分的。改革开放的进程可以分为**三个阶段**。第一个阶段称为**起步阶段**，指的是**1978年到1992年**。在对内改革方面，十一届三中全会之后，农村改革率先取得突破，**家庭联产承包责任制**推行，乡镇企业迅速发展。1978年冬，安徽凤阳县小岗村18户村民在一份分田到户的秘密契约上按下鲜红的手印，实行农业“大包干”，18枚红手印把农村原有的生产合作社变更为家庭联产承包责任制，最终上升为我国农村的**基本经营制度**。家庭联产承包责任制是在**土地公有制**的基础上，将土地长期承包给农民各家各户来使用，由集体经营变为分户自主经营、自负盈亏，当时流行一个顺口溜叫“交够国家的、留足集体的，剩下的全是自己的”。小岗村搞了大包干，第二年粮食产量增加了**四倍**，农民收入增加了**16倍**，村民人均收入从上年的22元跃升到了350元，小岗村一年就越过了温饱线。到1984年，**十二届三中全会**召开，标志着中国改革的重点**从农村转向了城市**，企业改革迈出重要步伐，尤其是国企改革，提出了**政企分开、自负盈亏**，降低国企对国家的依赖。90年代一大批效率低下、管理落后的国企被淘汰、关闭，还引发了一波下岗潮，放在当时是社会的阵痛，但从长远看有利于促进国企效率的提高和国家经济的腾飞。在对外开放方面，**1980年**设立了**深圳、珠海、汕头、厦门四个经济特区**，**1984年**开放了大连、青岛等**14个沿海港口城市**，**1988年**设立海南省、建立海南经济特区，**1990年**开放了上海浦东，1992年开放了沿长江五个城市、17个内陆省会城市，还有东北、西北、西南等一系列沿边城市，至此我国**全方位、多层次、宽领域**的对外开放格局基本形成：全方位指的是对世界所有国家开放；多层次指的是由点到线到面，先开放几个经济特区，此后又开放一批沿海港口城市，沿东南海岸线形成一条线，接着持续开放珠三角、闽南三角、长三角几大区域；宽领域不仅仅是在经济上打开国门，更是涵盖了经济、政治、科技、教育、文化、体育、卫生等众多领域。第二个阶段是**1992年到2012年**，也称为改革开放的**新阶段**，以**1992年邓小平南方谈话**和**党的十四大明确建立社会主义市场经济体制目标**为标志。南方谈话指的是邓小平在1992年年初视察武昌、深圳、珠海、上海等地的谈话，邓小平发表了“**计划经济不等于社会主义，资本主义也有计划；市场经济不等于资本主义，社会主义也有市场，计划与市场都是经济手段**”的重要论述。所以在这一阶段，对内改革完全是围绕着社会主义市场经济这一条主线展开的：在计划经济时代，粮票、布票、电视机票、自行车票都是产物，生产什么、生产多少、卖到哪里都是国家说了算，束缚了企业的手脚。1992年十四大提出建立社会主义市场经济体制的目标之后，1993年党的**十四届三中全会**就建立社会主义市场经济体制进行了部署，到了2003年党的**十六届三中全会**就围绕完善社会主义市场经济体制进行了部署。在对外开放方面，**2001年**中国成功地**加入了世界贸易组织**，标志着我国对外开放进入了一个新的阶段，中国的对外开放由**政策性开放向制度性开放**转变，入世之后中国积极兑现承诺，大幅度降低关税，积极参与国际经济合作和国际分工，加速与国际市场接轨，对外贸易得到了快速发展。**2012年党的十八大**提出了**全面建成小康社会和全面深化改革开放**的目标，于是进入改革开放的第三个阶段，叫做**全面深化阶段**。在对内改革方面，十八大以来党以巨大的政治勇气全面深化改革，打响改革攻坚战，加强改革顶层设计，坚决破除各方面的体制机制弊端，各领域基础性制度框架基本建立，许多领域实现了历史性变革、系统性重塑、整体性重构，新一轮党和国家机构改革全面完成，**中国特色社会主义制度更加成熟更加定型**，国家治理体系和治理能力现代化水平明显提高，比如十八大以来国家在反腐败领域坚持刀刃向内、重拳出击、保持高压态势。在对外开放方面，实行更加积极主动的开放战略，构建面向全球的高标准自由贸易区网络，加快推进自由贸易试验区、海南自由贸易港建设，共建“**一带一路**”成为深受欢迎的国际公共产品和国际合作平台，形成更大范围、更宽领域、更深层次对外开放格局。所以在全面深化阶段，对内持续深化改革，对外继续扩大开放，改革开放不断向纵深推进。其实在刚才每个阶段提到的代表性事件和重要会议中，经常出现**三中全会**：党的全国代表大会**每五年举行一次**，选举产生中央委员会，该届中央委员会召开的第三次全体会议就是三中全会。三中全会多出重大决策，尤其是经济改革的决策居多；改革开放以来党的历届三中全会都讨论深化改革问题，释放的重要信号就是我们党坚定不移高举改革开放伟大旗帜，坚定不移坚持党的十一届三中全会以来的理论、路线、方针和政策。课上两道练习题：第一题，关于中国故事的内容对应正确的是B选项——五四运动产生了马克思主义中国化的首个理论成果是错误的，首个理论成果指的是**毛泽东思想**；“半条被子”承载中国共产党的初心使命、执政为民，前半句正确但后半句错误，半条被子说的是革命过程中红军把自己的一条被子分给了人民群众半条，当时共产党还没有实现执政；“大包干”开启了波澜壮阔的改革开放是正确的，大包干说的是1978年的农村改革，开始实行家庭联产承包责任制；“一带一路”体现中国特色社会主义道路新发展新实践也是正确的。第二题，某校搜集的资料是1978年党召开十一届三中全会作出改革开放的决策，2013年党召开十八届三中全会系统设计全面推进改革，到2018年党召开十九届三中全会部署推进党和国家机构改革，符合这次研究性学习主题的是A选项——从1978年到2018年，关于改革这一主题一直没有停止、一直在深化，所以“实践永无止境，改革开放也永无止境”正确，改革就是对社会主义制度的自我完善与发展也正确；“从根本上改变了中国社会的发展方向”这是新中国成立的意义，新中国成立是在1949年，不符合主题；“中华民族有史以来最为广泛而深刻的社会变革”指的是三大改造确立社会主义制度，发生在1956年，也不符合主题。现在来总结改革开放的**意义**。首先通过40多年的改革开放，极大地改变了**四个面貌**：第一改变了**中国的面貌**，铸就了中国特色社会主义的生机与活力；第二改变了**中华民族的面貌**，提升了中华民族在国际上的地位和影响；第三改变了**中国人民的面貌**，满足了中国人民追求美好生活的愿望和期待；第四改变了**中国共产党的面貌**，中国共产党在今天已经成为了党员人数超过**九千万**的世界最大的执政党，还锻造了中国共产党驾驭市场经济的能力和本领。此外，自1978年实行改革开放之后，我国的经济实力在世界的排名不断前进，我国已经一跃成为**世界第二大经济体**，并且也是**制造业第一大国**。改革开放之后，全国居民人均可支配收入由**171元**增加到了**2.6万元**，贫困人口累计减少**7.4亿人**，建成了世界最大的社保体系，成为了世界上最有安全感的国家之一。所以说改革开放迎来了**三个飞跃**：中华民族迎来了**从站起来、富起来到强起来**的伟大飞跃，注意这里是**迎来**了而不是实现了；改革开放之后，中国共产党围绕中国特色社会主义这一主题，在实践中不断探索，取得了邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想等一系列重大理论创新成果，中国特色社会主义迎来了**从创立、发展到完善**的伟大飞跃；中国人民迎来了**从温饱不足到小康富裕**的伟大飞跃。今天的中华民族正以崭新的姿态屹立于世界的东方。所以我们说改革开放是党和人民**大踏步赶上时代的重要法宝**，注意是赶上时代而不是引领时代；还是**坚持和发展中国特色社会主义的必由之路**；是**决定当代中国命运的关键一招**，是决定实现**两个一百年**奋斗目标、实现中华民族伟大复兴的关键一招。2018年是改革开放40周年，党中央在北京人民大会堂隆重举行了庆祝改革开放四十周年大会，表彰一批为改革开放作出杰出贡献的个人，授予**改革先锋**称号，代表人物有国防科技事业改革发展的重要推动者**于敏**、公共卫生事件应急体系建设的重要推动者**钟南山**、杂交水稻研究的开创者**袁隆平**等，他们无不拥护中国共产党的领导和我们的社会主义制度，拥护改革开放，敢于冲破思想观念的束缚，敢于啃硬骨头、敢于涉险滩，爱岗敬业、无私奉献、作风优良。所以说改革开放的成功还得益于中国共产党的坚强领导和人民群众的开拓进取：**中国共产党是改革开放的领导核心**，而**人民是改革开放伟大奇迹的创造者**，是推动改革开放的力量源泉。那么时至今日，我国的改革开放就此完成了吗？当然没有，因为**实践发展永无止境，解放思想永无止境，改革开放也永无止境**，停顿和倒退没有出路；对外开放是中国的基本国策，当今世界是开放的世界，开放带来进步，封闭必然落后，**改革开放只有进行时，没有完成时**，改革开放一直在路上。第一框小结：共学习了两个问题，分别是改革开放的进程和意义；进程上先了解开端十一届三中全会，再分起步阶段、新阶段、全面深化阶段三个阶段及每个阶段的代表性事件；意义上学习了四个方面，概括为四个面貌、三个飞跃、重要法宝必由之路关键一招，以及改革开放永无止境。第二框是**中国特色社会主义的创立、发展和完善**，要学习四个问题：第一，改革开放以来党的全部理论和实践的**主题**是什么、如何理解；第二，中国共产党在实践探索中取得了哪些**重大理论创新成果**，从时间节点、主题、主要内容和历史贡献方面加以把握；第三，改革开放以来我国取得一切成绩和进步的**根本原因**；第四，中国特色社会主义**道路、理论、制度、文化**的重要性以及相互关系。1982年，中国共产党**第十二次全国代表大会**在北京召开，邓小平主持大会开幕式并致开幕词，在开幕词中他指出，我们的现代化建设必须要从中国的实际出发，应该学习和借鉴外国经验，但是绝不能照抄照搬，要把马克思主义的普遍真理同我国的具体实际结合起来，**走自己的路，建设有中国特色的社会主义**，这是我们总结长期历史经验得出的基本结论。所以说，以1982年党的十二大开幕式上邓小平第一次明确提出“走自己的路，建设有中国特色的社会主义”为标志，从此以后党的全部理论创新和实践创新，都是紧紧围绕着这一主题展开的，这一主题也可以简化为**中国特色社会主义**。这一主题的提出促使中国共产党坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，不断推进理论、实践、制度创新，成功开创、坚持和发展了中国特色社会主义。中国特色社会主义在发展过程中取得了**四大理论创新成果**：**邓小平理论**、“**三个代表”重要思想**、**科学发展观**和**习近平新时代中国特色社会主义思想**，这些合起来也被称为**中国特色社会主义理论体系**。这四大理论成果从四个方面回答了时代之问。问题一，我们要走什么样的道路？邓小平理论给出了答案，我们要走的是**中国特色社会主义道路**。这一理论是在十一届三中全会以后逐步形成的，围绕**什么是社会主义以及怎样建设社会主义**的主题，作出了第一次比较系统的回答。在邓小平理论出现之前，当时对社会主义的认识是不全面的：当时认为社会主义就是无产阶级专政、就是公有制，甚至把一些买卖自家鸡蛋的行为都定性为走资本主义道路、定性为挖社会主义的墙角；但按照马克思主义的理论，社会主义应该是人类的理想社会，理想社会最起码物质生活条件应该是富足的，而当时人民生活甚至连温饱都无法解决。所以邓小平对什么是社会主义、怎样建设社会主义的问题作出了回应，比如我们耳熟能详的那句话“**贫穷不是社会主义**”就是邓小平理论所提出的。在主要内容上，作出了把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策，**深刻揭示了社会主义本质**，确立社会主义初级阶段的基本路线，明确提出走自己的路、建设中国特色社会主义，科学回答了建设中国特色社会主义的一系列基本问题，制定了**三步走**战略。这里出现了三个名词，分别是社会主义本质、社会主义初级阶段基本路线以及三步走战略。第一个，**社会主义本质**是**解放生产力、发展生产力，消灭剥削、消除两极分化，最终达到共同富裕**。第二，党在**社会主义初级阶段的基本路线**是领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生、艰苦创业，为把我国建设成为**富强民主文明和谐美丽的社会主义现代化强国**而奋斗，也可以简称为**一个中心、两个基本点**。**三步走战略**是指：第一步在1981年到1990年实现国民生产总值比1980年翻一番，解决人民的温饱问题，这在20世纪80年代末就已经基本实现；第二步是1991年到20世纪末，国民生产总值再增长一倍，人民生活达到小康水平，这一目标也已经实现，在2000年我们就达到了**总体小康**；第三步目标到21世纪中叶基本实现现代化，人均国民生产总值达到中等发达国家水平，人民过上比较富裕的生活，这也是我们现在继续为之奋斗的目标。在历史贡献上，邓小平理论成功地**开创了中国特色社会主义**。问题二，建设什么样的党？“三个代表”重要思想给出了答案。它是在**1989年十三届四中全会以后**确立的，因为“三个代表”的内容提到，中国共产党要始终代表**中国先进生产力的发展要求**，始终代表**中国先进文化的前进方向**，始终代表**中国最广大人民的根本利益**。所以说它加深了对什么是社会主义、怎样建设社会主义和建设什么样的党、怎样建设党的认识。在主要内容上，确立了社会主义市场经济体制的改革目标和基本框架，确立了社会主义初级阶段**公有制为主体、多种所有制经济共同发展的基本经济制度**和**按劳分配为主体、多种分配方式并存的分配制度**，开创全面改革开放新局面，推进党的建设新的伟大工程。在历史贡献上，当时1989年正是东欧剧变、苏联解体，是世界社会主义出现严重曲折的时候，在国内外形势十分复杂、世界社会主义出现严重曲折的严峻考验面前，**捍卫了中国特色社会主义**，并且成功把中国特色社会主义**推向了21世纪**。问题三，新形势下实现什么样的发展、怎样发展？**科学发展观**给出了答案，它确立于**2002年的党的十六大以后**。科学发展观**第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾**。在主要内容上，强调坚持以人为本、全面协调可持续发展，着力保障和改善民生，促进社会公平正义，推进党的执政能力建设和先进性建设。在历史贡献上，成功在新形势下**坚持和发展了中国特色社会主义**；十六大之后的2002到2012这十年间，我国的国内生产总值有了大幅度的提高，经济总量也从世界第六位上升到世界第二位，国家面貌发生了新的历史性变化。问题四，面对党情、国情、世情的重大变化，处于新时代的我国应该怎么走下去？**习近平新时代中国特色社会主义思想**给出了回答，它是在**2012年党的十八大以来**确立的。当时中国国情的变化最大的状况就是**社会主要矛盾发生了变化**，变成了**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。以习近平同志为主要代表的中国共产党人，坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，坚持毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，深刻总结并充分运用党成立以来的历史经验，从新的实际出发，创立了习近平新时代中国特色社会主义思想。这一思想深刻地回答了**新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义**的重大课题，比如提出了“**五位一体**”总体布局、“**四个全面**”战略布局等一系列新理念新思想新战略。在历史贡献上，这一思想指导并推动党和国家事业取得历史性成就、发生历史性变革，使中国特色社会主义**进入了新时代**。关于这四大理论创新成果，要重点把握它的主题以及历史贡献：邓小平理论开创了中国特色社会主义，“三个代表”重要思想捍卫了中国特色社会主义并成功把它推向了21世纪，科学发展观又在新形势下坚持和发展了中国特色社会主义，习近平新时代中国特色社会主义思想推动中国特色社会主义进入了新时代，其实这一过程也就是中国特色社会主义**从创立到发展再到完善**的过程。课上时代课题排序练习：下列时代课题按照时间先后排列正确的是B选项——“走自己的路，建设有中国特色的社会主义”是邓小平理论在党的十二大上提出的；“建设什么样的党、怎样建设党”是“三个代表”重要思想在1989年之后逐步确立的；“新形势下实现什么样的发展、怎样发展”是科学发展观所回答的时代课题，时间是2002年到2012年；“新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义”是习近平新时代中国特色社会主义思想所回答的时代课题，时间是2012年之后。改革开放以来，我国在方方面面都取得了显著的成绩和进步：经济上我国现在是世界第二大经济体；政治上民主法治不断健全，国家治理体系和治理能力越来越现代化；文化上中国软实力备受全球关注，孔子学院开到了世界各地，越来越多的外国人也开始学习汉语；社会生活上人民从满足物质生活的需要向美好生活的目标迈进；生态文明建设上我们秉持“**绿水青山就是金山银山**”的理念，持续推进美丽中国建设。而以上经济、政治、文化、社会、生态文明五个方面成绩和进步的取得，**根本原因**就在于中国共产党带领中国人民**开辟了中国特色社会主义道路**、形成了**中国特色社会主义理论体系**、确立了**中国特色社会主义制度**、发展了**中国特色社会主义文化**。在这**四个自信**当中，**中国特色社会主义道路是必由之路**，**中国特色社会主义理论体系是行动指南**，**中国特色社会主义制度是中国一切发展进步的根本制度保障**，**中国特色社会主义文化是激励我们不断前进的精神力量**。下面具体研究这四个自信。第一，**中国特色社会主义道路**，它的主要内容是：在中国共产党领导下，立足基本国情，以经济建设为中心，坚持四项基本原则，坚持改革开放，解放和发展社会生产力，建设社会主义市场经济、社会主义民主政治、社会主义先进文化、社会主义和谐社会、社会主义生态文明，这叫做“五位一体”，促进人的全面发展，逐步实现全体人民共同富裕，建设富强民主文明和谐美丽的社会主义现代化强国。因为道路决定命运，中国特色社会主义道路既坚持了科学社会主义的基本原理，还具有鲜明的中国特色，它承载了几代中国共产党人的理想和探索，寄托了无数仁人志士的夙愿和期盼，凝聚了亿万人民的奋斗和牺牲，是党和人民历经千辛万苦、付出极大代价才开辟出来的道路，它也彻底改变了中国人的命运，使中国用70年的时间就走过了西方国家两三百年的工业化现代化道路，使中国一跃成为世界第二大经济体，创造了人类社会发展史上惊天动地的奇迹。所以历史告诉我们，既不要走**封闭僵化的老路**，也不要走**改旗易帜的邪路**，中国特色社会主义道路是实现社会主义现代化、创造人民美好生活的**必由之路**，是一条既适合中国国情、又适合时代发展要求、并且取得巨大成功的唯一正确道路。第二，**中国特色社会主义理论体系**，具体来说包括邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想，这套理论最大的特点是**实践性和创新性**，不是教条式地照搬马克思列宁主义，而是马克思列宁主义的中国化，是我们党从新的实践和时代特征出发，坚持和发展马克思主义，科学回答了建设中国特色社会主义的一系列基本问题，实现了马克思主义中国化时代化新的飞跃。十八大以来，党勇于理论探索和创新，深化对共产党执政规律、社会主义建设规律和人类社会发展规律的认识，取得重大理论创新成果，集中体现为习近平新时代中国特色社会主义思想；习近平新时代中国特色社会主义思想把中国特色社会主义理论体系推到了一个新的高度，牢牢把握了人民群众对美好生活的需要，贯穿了以人民为中心的初心和价值追求，具有跨时代意义和强大的真理力量。第三，**中国特色社会主义制度**，它是党和人民在长期实践探索中形成的科学制度体系，具体来说，它包括**人民代表大会制度**这一根本政治制度和三项基本政治制度，也包括中国特色社会主义法律体系，还包括国有制为主体、多种所有制经济共同发展的基本经济制度，以及建立在上述制度基础上的经济体制、政治体制、文化体制、社会体制等等，所以说是一个庞大的制度体系。我国国家治理一切工作和活动都依照中国特色社会主义制度展开，我国国家治理体系和治理能力就是中国特色社会主义制度及其执行能力的集中体现。而**制度优势是一个国家的最大优势，制度竞争是国家间最根本的竞争**，制度稳则国家稳。中国特色社会主义制度在实现广泛民主的基础上形成了正确的集中，具有**举国体制**优势，能够**集中力量办大事**，所以在脱贫攻坚、在抗击疫情、在发展航天事业的过程中，我们才能形成共同推动中国发展进步的强大力量。所以说中国特色社会主义制度和治理体系，是以马克思主义为指导、植根中国大地、具有深厚中华文化根基、深得人民拥护的制度和治理体系，是具有强大生命力和巨大优越性的制度和治理体系，是能够持续推动国家进步和发展、确保中华民族实现伟大复兴的制度和治理体系，所以我们有足够的理由充满**制度自信**。第四，**中国特色社会主义文化**，从形成来看，源自于中华民族五千多年文明历史所孕育的**中华优秀传统文化**，熔铸于党领导人民在革命、建设、改革中创造的**革命文化和社会主义先进文化**，植根于中国特色社会主义的伟大实践。发展中国特色社会主义文化就是以马克思主义为指导，坚守中华文化立场，立足当代中国现实，结合当今时代特点，发展**面向现代化、面向世界、面向未来的，民族的、科学的、大众的社会主义文化**，推动社会主义精神文明和物质文明协调发展。我们的文化有着丰富的内涵，由中华优秀传统文化、革命文化和社会主义先进文化共同组成。世界四大文明当中，只有中华文明是延续的。传统文化中，**大禹治水、愚公移山、精卫填海、女娲补天、夸父追日**讲的就是一心为公、自强不息。中国共产党人继承了这种精神，在战争年代抛头颅、洒热血，为了民族解放甘愿献出生命；社会主义建设年代，**雷锋、焦裕禄、王进喜、钱学森**怀着满腔热血投入到祖国的建设事业上。这种一心为国家、为民族奋斗的精神，正是中华文化之魂，具有强大的力量。所以说中国特色社会主义文化激荡着中华民族最深沉的精神追求，代表着中华民族独特的精神标识，是激励全党、全国各族人民奋勇前进的强大精神力量。并且，这**四个自信**之间并不是孤立的，他们是相互联系、相互作用，统一于中国特色社会主义伟大实践的。中国共产党从1921年成立至今，已经走过了一百多年的历史，党带领中国人民实现了中国的发展与壮大，让世界看到了可望而不可及的中国风骨、中国力量。所以说当今世界要说哪个政党、哪个国家、哪个民族能够自信的话，那中国共产党、中华人民共和国、中华民族是最有理由自信的。课上两道练习题：第一题，下列选项与四个自信对应正确的是A选项——道路自信“以中国式现代化全面推进中华民族伟大复兴”是正确的；把马克思主义基本原理同中华优秀传统文化相结合应该是理论自信，不是制度自信；坚持和完善“一国两制”、推进祖国统一属于制度自信，不是理论自信；坚持“两个毫不动摇”、构建高水平社会主义市场经济体制，经济制度也属于制度自信，不是文化自信。第二题，2023年12月甘肃发生地震造成重大人员伤亡，地震发生之后，财政部、应急管理部紧急向甘肃、青海预拨中央自然灾害救灾资金2亿元，国家综合性消防救援队伍共出动了一千多名消防救援人员赴灾区救援，国家卫健委紧急调派专家赶赴甘肃，组织临近甘肃的三支国家紧急医学救援队伍赴灾区支援，材料表明了中国特色社会主义制度，答案是B选项——这是在人民遇到巨大灾难的时候，多个不同的行为主体紧急集结、奔赴灾区，所以体现了能够集中人力、物力、财力办大事，也体现了在社会主义国家之下，是把人民的生命财产安全摆在第一位的，具有巨大的优越性。最后课堂小结：关于第三课第二框，中国特色社会主义的创立、发展和完善，我们共学习了两个问题，第一是改革开放以来党的全部理论和实践的主题，第二是中国特色社会主义道路、理论、制度和文化。首先关于党的全部理论和实践的主题，先明确是什么，简单概括就是中国特色社会主义；然后中国特色社会主义在发展的过程中还取得了四个重大的理论创新成果，分别是邓小平理论、“三个代表”重要思想、科学发展观以及习近平新时代中国特色社会主义思想，还要明确各自的时间节点、历史贡献、主要内容等。第二，围绕中国特色社会主义道路、理论、制度和文化，也就是四个自信来学习：首先要知道，这就是改革开放以来我国取得一切成就和进步的根本原因；其次还要分别掌握道路自信、理论自信、制度自信、文化自信以及他们之间的内在联系。", "vtech": [["“伟大转折”与“社会变革”别混", "看到“最”开头的定性句先问对象：十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折；社会主义制度的确立才是中华民族有史以来最为广泛而深刻的社会变革（三大改造，1956年）；“从根本上改变中国社会的发展方向”是新中国成立（1949年）的意义，不是改革开放。"], ["改革三阶段先定年份再想事件", "看到阶段题先定年份：起步阶段1978—1992、新阶段1992—2012、全面深化阶段2012年十八大以来；再把事件按年份落位：1980年四个经济特区、1984年14个沿海港口城市、1992年南方谈话、2001年加入世贸组织，1993年十四届三中全会部署建立市场经济体制、2003年十六届三中全会部署完善。"], ["意义题抓“四个面貌、三个飞跃”", "看到意义题先默写框架：四个面貌是中国、中华民族、中国人民、中国共产党的面貌；三个飞跃是中华民族从站起来、富起来到强起来，中国特色社会主义从创立、发展到完善，中国人民从温饱不足到小康富裕；注意“迎来”不是“实现”，“赶上时代”不是“引领时代”。"], ["四大理论成果按时间排历史贡献", "看到理论成果题先按时间排：邓小平理论开创了中国特色社会主义，“三个代表”重要思想捍卫了它并成功把它推向21世纪，科学发展观在新形势下坚持和发展了它，习近平新时代中国特色社会主义思想推动它进入新时代；时代课题排序也先定时间：十二大（1982年）—1989年后—2002—2012年—2012年十八大后。"]], "vgaokao": []}}, "u_pol_4": {"id": "u_pol_4", "name": "只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴", "secs": "第四课", "pageFrom": 42, "pageTo": 65, "members": ["pol_p007", "pol_p008", "pol_p009"], "video": {"bvid": "BV1YE421A7Qj", "p": 1, "t": "只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴", "dur": "83:10", "from": "政治老师爱政治", "vtop": ["新时代我国社会的主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾——“变”的是主要矛盾，“不变”的是社会主义初级阶段的基本国情和世界上最大的发展中国家的国际地位。", "中国梦的内涵是国家富强、民族振兴、人民幸福：国家富强是基础，民族振兴是核心内容，人民幸福是奋斗目标；中国梦归根到底是人民的梦。", "十个明确讲“是什么”（理论层面），十四个坚持讲“怎么做”（实践层面、基本方略）——两者别搞反；基本方略是十四个坚持，不是十个明确。"], "vsum": "本课讲第四课，只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴，讲的是我们国家 2012 年进入新时代之后的这段历史，分三框。第一框是中国特色社会主义进入新时代。先看什么是新时代：2017 年党的十九大作出判断，经过长期努力，中国特色社会主义进入了新时代，这是我国发展新的历史方位；但进入新时代是从 2012 年党的十八大开始算起的。**新时代的科学内涵**可以从五个方面把握：第一，从伟大事业看，是承前启后、继往开来，在新的历史条件下继续夺取中国特色社会主义伟大胜利的时代；第二，从奋斗目标看，是决胜全面建成小康社会、进而全面建设社会主义现代化强国的时代，其中决胜全面建成小康社会是第一个百年奋斗目标，全面建设社会主义现代化强国是第二个百年奋斗目标；第三，从人民的期待看，是全国各族人民团结奋斗、不断创造美好生活、逐步实现全体人民共同富裕的时代；第四，从历史使命看，是全体中华儿女勠力同心、奋力实现中华民族伟大复兴中国梦的时代；第五，从世界意义看，是我国不断为人类作出更大贡献的时代。中国特色社会主义进入新时代有重大意义：历史意义上，意味着近代以来久经磨难的中华民族迎来了从站起来、富起来到强起来的伟大飞跃，迎来了实现中华民族伟大复兴的光明前景——注意是“迎来了”而不是“实现了”；政治意义上，意味着科学社会主义在 21 世纪的中国焕发出强大生机活力，在世界上高高举起了中国特色社会主义伟大旗帜；世界意义上，中国走出了一条中国式现代化道路，打破了发展中国家对西方国家现代化的路径依赖，为他们树立了榜样、提供了全新选择。第二个问题是新时代我国社会的主要矛盾。党对社会主要矛盾的认识有过三次：1956 年党的八大、1981 年党的十一届六中全会、2017 年党的十九大。新时代我国社会的主要矛盾是**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。转变的原因有两方面：从人民需求看，由原来的物质文化需要发展为美好生活需要，要求更多、更高、更广泛；从社会生产看，社会生产力水平显著提高，社会生产能力在很多方面进入了世界前列，再说“落后的社会生产”已经不合适，不平衡的发展包括东中西区域之间、城乡之间的不平衡，不充分的发展体现在关键核心技术上的短板。如何解决主要矛盾，要把握“变与不变”：变的是主要矛盾的变化，人民日益增长的美好生活需要是合理的、正当的，不能让人民群众降低需求标准，只能从不平衡不充分的发展角度去解决，要在继续推动发展的基础上，着力解决好发展不平衡不充分的问题，大力提升发展的质量和效益；不变的有两个，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国作为世界上最大的发展中国家的国际地位没有变。所以要牢牢把握社会主义初级阶段这个基本国情，牢牢立足这个最大实际，牢牢坚持党的基本路线——以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生、艰苦创业，为把我国建设成为富强民主文明和谐美丽的社会主义现代化强国而奋斗。第三个问题是新时代坚持和发展中国特色社会主义要一以贯之：从历史进程看，中国特色社会主义是在改革开放四十多年的伟大实践中得来的，是在新中国成立七十多年的持续探索中得来的，是党领导人民进行伟大社会革命一百年的实践中得来的，是在近代以来中华民族由衰到盛一百八十多年的历史进程中得来的；中国特色社会主义是实现中华民族伟大复兴的必由之路；每一个人都是新时代的见证者、开创者、建设者，要不忘初心、牢记使命，以永不懈怠的精神状态和一往无前的奋斗姿态，一以贯之坚持和发展中国特色社会主义。第二框是实现中华民族伟大复兴的中国梦。**中国梦**这一概念的提出是在 2012 年 11 月 29 日，习近平总书记来到中国国家博物馆参观“复兴之路”展览并发表重要讲话，其中首次提出实现中华民族伟大复兴就是中华民族近代以来最伟大的梦想。“复兴”就是再一次强大兴盛起来：古代中华民族创造过辉煌灿烂的文明，科学技术曾经长期处于世界前列，有文明于世的四大发明；进入近代以来，由于闭关自守和没落的封建专制制度，以及西方列强的入侵，逐步沦为半殖民地半封建社会，遭受了前所未有的苦难。中国梦的内涵有三层：**国家富强**是中国梦的实现基础，中国梦首先是强国梦；**民族振兴**是中国梦的核心内容；**人民幸福**是中国梦的奋斗目标，国家富强和民族振兴最终的落脚点都是为了人民幸福；三者分别代表国家的追求、民族的向往和人民的期盼，融为一体，体现了中华民族和中国人民的整体利益。如何实现中国梦，从三个角度回答：从中国梦与人民的关系看，中国梦归根到底是人民的梦，人民是中国梦的主体，是中国梦的创造者和享有者，要紧紧依靠人民来实现，不断为人民造福；从中国梦与中华儿女的关系看，中国梦是国家的梦、民族的梦，同时也是每一个中华儿女的梦，国家好、民族好，大家才会好，要把人生理想融入国家和民族的伟大梦想之中，把小我融入大我，敢于有梦、勇于追梦、勤于圆梦；从中国梦与世界梦的关系看，中国梦与世界人民的梦想息息相通，中国一心一意办好自己的事，实现国家发展和稳定，既是对自己负责，也是为世界做贡献，中国维和部队是全球执行维和任务最多的国家。接下来是中国共产党的初心和使命：2017 年 10 月 18 日，习近平同志在党的十九大报告中说，中国共产党人的初心和使命就是**为中国人民谋幸福、为中华民族谋复兴**。为了实现中华民族伟大复兴的伟大梦想，必须进行**伟大斗争**（包括反腐败斗争、意识形态领域的斗争、反分裂斗争、维护国家利益的斗争等）、推进**党的建设新的伟大工程**、推进**中国特色社会主义伟大事业**。**四个伟大**之间紧密联系、相互贯通、相互作用，共同贯穿于新时代中国特色社会主义的发展过程，但各有侧重：伟大梦想是目标，伟大斗争是动力，深入推进党的建设这一新的伟大工程是保证，推进中国特色社会主义事业这一伟大事业是改革开放以来党的全部理论和实践的主题；在四个伟大中起决定性作用的是党的建设新的伟大工程。办好中国的事情关键在党，没有中国共产党的领导，民族复兴必然是空想；要更加自觉地增强**四个自信**——中国特色社会主义道路自信、理论自信、制度自信、文化自信，既不走封闭僵化的老路，也不走改旗易帜的邪路。第三个问题是分两步走建成社会主义现代化强国：1987 年召开的十三大明确提出了三步走战略，前两步已经完成，第三步的目标是到 21 世纪中叶基本实现现代化；而党的十九大明确了新时代中国特色社会主义发展的战略安排，可以简称为两步走：第一个阶段从 2020 年到 2035 年，在全面建成小康社会的基础上，再奋斗 15 年，基本实现社会主义现代化；第二个阶段从 2035 年到本世纪中叶，在基本实现现代化的基础上，再奋斗 15 年，把我国建成富强民主文明和谐美丽的社会主义现代化强国。如何建成，从国家角度要牢牢把握坚持和加强党的全面领导等重大原则，增强忧患意识，坚持底线思维；要抓住大有可为的历史机遇期；从青年角度，青年兴则国家兴，青年强则国家强，广大青年要坚定理想信念、志存高远、脚踏实地，在实现中国梦的生动实践中放飞青春梦想。第三框是习近平新时代中国特色社会主义思想，分上下两集。上集先讲这一思想回答的时代课题：新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义，建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国，建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党。然后讲这一思想产生的背景。国际背景是：世界进入新的动荡变革期，世界经济复苏乏力，逆全球化思潮抬头，单边主义、保护主义明显上升，世界需要中国理念、中国智慧、中国方案；中国发挥着世界和平的建设者、全球发展的贡献者、国际秩序的维护者的重要作用，构建人类命运共同体的理念被写入了联合国大会的相关决议。国内背景包括四个方面：第一，中华民族伟大复兴进入关键时期，社会生产力水平总体上显著提高，比历史上任何时期都更接近、更有能力、更有信心实现中华民族伟大复兴的目标；第二，中国式现代化拓展推进，中国仅用短短七十多年的时间，在发展的很多方面走过了西方发达国家上百年甚至数百年的资本主义现代化发展历程，创造了世所罕见的经济快速发展和社会长期稳定两大奇迹，中国式现代化是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，是人与自然和谐共生的现代化，是走和平发展道路的现代化；第三，科学社会主义的发展，20 世纪 80 年代末 90 年代初东欧剧变、苏联解体，世界社会主义运动的发展出现了严重的曲折，但中国用自己的发展成果证明了“中国崩溃论”的崩溃和“社会主义失败论”的失败；第四，党的自我革命开辟新的境界，正是在党不断实现自我净化、自我完善、自我革新、自我提高，以伟大自我革命引领伟大社会革命的过程中创立并不断丰富发展的。下集讲这一思想的主要内容，包括**十个明确**、**十四个坚持**和十三个方面成就。**十个明确**是这一思想最为核心关键的组成部分，是支撑习近平新时代中国特色社会主义思想的四梁八柱，集中反映着我们党对科学社会主义在当今时代的理论思考和理论贡献。其中第一明确是坚持和发展中国特色社会主义的总任务是实现社会主义现代化和中华民族伟大复兴，在全面建成小康社会的基础上，分两步走在本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国，以中国式现代化推进中华民族的伟大复兴；第八明确是党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，把人民军队建设成为世界一流军队；第九明确是中国特色大国外交要服务民族复兴、促进人类进步，推动建设新型国际关系、推动构建人类命运共同体；第十明确是全面从严治党的战略方针，提出新时代党的建设总要求，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争，以伟大自我革命引领伟大社会革命。**十四个坚持**是坚持和发展中国特色社会主义的基本方略，涵盖坚持党的领导和五位一体总体布局、四个全面战略布局，涵盖国防和军队建设、维护国家安全、对外战略，是实现两个一百年奋斗目标、实现中华民族伟大复兴中国梦的路线图和方法论。要注意区分：十个明确讲的是“是什么”的问题，侧重于理论层面的高度概括；十四个坚持讲的是“怎么做”的问题，侧重于在实践层面如何展开，两者体现了理论与实践的结合、认识论与方法论相统一。十三个方面成就是指 2021 年党的十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》，从 13 个方面分领域总结了新时代党和国家事业取得的历史性成就、发生的历史性变革。最后是这一思想的地位和作用：这一思想实现了马克思主义中国化时代化新的飞跃，是当代中国的马克思主义，是 21 世纪的马克思主义，是中华文化和中国精神的时代精华；它是马克思主义中国化的最新成果——注意是“最新成果”而不是“最终成果”；在当代中国，坚持和发展习近平新时代中国特色社会主义思想，就是真正坚持和发展马克思主义，就是真正坚持和发展科学社会主义。易混易错提醒：中国特色社会主义最本质的特征是党的领导；基本方略是十四个坚持，不是十个明确；要以党的自我革命引领伟大社会革命，顺序不能反；改革开放前三十年是探索、是铺垫，后三十年是继承、是发展，两者不能割裂。", "vtech": [["主要矛盾题先分变与不变", "看到新时代主要矛盾题 → 先分清“变”与“不变”：变的是主要矛盾（人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾）；不变的是社会主义初级阶段的基本国情和世界上最大的发展中国家的国际地位；“进入新时代就不再是社会主义初级阶段”是典型错句。"], ["“迎来了”不是“实现了”", "看到进入新时代的意义题 → 盯住“迎来了实现中华民族伟大复兴的光明前景”：是“迎来了”不是“实现了”；站起来、富起来到强起来的伟大飞跃，强起来是正在进行时，别写成已经完成。"], ["四个伟大各有分工，起决定作用的是伟大工程", "看到四个伟大题 → 先定分工：伟大梦想是目标，伟大斗争是动力，伟大工程是保证，伟大事业是中国特色社会主义事业；四者紧密联系、相互贯通，但起决定性作用的是党的建设新的伟大工程。"], ["自我革命引领社会革命，顺序别反", "看到“以……引领……”题 → 记住正确顺序是以党的伟大自我革命引领伟大社会革命；“以伟大社会革命引领自我革命”是说反了的错句；同样，十个明确是理论层面的“是什么”，十四个坚持才是实践层面的路线图和方法论。"]], "vgaokao": []}}, "u_pol_5": {"id": "u_pol_5", "name": "综合探究", "secs": "综合探究一、二", "pageFrom": 66, "pageTo": 76, "members": ["pol_p010", "pol_p011"], "video": {"bvid": "BV1gt4y1h7H6", "p": 1, "t": "综合探究", "dur": "38:31", "from": "教政治的月亮姐姐", "vtop": ["生产力决定生产关系、经济基础决定上层建筑；生产关系一定要适应生产力的状况，上层建筑一定要适应经济基础的状况——这是贯穿人类社会始终的基本矛盾。", "五种社会形态依次更替的根本原因是生产力发展；社会发展的总趋势是前进的、上升的，发展的过程是曲折的；在阶级社会里，阶级斗争是推动阶级社会发展的直接动力。", "在中国资本主义道路走不通——封建势力与帝国主义勾结、帝国主义不允许、中国资产阶级不具备条件；中国特色社会主义是科学社会主义理论逻辑和中国社会发展历史逻辑的辩证统一，必须毫不动摇地走下去。"], "vsum": "本课是必修一的综合探究，分两集、两位老师讲。第一集是“教政治的月亮姐姐”讲探究一，第二集换了一位老师“政是奋斗时”讲探究二，两集拼在一起共 38 分 31 秒。开场先说这节课的定位：前面必修一的知识点基本上已经上完了，综合探究是对前面所学内容的补充和回忆，很多老师上课时会直接忽略，但按课标要求是要讲的。总议题是“**回看走过的路，比较别人的路，远眺前行的路**”，这句话出自习近平总书记在哲学社会科学工作座谈会上的讲话：回望是为了更好地出发，比较是为了更加看清楚符合自己的路在哪里，眺望是为了描定好前行的方向。教材 62 页设计了三个探究题目，正好对应议题里的三句话：如何理解人类社会发展的一般进程，对应“回看走过的路”；如何看待世界各地历史发展的不同轨迹，对应“比较别人的路”；如何看待中国特色社会主义的科学真理性及历史必然性，对应“远眺前行的路”。第一个议题先回忆五种社会形态：**原始社会**是人类历史上第一个社会形态，存在了两三百万年，生产力的主要标志是使用石器，实行共同劳动、共同占有生产资料、平均分配；原始社会瓦解后出现**奴隶社会**，奴隶主在经济和上层建筑中居于主导地位；奴隶社会瓦解后是**封建社会**，地主阶级统治其他阶级的根本是封建土地所有制，地主通过掌握土地对农民用地租、放高利贷等手段进行剥削；封建社会之后是**资本主义社会**，资本归个人私有、雇佣劳动为基础，资本家通过雇佣关系赚取利润、占有剩余价值；资本主义社会之后是**社会主义社会**，目前世界上社会主义国家只有五个——中国、越南、朝鲜、老挝和古巴，都是由共产党执政。推动人类社会从低级向高级发展的，是**生产力的发展**。老师用一张表把五种社会形态放在一起对比，对比分三根线：生产力包括劳动者、劳动工具和劳动对象——原始社会劳动者技能水平非常低，到社会主义社会劳动者得到解放；劳动工具从原始社会的石器，到奴隶社会的金属工具、封建社会的铁制工具，再到资本主义社会和社会主义社会的机器；劳动对象从原始社会的自然界，发展到后来的自然界和太空。生产关系包括生产资料归谁所有、人们在生产中的地位和相互关系、产品分配关系——原始社会共同占有生产资料、平等互助、平均分配；奴隶社会是奴隶主占有生产资料并完全占有奴隶；封建社会是地主占有绝大部分土地；资本主义社会是资本家占有一切生产资料；社会主义社会是劳动者共同占有生产资料、平等互助合作、按劳分配。接着讲两组基本概念：**生产力**是人们利用和改造自然的能力，包括劳动者和劳动资料，劳动资料又包括生产工具和劳动对象，其中劳动者在生产中起主导作用，生产工具是生产力发展水平的重要标志。**生产关系**是在生产中形成的人与人之间的关系，包括生产资料所有制关系、人们在生产中的地位和相互关系、产品分配关系，其中**生产资料所有制是生产关系的基础**，决定着生产关系的其他两个方面。**经济基础**是指由社会一定发展阶段的生产力所决定的生产关系的总和；**上层建筑**是指建立在一定经济基础上的社会意识形态以及与之相适应的政治法律制度和设施等的总和，又分为思想上的上层建筑（政治思想、法律、道德、宗教、文学艺术等）和政治上的上层建筑（政治法律制度和设施、军队、警察、法庭、监狱等）。两组概念合起来就是两对关系：**生产力决定生产关系，生产关系反作用于生产力**——有什么样的生产力，就要求有什么样的生产关系与之相适应；生产关系适应生产力发展状况时促进生产力发展，不适应时阻碍甚至破坏生产力的发展。**经济基础决定上层建筑，上层建筑反作用于经济基础**——上层建筑适合经济基础状况时促进经济基础的巩固和完善，不适合时阻碍经济基础的发展和变革；当上层建筑为先进的经济基础服务时促进生产力的发展、推动社会进步，为落后的经济基础服务时束缚生产力的发展。由此得出议题一的结论：贯穿于人类社会始终的基本矛盾，是**生产力和生产关系的矛盾**以及**经济基础和上层建筑的矛盾**；**生产关系一定要适应生产力的状况，上层建筑一定要适应经济基础的状况**；这一规律决定着社会形态的依次更替、推动着人类向前发展。社会发展的总趋势是前进的、上升的，发展的过程是曲折的；在阶级社会里，社会基本矛盾的解决主要是通过阶级斗争实现，**阶级斗争是推动阶级社会发展的直接动力**。第二个议题看世界各国历史发展的不同轨迹，先看英国和美国。**英国的君主立宪制**是在保留君主制的前提下，通过立宪树立人民主权、限制君主权力，实现事实上的共和主义理想但不采用共和政体：议会是国家的最高立法机关、最高国家权力机关，由议会选举产生的政府首脑组织政府，是真正的国家权力中心，君主是象征性的国家元首，职责都是礼仪性的。英国君主立宪制从 1640 年革命开始，到 1689 年确立，形成的原因由英国的特殊国情决定：资产阶级新贵族和君主之间有一种长期的相互利用的关系，这是最主要的原因；英国历史上绝对君主制一直不够强大，议会始终保持着较多的权力；英国民众对君主有着强烈的感情；受启蒙思想的影响。课上还放了一段视频讲**光荣革命**：从 1688 年起，英国正式确立了议会高于王权的政治原则，并在以后的几十年里逐步建立起君主立宪制；英国人赶走詹姆斯二世、建立君主立宪制的革命没有流血，所以被历史学家称为光荣革命，它创造了一种用和平变革的方式实现社会进步的模式。**美国的民主共和制**是总统和议会分别由选举产生、任期限定，内阁由总统组织并对总统负责，总统既是国家元首又是政府首脑，与议会之间有权力制约的关系；美国形成民主共和制也是由它的国情决定的：所处的地理位置形成了人民渴望自由的政治基因，移民的到来形成了不同的州，殖民的历史造就了美国民主自由的思想。同样都是资本主义国家，英国是君主立宪制、美国是民主共和制，根子就在各自不同的国情。再看中国的情况：历史的以及血的代价告诉我们，在中国资本主义道路走不通，原因有三方面：封建势力同帝国主义相勾结，严重阻碍了民族资本主义经济的发展；帝国主义势力不允许中国走资本主义道路，帝国主义入侵中国的目的是要把中国变成他们的殖民地或者半殖民地，绝对不允许中国走资本主义道路变得强大起来、成为自己的竞争对手；中国的资产阶级也不具备建立资本主义制度的条件，靠中国资产阶级的力量，中国最终也不可能成为一个独立的资本主义国家。所以世界各国历史发展道路具有**多样性**，会受地理环境、文化传统和外部影响等因素的影响，各国各地区各民族的发展道路都会有着不同的表现；人类社会发展的一般进程，正是由各国各地区各民族历史的多样性反映出来的。中国要坚定不移地沿着**中国特色社会主义道路**前进，中国特色社会主义是党和人民历经千辛万苦、付出巨大代价取得的根本成就，是实现中华民族伟大复兴的正确道路。第三个议题通过几位历史人物的生平和天津利顺德大饭店的历史，来看中国特色社会主义的科学真理性与历史必然性。1912 年 2 月 12 日，溥仪被迫退位，宣告了统治中国几千年的封建统治结束；以梁启超为代表的资产阶级改良派，没有触动封建统治的根基，没有改变中国半殖民地半封建的社会制度；以孙中山先生为代表的资产阶级革命派，因为软弱性和妥协性，没有发动和依靠民众，也没有改变中国半殖民地半封建的社会制度；以毛泽东同志为代表的中国共产党人，经过浴血奋战成立了新中国，改变了中国的性质和面貌。利顺德饭店的命运跟着中国走：建国初饭店客人减少 40%、处于亏本状态，1952 年利顺德转交人民政府，成为名副其实的国有官办大型企业，一年之后就扭亏为盈；1978 年随着改革开放，利顺德加入改革开放的洪流，2010 年天津利顺德大饭店豪华精选酒店开业。社会主义制度和改革开放不仅让利顺德重新换发了生机，更让新中国换发了生机。回顾三个时间点：新中国成立为实现由新民主主义向社会主义过渡创造了前提条件，从根本上改变了中国社会的发展方向；1956 年生产资料私有制的社会主义改造取得决定性胜利，标志着我国实现了从新民主主义到社会主义的转变；1978 年至今中国进入改革开放的伟大进程。议题三的结论是：**中国特色社会主义是科学社会主义理论逻辑和中国社会发展历史逻辑的辩证统一，是根植于中国大地、反映中国人民意愿、适应中国和时代发展进步要求的科学社会主义**；中国特色社会主义道路是当代中国大踏步赶上时代、引领时代发展的康庄大道，必须毫不动摇地走下去。到这里探究一讲完，第一集的老师还总结说，必修一基本上就是这个样子，下节课开始上必修二经济与社会的内容。第二集换了一位老师“政是奋斗时”，讲综合探究二“**方向决定道路，道路决定命运**”。先讲方向、道路和命运这几个词：方向其实就是旗帜，我们中国高举中国特色社会主义的旗帜，走的是中国特色社会主义的道路；一个党、一个国家朝着什么样的方向发展，选择高举什么样的旗帜、走什么样的道路，就预示着将会有怎样的前途和命运，关系到国家能否实现富强、人民能否过上幸福的生活。我们选择走中国特色社会主义道路，这是实现社会主义现代化的必由之路，是实现国家富强、民族振兴的必由之路，是实现中华民族伟大复兴中国梦的必由之路。这一探究从四个方面分析。第一是聚焦中国成就：孙中山先生在《建国方略》里构想了中国建设的宏伟蓝图，要修建约 16 万公里的铁路、160 万公里公路、开凿并整治全国水道和运河、建设三个世界级大港、发展内河交通和水利、发展电力事业，只有这样才能振兴中华；如今孙中山先生描绘的蓝图早已实现，中国人创造的许多成就原本超出了孙中山先生的设想——中国从站起来、富起来到强起来，我们比历史上任何时期都更接近中华民族伟大复兴的目标，也比历史上任何时期都更有信心、有能力实现这个目标。为什么孙中山的设想在当时没有实现？从根本上说，他代表的是民族资产阶级，中国的资产阶级无法引导中国革命取得胜利，革命如果不能胜利，就没有和平稳定的社会条件；在半殖民地半封建的旧中国，资本主义道路是行不通的；从主观上说，资产阶级自身存在局限性，有软弱性和妥协性。为什么如今可以实现？首先是**党的领导**：党的领导是中国特色社会主义制度的最大优势，也是中国特色社会主义最本质的特征；在党的领导下，我们开辟了中国特色社会主义道路，形成了中国特色社会主义理论体系，确立了中国特色社会主义制度，发展了中国特色社会主义文化。还有全国各族人民的共同奋斗、顽强奋斗。实践证明，把马克思主义基本原理同中国具体实际相结合，坚持和发展中国特色社会主义，是实现中华民族伟大复兴中国梦的必由之路。新中国取得辉煌成就的原因还可以从这些角度想：根本原因就是中国共产党的领导，社会主义制度的优越性、能够集中力量办大事，国家统一、民族团结、新中国的综合国力提升，我们党带领我们走了自己的道路、建设了中国特色社会主义，坚持中国特色社会主义道路、理论、制度、文化，最后离不开人民——人民是改革开放伟大奇迹的创造者，是推动改革开放的力量源泉，还有党的建设。第二是点赞中国道路：回顾科学社会主义的发展历程，唯物史观和剩余价值学说的创立，使科学社会主义从空想到科学；巴黎公社使科学社会主义从理论到实践；俄国十月革命使科学社会主义从一国到多国；但是苏联解体让世界社会主义遭受了严重的挫折；21 世纪，科学社会主义在中国焕发出强大的生机与活力。苏联解体、东欧剧变之后，唱衰中国的舆论在国际上不绝于耳，“中国崩溃论”“历史终结论”等言论从未中断过，中国又是怎样面对这些言论的？批判“历史终结论”可以从三个角度：从社会历史发展的总趋势来看，马克思、恩格斯关于资本主义社会基本矛盾的分析指出，社会主义必然胜利、资本主义必然灭亡，社会发展的道路是曲折的，但社会主义的前途是光明的，所以走中国特色社会主义道路、选择科学社会主义是没有问题的；从实践的角度来说，中国特色社会主义是马克思主义基本原理同中国具体实际相结合的成果，是科学社会主义理论逻辑和中国社会发展历史逻辑的统一，中国特色社会主义的成功证明了科学社会主义具有强大的生机与活力；最后还是要集中力量办好自己的事情，为赢得未来打下更坚实的基础。第二个问题是各国的发展道路应该由各国人民去选择：人类社会发展有统一性和各国道路多样性这两种特点，世界上没有放之四海而皆准的具体发展模式，也没有一成不变的发展道路；如何判断我们这条道路是正确的，人民最有发言权，要看中国特色社会主义这样的道路有没有让我们的人民站起来、富起来、强起来，有没有让人民的生活水平不断提高；所谓“鞋子合不合脚，只有自己知道”，各国的发展道路也是由各国人民去选择的，任何干涉别国发展道路的做法都是错误的，要批判干涉别国发展道路的做法，并且一直坚定不移地走中国特色社会主义的道路，继续使科学社会主义焕发出强大的生机与活力。第三是贡献中国智慧、中国方案：绿水青山就是金山银山的理念、人类命运共同体在国际上达成共识、中国对其他国家的援助，都是中国在为世界贡献中国方案、中国智慧，还有国际减贫、推动全球气候治理、加强政策沟通、构建开放型世界经济，最熟悉的是一带一路，以及中国提倡的人类命运共同体、可持续发展观、全球治理观。中国方案、中国智慧的意义可以从三个角度梳理：从全球治理方面看，中国提出的新兴治理观念，比如构建人类命运共同体、构建新型国际关系，有利于全球治理；从政治文明方面看，中国高举和平发展、合作共赢等价值观念，维护了国际的公平正义；从共同发展的角度看，相互尊重、平等协商的思想开辟了与各国发展交往的新路，为各国共同发展提供了新动力。第四是坚定自信，实现中国梦：为什么要有自信？“四个自信”是实现中国梦、实现“两个一百年”奋斗目标的迫切需要，强调“四个自信”可以回应国外敌对势力对中国道路的质疑和否定；还可以从信心、信念、信仰的重要性来答，失去了自信会怎么样，课本 73 页有相关内容。为什么能有自信？分开讲四个自信各自的好处：理论自信之所以自信，不仅基于自身的科学性、时代性，更基于改革开放以来我国经济发展取得的巨大成就；文化自信更好说，我们是一个拥有 5000 多年文化的历史古国，这样的文化能够生生不息、源远流长，在人类文明的浩瀚星空中，中华文化应该是最值得、最有理由充满自信的；道路自信就是说我们所选择的道路是怎么走过来的——是在改革开放 40 多年的伟大实践中走出来的，是在中华人民共和国成立 70 多年的持续探索中走出来的，是在对近代以来 170 多年中华民族发展历程的深刻总结中走出来的，是在对中华民族 5000 多年悠久文明的传承中走出来的；制度自信在于它具有独特的优势、具有活力和潜力，中国所选择的制度适应我国的国情和发展要求，取得了显著的制度成效，是人民当家作主和中国发展进步的根本制度保障。如何坚定“四个自信”？要内化于心、外化于行，落实到实践上，“四个自信”也要不断创新，持续推进中国特色社会主义道路、制度、理论、文化。最后是实现中国梦：中国梦就是中华民族伟大复兴的中国梦，要全面建成社会主义现代化强国，这是实现“两个一百年”奋斗目标中的第二个百年奋斗目标；要实现中国梦，还离不开青年学生，实现中国梦、实现“两个一百年”奋斗目标都会涉及人民、涉及广大青年学生。课的最后做了一个小结：方向决定道路、道路决定命运，从聚焦中国成就、点赞中国道路、贡献中国智慧、坚定自信这四个方面探讨——为什么中国会取得这样的成就，是因为我们走自己的道路、坚持党的领导、建设中国特色社会主义；为什么中国不会被唱衰，是因为我们建立了社会主义基本经济制度、社会主义民主政治，是因为中国特色社会主义取得了伟大胜利，实践证明了选择科学社会主义、选择走中国特色社会主义道路的正确性；中国也要为世界的发展做出自己的贡献；最后坚定自信，畅想 2035 年建成社会主义现代化国家时那时候的中国是什么样，青年一代又有新的责任和担当。", "vtech": [["生产力与生产关系：谁决定谁、谁反作用于谁", "看到“决定”先想：生产力决定生产关系，经济基础决定上层建筑；看到“反作用”再看适应还是不适应——适应就促进，不适应就阻碍甚至破坏；易错点：生产资料所有制是生产关系的基础，决定着生产关系的其他两个方面，不要把决定关系说反。"], ["五种社会形态对比表：抓三根线", "看到对比题按三根线逐项核对：生产力看劳动者、劳动工具、劳动对象；生产关系看所有制、地位关系、分配；原始社会是共同占有、平均分配，社会主义社会是劳动者共同占有、按劳分配；易错点：目前世界上社会主义国家只有五个——中国、越南、朝鲜、老挝、古巴，都是由共产党执政。"], ["英国君主立宪制 vs 美国民主共和制：政体不同看国情", "英国：君主只是象征性国家元首、职责都是礼仪性的，议会是最高立法机关和最高国家权力机关，政府首脑由议会多数党领袖出任，是真正的国家权力中心，1640 年革命开始、1689 年确立；美国：总统既是国家元首又是政府首脑，与议会相互制约；判断信号：同是资本主义国家、政体不同，根子在各自的特殊国情，不要只记政体名称不记形成原因。"], ["中国道路为什么走得通：三点否定资本主义道路", "看到“中国资本主义道路为什么走不通”先答三点：封建势力同帝国主义相勾结、严重阻碍民族资本主义经济发展；帝国主义不允许中国变强大、成为自己的竞争对手；中国资产阶级自身软弱妥协、不具备建立资本主义制度的条件；正面论证看利顺德饭店：1952 年收归国有、一年扭亏为盈，1978 年改革开放后重焕生机。"]], "vgaokao": []}}}, "nodeUnit": {"pol_p001": "u_pol_1", "pol_p002": "u_pol_1", "pol_p003": "u_pol_2", "pol_p004": "u_pol_2", "pol_p005": "u_pol_3", "pol_p006": "u_pol_3", "pol_p007": "u_pol_4", "pol_p008": "u_pol_4", "pol_p009": "u_pol_4", "pol_p010": "u_pol_5", "pol_p011": "u_pol_5"}};
